-- nahual
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (0, 15, 'Tzikin', null, 'Pajaro', '<p>
    <strong>Características:</strong>
    Significa pájaro. Es el símbolo de la suerte, la fortuna y los bienes materiales. También es símbolo de libertad y es el nawal de las aves.
  </p>
  <p>
    Simboliza el pájaro sagrado Q’uq’umatz. Este día es propicio para pedir por la abundancia de los bienes como el dinero.
    Se quema el ajonjolí y el chocolate como ofrendas a Ajaw. Se encienden candelas de colmena pura y se le pide a Ajaw un buen negocio.
    Tz’ikin significa pájaro y simboliza la intermediación entre los seres humanos y Ajaw, representado por todo lo que hay en el espacio:
    el aire, las nubes, el frío y el calor. Son fuerzas invisibles, pero que El Corazón del Cielo y El Corazón de la Tierra las ha puesto
    a nuestro servicio y protección.
  </p>
  <p>
    También es un día de desarrollo espiritual y, por tanto, de  la plena realización humana.
    Es el día para agradecer los bienes materiales principalmente lo relacionado a dinero.
    Sin embargo, al no agradecer estos favores también puede traer la miseria.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Agradecimiento por los bienes materiales, principalmente lo del dinero.</li>
    <li> Propicia buena suerte en el negocio.</li>
    <li> Día de invocación porque las aves no molesten los sembradíos.</li>
    <li> Día para la protección del negocio.</li>
    <li> Día para realizar invocaciones para que las siembras estén protegidas de los animales.</li>
  </ul>
  <p><strong>Su origen:</strong> Kej <strong>destino:</strong> Aq\'ab\'al</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Es bueno para el negocio.</li>
    <li> Es mensajero, paciente y amable.</li>
    <li> De buen temperamento.</li>
    <li> Tiene habilidad para el análisis y es buen observador.</li>
    <li> Desarrolla mejor su inteligencia.</li>
    <li> Puede tener dotes para la predicción de las cosas.</li>
    <li> Puede ser afortunado en lo material.</li>
    <li> Puede tener bien desarrollado la parte espiritual.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Envidia</li>
    <li> Infidelidad</li>
    <li> Avaricia</li>
    <li> Tacañería</li>
    <li> En algún vicio</li>
  </ul>', 'Nahual_0', 'Es el Nawal del bienestar económico, la buena fortuna, día propicio para agradecer y pedir el bienestar económico.
Es la comunicación e intermediación entre Uk´ux Kaj y Uk´ux Ulew, el corazón del cielo y el corazón de la tierra.
Personas que construyen su propio bienestar.', 'src/imagenesNahuales/15.jpg', '<p>
    <strong>Ruwäch:</strong>
    Xb’an ri’ ruq’a’. Xb’an ri nimaj b’isonel, ri jun qak’u’, ri ruwäch qach’ab’äl chi q’aq’al. Xaq xb’an ri’ ruwäch k’ulaj ri xq’atb’al q’aq’al ri ruwäch aj tz’ikin.
  </p>
  <p>
    Xb’an ri nim q’aq’al Q’uq’umatz. Ri taq Q’ij xb’an chi k’amik ri b’anob’äl pa ri qach’ab’äl chi q’aq’al xa keq chi k’amik jun nimalaj qak’u’. Xk’ule Ajaw jun nimaj b’isonel chi ri qach’ab’äl chi pa taq’a. Xkatb’al ri ajonjolí chi ch’okolate chuchi Ajaw. Xkin kandelas chi pure ka’ab’ri chi Ajaw jun nimalaj b’isonel. Tz’ikin xb’an ri’ ruq’a’ ri xb’an ri chi k’amik jun k’aslemal pa El K’aslemal chuchi Ajaw, ri xkixqab’ ri ruq’a’, ri nim k’aslemal k’ul, ri k’as, ri ch’ich’. Xb’an ri nimaj k’a’ ch’ab’äl, xaq ri Ajaw ri ruchi’el ri le ch’ul ch’aq’ pa ch’uqa’.
  </p>
  <p>
    Xaq xb’an jun q’ij ri q’ijil pa ka ri k’aslemal k’aslemal, ri nimaj ruwäch k’aslemal. Ri q’ij pa xkatb’al chi k’amik ri b’anob’äl pa ri qach’ab’äl chi q’aq’al xa keq chi k’amik jun nimalaj qak’u’. Xkatb’al xa chuchi Ajaw ri jun q’aq’al man xb’an chi k’amik xa keq chi k’amik jun nim k’a’ ruwäch.
  </p>
  <p>
    <strong>Ruwäch Ajaw:</strong>
  </p>
  <ul>
    <li> Katb’al chi k’amik ri b’anob’äl pa ri qach’ab’äl chi q’aq’al xa keq chi k’amik jun nimalaj qak’u’.</li>
    <li> K’otem pa k’aslemal.</li>
    <li> Q’ij ri jun k’ikotem xb’ano ri tz’ikin man xb’ano jun chik pa k’uley.</li>
    <li> Q’ij pa q’atb’al chi k’amik jun nimalaj b’isonel chi ri qach’ab’äl chi pa taq’a.</li>
    <li> Q’ij pa q’atb’al chi k’amik jun nimalaj b’isonel chi ri qach’ab’äl chi pa ch’uqa’.</li>
  </ul>
  <p><strong>Ruwäch:</strong> Kej <strong>ru tz’i’:</strong> Aq\'ab\'al</p>
  <p>
    <strong>Nimalaj k’otem:</strong>
  </p>
  <ul>
    <li> Xk’ol pa ri qach’ab’äl chi pa taq’a.</li>
    <li> Xk’at pa ri ch’ab’äl, k’otem ri k’aslemal, xaq k’aslemal.</li>
    <li> Xk’am pa ri jun k’ul chi k’amik.</li>
    <li> Xkotem pa ri xkojik xa keq chi k’amik jun k’aslemal.</li>
    <li> Xk’at jun ri k’otem jun nimalaj ruwäch k’aslemal.</li>
    <li> Xk’at jun ri q’ijil ri jun q’aq’al.</li>
    <li> Xk’at jun ri b’isonel chi q’aq’al chi pa taq’a.</li>
    <li> Xk’at jun ri b’isonel chi ri nimaj k’aslemal.</li>
  </ul>
  <p>
    <strong>Nimalaj k’ul:</strong>
  </p>
  <ul>
    <li> Jun q’ijil</li>
    <li> Man xb’an chi k’amik</li>
    <li> Jun q’aq’al chi k’amik</li>
    <li> Jun nimalaj q’aq’al chi k’amik</li>
    <li> Jun tzij</li>
  </ul>
', '<p>
    <strong>U jats\'utsilo\'ob:</strong><br/>
    Le náwal le máam u yáax kaajil. Ku representaj k\'áajtal le kaaj (chantún, wits, káaltik u lu\'um). Tu\'ux ku meyaj u sakario\'ob ku ts\'áaj u jóok\'olil.<br/>
    Significa báalam.
</p>
<p>
    Ku representaj le altár maya (tab\'al). Ja’áanil u k\'iin tu yáakay xook u k\'áajtal ichil le báaxalil (waajil yéetel lu\'umil).<br/>
    Ku ts\'áaj u p\'óopil yéetel u ya\'al jun jach máak súutuk u k\'áajtal u k\'áaxo\'ob. Tu k\'iinil janlal ku jala\'ats u tax t\'aan ku ts\'áaji le x\'katzin verde, tumen ku representaj le k\'áajil máasewáalo\'.
</p>
<p>
    <strong>Toj óolalil:</strong>
</p>
<ul>
    <li> Ku ts\'áaj u óolal yéetel u suku\'unil ba\'ala\'ob.</li>
    <li> K\'iinil k\'uchul ja\'.</li>
    <li> K\'iinil inwóol u k\'áajtal icham.</li>
    <li> K\'iinil tu p\'áatal u nojoch máasewáalo\'ob.</li>
    <li> K\'iinil tu xokik táan u k\'áaxo\'ob mixba\'al u jok\'ol icham.
</li></ul>
<p><strong>K\'uchul:</strong> Keme <strong>Táan u bin:</strong> Iq\'
</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Toj óol, k\'áajal, ts\'aik, báat\', nojoch óol, púuts\'.</li>
    <li> Máansaj tsolom yéetel tsolam.</li>
    <li> Toj puksi\'ik\'al.</li>
    <li> Nojoch máanilo\' tu juuntal.</li>
    <li> Puede ser nojoch ajk\'olnaj tu sáastal u k\'áajtal.
</li></ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> U chi\'i\'ik\' óol ka jats\'uts.</li>
    <li> Ka p\'áataj óol ichil k\'iin.</li>
    <li> Su óol ka tu\'ux aj ts\'íib\', noj óol, páach óol, y u ts\'aik suuk\'ul.
</li></ul>', '<p>
    <strong>Characteristics:</strong>
    It is the symbol and energy of Mother Earth. It represents the places or ceremonial centers where ceremonies take place.
    They are the hills, the mountains, the plains. It means Jaguar.
</p>
<p>
    It represents the Maya altar or tab\'al. It is a special day to ask for the life of animals, both domestic and wild.
    Ajaw is asked for a good harvest of any crop, especially vegetables.
    On this day, candles of green color are lit, as they symbolize the color of Mother Earth.
</p>
<p>
    It represents the Maya altar or tab\'al. It is a special day to ask for the life of animals, both domestic and wild.
    Ajaw is asked for a good harvest of any crop, especially vegetables. On this day, candles are lit
    of green color, as they symbolize the color of Mother Earth.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Provides spiritual and physical energy.</li>
    <li> Invocation for rain.</li>
    <li> Invocation for the life of animals.</li>
    <li> Day of invocation for the health of all humanity.</li>
    <li> Day to make invocations so that crops are protected from animals.</li>
</ul>
<p><strong>Its origin:</strong> Keme <strong>destination:</strong> Iq\'</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> He is patient, strong, responsible, brave, respectful, vigorous, and daring.</li>
    <li> He is decisive and realistic.</li>
    <li> He has a good heart.</li>
    <li> Good family man.</li>
    <li> He can be a leader and famous if he knows how to channel his energies.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> He can have a strong character.</li>
    <li> Sometimes he gets angry and impatient.</li>
    <li> His character can make him arrogant, proud, angry, serious, and vindictive.</li>
</ul>
', '<p>
    <strong>K\'u\'xaj:</strong>
    Ri\' k\'i\' ruk\'ub\'al chuwach pájaro. On ri\' k\'i\' ruk\'ub\'al k\'ak\'al, chuwach q\'ij y ri\' k\'ak\'ab\'aj ulew. Ta\' k\'i\' ruk\'ub\'al k\'ak\'al k\'o\' nawal ri\' chuwach.
</p>
<p>
    K\'o\' k\'u\'xaj k\'i\' ruk\'ub\'al q\'ij Q’uq’umatz. Ri\' q\'ij k\'o\' chuwach k\'o\' taj k\'i\' ri\' k\'ol re k\'u\'xaj re k\'ak\'al k\'ax ri\' ri\' k\'i\' q\'ij k\'o\' chuwach.
    Ta\' k\'o\' mach k\'i\' Ajaw. Ta\' k\'i\' k\'o\' pura k\'axel q\'ij chocolaj chuwach k\'i\' Ajaw. Ta\' k\'i\' jay colmena pura q\'ij ch\'ele chuwach k\'i\' Ajaw ri\' k\'o\' chuwach k\'o\' taj k\'i\' waj ri\' k\'i\' chak\'ik.
    Tz’ikin k\'o\' chuwach pájaro k\'o\' k\'ak\'al ri\' ch\'umilkaj ri\' winaq ri\' k\'i\' Ajaw, q\'ij re k\'u\'xaj:
    ri\' ruk\'ut, ri\' jun ri\' k\'ut, ri\' xelaj jun ri\' k\'ut. Ta\' k\'o\' q\'ij k\'o\' chak\'ik ri\' k\'ak\'ab\'aj, chi\' k\'o\' k\'ol re k\'ol k\'o\' mach:
    ri\' xruwi\', q\'ut, ri\' saqil, k\'o\' ri\' taj.
</p>
<p>
    Ta\' k\'o\' k\'u\'xaj k\'o\' ri\' k\'i\' ch\'uti\'al chuwach ri\' k\'o\' ri\' k\'ak\'ab\'aj, k\'o\' k\'o\' xik\' ri\' xruwi\'.
    Ta\' k\'o\' q\'ij chak\'ik ri\' k\'u\'xaj xik\' re k\'i\' ruk\'ub\'al chuwach ch\'uti\'al ri\' k\'i\' k\'ak\'ab\'aj.
    Sin embargo, chi\' k\'o\' mach xik\' ta\' k\'i\' k\'u\'xaj k\'o\' re k\'u\'xaj ri\' k\'o\' ch\'uti\'al.
</p>
<p>
    <strong>Función Espiritual:</strong>
</p>
<ul>
    <li> Q\'ij chak\'ik ta\' k\'o\' k\'u\'xaj k\'o\' xik\' ri\' k\'i\' ruk\'ub\'al chuwach, k\'o\' k\'o\' xik\' re k\'u\'xaj xik\'.</li>
    <li> Ta\' k\'o\' xik\' ri\' k\'i\' chak\'ik re k\'u\'xaj ri\' k\'ak\'ab\'aj.</li>
    <li> Q\'ij k\'o\' k\'ak\'al re k\'ak\'ab\'aj k\'o\' k\'i\' chak\'ik xik\' ri\' k\'ak\'ab\'aj ri\' k\'o\' xik\' q\'ij k\'u\'xaj k\'o\' chuwach.</li>
    <li> Q\'ij k\'o\' k\'ak\'al k\'i\' chak\'ik ri\' k\'ak\'ab\'aj.</li>
    <li> Q\'ij k\'o\' k\'ak\'al chak\'ik ta\' k\'i\' chak\'ik ta\' k\'o\' ri\' k\'i\' chak\'ik xik\' ri\' k\'i\' k\'u\'xaj k\'o\' ri\' k\'ak\'ab\'aj.</li>
</ul>
<p><strong>K\'a\'wi\' che\' ri\' k\'aj:</strong> Kej <strong>ruwi\' q\'ij:</strong> Aq\'ab\'al</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Ta\' k\'o\' q\'ij re k\'i\' chak\'ik xik\' ri\' k\'ak\'ab\'aj.</li>
    <li> Ta\' k\'o\' ch\'ele ri\' k\'ak\'ab\'aj, xik\' ri\' k\'i\' q\'ij k\'o\' k\'ak\'al.</li>
    <li> Ta\' k\'o\' k\'i\' winaq jun chi\' k\'o\' muk\'ul.</li>
    <li> Ta\' k\'o\' chi\' k\'o\' k\'ak\'al re k\'ak\'ab\'aj k\'i\' k\'ak\'al q\'ij k\'o\'.</li>
    <li> Ta\' k\'o\' rik\'ab\'al chi\' k\'o\' winaq k\'i\' k\'ak\'ab\'aj.</li>
    <li> Ta\' k\'o\' xik\' re k\'i\' k\'ak\'ab\'aj k\'o\' chak\'ik q\'ij k\'o\'.</li>
    <li> Ta\' k\'o\' k\'i\' winaq xik\' k\'o\' re k\'ak\'ab\'aj k\'i\' k\'ak\'al q\'ij k\'o\'.</li>
    <li> Ta\' k\'o\' rik\'ab\'al ri\' k\'i\' k\'ak\'ab\'aj xik\'.</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Tz\'ik\' ri\' xik\'.</li>
    <li> Ajchajik\'</li>
    <li> Ta\' k\'o\' q\'ij re k\'i\' xik\'.</li>
    <li> Ta\' k\'o\' ch\'ak\'al chuwach k\'i\' xik\'.</li>
    <li> Chi\' k\'o\' ajpuch.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (1, 16, 'Ajmaq', null, 'Búho, falta o culpa', '<p>
    <strong>Características:</strong>
    Esta palabra significa pecador en K’iche’.  Es el día de los pecadores.  Este día se dedica a pedir perdón por los pecados y por los pecadores.
    Es el día dedicado a los difuntos.  El pecado es una columna de humo que nos oculta delante de la presencia de Dios.
    Nuestros antepasados dijeron:  “que el pecado es la ofensa que se hace directamente a Dios.
    No creer, no servir, no alabar al Corazón del Cielo, al corazón de la Tierra.  Mak es ofensa a Dios y Wuqub’ qak’ix  es ofensa al prójimo”
  </p>
  <p>
    Es el día de los que no podemos ver, el día de los difuntos.  El día de la fortaleza que nos da la historia de nuestro pasado.
    También es el día del castigo cuando no estamos actuando en concordancia con las enseñanzas que ellos nos legaron.  Es el día del enojo de los difuntos. (BEA)
  </p>
  <p>
    “Ajmaq no es un mal día.  Es un día para pedir perdón por los pecados.
    Son  los días en los cuales se reza por protección, ya que de estos días puede venirle a uno, daño por sus pecados o sus malos pensamientos.
  </p>
  <p>
    es la muerte en casa, la muerte natural por enfermedad, la muerte tranquila.
    En ese día se habla con los difuntos, es para pedir perdón en el caso de los pecadores.
  </p>
  <p>
    <strong>Significa:</strong>
  </p>
  <ul>
    <li> Purificar el espíritu de los muertos y vivos.</li>
    <li> Día para conmemorar los difuntos.</li>
    <li> Perdón para nuestros pecados.</li>
  </ul>
  <p><strong>Significado Clave:</strong> Autoridad y Estatus.</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Posee sabiduría, inteligencia</li>
    <li> Buena memoria</li>
    <li> Muy valiente</li>
    <li> Se les facilita el diálogo</li>
    <li> Prudente, discreto</li>
    <li> Buenos maestros y consejeros</li>
    <li> Muy sociable</li>
    <li> Es profundo</li>
    <li> Es serio</li>
    <li> Realista</li>
    <li> Predicador</li>
    <li> Comunicativo</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Pecador</li>
    <li> Enamorado</li>
    <li> Alcohólico</li>
    <li> Destructores de la herencia</li>
    <li> Mentirosos</li>
    <li> Afamados</li>
    <li> Resentido</li>
    <li> Ladrón</li>
    <li> Adúltero</li>
    <li> Fríos e insensibles</li>
    <li> Minimizan los sentimientos de los demás</li>
    <li> Interesados en la autoridad y posición social y política</li>
  </ul>', 'Nahual_1', 'Es el Nawal de todas las faltas, es el día de los abuelos que ya no están (difuntos).
Es el día para pedir perdón por las faltas.
Personas valientes y de sangre dulce que  fácilmente caen en culpas.', 'src/imagenesNahuales/16.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ri taq tzij xb’an ri mak pa K’iche’. Ja ri q’ij ri mako’ pa ri q’ij ri mak. Ja ri q’ij k’atb’al chi k’amik chi q’apoj ri mak k’a ri mak. Ja ri q’ij k’atb’al chi ri k’aslemal k’o. Ri mak ja ri xtäq’ab’äl ri xtaniwach pa ruwi’ Ajaw. Ri qati’t qamama’ xpe pa ri q’ij: “ri mak ja ri xtz’amäj ri xq’ab’äl pa ruwi’ Ajaw. Man xwajo, man xb’ano, man xtz’ulo junq’ij Ajaw, ri q’aq’ Ajaw ri El K’aslemal, ri ri le q’ij ja ri xtz’amäj ri Ajaw wuqub’ qak’ix ja ri xtz’amäj ri q’atb’al”
  </p>
  <p>
    Ja ri q’ij ri man xkib’ano, ri q’ij ri k’aslemal k’o. Ja ri q’ij ri ruwäch ch’ab’äl chi ri xtzij ri qati’t qamama’. Xb’an xa ri q’ij ri k’o chi k’amik pa ri q’ij ri xb’ano k’o ri xtz’ulo ri k’aslemal ri xtzo’ri’ k’o. Ja ri q’ij ri xtz’i’ ri k’aslemal k’o. (BEA)
  </p>
  <p>
    “Ajmaq man xb’an jun q’ij k’aslemal. Ja ri q’ij k’atb’al chi k’amik chi q’apoj ri mak k’a ri xtz’amäj.
    Ri xtz’i’ ja ri q’ij ri xtz’i’ k’atb’al chi k’amik pa jun nim q’aq’al chi ri xtz’amäj pa ri q’ij ri xtz’amäj k’o ri xtz’ulo k’a xtz’ulo ri xtz’aq k’a xtz’i’ k’ojon pa jun nima’ q’aq’al.”
  </p>
  <p>
    Ja ri xto’ pa jay, ri xto’ jun k’aslemal chi jun xuquje’ ri k’aslemal chi xwätiq.
    Pa ri q’ij xb’an chi k’amik chi xwajo ri k’aslemal, ja chi k’atb’al chi k’amik pa ri q’ij ri xtz’amäj ri mak k’a ri mak.
  </p>
  <p>
    <strong>Ruwäch:</strong>
  </p>
  <ul>
    <li> K’atb’al chi k’amik ri ch’ab’äl chi k’aslemal k’o.</li>
    <li> Q’ij pa ri k’atb’al chi k’amik pa ri k’aslemal k’o.</li>
    <li> Q’apoj chi q’apoj ri mak k’a ri xtz’amäj.</li>
  </ul>
  <p><strong>Ruwäch Chi’aj:</strong> Q’aq’ ri k’aslemal.</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> Xk’at pa q’ij chi k’aslemal, q’ijil</li>
    <li> Xk’at jun q’ijil</li>
    <li> Xak’am ri q’aq’</li>
    <li> Xkotem ri q’ij chi k’amik</li>
    <li> Xk’at jun ruwäch k’aslemal</li>
    <li> Xk’at ri q’ijil pa q’aq’al</li>
    <li> Xk’at jun q’aq’ k’aslemal</li>
    <li> Xk’at jun ruwäch k’aslemal</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> Ri mako’</li>
    <li> Ri q’aq’alil</li>
    <li> Ri ch’ich’ k’ul</li>
    <li> Ri xto’ q’ijil</li>
    <li> Ri xtzij</li>
    <li> Ri xto’ q’ijil k’otem</li>
    <li> Ri xto’ k’a’</li>
    <li> Ri xtzo’</li>
    <li> Ri xtz’aqil</li>
    <li> Ri k’a’ man xb’an chi k’amik</li>
    <li> Ri xtan xtz’i’ pa q’ij</li>
    <li> Ri xtz’ulo chi k’aslemal pa k’ul, k’aslemal o q’aq’ k’a’</li>
  </ul>
', '<p>
    <strong>U jats\'utsilo\'ob:</strong><br/>
    "Ajmaq" u k\'áaba\' mixba\'al ma\'ax mix juntéene\' tu K’iche’. Le k\'iinil baknik ma\'ako\'ob. Ja\'aj u k\'iinil tu yáajal k\'áat chi\'ibal u jóok\'olol máako\'ob.
    Ja\'aj u k\'iinil tu yáal ajawil le pixano\'ob máak tso\'ok u béeyal.
</p>
<p>
    U k\'iinil u pixano\'ob ku sáansamal k\'uchul k baket óol. Tu k\'iinil jump\'éel k\'ax óol máan u maaya\'al ku uts k suku\'unil, bey xan ku tsola\'al k\'áax le kuxtalil baket.
</p>
<p>
    <strong>Ba\'ax ku ts\'íib:</strong>
</p>
<ul>
    <li> Ku ch\'úupal pixano\'ob máam yéetel yáax.</li>
    <li> K\'iinil ilikba\'al u pixano\'ob.</li>
    <li> K\'aatenil p\'áaxil k siniko\'ob.</li>
</ul>
<p><strong>Máanil t\'aan:</strong> Toj óolal yéetel status.
</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> U nojoch na\'at, na\'atik.</li>
    <li> Ajidlil, tsikbalil.</li>
    <li> Jach k\'áajal.</li>
    <li> U t\'aan yaan fácil.</li>
    <li> Naatil, na\'at óol.</li>
    <li> Maestros, ajkonsejero\'ob.</li>
    <li> Jach k\'a\'asaj.</li>
    <li> Tu púuts\' óol.</li>
    <li> Jach máan na\'at.</li>
    <li> Tu ts\'íib t\'aan.</li>
    <li> Aj kommunikador.
</li></ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Máako\', pecador.</li>
    <li> In laj lo\'ol.</li>
    <li> Aj  púuts\'il.</li>
    <li> Ku sok u na\'atilo\'ob le kúuchul.</li>
    <li> Ku ts\'íibil.
</li></ul>', '<p>
    <strong>Características:</strong>
    This word means sinner in K\'iche\'. It is the day of sinners. This day is dedicated to asking for forgiveness for sins and sinners.
    It is the day dedicated to the deceased. Sin is a column of smoke that hides us from the presence of God.
    Our ancestors said: "that sin is the offense directly to God.
    Not to believe, not to serve, not to praise the Heart of Heaven, the heart of the Earth. Mak is an offense to God and Wuqub’ qak’ix is an offense to one\'s neighbor."
</p>
<p>
    It is the day of those we cannot see, the day of the deceased. The day of the strength that our past history gives us.
    It is also the day of punishment when we are not acting in accordance with the teachings they left us. It is the day of the anger of the deceased. (BEA)
</p>
<p>
    "Ajmaq is not a bad day. It is a day to ask for forgiveness for sins.
    These are the days in which one prays for protection, since from these days harm can come to one because of their sins or bad thoughts.
</p>
<p>
    it is death at home, natural death from illness, peaceful death.
    On that day one speaks with the deceased, it is to ask for forgiveness in the case of sinners.
</p>
<p>
    <strong>Significa:</strong>
</p>
<ul>
    <li> Purify the spirits of the dead and the living.</li>
    <li> Day to commemorate the deceased.</li>
    <li> Forgiveness for our sins.</li>
</ul>
<p><strong>Significado Clave:</strong> Authority and Status.</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Possesses wisdom, intelligence</li>
    <li> Good memory</li>
    <li> Very brave</li>
    <li> Dialogue comes easily to them</li>
    <li> Prudent, discreet</li>
    <li> Good teachers and counselors</li>
    <li> Very sociable</li>
    <li> Deep</li>
    <li> Serious</li>
    <li> Realistic</li>
    <li> Preacher</li>
    <li> Communicative</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Sinner</li>
    <li> In love</li>
    <li> Alcoholic</li>
    <li> Heritage destroyers</li>
    <li> Liars</li>
    <li> Notorious</li>
    <li> Resentful</li>
    <li> Thief</li>
    <li> Adulterer</li>
    <li> Cold and insensitive</li>
    <li> Minimize the feelings of others</li>
    <li> Interested in authority and social and political position</li>
</ul>
', '<p>
    <strong>Ta\' k\'ol:</strong>
    On ri\' k\'ak\' saqil pecador. Ri\' k\'i\' ruk\'ub\'al q\'ij pecador. On ri\' k\'i\' q\'ij ruk\'ub\'al q\'ij pecados ri\' ruk\'ub\'al pecadores. Ri\' k\'i\' k\'ol ruk\'ub\'al kamik ri\' k\'ol.
    Q\'ij k\'ol ruk\'ub\'al chi\' k\'o\' ri\' k\'ol k\'ak\'al.
    Ta tuk ri\' k\'i\' ruk\'ub\'al mach. "Ta winaq ri\' k\'ak\'ab\'aj Dios.
    Ma\' k\'at ri\', ma\' k\'at ri\', ma\' k\'at ri\' k\'ol kaq\'al. Mak k\'o\' mach ri\' k\'ak\'ab\'aj Wuqub\' qak\'ix k\'o\' mach ri\' k\'ak\'ab\'aj."
</p>
<p>
    Ri\' k\'i\' q\'ij ruk\'ub\'al q\'ij chuwach. Ri\' k\'i\' ruk\'ub\'al k\'o\' chuwach.
    Ta\' k\'i\' ruk\'ub\'al q\'ij saqil chuwach ri\' q\'ij aq\'al chuwach.
    K\'ol ruk\'ub\'al k\'o\' chuwach. (BEA)
</p>
<p>
    "Ajmaq k\'o\' ri\' k\'ol mach. Ta\' k\'i\' ruk\'ub\'al q\'ij q\'ij pecador.
    Ruk\'ub\'al k\'o\' mach ri\' k\'i\' ruk\'ub\'al re ruwi\', chi\' k\'o\' ruk\'ub\'al mach re q\'ij winaq chuwach k\'o\' kaj winaq, mach k\'o\' winaq ri\' k\'i\' q\'ij chuwach.
</p>
<p>
    Ta\' k\'ol ruk\'ub\'al mach k\'o\' ri\' k\'i\' q\'ij, k\'o\' k\'ak\'al ri\' k\'i\' chuwach, k\'ol k\'o\' mach ri\' k\'ak\'ab\'aj.
</p>
<p>
    <strong>Significado:</strong>
</p>
<ul>
    <li> K\'ak\'al ri\' q\'ij k\'ol ruk\'ub\'al chuwach re k\'ol k\'o\' k\'ak\'al.</li>
    <li> Q\'ij k\'o\' chuwach re ruk\'ub\'al k\'o\' chuwach.</li>
    <li> Q\'ij ruk\'ub\'al k\'o\' re ri\' k\'i\' pecados.</li>
</ul>
<p><strong>Significado Q\'ij:</strong> Ri\' chuwach re lekil k\'ol.</p>
<p>
    <strong>K\'ak\'al:</strong>
</p>
<ul>
    <li> Ta\' k\'o\' ruwi\', k\'ak\'ab\'aj</li>
    <li> Ta\' k\'o\' xqi\'ij</li>
    <li> Ta\' k\'o\' k\'ak\'al q\'ij k\'o\'</li>
    <li> Ta\' k\'o\' tajik rik\'ab\'al ri\' k\'ak\'al</li>
    <li> Ta\' k\'o\' chi\' k\'o\' muk\'ul, xruwi\'</li>
    <li> Ta\' k\'o\' k\'ak\'al ri\' maestro y k\'o\' k\'ol k\'o\'</li>
    <li> Ta\' k\'o\' k\'ak\'al q\'ij k\'ol</li>
    <li> Ta\' k\'o\' k\'ak\'al q\'ij tukul</li>
    <li> Ta\' k\'o\' k\'ak\'al xtu\'ul</li>
    <li> Ta\' k\'o\' k\'ak\'al q\'ij</li>
    <li> Ta\' k\'o\' k\'ak\'al chuwach</li>
    <li> Ta\' k\'o\' ruwi\' ri\' maestro</li>
</ul>
<p>
    <strong>Q\'ijochik:</strong>
</p>
<ul>
    <li> Pecador</li>
    <li> Ma\'k\'akab\'aj</li>
    <li> K\'atiquin ri\' chuwach</li>
    <li> Xchiwach</li>
    <li> K\'umuk\'ul ri\' lekil</li>
    <li> Wajxa\'k\'ib\'äl</li>
    <li> Ruk\'ut\'a\'wa\' xtojik</li>
    <li> Tzukut</li>
    <li> Xqa\'k\'alajik</li>
    <li> Muy xtu\'ul</li>
    <li> Xqupala ri\' lekil k\'ol</li>
    <li> Xo\'kajik ri\' k\'ak\'ab\'aj k\'o\' q\'ij k\'ol ri\' k\'ak\'ab\'aj k\'ol k\'o\'.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (2, 17, 'No\'j', null, 'Idea o sabiduria', '<p>
    <strong>Características:</strong>
    Es la sabiduría y el conocimiento. Es el nawal de la inteligencia. Es el buen consejo, según los abuelos y abuelas.
    Es la sabiduría que viene del Formador y Creador. También es uno de los Cargadores del Tiempo.
    Día propicio para agradecer el conocimiento y pedir buenos pensamientos.
  </p>
  <p>
    El que nace bajo la influencia del No’j será inteligente, activo y tendrá buenos pensamientos, siempre y cuando sepa manejar las energías del día.
    Significa también idea y sabiduría. Según los mayas ningún hombre es sabio. Por eso, el hombre, para recibir ideas y consejos,
    debe consultar al Ajaw por medio del “xukulem” o la ceremonia maya. También puede realizar dichas consultas por medio del tz’ite’,
    mediante la intermediación del Ajq’ij, para recibir los consejos de los abuelos y abuelas. Dentro de la espiritualidad maya,
    el hombre tiene ideas pero no sabiduría. Por eso, es importante juntarse en consejo para unir ideas y formar así  una ciencia.
    Nuestros antepasados se reunían en consejo bajo la protección del No’j.
  </p>
  <p>
    es el día de la sabiduría. Es el día  para tomar decisiones de manera particular o en consejo. Es un día que propicia la planificación de algún proyecto y de los
    lineamientos a seguir en la conducción de la comunidad y de la sociedad en general. También es el día en que nuestro pensamiento puede tener mayor fluidez.
  </p>
  <p>
    <strong>Función espiritual:</strong>
  </p>
  <ul>
    <li> Agradecer el conocimiento y las ideas.</li>
    <li> Agradecer la inteligencia.</li>
    <li> Día para acrecentar la memoria.</li>
    <li> Agradecer la inteligencia.</li>
    <li> Día para pedir buenos consejos.</li>
  </ul>
  <p><strong>Su origen:</strong> Toj <strong>destino:</strong> Kan</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Es poseedor de muchos conocimientos.</li>
    <li> Es inteligente y es consejero.</li>
    <li> Puede llegar a ser científico.</li>
    <li> Es ordenado y creativo.</li>
    <li> Es justo y humanista.</li>
    <li> Es buen estudiante.</li>
    <li> Puede llegar a ser un buen líder.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede caer en el orgullo.</li>
    <li> Se puede enojar con facilidad.</li>
    <li> Le cuesta tomar decisiones.</li>
    <li> Puede ser individualista y egoísta.</li>
  </ul>', 'Nahual_2', 'Significa idea, sabiduría.
Es el Nawal de la inteligencia, día dedicado a pedir la sabiduría, el talento, el buen pensamiento.
Es el Nawal del temblor o sismo.
Personas muy creativas e imaginativas.', 'src/imagenesNahuales/17.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ja ri ch’ab’äl ri b’anob’äl. Ja ri nawal ri nima’ k’ul. Ja ri b’ixan k’ul, xkib’an qati’t qamama’.
    Ja ri ch’ab’äl k’ul xuk’ex chi Tz’aqol B’itol. Xaq k’o jun ri K’aslemal q’ij. Ja ri q’ij k’atb’al chi k’amik ri b’anob’äl ri q’ijil k’ul.
  </p>
  <p>
    Ri xpe jun ri No’j k’o ri nima’ k’ul, nimaj b’ixan k’ul, k’o chi jun ri q’ij k’atb’al chi k’amik ri k’ul ri q’ij.
    Ja ri xb’an q’ij chi tzij k’ul. Xpe ri mayab’ man k’a b’ij k’ul. Rumal ja ri ruwi’ ri b’an chi k’amik jun b’ixan k’ul,
    xkatb’al chuchi Ajaw ri “xukulem” o ri aj k’aslemal. Xaq xb’an jun ri xtz’i’,
    xkan jun ri Ajq’ij, ri xpe pa qati’t qamama’ k’ul. Chupam ri k’aslemal mayab’,
    ja ri winaq k’ul man b’ij k’ul. Rumal ja ri k’atb’al chi jun ch’ol chi q’ij pa k’aslemal chi ri b’ixan k’ul.
    Qati’t qamama’ xpe pa k’aslemal pa xukulem chuchi No’j.
  </p>
  <p>
    ja ri q’ij ri ch’ab’äl k’ul. Ja ri q’ij ri xb’an chi k’amik ri nima’ tzij k’ul pa jun ch’ol. Ja ri q’ij xb’an jun ch’atik ri nimal q’ij pa ri
    nima’ chi k’amik, xaq xb’an chi k’amik jun b’ixan ri k’otemab’äl pa jun nim ja ri k’aslemal chi kik’.
  </p>
  <p>
    <strong>Ruwäch Ajaw:</strong>
  </p>
  <ul>
    <li> Katb’al chi k’amik ri b’anob’äl chi q’ij k’ul.</li>
    <li> Katb’al chi k’amik ri nima’ k’ul.</li>
    <li> Ja ri q’ij k’atb’al chi k’amik jun nima’ ri katzijonem.</li>
    <li> Katb’al chi k’amik ri nima’ k’ul.</li>
    <li> Ja ri q’ij k’atb’al chi k’amik b’ixan k’ul.</li>
  </ul>
  <p><strong>Ruwäch:</strong> Toj <strong>ru tz’i’:</strong> Kan</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> K’o ri nima’ tzij k’ul.</li>
    <li> K’o ri nima’ k’ul xaq b’ixan k’ul.</li>
    <li> Xk’at pa jun b’ixan ch’ab’äl.</li>
    <li> K’o ri xojib’al xaq k’otemab’äl.</li>
    <li> K’o ri jun tzij xaq k’aslemal.</li>
    <li> Xk’at pa jun xojib’al k’ul.</li>
    <li> Xk’at pa jun q’ij k’otemab’äl.</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> Xk’o pa jun ch’ab’äl.</li>
    <li> K’o ri xk’axik xb’an jun nima’ ch’aq.</li>
    <li> Xk’at pa jun nima’ tzij k’ul.</li>
    <li> Xk’at pa jun xatb’al xaq ch’aq.</li>
  </ul>
', '<p>
    <strong>U jats\'utsilo\'ob:</strong><br/>
    U nojoch na\'at yéetel u na\'atsil. Nawal u ts\'íib, na\'at. Jats\'uts u k\'a\'ansaj máats\'il t\'aan.
    Yaan u na\'atsil t\'aan k inwóol tu Ts\'aajol yéetel Bó\'ots\'.
    Beyxʼe, ja\'aj unoob le “cargadores del tiempo”.
</p>
<p>
    Jump\'éel k\'iin jach uts tu dáal gracia yéetel k\'áat chi\' u yo\'osal na\'atsil.
    Máak tu ja\' kex No\'j ku síijil ba\'ala\' yéetel na\'at (bey tsel ka síijil). Tu Maya u na\'atsil máan nakaj.
    Túumbenil na\'at k uno\'oba\' ku bisik u tsol.
</p>
<p>
    <strong>Toj óolal:</strong>
</p>
<ul>
    <li> Ts\'áaj gracia tech tu na\'at.</li>
    <li> Ts\'áaj gracia a k\'uchulil na\'at.</li>
    <li> K\'iinil jump\'éel meyajil ichil k\'áat u xu\'ul u máan na\'at.</li>
    <li> Ts\'áaj tsol u nojoch na\'at.</li>
    <li> K\'iinil u k\'a\'at chi\' u nojoch k\'uchulil konsejo.
</li></ul>
<p><strong>K\'uchul:</strong> Toj <strong>Táan u bin:</strong> Kan
</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Jach paach na\'at.</li>
    <li> Ajna\'at, ajkonsejero.</li>
    <li> Puede tornarse aj científico.</li>
    <li> U nojoch ch\'ool beyo.</li>
    <li> Jach tu tsolil, ajto\'on.</li>
    <li> U tsolil tu t\'aan.</li>
    <li> Puede ser ajt\'aanaj nojoch.
</li></ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Sáasal u púuts\' óol.</li>
    <li> Túumbenil inwu\'uy óol.</li>
    <li> Ku ya\'al u púuts\'il tsol.</li>
    <li> Jach ajts\'íib ku síijil sólo.
</li></ul>', '<p>
    <strong>Characteristics:</strong>
    It is wisdom and knowledge. It is the nawal of intelligence. It represents good advice, according to grandparents.
    It is the wisdom that comes from the Formator and Creator. It is also one of the Time Carriers.
    A favorable day to give thanks for knowledge and ask for good thoughts.
</p>
<p>
    One born under the influence of No\'j will be intelligent, active, and will have good thoughts, as long as they know how to manage the energies of the day.
    It also means idea and wisdom. According to the Maya, no man is wise. That is why, in order to receive ideas and advice,
    one must consult the Ajaw through the "xukulem" or the Maya ceremony. They can also make such consultations through the tz\'ite\',
    through the mediation of the Ajq’ij, to receive the advice of the grandparents. Within Maya spirituality,
    man has ideas but not wisdom. That is why it is important to gather in council to unite ideas and thus form a science.
    Our ancestors gathered in council under the protection of No\'j.
</p>
<p>
    It is the day of wisdom. It is the day to make decisions individually or in council. It is a day that promotes the planning of a project and of the
    guidelines to follow in the leadership of the community and society in general. It is also the day when our thinking can flow more freely.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Give thanks for knowledge and ideas.</li>
    <li> Give thanks for intelligence.</li>
    <li> Day to increase memory.</li>
    <li> Give thanks for intelligence.</li>
    <li> Day to ask for good advice.</li>
</ul>
<p><strong>Origin:</strong> Toj <strong>destination:</strong> Kan</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Possesses much knowledge.</li>
    <li> Is intelligent and is a counselor.</li>
    <li> Can become a scientist.</li>
    <li> Is organized and creative.</li>
    <li> Is fair and humanistic.</li>
    <li> Is a good student.</li>
    <li> Can become a good leader.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Can fall into pride.</li>
    <li> Can get angry easily.</li>
    <li> Struggles to make decisions.</li>
    <li> Can be individualistic and selfish.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    Rechajolilal u k\'aslemal k\'u\' rech k\'i\'wach. Rechajolilal u nawal ri ch\'utuq\'aj. Rechajolilal u k\'i\'wach k\'u\' ri ri abuelo ri ri abuela.
    Rechajolilal u k\'aslemal rech k\'u\' ri Wach k\'u\' Ulew chik k\'ut k\'u\' ch\'utuj k\'u\' rechajolilal. Rechajolilal xkik\'aj rech Cargadores k\'u\' rech K\'atun.
    Q\'ij rechajolilal paq\'ajolilal k\'u\' chik\'ol k\'u\' k\'ut k\'u\' wuj winaq rechajolilal rechajolilal xk\'ut k\'u\' ri k\'u\' chik\'aj k\'u\' rechajolilal.
</p>
<p>
    Ri\'el u rechajolilal paq\'ajolilal k\'u\' rech k\'at k\'u\' No’j chik\'aj k\'u\' chik\'aj k\'u\' xk\'ut k\'u\' ri rech k\'at k\'u\' winaq k\'u\' ch\'utuj k\'u\' chik\'aj,
    k\'u\' rechajolilal ri\'el k\'u\' ri Ajaw k\'u\' ri xukulem rechajolilal k\'u\' ri jun chik\' k\'u\' ri rech k\'i\'wach. Rechajolilal k\'u\' paq\'ajolilal rechajolilal xk\'ut k\'u\'
    tz’ite’, chik\'aj u ch\'aj rech k\'i\'wach rech k\'u\' abuelos k\'u\' ri abuelas. Paq\'ajolilal chik\'aj espiritualidad maya, winaq k\'u\' jun k\'aslemal pero rechajolilal.
    K\'u\' rechajolilal, rechajolilal uq\'ij chik\'aj paq\'ajolilal uwojel rech k\'i\'wach k\'u\' chik\'aj k\'u\' ri k\'i\'wach uwojel k\'u\' chik\'aj k\'u\' rechajolilal.
    Ri\'el wach k\'u\' rech k\'i\'wach k\'u\' No’j.
</p>
<p>
    U k\'i\'wach k\'u\' ri k\'aslemal. Ri\'el k\'u\' q\'ij paq\'ajolilal chik\'aj rechajolilal uwojel ri k\'at ri rechajolilal k\'u\' chik\'aj rechajolilal.
    Q\'ij k\'u\' chik\'aj k\'u\' paq\'ajolilal chik\'aj rechajolilal k\'u\' k\'at winaq uq\'ij xkik\'aj k\'u\' rech k\'i\'wach k\'u\' ri k\'i\'wach k\'u\' winaq chik\'aj k\'u\' rechajolilal.
  </p>
<p>
    <strong>Función espiritual:</strong>
</p>
<ul>
    <li> Agradecer ri k\'aslemal k\'u\' ri k\'ut k\'u\' rech k\'i\'wach.</li>
    <li> Agradecer ri k\'i\'wach.</li>
    <li> Q\'ij k\'u\' rechajolilal k\'u\' paq\'ajolilal ri rechajolilal.</li>
    <li> Agradecer ri k\'i\'wach.</li>
    <li> Q\'ij k\'u\' paq\'ajolilal k\'u\' ri chik\'aj rechajolilal.</li>
</ul>
<p><strong>Jun K\'ab\'al:</strong> Toj <strong>destino:</strong> Kan</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Uwojel k\'u\' jun k\'aslemal rech k\'i\'wach.</li>
    <li> Uwojel k\'u\' k\'at k\'u\' rechajolilal k\'u\' k\'at chik\'aj.</li>
    <li> Uwojel k\'u\' ch\'utuj k\'u\' científico.</li>
    <li> Uwojel k\'u\' xk\'ut k\'u\' chik\'aj ch\'utuj.</li>
    <li> Uwojel k\'u\' chak\'ol k\'u\' humanista.</li>
    <li> Uwojel k\'u\' chik\'aj ch\'utuj ri rechajolilal.</li>
    <li> Uwojel k\'u\' k\'at k\'u\' chak\'ol k\'u\' ri k\'ut rechajolilal.</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Uwojel k\'u\' paq\'ajolilal k\'u\' chak\'aj chik\'aj.</li>
    <li> Uwojel k\'u\' paq\'ajolilal k\'u\' k\'ut chik\'aj winaq chik\'aj.</li>
    <li> Uwojel k\'u\' paq\'ajolilal k\'u\' k\'i\'wach rechajolilal.</li>
    <li> Uwojel k\'u\' chak\'aj chik\'aj k\'u\' egoísta.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (3, 18, 'Tijax', null, 'Pedernal o obsidiana', '<p>
    <strong>Características:</strong>
    Significa piedra y obsidiana. Es el símbolo del pedernal. Es la energía de la persona que cura en la cultura maya.
    Es el poder del trueno y el rayo. La persona que nace bajo la influencia de este día, puede ser un gran curandero o médico con mucha energía en las manos.
    Es ajq’íj, cura enfermedades físicas y psicológicas. Puede arreglar fracturas de los huesos.
  </p>
  <p>
    Una de las influencias negativas del día es que puede causar algún sufrimiento o malestar. Según los Ajq’ijab’, es un día que “come”.
    Para no ser alcanzado por estas influencias negativas debe hacerse alguna ofrenda y solicitar la intermediación del Guía Espiritual.
  </p>
  <p>
    Es un día que puede evitar la humillación y la ruina a causa de algo o alguien. Es un día de protección.
    Los que nacen es este día pueden llegar a ser coléricos y pueden destruir espiritual o emocionalmente a alguien.
    A veces, nadie les aguanta y resulta difícil comprenderlos.
  </p>
  <p><strong>Su origen:</strong> Tz\'i <strong>destino:</strong> Keme</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Es protector de la justicia.</li>
    <li> Es fuerte y servicial.</li>
    <li> Es incansable por lo que quiere lograr.</li>
    <li> Puede llegar a ser Guía Espiritual.</li>
    <li> Posee habilidad para arreglar fracturas en los huesos.</li>
    <li> Se puede defender muy bien ante cualquier problema.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede ser violento y enojado.</li>
    <li> Puede sufrir enfermedades.</li>
    <li> Puede ofenderse fácilmente.</li>
    <li> Puede caer en la venganza y en los pleitos.</li>
  </ul>', 'Nahual_3', 'Nawal de la muerte repentina y los sufrimientos.
Día propicio para curanderos y autoridades,  para cortar males y enfermedades.
Personas confrontativas que cortan toda clase de males y problemas.
', 'src/imagenesNahuales/18.jpg', '<p>
    <strong>Ruwäch:</strong>
    Xb’an ri ab’aj ch’aq’ab’aj. Ja ri ruwäch ri ajmakil. Ja ri k’ulik ri winaq k’aslemal pa mayab’. Ja ri q’ij ri k’ulik ri ya’ y ri q’aq’. Ri winaq ri xpe chi ri q’ij, k’o chi jun nima’ ajmakil o aj ruwäch k’aslemal jun k’ulik. K’o ri ajq’íj, ajmak chi nima’ ri k’aslemal xaq ruwäch ch’uqa’. K’o ri k’ulik chi xtan ri q’aq’.
  </p>
  <p>
    Jun ri ruwäch xa keq chi ri q’ij ja ri xb’an chi xtanik ri jun q’aq’ o jun nima’. Xpe ri Ajq’ijab’, ja ri q’ij ja ri “yow”. Xa ri xb’an chi man xkik’ut xa xb’an chi keq chi b’ix ri Ajq’ij.
  </p>
  <p>
    Ja ri q’ij xb’an chi xq’aj k’as o ri q’ax chi jun winaq o k’o jun k’a’. Ja ri q’ij ri k’ulik. Ri winaq ri xpe pa ri q’ij xb’anol jun q’atalik o xb’ano chi xtan ruwäch o ruwäch ch’uqa’. Tz’ulo, man k’o jun xjip ja xb’ano chi xb’in pa keq chi k’ul.
  </p>
  <p><strong>Ruwäch:</strong> Tz\'i <strong>ru tz’i’:</strong> Keme</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> Ajk’amol chi ri k’ax.</li>
    <li> K’o jun k’ax xaq xb’an k’ax.</li>
    <li> Xk’at jun ruwäch chi k’amik jun k’ax.</li>
    <li> Xpe chi Ajq’ij.</li>
    <li> K’o ri ruwäch chi xtan ri q’aq’.</li>
    <li> Xk’at jun ruwäch chi xb’anol jun nim k’ax.</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> K’o ri xtan ri xyaq’ik xaq xyaq’ik.</li>
    <li> K’o chi xtan chi xkik’. </li>
    <li> K’o chi xkik’. </li>
    <li> K’o chi xtanik ri xb’in xaq xtanim ri k’ax.</li>
  </ul>
', '<p>
    <strong>U jats\'utsilo\'ob:</strong><br/>
    Significa tu\'ulil yéetel obsidiana. U símbolo ti\' tuunil. Ku jach máak u ts\'ak ichil Maya.
    U p\'áatal le rayos yéetel u t\'óh. Máak meyaj tu k\'iinil Tijax puede ser nojoch ajts\'aak.
</p>
<p>
    Ba\'ax ma\' uts: le k\'iin ku jats\' oksaj k\'áaxal. Ajq\'ijobo\'ob tu ya\'al u k\'iin “ku jantaj”.
    Para evitar ba\'ax ma\' uts, ku jolóʼob u ofrenda yéetel ku k\'áat u beyo aj Ajq\'ij.
</p>
<p>
    U k\'iin ku jach k\'áajal tu ya\'al baketel k\'áat. Ku jach k\'áajal u k\'uchulil.
    Máak nacido tu k\'iin siliy kaj to\'on ku t\'aata\'amix tu óol mix k\'áansaj.
</p>
<p><strong>K\'uchul:</strong> Tz\'i <strong>Táan u bin:</strong> Keme
</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Aj defensolil nojoch ts\'íib.</li>
    <li> Nojoch puksi\'ik\'al, ajayuda\'an.</li>
    <li> Ku meyaj ma\' tojíinol.</li>
    <li> Puede ser ajq\'ij.</li>
    <li> Ajts\'aak tu tuunil.</li>
    <li> U káat chi\' le k\'uchuk óol.
</li></ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Jach k\'áaxal, jach púuts\' óol.</li>
    <li> U yáanal kaxan.</li>
    <li> Jach tímido tu púuts\'.</li>
    <li> Puede tornarse vengativo.
</li></ul>', '<p>
    <strong>Characteristics:</strong>
    It means stone and obsidian. It is the symbol of flint. It is the energy of the person who heals in Mayan culture.
    It is the power of thunder and lightning. The person born under the influence of this day can be a great healer or doctor with a lot of energy in their hands.
    It is ajq’íj, curing physical and psychological illnesses. It can fix bone fractures.
</p>
<p>
    One of the negative influences of the day is that it can cause some suffering or discomfort. According to the Ajq’ijab’, it is a day that "eats".
    To avoid being reached by these negative influences, some offering must be made and the intervention of the Spiritual Guide must be requested.
</p>
<p>
    It is a day that can prevent humiliation and ruin due to something or someone. It is a day of protection.
    Those born on this day can become choleric and can spiritually or emotionally destroy someone.
    Sometimes, nobody can stand them and it is difficult to understand them.
</p>
<p><strong>Origin:</strong> Tz\'i <strong>destination:</strong> Keme</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Is a protector of justice.</li>
    <li> Is strong and helpful.</li>
    <li> Is tireless in achieving what it wants.</li>
    <li> Can become a Spiritual Guide.</li>
    <li> Has the ability to fix bone fractures.</li>
    <li> Can defend themselves very well against any problem.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Can be violent and angry.</li>
    <li> Can suffer from illnesses.</li>
    <li> Can easily take offense.</li>
    <li> Can fall into revenge and quarrels.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    Rechajolilal u k\'ajol k\'u\' q\'ij rech chik\'al rechajolilal. Rechajolilal u k\'i\'wach k\'u\' ri uk\'ux\'aj. Rechajolilal u k\'i\'wach k\'u\' winaq k\'u\' xkik\'aj ch\'okajol rechajolilal rech maya.
    Rechajolilal u k\'at ri loq\' xk\'ut rechajolilal k\'u\' k\'at chak\'ul k\'u\' wuj. U winaq rechajolilal paq\' chik\'aj ri\'el rechajolilal q\'ij, xkik\'aj rech wuj ronojel k\'u\' rechajolilal.
    Rechajolilal u k\'i\'wach ri ajq’íj, chik\'aj ch\'okajol k\'u\' winaq k\'u\' winaq. Paq\'ol rech k\'ajol k\'u\' winaq xk\'ut rechajolilal k\'u\' jun.
</p>
<p>
    Ri\'el chik\'aj uwojel chik\'aj u rechajolilal ri\'el q\'ij k\'u\' chik\'ol k\'u\' paq\' k\'u\' winaq chik\'aj. Ri\'el u rechajolilal paq\'ajol k\'u\' u q\'ijilal "ch\'okajol".
    Chik\'aj q\'ijilal ri\'el rechajolilal paq\'ajolilal chik\'aj chik\'aj k\'u\' k\'o\'x k\'u\' ri Guía Espiritual.
</p>
<p>
    Chik\'aj jun q\'ij chik\'aj paq\'ajolilal ri\'el chik\'aj ri chik\'aj k\'u\' ri xk\'een k\'u\' ri q\'ij k\'u\' wuj. Chik\'aj jun rechajolilal paq\'ajol k\'u\' q\'ijilal k\'u\' xk\'een k\'u\' ri chik\'aj.
    Chik\'aj q\'ij k\'u\' rechajolilal q\'ij k\'u\' ri winaq k\'u\' k\'ut xk\'ut rechajolilal chik\'aj chik\'aj chik\'aj k\'u\' winaq.
    Chik\'aj winaq wuj le ajq’íj k\'u\' u chik\'aj chik\'aj chik\'aj winaq.
</p>
<p><strong>Jun K\'ab\'al:</strong> Tz\'i <strong>destino:</strong> Keme</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Rechajolilal uwojel chik\'aj ri\'el winaq ri chik\'ol.</li>
    <li> Rechajolilal uwojel k\'u\' ch\'okajol k\'u\' chik\'aj.</li>
    <li> Rechajolilal uwojel k\'u\' chak\'aj chik\'aj winaq k\'u\' winaq.</li>
    <li> Rechajolilal uwojel chik\'aj Guía Espiritual.</li>
    <li> Rechajolilal uwojel chik\'aj chik\'aj xk\'ut rechajolilal ri k\'at chak\'ul.</li>
    <li> Rechajolilal uwojel k\'u\' paq\'ajolilal chik\'aj chik\'aj xk\'ut k\'u\' chik\'aj q\'ij k\'u\' ri k\'i\'wach k\'u\' rechajolilal.</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Rechajolilal uwojel chik\'aj k\'u\' chak\'aj k\'u\' chik\'aj.</li>
    <li> Rechajolilal uwojel chik\'aj k\'u\' q\'ij chik\'aj.</li>
    <li> Rechajolilal uwojel chik\'aj k\'u\' chik\'aj k\'u\' ch\'okajol k\'u\' paq\'ajolilal.</li>
    <li> Rechajolilal uwojel chik\'aj k\'u\' xk\'een k\'u\' chik\'aj k\'u\' k\'ut k\'u\' q\'ijilal.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (4, 19, 'Kawoq', null, 'Trueno o dificultad', '<p>
    <strong>Características:</strong>
    Es el nawal de la mujer como comadrona. Es el día de la Vara Espiritual, le Pisom Q’aq’al. Es el relámpago.
    Es la dualidad del fuego sagrado en función de la espiritualidad maya. Es el día de la comunidad, de la familia, del grupo y de la sociedad.
    Es la energía que facilita las lluvias para darnos buenas cosechas, principalmente la del maíz.
  </p>
  <p>
    Proporciona capacidad y habilidad para curar y orientar. Es la energía que fortalece a las Guías Espirituales. Mantiene la energía y la fertilidad.
    Es un día de mucha relación con la Madre Tierra y los elementos al proveer sabiduría para el manejo de las plantas medicinales.
    Facilita la unidad y el cuidado de la familia. Es el día de la mujer como esposa y madre que calienta el seno del hogar.
    También es un día especial para la plena realización de la mujer en la comunidad y en la sociedad.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Día del terapeuta (el que arregla huesos) y de la comadrona.</li>
    <li> Uno de los días para tratar enfermedades.</li>
    <li> Día para invocar por la familia (hogar) y la comunidad.</li>
    <li> Uno de los días especiales para pedir lluvia.</li>
    <li> Día para invocar para que los niños y niñas al nacer no vengan con defectos físicos.</li>
  </ul>
  <p><strong>Su origen:</strong> B\'atz\' <strong>destino:</strong> Kej</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Es equilibrado y cariñoso.</li>
    <li> Vive y trabaja por su familia.</li>
    <li> Si es mujer, puede ser comadrona.</li>
    <li> Puede llegar a ser Guía Espiritual.</li>
    <li> Es buen comunicador y expositor.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede caer en el enojo.</li>
    <li> A veces es perseguido por los problemas y los pleitos.</li>
    <li> No es muy afortunado en el amor.</li>
    <li> Se le puede culpar de todo lo que pasa.</li>
    <li> Muy hablador.</li>
    <li> Se puede meter en donde no es llamado.</li>
  </ul>', 'Nahual_4', 'Es el Nawal de toda clase de pleitos, es el día de la mujer,  día para curar enfermedades.
Nawal de la piedra de cuarzo y de las semillas de Tz´ité.
Personas creativas, defensoras de la mujer.', 'src/imagenesNahuales/19.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ja ri nawal ri ixoq rik’in ri komadrona. Ja ri q’ij ri Q’atb’al Ch’ab’äl, le Pisom Q’aq’al. Ja ri ya’.
    Ja ri jun q’aq’al chi ri ch’ab’äl k’aslemal chi ruwi’ ri mayab’ k’aslemal. Ja ri q’ij ri winaqi’, ri k’aslemal, ri taq tzij ch’uqa’ ri ri kajay.
    Ja ri k’ulik xb’an chi kaq’ix ri ya’ chi k’amik jun nimal ch’ich’, xkajo’ ri q’aq’ ch’aqa’ ri saq’il.
</p>
<p>
    Xk’ul k’aslemal ri xb’an chi xtan ri q’aq’al. Ja ri k’ulik xb’an chi kik’ul chi Ajq’ijab’. Xkixri’ ri k’ulik xaq nim k’utal.
    Ja ri q’ij ri xb’an chi q’ix ri Jun Iximulew xaq ri b’an ch’umil xuk’ex chi xtan ri q’ul richin ri ru winaqi’.
    Ja ri k’ulik xb’an chi ajilan xaq k’amon ri kajay. Ja ri q’ij ri ixoq xa xi kajay xaq ri ixoq ri xkoy chi k’amon ri nuk.
    Xaq ri q’ij xa jun k’ulik chi jun ixoq chi k’amik pa ri k’aslemal xaq pa ri kajay.
</p>
<p>
    <strong>Ruwäch Ajaw:</strong>
</p>
<ul>
    <li> Ja ri q’ij ri terapeuta (ri xtan ri q’aq’) xaq ri komadrona.</li>
    <li> Jun taq q’ij chi xtan richin ri k’aslemal.</li>
    <li> Ja ri q’ij chi b’ixan richin ri kajay (nuq) xaq ri kajay.</li>
    <li> Jun taq q’ij xa ri xb’an chi xtz’i ri ya’ chi k’amik.</li>
    <li> Ja ri q’ij chi b’ixan chi man jun qach’ab’äl xikamisaj k’ut richin ya’ xik’am ri ixoq richin ch’atb’al.</li>
</ul>
<p><strong>Ruwäch:</strong> B\'atz\' <strong>ru tz’i’:</strong> Kej</p>
<p>
    <strong>Ruwäch K’otem:</strong>
</p>
<ul>
    <li> Ja ri q’ijil xaq k’amon.</li>
    <li> Xb’an xaq xq’aq’al ch’uqa’ ri kajay.</li>
    <li> Xa ri ixoq, xkoy richin komadrona.</li>
    <li> Xb’an ri Ajq’ij.</li>
    <li> K’o jun xkitzij xaq ruwäch ch’ab’äl.</li>
</ul>
<p>
    <strong>Ruwäch K’ul:</strong>
</p>
<ul>
    <li> Xkik’aq’ik.</li>
    <li> K’o ri xtz’ulo pa ri xtanik xaq xch’e’.</li>
    <li> Man xb’an chi q’ijil richin ruwäch k’aslemal.</li>
    <li> Xman jun chi xk’ol richin jun ch’ab’äl richin xk’ay.</li>
    <li> K’o jun xkitzij xaq xb’an chi xtz’i.</li>
    <li> Xkik’ul chi xb’an chi xtanik xib’iri xb’anol.</li>
</ul>
', '<p>
    <strong>U jats\'utsilo\'ob:</strong><br/>
    Nawal in xch\'úupal (partera). Ja\'aj u k\'iinil le bacab’ t’aan: Pisom Q’aq’al. Ku t’an u ya’.<br/>
    Dualidad le k\'a\'ak\' ichil Maya. K\'iinil x-ko\'olelo\'ob, familia yéetel kajil.
    Ku k\'al tech k\'áat áanalte\' jump\'éel k\'uxtalil ja’.
</p>
<p>
    Ku ts\'aaj u síijil yéetel u t\'aan a ajq\'ijobo\'ob. Ku janal u k\'áat u ts\'íibo\'ob ts\'aak.
    Ku jóok\'ol ti\' Máasewal Kaab yéetel le che\'oba\', ku ts\'íib u yóoltik aj ts\'aak pak\'al.
    Ku bejo\'l tu familia. U k\'iin le xch\'úupal tu báak’ yéetel in mejen k\'áajal súut.
</p>
<p>
    <strong>Toj óolal:</strong>
</p>
<ul>
    <li> K\'iinil ajts\'aak (aj tuntun) yéetel aj xch\'úupal.</li>
    <li> Jun tu\'uxilemil ts\'aak.</li>
    <li> K\'iinil k\'áat chi\' le kajil.</li>
    <li> K\'iinil k\'áat ja\'.</li>
    <li> K\'iin tu k\'a\'at u k\'áajtal chen ba\'alche\' máanen juntúul in mejen.
</li></ul>
<p><strong>K\'uchul:</strong> B\'atz\' <strong>Táan u bin:</strong> Kej
</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Balanceado yéetel áalik.</li>
    <li> Meyaj tu familia.</li>
    <li> Xch\'úupal → ajkomadrona.</li>
    <li> Puede ser ajq\'ij.</li>
    <li> Jach ajchan t\'aan.</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> U púuts\' óol ka pach\'il.</li>
    <li> Problemas siijik.</li>
    <li> Maʼatsil tu yaak\'el.</li>
    <li> Ix ku k\'ajad t’aan t’aan.</li>
    <li> Jach tu tsikbalo\'ob.</li>
    <li> Mejen mix báaxtik.
</li></ul>', '<p>
    <strong>Characteristics:</strong>
    It is the nawal of the woman as a midwife. It is the day of the Spiritual Staff, the Pisom Q’aq’al. It is the lightning.
    It is the duality of the sacred fire in function of Mayan spirituality. It is the day of the community, of the family, of the group, and of society.
    It is the energy that facilitates rains to give us good harvests, mainly that of corn.
</p>
<p>
    It provides the capacity and ability to heal and guide. It is the energy that strengthens the Spiritual Guides. It maintains energy and fertility.
    It is a day of much connection with Mother Earth and the elements by providing wisdom for the management of medicinal plants.
    It facilitates the unity and care of the family. It is the day of the woman as a wife and mother who warms the hearth of the home.
    It is also a special day for the full realization of women in the community and society.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Day of the therapist (the one who fixes bones) and the midwife.</li>
    <li> One of the days to treat illnesses.</li>
    <li> Day to invoke for the family (home) and the community.</li>
    <li> One of the special days to ask for rain.</li>
    <li> Day to invoke so that children born do not come with physical defects.</li>
</ul>
<p><strong>Origin:</strong> B\'atz\' <strong>destination:</strong> Kej</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Is balanced and affectionate.</li>
    <li> Lives and works for their family.</li>
    <li> If a woman, can be a midwife.</li>
    <li> Can become a Spiritual Guide.</li>
    <li> Is a good communicator and presenter.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Can fall into anger.</li>
    <li> Sometimes is pursued by problems and quarrels.</li>
    <li> Not very lucky in love.</li>
    <li> Can be blamed for everything that happens.</li>
    <li> Very talkative.</li>
    <li> Can interfere where not called.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    Rechajolilal u nawal k\'u\' ri k\'i\'wach k\'u\' xub\'an rech winaq k\'u\' xub\'an. Rechajolilal u q\'ij k\'u\' ri Q\'eq\'al rech Winaq, le Pisom Q’aq’al. Rechajolilal u ch\'uk rech k\'i\'wach.
    Rechajolilal u kechajajol rech k\'at ulew rech k\'i\'wach rechajolilal rech k\'u\'uq ri espiritualidad maya. Rechajolilal u q\'ij k\'u\' tinamit, k\'u\' rukama, k\'u\' ub\'ixik rech k\'u\'uq rech tinamit.
    Rechajolilal uwojel k\'u\' uwojel k\'u\' jun uwach k\'u\' paq\'ejolilal xk\'een rech winaq k\'u\' woj k\'ut chik\'iyal rech wuj winaq, k\'ut k\'u\' yich\' k\'i\' k\'u\' chik\' ch\'ip k\'u\' rech winaq.
</p>
<p>
    Rechajolilal paq\'ajolilal k\'u\' rechajolilal k\'u\' ch\'okajolilal rechajolilal k\'u\' ri Guías Espirituales. Rechajolilal uwojel k\'u\' ri wuj k\'u\' ri ki\'wach.
    Rechajolilal u k\'i\'wach rechajolilal k\'u\' tinamit k\'u\' rech xkik\'ajol rech u q\'ijilal ri chik\' le k\'aslemal uwe ri k\'ab\'ik ri chik k\'u\' paq\'ojolilal ri uwojel k\'u\' q\'ijilal.
    Rechajolilal k\'u\' ri rukama ri uq\'ij k\'u\' rech k\'i\'wach k\'u\' paq\'ajolilal uwojel k\'u\' rech k\'at rech k\'aslemal k\'u\' rech tinamit k\'u\' rech k\'u\'uq rech tinamit.
    Uwojel k\'u\' ri q\'ijilal k\'u\' ri winaq k\'u\' ri rech tinamit.
</p>
<p>
    <strong>Jun K\'ab\'al:</strong>
</p>
<ul>
    <li> Q\'ij rechajolilal paq\'ajolilal k\'u\' chak\'ol rech k\'ajol rech k\'ut ch\'utuj k\'u\' le xub\'an k\'u\' rech k\'ajol.</li>
    <li> Rechajolilal k\'u\' jun rech q\'ijilal paq\'ajolilal k\'u\' paq\'ajolilal.</li>
    <li> Q\'ij rechajolilal paq\'ajolilal paq\' k\'u\' ri ulej k\'u\' q\'ij k\'u\' le xub\'an.</li>
    <li> Rechajolilal k\'u\' jun rech q\'ijilal paq\'ajolilal k\'u\' k\'ut k\'u\' k\'ut rech wuj ch\'ip k\'u\' k\'ut k\'u\' winaq uwojel winaq k\'u\' k\'u\'uq.</li>
    <li> Q\'ij rechajolilal paq\'ajolilal paq\' k\'u\' rech xk\'een ri\'el k\'u\' rech q\'ijilal k\'u\' rech k\'i\'wach k\'u\' q\'ijilal.</li>
</ul>
<p><strong>Jun K\'ab\'al:</strong> B\'atz\' <strong>destino:</strong> Kej</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Rechajolilal uwojel k\'u\' k\'at chak\'ul k\'u\' chiq\'.</li>
    <li> Rechajolilal uwojel k\'u\' wuj paq\' ch\'okajol k\'u\' le xub\'an.</li>
    <li> Rechajolilal uwojel k\'u\' q\'ij k\'u\' xub\'an, xub\'an.</li>
    <li> Rechajolilal uwojel k\'u\' ri Guías Espirituales.</li>
    <li> Rechajolilal uwojel k\'u\' winaq ch\'ik ch\'okajol k\'u\' rech winaq ch\'ip k\'u\' le ch\'okajol k\'u\' ch
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (5, 20, 'Ajpu', null, 'Cerbatanero o señor principal', '<p>
    <strong>Características:</strong>
    Es la luz y es la representación del Abuelo Sol. Significa cerbatanero, cazador, tirador y caminante.
    Es el día de la fuerza corporal y del triunfo del bien sobre los obstáculos.
    Es la representación del triunfo de Jun Ajpu e Ixbalamke sobre los señores de Xib’alb’a. Esta señal le fue dada a la abuela Ixmukane
    cuando retoñó el cañaveral que sembraron los dos muchachos en el patio de la casa.
  </p>
  <p>
    Es el día del gran Ajaw, el padre y su representación solar, el día de la grandeza, de la fuerza de la vida.
    Es el que trae luz y claridad a los seres humanos y sobre toda la humanidad.
  </p>
  <p>
    Es la fuerza regenerativa, el ciclo de la vida. La facultad para tener a toda la galaxia.
    Rige los eclipses lunares y solares. Es el momento de servir a los demás.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Día para ofrendar a los abuelos y abuelas fallecidas.</li>
    <li> Día propicio para tratar enfermedades.</li>
    <li> Se pide la vida y la fuerza.</li>
    <li> Día para pedir el triunfo del bien sobre el mal.</li>
  </ul>
  <p><strong>Su origen:</strong> E <strong>destino:</strong> Q\'anil</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Puede desarrollar mejor la inteligencia.</li>
    <li> Puede tener dotes de artista.</li>
    <li> Es alegre.</li>
    <li> Se defiende muy bien.</li>
    <li> Puede llegar a ser Guía Espiritual.</li>
    <li> Es bueno para la cacería.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede caer en el enojo.</li>
    <li> Puede ser tajante.</li>
    <li> Es delicado.</li>
    <li> Puede enfermarse.</li>
    <li> Puede evadir responsabilidades.</li>
    <li> Le dificulta aceptar correcciones.</li>
    <li> Puede tener una actitud autosuficiencia.</li>
  </ul>', 'Nahual_5', 'Es el Nawal de sol, día para pedir sabiduría, talento y fortaleza física.
Nawal de las flores, la  música, el deporte,  los cazadores y la agricultura.
Personas líderes, selectivas, buscan primero su beneficio.', 'src/imagenesNahuales/20.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ja ri saqil xaq ri nawal Ajaw Q’ij. K’o ri tz’aq, achi’il, aq’anik xaq b’i.
    Ja ri q’ij ri k’ax chi ruwäch xaq ri b’isonel pa jun rik’in q’ax.
    Ja ri nawal ri b’isonel Jun Ajpu e Ixbalamke ch’aqa’ ri ajawaxel Xib’alb’a. Ja ri xb’an ri Ixmukane
    k’o jun q’aq’al xik’as ri xtz’aq’onik k’o jun achi k’o pa richin jay.
</p>
<p>
    Ja ri q’ij ri nima Ajaw, ri tata’ xaq ri nawal ri q’ij, ja ri q’ij ri nimaq’ij, ri q’ulik ri k’aslemal.
    Ja ri xb’an saqil xaq ch’o’ol pa jun winaq k’aslemal xaq pa ri nima winaq k’aslemal.
</p>
<p>
    Ja ri k’ax xb’an, ri q’ij chi k’aslemal. Ri nima’ k’ax xb’an chi k’o ri nimaq’ij pa jun q’aq’ b’ox.
    Ruwäch ajawaxel ch’ab’äl k’aslemal xaq ri saqil q’ij. Ja ri q’ij chi xtan ri jun winaq k’aslemal.
</p>
<p>
    <strong>Ruwäch Ajaw:</strong>
</p>
<ul>
    <li> Ja ri q’ij chi b’ixan chuchi qati’t qamama’ xb’in ri k’aslemal.</li>
    <li> Ja ri q’ij xb’an chi xtan richin ri k’aslemal.</li>
    <li> Xb’an chi b’ixan chi ruwäch xaq ri k’aslemal.</li>
    <li> Ja ri q’ij xb’an chi b’ixan chi b’isonel ch’aqa’ ri xa k’aslemal.</li>
</ul>
<p><strong>Ruwäch:</strong> E <strong>ru tz’i’:</strong> Q\'anil</p>
<p>
    <strong>Ruwäch K’otem:</strong>
</p>
<ul>
    <li> Xk’at jun nima’ k’ax ruwäch k’aslemal.</li>
    <li> Xk’at jun b’ixan ch’ab’äl.</li>
    <li> Xk’at jun k’ax k’aslemal.</li>
    <li> Xb’an xk’ax ruwäch k’aslemal.</li>
    <li> Xpe chi Ajq’ij.</li>
    <li> Xk’at jun b’ixan chi xaki’il.</li>
</ul>
<p>
    <strong>Ruwäch K’ul:</strong>
</p>
<ul>
    <li> Xkik’aq’ik.</li>
    <li> Xk’ax k’ul.</li>
    <li> Man xb’an chi q’aq’ k’aslemal.</li>
    <li> Xk’ax jun k’ax k’aslemal.</li>
    <li> Xkik’ul chi xb’an chi xaki’il k’aslemal.</li>
    <li> Xk’ax ri k’ax xb’in chi xb’an chi xtanim.</li>
    <li> Xkik’ax k’aslemal chi xb’an chi xtaxtanim.</li>
</ul>
', '<p>
    <strong>U jats\'utsilo\'ob:</strong><br/>
    Le sáastal yéetel representación le K\'inich Ajaw. Significa aj tóohil, aj jant\'aj.
    K\'iinil u sásik le ba\'ax k\'axan. Ku representaj le najilil Jun Ajpu yéetel Ixbalamke.
</p>
<p>
    K\'iinil nojoch Ajawil, le Táata Kaab, ch\'ok sáastalil k\'aax.
    Ku ts\'áaj sáastal yéetel ch\'áanal ba\'ax yéetel máasewalil.
</p>
<p>
    Ku tuukul le sáastal, ja\'aj u jaasik k\'uxtal. Yaan u p\'aaxil tu yaanil k\'inx.
</p>
<p>
    <strong>Toj óolal:</strong>
</p>
<ul>
    <li> K\'iinil tsikbalo\'ob le pixano\'ob.</li>
    <li> Uts u k\'iinil ts\'aak.</li>
    <li> Ku k\'áat jump\'éel nojoch k\'áajtal.</li>
    <li> K\'iinil u k\'áat chi\' tu sáastalil tu jump\'éel k\'ax.
</li></ul>
<p><strong>K\'uchul:</strong> E <strong>Táan u bin:</strong> Q\'anil
</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Máan tu na\'at.</li>
    <li> Habilidad artística.</li>
    <li> Aj su\'utuk.</li>
    <li> Defiende ba\'ax k\'ajáane\'.</li>
    <li> Puede ser ajq\'ij.</li>
    <li> Aj tóohil.
</li></ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Púuts\' óol.
    </li><li> Jach suuk\'ul.</li>
    <li> Tzok.
    </li><li> K\'aax.
    </li><li> Mix sáastal tu k\'uxaj.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    It is the light and the representation of Grandfather Sun. It means archer, hunter, shooter, and walker.
    It is the day of bodily strength and triumph of good over obstacles.
    It represents the triumph of Jun Ajpu and Ixbalamke over the lords of Xib’alb’a. This sign was given to grandmother Ixmukane
    when the cane field sprouted that the two boys planted in the courtyard of the house.
</p>
<p>
    It is the day of the great Ajaw, the father and his solar representation, the day of greatness, of the strength of life.
    It brings light and clarity to human beings and over all humanity.
</p>
<p>
    It is the regenerative force, the cycle of life. The faculty to have the entire galaxy.
    It governs lunar and solar eclipses. It is the moment to serve others.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Day to offer to deceased grandparents.</li>
    <li> Propitious day to treat illnesses.</li>
    <li> Life and strength are requested.</li>
    <li> Day to ask for the triumph of good over evil.</li>
</ul>
<p><strong>Origin:</strong> E <strong>destination:</strong> Q\'anil</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Can develop intelligence better.</li>
    <li> Can have artistic skills.</li>
    <li> Is joyful.</li>
    <li> Defends themselves very well.</li>
    <li> Can become a Spiritual Guide.</li>
    <li> Is good at hunting.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Can fall into anger.</li>
    <li> Can be blunt.</li>
    <li> Is delicate.</li>
    <li> Can get sick.</li>
    <li> Can evade responsibilities.</li>
    <li> Has difficulty accepting corrections.</li>
    <li> Can have a self-sufficient attitude.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    Rechajolilal k\'u\' rech\'ajolilal rech k\'i\'wach k\'u\' rech k\'ajol k\'u\' nawal Abuelo Sol. Q\'ij rechajolilal ri ch\'ak yaxb\' k\'u\' ri k\'u\'uq ta k\'u\' q\'ij rechajolilal.
    Rechajolilal u k\'at chak\'ul k\'u\' q\'ijilal rech winaq rech k\'i\'wach k\'u\' ri xaq\'ijilal rech k\'u\'uq k\'u\' ri k\'ajol rech winaq ri\'el.
    Rechajolilal u k\'at q\'ij rech k\'u\'uq chik\', k\'u\' k\'at q\'ijilal rech Jun Ajpu e Ixbalamke k\'u\' rech k\'at q\'ij rech Xib\'alb\'a. U k\'i\'wach k\'u\' uq\'ij rech k\'at chak\'ajolilal ri Ixmukane
    xkik\' k\'u\' ri\'el loq\' tinamit q\'ij rech xkik\'oj q\'ijel rech k\'u\'uq k\'u\' k\'o\'x rech winaq k\'u\' jun.
</p>
<p>
    Rechajolilal u k\'at q\'ij rech k\'u\'uq Ajaw, u k\'at chak\'ul k\'u\' ri q\'ijilal ch\'uti\' k\'u\' chak\'ul rech winaq.
    Rechajolilal u k\'at xkik\' k\'u\' chak\'ul k\'u\' winaq rechajolilal k\'u\' ri k\'u\'uq k\'u\' rech winaq k\'u\' u k\'at chak\'ul rech winaq.
</p>
<p>
    Rechajolilal u k\'at chak\'ul k\'u\' ri rechajolilal, ri ch\'aj rech k\'i\'wach. Ri wo\'k ri pa ri k\'i\'wach.
    Uwojel rechajolilal ri q\'ijilal ch\'uti\' k\'u\' ri q\'ijilal k\'at. Rechajolilal u k\'i\'wach k\'u\' rech winaq k\'u\' uwojel ri k\'i\'wach.
</p>
<p>
    <strong>Jun K\'ab\'al:</strong>
</p>
<ul>
    <li> Q\'ij rechajolilal paq\' chik rech xkik\'aj ri\'el k\'u\' xkik\'aj ch\'okajol k\'u\' k\'o\'x ri ronojel k\'u\' ri k\'ajol k\'u\' ronojel k\'u\' ronojel k\'u\' k\'o\'x rech winaq.</li>
    <li> Q\'ij rechajolilal k\'u\' k\'at paq\' chik k\'u\' q\'ij rech k\'i\'wach k\'u\' ch\'okajol k\'u\' xkik\'aj k\'u\' chikajolilal.</li>
    <li> Q\'ij rechajolilal k\'u\' paq\' chik k\'u\' ri q\'ijilal k\'u\' ri q\'ijilal k\'u\' k\'u\'uq rech winaq k\'u\' ri k\'at k\'u\' ri xkik\'aj.</li>
    <li> Q\'ij rechajolilal paq\' k\'u\' paq\'ajolilal k\'u\' ri k\'at q\'ijilal k\'u\' k\'u\'uq.</li>
</ul>
<p><strong>Jun K\'ab\'al:</strong> E <strong>destino:</strong> Q\'anil</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Uwojel rechajolilal ri\'el k\'u\' ri ch\'okajol k\'u\' q\'ijilal.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' paq\' k\'u\' ch\'okajol k\'u\' k\'at chak\'ul k\'u\' paq\'ajolilal.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' ch\'okajol k\'u\' q\'ijilal k\'u\' k\'at chak\'ul k\'u\' ri ch\'okajol.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' paq\' chik k\'u\' k\'at q\'ijilal k\'u\' wujq\'ajol.</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Uwojel rechajolilal ri\'el k\'u\' ri ch\'okajol k\'u\' wek\' k\'u\' q\'ijilal.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' paq\' chik k\'u\' ch\'okajol k\'u\' paq\'ajolilal.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' k\'at chak\'ul k\'u\' paq\' k\'u\' xkik\'ajolilal.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' paq\'ajolilal k\'u\' ch\'okajol k\'u\' k\'at chak\'ul.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' paq\'ajolilal k\'u\' ch\'okajol k\'u\' xkik\'ajolilal.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' paq\'ajolilal k\'u\' ch\'okajol k\'u\' ri k\'i\'wach k\'u\' paq\'ajolilal.</li>
    <li> Uwojel rechajolilal ri\'el k\'u\' paq\'ajolilal k\'u\' paq\'ajolilal k\'u\' xkik\'ajolilal.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (6, 1, 'Imox', null, 'Locura o pez', '  <p>
    <strong>Características:</strong>
    Símbolo de las fuerzas ocultas del universo manifestadas en demencia. “Imox” es el nombre de  todas las cosas secretas.
    En general, es un día de influencias negativas. Es un día peligroso. Es símbolo del hemisferio izquierdo, la parte sutil de los seres humanos,
    es la sensibilidad. Es la esencia de nuestra conciencia y de nuestra mente.
  </p>
  <p>
    Es el nawal o espíritu del agua. Genera movimiento pero, también, descontrol emocional. Es un día con influencias negativas
    y los que nacen en este día pueden convertirse en busca pleitos. Por eso, el día es propicio para las ceremonias de limpieza emocional.
  </p>
  <p>
    Significa idiotez y locura. Es un día especial para pedir la abundancia de agua. Día para invocar por los ríos y
    nacimientos de agua para que no se sequen. Su trabajo es ayudar al hemisferio derecho del cerebro a realizar un mejor trabajo y a tomar una buena actitud.
  </p>
  <p>
    Es el día de la perturbación mental o de la equivocación.  No es indicado para tomar decisiones. Es el día en que se puede implorar y limpiar
    las perturbaciones provocadas por el enemigo en todos los órdenes de la vida.
  </p>
  <p>
    <strong>Funcion Espiritual:</strong>
  </p>
  <ul>
    <li> Tratamiento de las perturbaciones mentales.</li>
    <li> Día especial para invocar por el agua.</li>
    <li> Invocaciones para mantener el equilibrio mental, espiritual, físico y emocional.</li>
  </ul>
  <p><strong>Su origen:</strong> Aj <strong>destino:</strong> Toj</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Puede desarrollar la clarividencia.</li>
    <li> Puede captar los mensajes y señales de la naturaleza.</li>
    <li> Puede desarrollar con mayor grado su hemisferio izquierdo.</li>
    <li> Puede tener buenas iniciativas.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Se le olvida con facilidad las cosas.</li>
    <li> Puede resultar muy inseguro.</li>
    <li> Puede tener reacciones violentas.</li>
    <li> Es ordenado en sus cosas.</li>
    <li> Puede tener un carácter variado.</li>
  </ul>', 'Nahual_6', 'Es el Nawal del mar, ríos y lagos, día para sanar enfermedades de la mente, para agradecer y pedir la lluvia, enfermedades de la mente. El Nawal de todos los lugares donde está el agua.
No es el concepto de locura que conocemos comúnmente,  es la capacidad de sentir lo que otros no sienten, por eso dicen que  hablan locuras.
', 'src/imagenesNahuales/1.jpg', '<p>
    <strong>Ruwäch:</strong>
    Xb’an ri ruwäch ri tzij q’aq’al pa ri xq’aq’al chi ruwäch. “Imox” ja ri b’i ri ronojel ri taq tzij ri k’aslemal.
    Jun rik’in, ja ri q’ij ri xq’aq’al chi ruwäch. Ja ri q’ij ri ri k’aslemal. Ja ri ruwäch ri q’aq’al xkip k’aslemal, ri xukub’al q’ij,
    ri k’ax pa q’ij. Ja ri nima’ k’aslemal ri ruwäch ri winaq xaq ri ch’ab’äl.
</p>
<p>
    Ja ri nawal o ch’ab’äl ri ya’. Xb’an chi ruchaq’aj xaq k’ax chi k’aslemal. Ja ri q’ij ri xq’aq’al chi ruwäch
    xaq ri ri xpe pa ri q’ij xak’ol ch’ab’äl. Rumal ja ri q’ij ri xb’an chi jun q’aq’ chi ch’ab’äl ruwäch ri k’aslemal.
</p>
<p>
    Xb’an ri xtzi’ ri k’aslemal. Ja ri q’ij chi b’ixan chi ya’. Q’ij chi xtan richin ya’
    xaq xukub’al chi jun q’aq’ chi jun ya’ xa keq chi xb’ano. Ruwäch xb’an chi xtan ri q’ax pa q’aq’ ri xti’ chi ruwäch xaq chi jun q’aq’ chi k’ax.
</p>
<p>
    Ja ri q’ij ri xb’ano jun winaq k’aslemal o ri xtz’aq’il. Man xpe pa q’ij chi b’ixan richin jun jun nim b’ixan. Ja ri q’ij xb’an chi xtz’i chi xb’ano
    ri xq’aq’al xb’an richin ri xq’aq’al ch’aqa’ ri taq q’ax pa ri k’aslemal.
</p>
<p>
    <strong>Ruwäch Ajaw:</strong>
</p>
<ul>
    <li> Xtanik richin xq’aq’al xb’an.</li>
    <li> Ja ri q’ij chi xtz’i richin ya’.</li>
    <li> Xtanik ri q’aq’ chi xb’an ruwäch k’aslemal, ch’ab’äl, k’aslemal xaq ri k’aslemal.</li>
</ul>
<p><strong>Ruwäch:</strong> Aj <strong>ru tz’i’:</strong> Toj</p>
<p>
    <strong>Ruwäch K’otem:</strong>
</p>
<ul>
    <li> Xk’at jun b’ixan k’ax xb’an chi xb’an.</li>
    <li> Xk’at jun ruwäch k’ax xaq xb’an xb’an ri xq’aq’al.</li>
    <li> Xk’at xb’an chi xq’aq’al xb’an chi ri k’aslemal xb’an.</li>
    <li> Xk’at jun xk’ay.</li>
</ul>
<p>
    <strong>Ruwäch K’ul:</strong>
</p>
<ul>
    <li> Xb’in xa jun q’ax xb’in jun tzij.</li>
    <li> Xb’an jun q’ax xb’in chi ruwäch.</li>
    <li> Xb’an xb’in jun ruwäch q’aq’al.</li>
    <li> Xb’an xb’in chi k’as xb’in jun xk’ay.</li>
    <li> Xb’an xb’in jun ruwäch xaq xb’in jun q’aq’al xb’an xb’in xb’an xb’in chi xb’an jun q’aq’al xb’an.</li>
</ul>
', '<p>
    <strong>U jats\'utsilo\'ob:</strong><br/>
    Símbolo le púuts\' ka k\'uch (imox). “Imox” u k\'aba\' to\'onil ba\'ax ts\'íib\'.
    Tu mayoría, u k\'iinil jach kaxan. Ja\'aj u nawal le ya’.
</p>
<p>
    Ku yilik jump\'éel imbalance emocional. Meyaj k\'iinil pa tza\'ak óol.
</p>
<p>
    Significa locura yėetel ne\'neel. U k\'iin tu k\'a\'at chi\' ja\'.
    K\'iinil ku k\'a\'at chi\' ba\'ax ya\' jats\'uts.
</p>
<p>
    U k\'iinil ba\'ax t’aaj óol. Ma\' wáaj uts jump\'éel nojoch ts\'aik tsol.
</p>
<p>
    <strong>Toj óolal:</strong>
</p>
<ul>
    <li> Ts\'aak tzaik óol.</li>
    <li> Tza\'ak u ya\'.</li>
    <li> Ku balansaj óol, pixan, puksi\'ik\'al, ba\'ak\'.
</li></ul>
<p><strong>K\'uchul:</strong> Aj <strong>Táan u bin:</strong> Toj
</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Ku tuukul/wa\'al.</li>
    <li> Ku u túukul yilik le natureza.</li>
    <li> Ku yaaj u izquierda hemisferio.</li>
    <li> Jach inwóol pa túumbenil tuukul.
</li></ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Ts\'ajtal inwóol.</li>
    <li> Inseguro.</li>
    <li> Aj púuts\'il.</li>
    <li> Desordenado.</li>
    <li> Carácter jump\'éel túumbenil.
</li></ul>', '<p>
    <strong>Characteristics:</strong>
    Symbol of the hidden forces of the universe manifested in madness. "Imox" is the name of all secret things.
    In general, it is a day of negative influences. It is a dangerous day. It is a symbol of the left hemisphere, the subtle part of human beings,
    it is sensitivity. It is the essence of our consciousness and our mind.
</p>
<p>
    It is the nawal or spirit of water. It generates movement but also emotional imbalance. It is a day with negative influences
    and those born on this day can become troublemakers. Therefore, the day is suitable for emotional cleansing ceremonies.
</p>
<p>
    It means idiocy and madness. It is a special day to ask for the abundance of water. A day to invoke for rivers and
    water sources so they do not dry up. Its work is to help the right hemisphere of the brain to do a better job and to adopt a good attitude.
</p>
<p>
    It is the day of mental disturbance or error. It is not suitable for making decisions. It is the day when one can implore and cleanse
    disturbances caused by the enemy in all aspects of life.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Treatment of mental disturbances.</li>
    <li> Special day to invoke for water.</li>
    <li> Invocations to maintain mental, spiritual, physical, and emotional balance.</li>
</ul>
<p><strong>Origin:</strong> Aj <strong>destination:</strong> Toj</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Can develop clairvoyance.</li>
    <li> Can perceive the messages and signals of nature.</li>
    <li> Can develop their left hemisphere to a greater degree.</li>
    <li> Can have good initiatives.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Forgets things easily.</li>
    <li> Can be very insecure.</li>
    <li> Can have violent reactions.</li>
    <li> Is orderly in their things.</li>
    <li> Can have a varied character.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    K\'i\'wach rech k\'ajol rech winaq paq\' le k\'i\'wach xch\'okajol k\'u\' q\'ijilal rech Imox. "Imox" k\'u\' le k\'i\'wach rech rech k\'i\'wach chak\'ajolilal.
    Rechajolilal, rechajolilal rechajolilal, ri q\'ij k\'u\' ri k\'i\'wach k\'u\' uq\'ij rech tinamit.
    Rechajolilal u nawal k\'u\' ruq\' rech ulej, rechajolilal k\'u\' ruq\'el ch\'uti\', uwojel rechajolilal rech ch\'uti\' rech winaq k\'u\' rech winaq.
</p>
<p>
    Rechajolilal k\'u\' Imox. Uwojel rechajolilal chak\'ajolilal pero k\'u\' q\'ij rechajolilal rech le uq\'ij rech winaq. Rechajolilal rechajolilal rechajolilal k\'u\' le k\'i\'wach q\'ijilal,
    k\'u\' rechajolilal rechajolilal. Uwojel rechajolilal k\'u\' ruq\' rech uch\'utij k\'u\' rech winaq k\'u\' uwojel ch\'uti\' rech k\'i\'wach.
</p>
<p>
    Rechajolilal u k\'ab\' k\'u\' ri rech k\'i\'wach paq\' k\'u\' winaq k\'u\' ri k\'i\'wach q\'ij k\'u\' le k\'i\'wach k\'u\' le k\'i\'wach k\'u\' k\'i\'wach k\'u\' q\'ij.
    Junajolilal k\'u\' k\'i\'wach paq\' k\'u\' ri riyoj k\'u\' ri chawal rech k\'i\'wach k\'u\' ri rech winaq k\'u\' uch\'utij.
</p>
<p>
    Rechajolilal k\'u\' u k\'at rech xkan ch\'okajolilal k\'u\' ri xk\'een k\'u\' k\'u\'x ri xk\'een k\'u\' le k\'i\'wach. Q\'ij rechajolilal paq\' k\'u\' jun k\'i\'wach k\'u\' le xkan ch\'okajolilal rech k\'i\'wach.
</p>
<p>
    <strong>Jun K\'ab\'al:</strong>
</p>
<ul>
    <li> Paq\' k\'u\' xkan ch\'okajolilal k\'u\' ri xkan ch\'okajol k\'u\' q\'ij k\'u\' rumal.</li>
    <li> Junajolilal k\'u\' paq\' ch\'okajol k\'u\' le k\'i\'wach.</li>
    <li> Q\'ij rechajolilal paq\' k\'u\' q\'ij rech k\'i\'wach, ch\'okajol, uq\'ij k\'u\' q\'ijilal k\'u\' rechajolilal k\'u\' xk\'een.</li>
</ul>
<p><strong>Jun K\'ab\'al:</strong> Aj <strong>destino:</strong> Toj</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Uwojel ri\'el k\'u\' ri chik ch\'okajolilal.</li>
    <li> Uwojel ri\'el k\'u\' ri k\'i\'wach k\'u\' rumal k\'u\' q\'ij k\'u\' rumal.</li>
    <li> Uwojel ri\'el k\'u\' ri chikajolilal ch\'okajol k\'u\' chikajol.</li>
    <li> Uwojel ri\'el k\'u\' ri k\'i\'wach k\'u\' wek\' chik.</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Xe\'el k\'u\' ri chik ch\'okajolilal uj.</li>
    <li> Uwojel ri\'el k\'u\' ri chikajolilal uj.</li>
    <li> Uwojel ri\'el k\'u\' ri xk\'een uj.</li>
    <li> Uwojel ri\'el k\'u\' ri chik ch\'okajolilal uj.</li>
    <li> Uwojel ri\'el k\'u\' ri xk\'een uj.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (7, 2, 'Iq\'', null, 'Viento o luna', '<p>
    <strong>Características:</strong>
    Es el viento y la vida. Es nawal de la lluvia. Es el día del Corazón del Cielo y Corazón de la Tierra. Es el aire y el soplo sagrado que da fuerza y vida.
    En este día se le pide al viento que se lleve los sufrimientos o las enfermedades de la persona.
  </p>
  <p>
    Significa aire y aliento de vida. También, es el nawal de Junraqan (Huracán) convertido en tornado. Es uno de los Cargadores del Tiempo.
    Es, también, la respiración de la persona. Es el soplo sagrado, suave y apacible purificador del cuerpo, de la mente, del espíritu y de las emociones.
    Es el espacio invisible existente entre la materia. Es uno de los elementos que produce los fenómenos naturales.
  </p>
  <p>
    El niño que nace en Iq’ es un niño que hace de todo pero no llega a nada. Es como el aire que toca y arrastra todo lo que encuentra en su camino.
    Puede construir pero también destruye.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Es día propicio para efectuar ceremonias al espíritu del aire o viento.</li>
    <li> Día para tratar enfermedades respiratorias, psicológicas y emocionales.</li>
    <li> Día de invocación para que el aire no destruya las siembras.</li>
  </ul>
  <p><strong>Su origen:</strong> I\'x <strong>destino:</strong> Tz\'i\'</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Puede adaptarse a cualquier situación.</li>
    <li> Posee fuerza física.</li>
    <li> Es soñador e imaginativo.</li>
    <li> Puede tener ideas futuristas.</li>
    <li> No asusta casi nada.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> De carácter muy fuerte.</li>
    <li> Puede resultar inseguro e impulsivo.</li>
    <li> Puede caer en la infidelidad con su pareja.</li>
    <li> Puede sufrir algunos problemas sociales y económicos.</li>
    <li> Le encanta decir directamente las cosas.</li>
  </ul>', 'Nahual_7', 'Es el Nawal del aire y la luna, del espíritu del ser humano. Día para alejar energías malas y enfermedades. Es el viento que limpia nuestra casa y nuestro cuerpo.
Personas nobles que se involucran en los problemas de otros fácilmente. Van y vienen de un lugar a otro, como el viento.', 'src/imagenesNahuales/2.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ja ri k’aslemal xaq ri ya’. Ja ri nawal ri ya’. Ja ri q’ij ri K’u’x K’aslemal xaq K’u’x ulew. Ja ri ya’ xaq ri q’aq’al k’aslemal ri k’ax xaq ri k’aslemal.
    Pa ri q’ij xb’an chi b’ixan ri ya’ xa keq chi xb’an ri raxik’ o ri k’ax ri jun winaq.
  </p>
  <p>
    Xb’an ri ya’ xaq ri q’aq’al k’aslemal. Xaq, ja ri nawal ri Junraqan (Huracán) ri xb’an chi q’aq’al. Ja ri K’aslemal q’ij.
    Xaq, ja ri k’aslemal ri winaq. Ja ri q’aq’al k’aslemal, xub’a’ xaq xub’a’ xb’an ruwäch ch’akulil, ri ch’ab’äl, ri k’aslemal xaq ri k’aslemal.
    Ja ri k’ul ri man xb’an xa k’aslemal pa ri q’aq’al. Ja ri K’aslemal xb’an chi ri k’aslemal k’aslemal ri ya’.
  </p>
  <p>
    Ri ak’wal ri xb’an chi Iq’ jun ak’wal ri xb’an xaq man xkiq’ax xb’an. Ja ri ya’ xb’an xaq xb’an chi xb’in chi xb’an ri k’aslemal k’aslemal.
    Xb’an chi xb’an xaq xb’an.
  </p>
  <p>
    <strong>Ruwäch Ajaw:</strong>
  </p>
  <ul>
    <li> Ja ri q’ij xb’an chi xtz’i ri ch’ab’äl ri ya’ o ya’.</li>
    <li> Ja ri q’ij xb’an chi xtanik chi k’aslemal k’aslemal, ch’ab’äl xaq k’aslemal.</li>
    <li> Ja ri q’ij chi xtz’i chi xb’an ri ya’ man xb’anol ri xb’an chi ri xtz’aq’on.</li>
  </ul>
  <p><strong>Ruwäch:</strong> I\'x <strong>ru tz’i’:</strong> Tz\'i\'</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> Xkik’ul chi k’aslemal k’aslemal.</li>
    <li> K’o jun k’ax xb’an.</li>
    <li> K’o jun k’ax xb’an chi ch’ab’äl xaq xb’anol.</li>
    <li> K’o jun ruwäch q’ij.</li>
    <li> Man xb’an jun q’ij k’aslemal.</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> Ri q’aq’al ri k’aslemal.</li>
    <li> K’o jun ri k’aslemal xaq q’aq’al.</li>
    <li> Xkik’ul chi xb’an chi xatb’al xaq k’ax.</li>
    <li> K’o jun k’aslemal xaq xb’an xb’in jun q’ij xb’an xaq k’aslemal xb’an.</li>
    <li> Xkik’ul chi xb’an xb’in jun q’ij xb’an xb’in xb’an.</li>
  </ul>
', '<p>
    <strong>U jats\'utsilo\'ob:</strong><br/>
    U ya’ yéetel u k\'áajtal. Nawal u ja’. K\'iinil K’u’x Kaab yéetel K’u’x Kaj. Ku páatal le ik’ yéetel u puksi\'ik\'al.
    Tu k\'iin ku k\'a\'at chi ja’ jats\'uts u k\'áajal le maako\'ob.
</p>
<p>
    Significa ik’ yéetel sáastal kuxtal. Nawal Jun Raqan (Huracán) tu tornado. Bey xan cargador túumbenil.
    Ku representaj u jíik’ le wíinkil. Le sáastal jump\'éel suuk\'ulil ku p\'áatal.
</p>
<p>
    In palal tu k\'iin Iq’ ku meyaj ba\'ax tsol máax uts. Bey le ik’ ku xkup’éel ba’ax.
</p>
<p>
    <strong>Toj óolal:</strong>
</p>
<ul>
    <li> Meyajil tu ja’.</li>
    <li> K\'iinil tza\'ak óol, pixan yéetel puksi\'ik\'al.</li>
    <li> K\'iinil k\'áat chi\' ik’ ma\' deroos le yaalba\'al.
</li></ul>
<p><strong>K\'uchul:</strong> I\'x <strong>Táan u bin:</strong> Tz\'i\'
</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Adaptable.</li>
    <li> Puksi\'ik\'al ch\'ujuk.</li>
    <li> Aj sueños, aj na’at futura.</li>
    <li> Jach kreativo.
</li></ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Taj óol fuerte.</li>
    <li> Inseguro yéetel impulsivo.</li>
    <li> Infidelidad.</li>
    <li> Problemas sociales.</li>
    <li> T\'aan directo.
</li></ul>', '<p>
    <strong>Characteristics:</strong>
    It is the wind and life. It is the nawal of rain. It is the day of the Heart of the Sky and Heart of the Earth. It is the air and the sacred breath that gives strength and life.
    On this day, the wind is asked to carry away the person\'s sufferings or illnesses.
</p>
<p>
    It means air and breath of life. It is also the nawal of Jun Raqan (Hurricane) turned into a tornado. It is one of the Time Carriers.
    It is also the person\'s breath. It is the sacred, gentle, and peaceful breath that purifies the body, mind, spirit, and emotions.
    It is the invisible space existing between matter. It is one of the elements that produces natural phenomena.
</p>
<p>
    The child born on Iq\' is a child who does everything but achieves nothing. It is like the air that touches and drags everything it finds in its path.
    It can build but also destroy.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> It is a favorable day for ceremonies to the spirit of air or wind.</li>
    <li> Day to treat respiratory, psychological, and emotional illnesses.</li>
    <li> Invocation day for the wind not to destroy the crops.</li>
</ul>
<p><strong>Origin:</strong> I\'x <strong>destination:</strong> Tz\'i\'</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Can adapt to any situation.</li>
    <li> Has physical strength.</li>
    <li> Is dreamy and imaginative.</li>
    <li> Can have futuristic ideas.</li>
    <li> Is hardly scared of anything.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Very strong-willed.</li>
    <li> Can be insecure and impulsive.</li>
    <li> Can fall into infidelity with their partner.</li>
    <li> May suffer some social and economic problems.</li>
    <li> Loves to speak directly.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    Rechajolilal u k\'ajol k\'u\' ronojel k\'u\' winaq. Rechajolilal u nawal ri xuwach k\'u\' winaq. Rechajolilal u k\'ab\' rech Corazón del Cielo k\'u\' Corazón de la Tierra. Rechajolilal u yax k\'u\' u ch\'ulel rech k\'u\' uchol rech ch\'ulel k\'u\' yax.
    Ri wek\' k\'u\' chakajol u k\'ajol k\'u\' u k\'i\'wach k\'u\' u k\'u\'uq rech winaq.
</p>
<p>
    Rechajolilal k\'u\' k\'ajol k\'u\' k\'at rech winaq. Junraqan (Huracán) rech ri nawal k\'u\' Tz\'i\' rech. Rechajolilal jun q\'o\'olal rech k\'aslemal rech uwojel.
    Rechajolilal k\'u\' u k\'ab\' rech k\'i\'wach k\'u\' u k\'ab\' rech k\'u\'uq rech winaq, rech k\'u\'uq k\'u\' ch\'ulel, rech k\'u\'uq k\'u\' k\'aslemal k\'u\' rech k\'u\'uq rech winaq.
    Rechajolilal k\'u\' k\'at k\'u\' winaq k\'u\' uwojel ri k\'u\'uq rech ronojel ri\'el, k\'u\'uq rech k\'u\'uq rech tinamit rech winaq.
</p>
<p>
    U q\'ij rech winaq k\'u\' ri k\'i\'wach ri nimaq k\'u\' ri k\'u\'uq ri k\'u\'uq. Rechajolilal k\'u\' ri k\'ab\' rech k\'i\'wach k\'u\' rech ruq\' rech winaq rech loq\'ij k\'u\' winaq.
    U k\'i\'wach k\'u\' ri k\'u\'uq k\'u\' rech k\'ab\' rech.
</p>
<p>
    <strong>Jun K\'ab\'al:</strong>
</p>
<ul>
    <li>U q\'ij rech propicia k\'u\' jun ruq\' rech k\'i\'wach k\'u\' winaq k\'u\' u nawal rech u k\'ajol k\'u\' winaq.</li>
    <li>Q\'ij rech ronojel ri k\'ab\' rech q\'ij k\'u\' tinamit, k\'u\' u k\'ab\' k\'u\' ronojel, k\'u\' ri k\'u\'uq rech loq\'ij.</li>
    <li>Q\'ij rech paq\'chij rech k\'u\' u nawal rech u q\'ij k\'u\' loq\'ij k\'u\' rech k\'i\'wach.</li>
</ul>
<p><strong>Jun K\'ab\'al:</strong> I\'x <strong>destino:</strong> Tz\'i\'</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li>U chik k\'u\' ri chak\'ab\' paq\' rech k\'u\' jun chiq\'.</li>
    <li>U chik k\'u\' rechajolilal k\'u\' tinamit.</li>
    <li>U k\'i\'wach k\'u\' u k\'u\'uq rech rechajolilal.</li>
    <li>U chik k\'u\' wek\' paq\' chik k\'u\' ri k\'i\'wach rech winaq.</li>
    <li>U k\'i\'wach k\'u\' ri k\'ab\' rech k\'i\'wach k\'u\' muk\'.</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li>U chik ri\'el k\'u\' ri q\'ij k\'u\' rumal.</li>
    <li>U chik k\'u\' chikajolilal k\'u\' ri k\'i\'wach k\'u\' rech q\'utuj.</li>
    <li>U k\'i\'wach k\'u\' paq\'ajolilal k\'u\' wi\'ijol k\'u\' xuch\'ijol ri ronojel k\'u\' q\'utuj.</li>
    <li>U k\'i\'wach k\'u\' paq\'ajolilal k\'u\' wi\'ijol k\'u\' tinamit k\'u\' wek\'.</li>
    <li>U chik k\'u\' rechajolilal ri riq\' ri k\'i\'wach.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (8, 3, 'Aq\'ab\'al', null, 'Amanecer, aurora y mano', '<p>
    <strong>Características:</strong>
    Es el símbolo de la mano y de la aurora formada por los primeros rayos del sol que se asoman sobre
    las montañas para disipar las tinieblas y la oscuridad de la noche.
  </p>
  <p>
    Significa amanecer, aurora, luz, claridad, nuevo día. Es la renovación de energía.
    Es la llegada de la luz, del crepúsculo, la luz que se asoma detrás de los cerros y montañas.
  </p>
  <p>
    Es el día del amanecer, del futuro promisorio que esperamos cada día, los mejores días para nuestro pueblo y para cada persona en particular.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Aclara los conocimientos.</li>
    <li> Aclara el camino de la vida.</li>
    <li> Conduce a nuevas oportunidades de la vida.</li>
    <li> Ilumina las cosas ocultas.</li>
    <li> Día para agradecer la creación del ser humano.</li>
  </ul>
  <p><strong>Su origen:</strong> Tz\'ikin <strong>destino:</strong> Batz\'</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Es madrugador, alegre y sereno.</li>
    <li> Puede tener buen carácter.</li>
    <li> Puede tener dotes para tratar enfermedades.</li>
    <li> Puede ser Guía Espiritual.</li>
    <li> Son fuertes, dinámicos y astutos.</li>
    <li> Puede tener seguridad mental y física.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> No es bien reconocido en su tierra.</li>
    <li> Puede encontrar el fracaso.</li>
    <li> Puede caer en la mentira y la traición.</li>
    <li> Puede tener dificultades en lo económico.</li>
    <li> Es un poco reservado y aislado.</li>
  </ul>', 'Nahual_8', 'Es el Nawal de la claridad, día para pedir que salga la luz en todas las cosas.
El día de las personas que componen los huesos de los enfermos y de los curanderos con plantas.
Personas que cumplen sus compromisos.
', 'src/imagenesNahuales/3.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ja ri ruwäch ri k’ab’ xaq ri q’aq’al xb’an ri q’aq’al q’ij ri xb’an ch’aqa’ ri q’axk’al taq jun ya’ xb’an xb’an
    k’aqa’ ri nima ri ri jun pa ruya’ pa jun k’aslemal chi xb’in xb’an ri juyub’ xaq ri k’aqa’ pa ri xqa’ kumatz pa q’iij pa.
  </p>
  <p>
    Xb’an ri k’aslemal, q’aq’al, k’aslemal, q’aq’al, q’aq’al jun q’ij. Ja ri xik’i ri k’aslemal.
    Ja ri xb’an ri k’aslemal, ri xk’axk’al ri q’aq’al, xb’an xb’an ri q’aq’al xb’an xb’an ri q’aq’al xb’an ri k’aqa’ ri ri xb’an.
  </p>
  <p>
    Ja ri q’ij ri xkaqan, ri q’ij ri xb’an k’aslemal pa xkan, jun xki k’aslemal xb’an, jun jun winaq pa jun jun.
  </p>
  <p>
    <strong>Ruwäch Ajaw:</strong>
  </p>
  <ul>
    <li> Xb’an ruwäch chi k’aslemal.</li>
    <li> Xb’an k’ax chi k’aslemal.</li>
    <li> Xb’an chi jun b’isonel ri q’aq’al ri k’aslemal.</li>
    <li> Xb’an chi k’ax pa taq tzij.</li>
    <li> Ja ri q’ij xb’an chi b’ixan chi k’aslemal xb’in ri q’aq’al xb’in ri b’isonel xb’an.</li>
  </ul>
  <p><strong>Ruwäch:</strong> Tz\'ikin <strong>ru tz’i’:</strong> Batz\'</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> Ja ri q’ijil, k’ax xaq ch’ab’äl.</li>
    <li> Xkik’ul chi k’aslemal.</li>
    <li> Xk’at jun b’ixan xb’an chi k’aslemal.</li>
    <li> Xpe chi Ajq’ij.</li>
    <li> Xb’an ri k’ax, jun nim xaq xb’an.</li>
    <li> Xk’at jun k’aslemal chi xb’an xb’an xaq xb’an xb’an.</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> Man xb’an xb’in xb’an chi ri ri b’in chi k’aslemal xb’an.</li>
    <li> Xb’an jun k’ax xb’an xb’an chi xb’an xb’an.</li>
    <li> Xkik’ul chi xb’an xb’in chi xk’ay xaq xb’an.</li>
    <li> K’o ri ruwäch q’ax xb’in xb’an xb’in chi xb’an xb’an.</li>
    <li> Man xb’an xb’in xb’an chi jun k’aslemal xb’an.</li>
  </ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    U náajil kʼàabʼ yéetel u jaʼatsʼlal kʼíin. Representa le lúum, le túukʼuloʼ yéetel le cheʼil. Joʼokol u kʼáakʼ tu chʼóchʼoʼ kʼíin; tsʼíib le “Aqʼabʼal” kuʼuchul ichil le maayaʼiloʼob bey juntúul luʼumtsʼíib.
</p>
<p>
    Táan u túukʼulil u beel u kʼáanat u yóokʼol kaabʼ. Mixbaʼal ku jantaj u tsʼíib le lúum tuʼux se keʼeloʼob hopel kʼíin. Le kʼáan yéetel le chʼíinbal ku kʼáat chiʼobaʼ Ajaw kʼu yóokʼol kʼiinil kaʼanalil tiʼ jumpʼéel jaʼatsʼilil.
</p>
<p>
    <strong>Takpʼakalilililil:</strong>
</p>
<ul>
    <li>Katsʼuk u puksiʼikʼaloʼob yéetel u óol.</li>
    <li>Jatsʼuts u kʼáatalil xíikin jaʼatsʼil.</li>
    <li>Katsʼuk u kʼuchulil tiʼ wáayiloʼob yéetel báalamiloʼob.</li>
    <li>Máax ku síijil tiʼ a kʼáabaʼloʼob yéetel u jaʼatsʼilil kʼuchul u yaalkʼaboʼ.</li>
    <li>Kʼáat u kaanantik bejlaʼeʼ u kʼuum kʼáat u kénsaj junpʼeekʼ maʼwaloʼob wíinik.</li>
</ul>
<p><strong>Jóokʼol:</strong> Keme   <strong>Ichil:</strong> Iqʼ</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Máaniktik, takpʼáal, tsʼíibtaʼan, kʼáankun, koʼoleloʼob.</li>
    <li>Túukulil chak, máakʼ tuchel yéetel ch´íʼibal jaatsʼ.</li>
    <li>Oox tu yóokʼol kaabʼ.</li>
    <li>Mixbaʼal ku súut kʼáat jumpʼéel kóokay tsol.</li>
    <li>Yaantal u yuumtak ku betik máaxoʼob tu beel.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    It is the symbol of the hand and of the dawn formed by the first rays of the sun that peek over
    the mountains to dispel the darkness of the night.
</p>
<p>
    It means dawn, sunrise, light, clarity, new day. It is the renewal of energy.
    It is the arrival of light, of twilight, the light that peeks behind the hills and mountains.
</p>
<p>
    It is the day of dawn, of the promising future that we await every day, the best days for our people and for each individual.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Clarifies knowledge.</li>
    <li> Clears the path of life.</li>
    <li> Leads to new opportunities in life.</li>
    <li> Illuminates hidden things.</li>
    <li> Day to thank for the creation of the human being.</li>
</ul>
<p><strong>Origin:</strong> Tz\'ikin <strong>destination:</strong> Batz\'</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Is an early riser, cheerful, and serene.</li>
    <li> Can have a good character.</li>
    <li> May have skills to treat illnesses.</li>
    <li> Can be a Spiritual Guide.</li>
    <li> They are strong, dynamic, and astute.</li>
    <li> Can have mental and physical security.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Not well recognized in their land.</li>
    <li> May encounter failure.</li>
    <li> May fall into lying and betrayal.</li>
    <li> May have economic difficulties.</li>
    <li> Can be somewhat reserved and isolated.</li>
</ul>
', '<p>
    <strong>Tz\'ikin:</strong>
    Wach k\'ab\'al rech loq\' u rejawik k\'u\' wi ajawilal rech ri q\'ij rech tijoxikilalil ja\' ronojel q\'ijilal ja\' ronojel k\'u\' wach tinajolilal.
</p>
<p>
    Rechajolilal rech uwojel k\'u\' wach, ajawilal, ruk\'ub\'al, chak\'ul, k\'in k\'at, ch\'orik\'. U rejawik k\'u\' loq\' k\'ab\' wach.
    Uwojel rech ri chak\'ul, k\'u\' xewinaq k\'u\' ronojel, k\'u\' rechajolilal k\'u\' muk\'ul rech wach.
</p>
<p>
    Ri k\'u\' k\'at chak\'ul, ja\' k\'ab\'ij k\'u\' uq\'ij rech ronojel uwojel rech, u sa\' jun wek\' pitzilal k\'u\' u sa\' wek\' pa rumal ri k\'u\' xewinaq k\'u\' ri k\'u\' kaqul.
</p>
<p>
    <strong>Jun K\'ab\'al:</strong>
</p>
<ul>
    <li>U k\'ab\'al rech che\'loq\'ajol.</li>
    <li>U k\'ab\'al rech k\'o\'xajol k\'u\' wach.</li>
    <li>U k\'ab\'al rech wachijol chak\'ul ri rechajol.</li>
    <li>U k\'ab\'al rech wi\'ijolilal ri k\'u\' tinamit ri winaq k\'u\' wek\'.</li>
    <li>U k\'ab\'al rech a\'lelok, wujq\'ajol k\'u\' q\'utuj.</li>
</ul>
<p>
    <strong>K\'ak\'aslemal:</strong>
</p>
<ul>
    <li>U chik ri\'el ri tinamit q\'ij k\'u\' jun.</li>
    <li>U k\'ab\'al rech loq\'ajol k\'u\' chak\'ul.</li>
    <li>U k\'ab\'al rech ri\'ijolilal k\'u\' uq\'ijol, k\'u\' wi\'ijol.</li>
    <li>U k\'ab\'al rech winaq k\'u\' loq\'ajol ja\' wek\'.</li>
    <li>U k\'ab\'al rech kaq\'ajol ja\' k\'o\'k\'ol k\'u\' ri\'o.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (9, 4, 'K\'at', null, 'Red, cautiverio o iguana', '<p>
    <strong>Características:</strong>
    Está relacionado con la palabra k’atik que significa arder. Símbolo del fuego y de la red. En el ritual se hace mención del día como
    tiempo para el enredo y el desenredo. Es el que enreda y desenreda la vida.
  </p>
  <p>
    Es la red donde se guarda la mazorca. La red con la que se pesca. La red donde mueren los peces. Significa cautiverio y ausencia de libertad.
    Signo de opresión que se ejerce sobre una comunidad.
  </p>
  <p>
    Es el trastecito o el bracero que le entregan a uno cuando recibe el Pisom Q’aq’al o la Vara Sagrada.
    Para los nacidos en K’at, en la espiritualidad maya, se les recomienda visitar al Ajq’ij cada veinte días para efectuar su ceremonia.
    De lo contrario, pueden tener muchos enredos en el camino, en el trabajo y en la vida.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Se puede pedir por la liberación de algún preso.</li>
    <li> Pedir porque el parto sea normal.</li>
    <li> Día del desenvolvimiento e investigación de la ciencia.</li>
    <li> Día para arreglar problemas emocionales y de amor.</li>
  </ul>
  <p><strong>Su origen:</strong> Ajmaq <strong>destino:</strong> E</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Persona sincera y ordenada.</li>
    <li> Puede ser líder.</li>
    <li> Puede ser una persona muy afortunada en lo económico.</li>
    <li> Puede ser Guía Espiritual.</li>
    <li> Persona muy activa y curiosa.</li>
    <li> Puede recordar las cosas facilidad.</li>
    <li> Puede ser muy tajante en su decisión.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede caer en los chismes y en el enojo.</li>
    <li> Puede resultar nervioso.</li>
    <li> Puede perder las cosas con facilidad.</li>
    <li> Puede estar propenso a malas influencias.</li>
    <li> Puede caer en el individualismo.</li>
    <li> Puede caer en el orgullo.</li>
    <li> Con tendencia a meterse en los problemas ajenos.</li>
  </ul>', 'Nahual_9', 'Es el Nawal de las cárceles visibles e invisibles. Es guardador.
Representa la red donde se guarda el  maíz y donde se atrapan los peces. Día para pedir por los que están presos, para enredar y desenredar las cosas.
Personas con mucho fuego en su ser.  Manejan energías positivas y negativas', 'src/imagenesNahuales/4.jpg', '<p>
    <strong>Ruwäch:</strong>
    Xb’an ri jun tzij chi k’ax pa q’ax ri xb’an. Ruwäch ri q’aq’al xaq ri ch’ol. Pa ri aj k’aslemal xb’an chi b’ixan jun q’ij ri k’aslemal
    pa jun k’ax xaq xk’ax ri ch’ol. Ja ri k’ax xaq xk’ax ri k’aslemal.
  </p>
  <p>
    Ja ri ch’ol chi xajo’ xb’an pa ri saq’il. Ri ch’ol xb’an pa q’ax. Ja ri ch’ol xb’an chi xb’ano ri ch’o’ol. Xb’an ri q’ax xaq jun k’ax chi k’ul.
    Ja ri ruwäch ri xb’an ch’aqa’ jun winaq k’aslemal.
  </p>
  <p>
    Ja ri ak’al o ri q’aq’al xb’an xb’in chi xb’an xb’in jun Pisom Q’aq’al o ri Vara Sagrada.
    Pa ri xpe pa K’at, pa ri k’aslemal mayab’, xb’an chi xb’ano chi jun Ajq’ij jun ruwäch chi jun ch’ab’äl.
    Man xb’an chi xb’ano xb’an k’ax chi xb’an chi xb’ano ri k’aslemal, jun k’ax xaq chi xb’ano.
  </p>
  <p>
    <strong>Ruwäch Ajaw:</strong>
  </p>
  <ul>
    <li> Xb’an chi b’ixan chi q’ax chi jun xb’ano.</li>
    <li> B’ixan chi xb’in ri xk’ay xb’in.</li>
    <li> Ja ri q’ij chi xtz’i ri k’aslemal xaq ri k’aslemal chi xb’ano.</li>
    <li> Ja ri q’ij chi xb’ano chi xajo’ xaq xk’ay.</li>
  </ul>
  <p><strong>Ruwäch:</strong> Ajmaq <strong>ru tz’i’:</strong> E</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> Ri winaq xb’an ri jun xb’an xb’in xaq xb’ano.</li>
    <li> Xpe chi jun aj q’ij.</li>
    <li> Xb’an chi jun winaq k’aslemal xb’an chi xb’ano.</li>
    <li> Xpe chi Ajq’ij.</li>
    <li> Xb’an jun winaq xaq xajo’ xb’in.</li>
    <li> Xb’an xb’in chi jun q’ax xb’in xb’ano.</li>
    <li> Xb’an xb’in chi jun k’ax ri xb’ano xb’in.</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> Xb’an chi jun q’ax xaq jun q’ax.</li>
    <li> Xb’an jun k’aslemal xb’in xaq k’aslemal.</li>
    <li> Xb’an xb’in chi jun k’aslemal xb’in chi xb’ano.</li>
    <li> Xb’an xb’in jun xb’ano xaq xb’an xb’ano xb’in.</li>
    <li> Xb’an xb’in xb’in chi xb’ano xb’in jun xb’an xb’in xb’an.</li>
    <li> Xb’an xb’in chi xb’ano xb’in chi xb’ano xb’in xb’ano xb’in chi xb’ano.</li>
  </ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    “Kʼàat” tu maayaʼ tʼàan túunil “kʼat” – lúub yéetel metsah. U síimboloʼ tiʼ kʼáakʼ yéetel u paach. Ichil le kʼaʼabal maaya’ ku jantaj bey jaatsʼil–antʼil máaxoʼob yéetel u beel ku kaanantik baʼax kʼat yéetel tsʼil.
</p>
<p>
    Le metsahil ku helmaj kʼáancheʼ, ku kachʼansik jóokʼol kʼaʼanal yéetel u jaʼatsʼilil tsʼíib. Baʼaleʼ mix uts yáanal u baah; maʼ inwáantaj u kʼáanalil a visitaj Ajqʼij tu letiʼ kʼiʼin tak pʼéel kʼiʼinil. Lay u beel k mix k-on a kʼat u puksiʼikʼal baʼax.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Kʼáat chiʼobaʼ u jáach tuláakal jumpeʼel preso.</li>
    <li>Kʼáat kʼáabalil kaansaj kushkabalil u almehen.</li>
    <li>Kʼaʼabalil k nuʼukulil túukul yéetel níibsaj naʼats.</li>
    <li>U kʼáat puksiʼikʼalil kʼáajtalil óol yéetel a síijil ichil mukʼaʼan tsol.</li>
</ul>
<p><strong>Jóokʼol:</strong> Ajmaq   <strong>Ichil:</strong> E</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Máakʼ jatsʼutsiloʼob, nukuch pʼéelil.</li>
    <li>Pʼáatal u beel.</li>
    <li>Pʼáaytak u pʼáastalil pʼektaj kʼáatchilil.</li>
    <li>U yáanalil tiʼ ajqʼij.</li>
    <li>Yaantal u báalamilil, inwáantajoʼob.</li>
    <li>Tsʼíib kʼáat u beel.</li>
    <li>Jach táan u túukul.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Chʼakbaloʼob, tsʼíibtuniloʼob.</li>
    <li>Méeyaʼan tu puksiʼikʼal.</li>
    <li>Perdioʼ yéetel báaxal kunáan tu béelil.</li>
    <li>Tálentik pʼeekʼ.</li>
    <li>Kax tsol tsol tu yóokʼol.</li>
    <li>Yaantal u naʼatsil.</li>
    <li>Chokoj baʼax maʼ uts taan u yaantal baʼax tu núuk.</li>
</ul>', '<p> <strong>Characteristics:</strong>
    It is related to the word k’atik which means to burn. Symbol of fire and of the net. In the ritual, the day is mentioned as
    a time for entanglement and disentanglement. It is the one who tangles and untangles life.
</p>
<p>
    It is the net where the corn is stored. The net used for fishing. The net where fish die. It signifies captivity and lack of freedom.
    Sign of oppression exercised over a community.
</p>
<p>
    It is the little bundle or the brazier that one is given when receiving the Pisom Q’aq’al or the Sacred Staff.
    For those born on K\'at, in Maya spirituality, it is recommended to visit the Ajq’ij every twenty days to perform their ceremony.
    Otherwise, they may encounter many entanglements in their path, work, and life.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> One can pray for the liberation of a prisoner.</li>
    <li> Pray for a normal childbirth.</li>
    <li> Day for the development and investigation of science.</li>
    <li> Day to address emotional and love problems.</li>
</ul>
<p><strong>Origin:</strong> Ajmaq <strong>destination:</strong> E</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Honest and orderly person.</li>
    <li> Can be a leader.</li>
    <li> Can be very fortunate economically.</li>
    <li> Can be a Spiritual Guide.</li>
    <li> Very active and curious person.</li>
    <li> Can easily remember things.</li>
    <li> Can be very decisive.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Can fall into gossip and anger.</li>
    <li> Can be nervous.</li>
    <li> Can easily lose things.</li>
    <li> Can be prone to bad influences.</li>
    <li> Can fall into individualism.</li>
    <li> Can fall into pride.</li>
    <li> Tends to meddle in other people\'s problems.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    K\'iche\': Ri chiri\'wi chi ri b\'i\' k\'ut k\'atik chi ri q\'ij. Kik\'aslemaj chi ri chik\'ajaj chi ri\' ch\'umil kik\'aslemaj. Ri q\'ij ri chik\'ajaj kik\'aslemaj chi ri chik\'ajaj kik\'aslemaj. Ri\' q\'ij kik\'aslemaj k\'u kik\'aslemaj ri b\'i\' k\'ut kik\'aslemaj.
  </p>
  <p>
    Ri k\'ut kik\'aslemaj chi ri q\'ij b\'i\' chak k\'u kik\'aslemaj. Ri k\'ut kik\'aslemaj chi ri chik\'ajaj kik\'aslemaj. Ri k\'ut kik\'aslemaj chi ri q\'ij chi ri chik\'ajaj kik\'aslemaj. Kik\'aslemaj chi ri q\'ij kik\'aslemaj chi ri b\'i\' k\'ut kik\'aslemaj.
    Q\'ij kik\'aslemaj chi ri k\'u ri k\'ut kik\'aslemaj. Kik\'aslemaj ri q\'ij chi ri chik\'ajaj kik\'aslemaj.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Kik\'aslemaj chi ri chik\'ajaj chi ri k\'u chik\'ajaj.</li>
    <li> Kik\'aslemaj b\'i\' b\'anoj kik\'aslemaj chi ri chik\'ajaj.</li>
    <li> B\'i\' chak kik\'aslemaj chi ri\' chik\'ajaj k\'u chi ri q\'ijilal.</li>
    <li> B\'i\' chak kik\'aslemaj chi ri chik\'ajaj kik\'aslemaj k\'u b\'i\' k\'utunlaj.</li>
  </ul>
  <p><strong>Su origen:</strong> Ajmaq <strong>destino:</strong> E</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Winaq nimla\' kik\'aslemaj chi ri ch\'uti\' xko\'jolom.</li>
    <li> B\'i\' kik\'aslemaj chi ri xk\'utunlaj.</li>
    <li> B\'i\' kik\'aslemaj chi ri b\'i\' k\'ut kik\'aslemaj.</li>
    <li> B\'i\' kik\'aslemaj chi ri k\'utunlaj k\'u Guía Espiritual.</li>
    <li> Winaq chik\'ajaj chi ri b\'i\' xk\'utunlaj kik\'aslemaj.</li>
    <li> B\'i\' kik\'aslemaj chi ri k\'utunlaj k\'u.</li>
    <li> B\'i\' kik\'aslemaj chi ri k\'utunlaj k\'u.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Kik\'aslemaj chi ri q\'ij k\'u ri k\'utunlaj, k\'u ri k\'utunlaj kik\'aslemaj.</li>
    <li> B\'i\' kik\'aslemaj chi ri q\'ij.</li>
    <li> Kik\'aslemaj chi ri xk\'utunlaj chi ri b\'i\' k\'ut kik\'aslemaj.</li>
    <li> B\'i\' kik\'aslemaj chi ri chik\'ajaj kik\'aslemaj k\'u.</li>
    <li> B\'i\' kik\'aslemaj chi ri b\'i\' k\'ut kik\'aslemaj.</li>
    <li> B\'i\' kik\'aslemaj chi ri b\'i\' k\'ut kik\'aslemaj.</li>
    <li> Kik\'aslemaj chi ri chik\'ajaj kik\'aslemaj chi ri k\'ut kik\'aslemaj.</li>
  </ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (10, 5, 'Kan', null, 'Serpiente emplumada', ' <p>
    <strong>Características:</strong>
    Significa movimiento, Es el símbolo de la Gran Energía que creó el Universo. Es la Serpiente Emplumada o Q’uq’umatz.
    Es la evaluación humana y el desarrollo espiritual. Es la Sabiduría y el ciclo del tiempo. Es guardián del bosque. Es el día de la transformación.
  </p>
  <p>
    significa justicia y equilibrio. Es un día muy fuerte y “enojado”. Es un día que puede traer malas influencias como el enojo y la riña.
    Sin embargo, es un símbolo de la verdad y es rápido e implacable cuando la justicia señala a alguien el lugar de los perdedores.
    La energía del día se presta para la solución de problemas.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Invocaciones por la igualdad y justicia.</li>
    <li> Día para desarrollar la fuerza física.</li>
    <li> Día para desarrollar el fuego interior y la evolución espiritual.</li>
    <li> Uno de los días para realizar invocaciones por la lluvia.</li>
    <li> Día para alejar el enojo, la timidez y el mal carácter.</li>
  </ul>
  <p><strong>Su origen:</strong> No\'j <strong>destino:</strong> Aj</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Persona con mucho conocimiento.</li>
    <li> Puede tener mucha habilidad para la intuición.</li>
    <li> Muy inteligente.</li>
    <li> Practica la sinceridad y la justicia.</li>
    <li> Puede llegar a ser líder.</li>
    <li> Puede tener habilidad para los pronósticos y la clarividencia.</li>
    <li> Puede ser Guía Espiritual.</li>
    <li> Es humilde.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede estar influenciado por el enojo y la traición.</li>
    <li> Puede caer en el resentimiento y la avaricia.</li>
    <li> Es desconfiado y sorpresivo.</li>
  </ul>', 'Nahual_10', 'Es el Nawal de la creación del hombre y la mujer. Es el dueño de todas las cosas materiales.  Día para pedir solución a toda clase de problemas y necesidades.
Personas con un alto sentido de la lealtad.', 'src/imagenesNahuales/5.jpg', '<p>
    <strong>Ruwäch:</strong>
    Xb’an chi q’ax chi xb’an. Ja ri ruwäch ri Nim K’ax k’aslemal xb’an chi ri El k’aslemal. Ja ri Q’uq’umatz ri q’aq’al ri xk’ax jun nima q’ij.
    Ja ri k’aslemal xaq xb’ano ch’ab’äl. Ja ri Ch’ab’äl xaq q’ij chi k’aslemal. Xaq k’amowik ri jay. Ja ri q’ij ri xb’an ri ruwäch k’aslemal.
</p>
<p>
    Xb’an chi k’as xaq k’a’. Ja ri q’ij ri k’ax xaq “xkik’aq’ik”. Ja ri q’ij xb’an chi xb’in ri q’aq’ k’aslemal xb’an chi xb’ano.
    Xq’aq’al chi xb’in xb’an ri xkik’aq’ik xaq xb’an chi xb’ano chi q’aq’al ri winaq.
    Ja ri ruwäch k’as xb’an chi xtijonem xb’an.
</p>
<p>
    <strong>Ruwäch Ajaw:</strong>
</p>
<ul>
    <li> Xb’an chi xtz’i ri k’a’ xaq k’as.</li>
    <li> Ja ri q’ij xb’an chi xb’ano k’ax ruwäch k’aslemal.</li>
    <li> Ja ri q’ij xb’an chi xb’ano q’aq’al xb’an xaq xb’ano ch’ab’äl.</li>
    <li> Jun taq q’ij xb’an chi xtz’i ri ya’.</li>
    <li> Ja ri q’ij xb’an chi xb’in ri xkik’aq’ik, xaq jun k’ax xb’in xb’an k’aslemal.</li>
</ul>
<p><strong>Ruwäch:</strong> No\'j <strong>ru tz’i’:</strong> Aj</p>
<p>
    <strong>Ruwäch K’otem:</strong>
</p>
<ul>
    <li> Ri winaq xb’an chi jun ruwäch k’aslemal.</li>
    <li> Xk’at ri ruwäch xb’an chi xb’ano.</li>
    <li> Ja ri winaq k’ax xb’an xb’in.</li>
    <li> Xb’an chi k’as xaq k’a’ k’aslemal.</li>
    <li> Xpe chi jun aj q’ij.</li>
    <li> Xb’an chi ri b’ixan xaq jun k’ax k’aslemal.</li>
    <li> Xpe chi Ajq’ij.</li>
    <li> Xb’an ri k’ax xaq xb’an xb’in.</li>
</ul>
<p>
    <strong>Ruwäch K’ul:</strong>
</p>
<ul>
    <li> Xb’an chi xb’ano chi xkik’aq’ik xaq xk’at xb’an.</li>
    <li> Xb’an chi xkik’aq’ik xaq xk’at xb’an.</li>
    <li> Ja ri winaq man xb’an xb’in xb’an chi xk’ay xaq xb’an.</li>
</ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    “Kan” taan u tʼaanil nojoch núuk; le Kʼukʼumáats’ – le Serpiente Emplumada. U jóokʼolil jun kʼáakʼil tiʼ tukʼul yéetel kʼáajalil. Síimboloʼil justicia yéetel equilibrio. Pa le kʼiʼin mix jach píib u beel; jach kaxan u yiichnan najil kaxan óol.
</p>
<p>
    Maan uts ken kaʼansik in wóol mix bʼáaxten; baʼaleʼ le najil justíciaʼ ku tsʼook u kaxan tu keʼel taanchaj yéetel tu tsʼíib yilaʼetal.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Tsolmayáanalil justiciaʼ yéetel iikʼnal.</li>
    <li>Kʼáat kʼajóoltaʼal puksiʼikʼalil kʼáakʼ.</li>
    <li>Kʼáat síijilil u kʼáakʼ tu yóokʼol óol yéetel kʼáajalil.</li>
    <li>Jun máaxilil tumen kén tsʼíik le jaʼatsʼil.</li>
    <li>Kʼáat páajtalil tsʼéen naj óol, chajoʼ yéetel kaxanchaj.</li>
</ul>
<p><strong>Jóokʼol:</strong> Noʼj   <strong>Ichil:</strong> Aj</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Máax tuʼux inwáantaj jach naj túukul.</li>
    <li>Túukul tuʼux yujtal u wíinklilal.</li>
    <li>Jach kʼáanantiloʼob.</li>
    <li>Tiach jalach óolilil justiciaʼ yéetel tzij.</li>
    <li>Tán u beelil juntúul meyajnoʼ.</li>
    <li>Yaantal u meyaj pʼeekʼ kʼáanantiloʼob.</li>
    <li>Potbil inwáantaj ajqʼij souʼtikin.</li>
    <li>Humildeʼ.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Joʼokʼolil kaxanchaj, bolon tiʼ.</li>
    <li>Mookʼolil kaxan óol yéetel wéensik.</li>
    <li>Yaan u kuxtalil nojoch kalkbaʼ, mix tuʼux béey.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    It means movement, the symbol of the Great Energy that created the Universe. It is the Plumed Serpent or Q’uq’umatz.
    It is human evaluation and spiritual development. It is Wisdom and the cycle of time. It is the guardian of the forest. It is the day of transformation.
</p>
<p>
    It signifies justice and balance. It is a very strong and "angry" day. It is a day that can bring bad influences like anger and quarrels.
    However, it is a symbol of truth and is quick and relentless when justice points someone to the losers\' place.
    The energy of the day lends itself to problem-solving.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Invocations for equality and justice.</li>
    <li> Day to develop physical strength.</li>
    <li> Day to develop inner fire and spiritual evolution.</li>
    <li> One of the days for invoking rain.</li>
    <li> Day to ward off anger, shyness, and bad temper.</li>
</ul>
<p><strong>Origin:</strong> No\'j <strong>destination:</strong> Aj</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Person with a lot of knowledge.</li>
    <li> Can have great intuition.</li>
    <li> Very intelligent.</li>
    <li> Practices sincerity and justice.</li>
    <li> Can become a leader.</li>
    <li> Can have abilities for forecasts and clairvoyance.</li>
    <li> Can be a Spiritual Guide.</li>
    <li> Humble.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Can be influenced by anger and betrayal.</li>
    <li> Can fall into resentment and greed.</li>
    <li> Distrustful and unpredictable.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    K\'iche\': Ri kik\'aslemaj kaj k\'utunlaj, K\'ajawil ri k\'utunlaj ri B\'anoj Enerjia b\'i\' ri ch\'umil ri Q\'ij. K\'ajawil ri k\'utunlaj ri K\'uk\'umatz. Ri chiri\'wi q\'ijilal chi ri ri winaq kik\'aslemaj chi ri\' xko\'jolom. Ri chiri\'wi Utzijaj ri q\'ijilal.
  </p>
  <p>
    Kik\'aslemaj chik\'ajaj chi ri k\'utunlaj chi ri xko\'jolom. Kik\'aslemaj chi ri b\'i\' k\'utunlaj k\'u kik\'aslemaj. Ri k\'utunlaj kik\'aslemaj chi ri\' q\'ijilal chi ri winaq kik\'aslemaj. Ri chiri\'wi ch\'umil chi ri\' chik\'ajaj.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Kik\'aslemaj chi ri q\'ijilal chi ri b\'i\' k\'utunlaj kik\'aslemaj.</li>
    <li> B\'i\' chak kik\'aslemaj chi ri q\'ijilal k\'utunlaj.</li>
    <li> B\'i\' chak kik\'aslemaj chi ri b\'i\' kik\'aslemaj k\'u evolución espiritual.</li>
    <li> B\'i\' chak k\'utunlaj kik\'aslemaj chi ri q\'ijilal k\'utunlaj.</li>
    <li> B\'i\' k\'utunlaj kik\'aslemaj chi ri xk\'utunlaj, ri\' q\'eqen, k\'u b\'i\' b\'anoj kik\'aslemaj.</li>
  </ul>
  <p><strong>Su origen:</strong> No\'j <strong>destino:</strong> Aj</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Ri winaq b\'i\' ch\'uti\' xko\'jolom.</li>
    <li> B\'i\' kik\'aslemaj chi ri q\'ijilal k\'utunlaj.</li>
    <li> K\'u b\'i\' winaq kik\'aslemaj k\'u.</li>
    <li> K\'ajawil ri b\'i\' kik\'aslemaj chi ri chik\'ajaj.</li>
    <li> Ri winaq b\'i\' kik\'aslemaj k\'u liderazgo.</li>
    <li> K\'u b\'i\' kik\'aslemaj chi ri q\'ijilal k\'utunlaj k\'u ri\' q\'eqen kik\'aslemaj.</li>
    <li> B\'i\' kik\'aslemaj k\'u Guía Espiritual.</li>
    <li> Chiri\'wi ch\'uti\' xko\'jolom.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Kik\'aslemaj chi ri xk\'utunlaj, ri k\'u b\'i\' k\'utunlaj.</li>
    <li> Kik\'aslemaj chi ri xk\'utunlaj, ri k\'u b\'i\' k\'utunlaj.</li>
    <li> Chiri\'wi ch\'uti\' k\'u b\'i\' kik\'aslemaj chi ri b\'i\' k\'utunlaj.</li>
  </ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (11, 6, 'Kame', null, 'Muerte o dueño de la oscuridad', '<p>
    <strong>Características:</strong>
    Es el símbolo de la muerte. Símbolo de la disolución final de todas las cosas, buenas y malas. Significa tecolote y muerte.
    Es el renacimiento. Significado que se expresa a través de los sagrados granos de Tz’ite’ o Palo de Pito. Es día propicio para
    pedir por la salud de los enfermos y para hacer ofrendas porque progrese el negocio.
  </p>
  <p>
    Es la energía de las personas que mueren de manera natural. Puede restar fuerza a una persona o fortalecerla. Pronostica lo bueno y lo malo.
    Es la comunicación con las abuelas y abuelos a través de las candelas de cebo que se ofrecen en las ceremonias.
    Prudencia y protección para evitar accidentes. Es el Juez Supremo de todas las cosas. Nawal de la enfermedad y de la muerte.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Es un día bueno para el negocio.</li>
    <li> Día especial para comunicarse con los ancestros.</li>
    <li> Fortalecimiento de la vida.</li>
    <li> Día para pedir protección en los viajes.</li>
    <li> Día para contrarrestar enfermedades.</li>
  </ul>
  <p><strong>Su origen:</strong> Tijax <strong>destino:</strong> I’x</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Puede ser médico.</li>
    <li> Es fuerte ante sus enemigos.</li>
    <li> Es inteligente, respetuoso y seguro.</li>
    <li> Puede controlarse.</li>
    <li> Puede desarrollar habilidades para la clarividencia.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede tener un temperamento fuerte.</li>
    <li> Propenso al suicidio.</li>
    <li> Puede sufrir mucho al no cumplir con sus obligaciones con la Madre Naturaleza.</li>
    <li> Puede tener tendencias a la mentira y a la infidelidad con su pareja.</li>
  </ul>', 'Nahual_11', 'Es el Nawal de toda clase de muertes, día para pedir que se aleje la muerte. Se pide el descanso y  paz de un moribundo. La Muerte no es mala,  es el complemento de la vida, el descanso.
Es el día para retirar energías negativas en las personas. Personas con habilidad para las artes y oficios.', 'src/imagenesNahuales/6.jpg', '<p>
    <strong>Ruwäch:</strong>
    Xb’an chi q’ax chi xb’an. Ja ri ruwäch ri Nim K’ax k’aslemal ri xb’an chi ri El k’aslemal. Ja ri Q’uq’umatz ri q’aq’al ri xk’ax jun nima q’ij.
    Ja ri k’aslemal xaq xb’ano ch’ab’äl. Ja ri Ch’ab’äl xaq jun q’ij chi k’aslemal. Xaq k’amowik ri jay. Ja ri q’ij ri ruwäch k’aslemal.
</p>
<p>
    Xb’an chi k’as xaq k’a’. Ja ri q’ij ri k’ax xaq “xkik’aq’ik”. Ja ri q’ij xb’an chi xb’in ri q’aq’ k’aslemal xb’an chi xb’ano.
    Xq’aq’al chi xb’in xb’an ri xkik’aq’ik xaq xb’an chi xb’ano chi q’aq’al ri winaq.
    Ja ri ruwäch k’as xb’an chi xtijonem xb’an.
</p>
<p>
    <strong>Ruwäch Ajaw:</strong>
</p>
<ul>
    <li> Xb’an chi xtz’i ri k’a’ xaq k’as.</li>
    <li> Ja ri q’ij xb’an chi xb’ano k’ax ruwäch k’aslemal.</li>
    <li> Ja ri q’ij xb’an chi xb’ano q’aq’al xb’an xaq xb’ano ch’ab’äl.</li>
    <li> Jun taq q’ij xb’an chi xtz’i ri ya’.</li>
    <li> Ja ri q’ij xb’an chi xb’in ri xkik’aq’ik, xaq jun k’ax xb’in xb’an k’aslemal.</li>
</ul>
<p><strong>Ruwäch:</strong> No\'j <strong>ru tz’i’:</strong> Aj</p>
<p>
    <strong>Ruwäch K’otem:</strong>
</p>
<ul>
    <li> Ri winaq xb’an chi jun ruwäch k’aslemal.</li>
    <li> Xk’at ri ruwäch xb’an chi xb’ano.</li>
    <li> Ja ri winaq k’ax xb’an xb’in.</li>
    <li> Xb’an chi k’as xaq k’a’ k’aslemal.</li>
    <li> Xpe chi jun aj q’ij.</li>
    <li> Xb’an chi ri b’ixan xaq jun k’ax k’aslemal.</li>
    <li> Xpe chi Ajq’ij.</li>
    <li> Xb’an ri k’ax xaq xb’an xb’in.</li>
</ul>
<p>
    <strong>Ruwäch K’ul:</strong>
</p>
<ul>
    <li> Xb’an chi xb’ano chi xkik’aq’ik xaq xk’at xb’an.</li>
    <li> Xb’an chi xkik’aq’ik xaq xk’at xb’an.</li>
    <li> Ja ri winaq man xb’an xb’in xb’an chi xk’ay xaq xb’an.</li>
</ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    Síimboloʼil kíimak. U toholilil jatsʼuts jumpʼéel púutsʼil: chukulil túumben yéetel jaatsʼilil. Mentaj “Chʼujuk”, kʼuxaj le nojoch bʼuʼuk\' tecolote. U beelil tsʼíib u kiʼimak ku kʼukʼul teʼ u tziitʼilil ichil le tʼzik.
</p>
<p>
    Le kʼuux tuukun u baah máaxoʼob ku kíimen bejlaʼeʼ. U jatsʼutsilil u kaajal ku sáastik óol máaxoʼob; ka ichʼ mak jumpʼéel káajal. Ku tʼaanaj ichil wóolilil le nojoch nojoch winikoʼob; yaantal u nikteʼaj ku tsʼíibtik tiʼ chʼujuk siʼipil.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Icham kaʼan tu buʼulo ob – buenilil negocioʼob.</li>
    <li>Kúuchilil tsol tsʼehchajuʼ yuumtsil.</li>
    <li>Kúuchilil suutsʼilil puksiʼikʼal.</li>
    <li>Kʼáat náajtalil baatsilil túumben jaatsʼilil.</li>
    <li>Kʼáat paakatililoʼob chʼíibaloʼob.</li>
</ul>
<p><strong>Jóokʼol:</strong> Tijax   <strong>Ichil:</strong> Iʼx</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Ajmen tsʼaak, kʼáankuntiʼ u wíinklilal.</li>
    <li>Jach kʼáanant u yáanalilil tu xíimbalil baax.</li>
    <li>Jiʼib, respetado, yáanal u báalamil óol.</li>
    <li>Máax ku kaansik baʼax.</li>
    <li>Yaantal u pʼeekʼ wíinikil clairvoyancia.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Jach kʼáankun u puksiʼikʼal.</li>
    <li>Jatsʼuts aaysh jaatsʼilil tu peep.</li>
    <li>Máax ku kʼaxsik u lúum kiʼimak mix keʼen a jantaj a puksiʼikʼal.</li>
    <li>Taʼakuntik tu tsʼáan u tsʼíibel xmaʼ u puksiʼikʼal tu máakoʼob.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    It is the symbol of death. Symbol of the final dissolution of all things, good and bad. It means owl and death.
    It is rebirth. Meaning expressed through the sacred grains of Tz’ite’ or Palo de Pito. It is a favorable day
    to ask for the health of the sick and to make offerings for the progress of business.
</p>
<p>
    It is the energy of people who die naturally. It can take away strength from a person or strengthen it. It predicts the good and the bad.
    It is communication with grandparents through the tallow candles offered in ceremonies.
    Prudence and protection to avoid accidents. It is the Supreme Judge of all things. Nawal of disease and death.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> It is a good day for business.</li>
    <li> Special day to communicate with ancestors.</li>
    <li> Strengthening of life.</li>
    <li> Day to ask for protection in travels.</li>
    <li> Day to counteract diseases.</li>
</ul>
<p><strong>Origin:</strong> Tijax <strong>destination:</strong> I’x</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Can be a healer.</li>
    <li> Strong against enemies.</li>
    <li> Intelligent, respectful, and confident.</li>
    <li> Can control oneself.</li>
    <li> Can develop abilities for clairvoyance.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> May have a strong temperament.</li>
    <li> Prone to suicide.</li>
    <li> Can suffer greatly by not fulfilling obligations to Mother Nature.</li>
    <li> May have tendencies towards lying and infidelity to their partner.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    K\'iche\': K\'ajawil kik\'aslemaj ri k\'ut. K\'ajawil kik\'aslemaj ri b\'i\' chak\'at, xka\' chak\'at. K\'ajawil kik\'aslemaj chi ri b\'anoj k\'utunlaj chik ri\' chik\'ajaj k\'utunlaj, xka\' chik ri\' b\'anoj k\'utunlaj.
  </p>
  <p>
    Chik\'ajaj kik\'aslemaj chi ri xk\'utunlaj chi k\'ut kik\'aslemaj. Xk\'utunlaj kik\'aslemaj chi ri k\'utunlaj chak k\'utunlaj chiri\'wi. K\'utunlaj ri chik\'ajaj chi ri b\'i\' k\'utunlaj, xk\'utunlaj chi ri q\'ijilal k\'utunlaj. K\'ajawil kik\'aslemaj chi ri k\'ut k\'utunlaj chi ri b\'anoj k\'utunlaj. Xk\'utunlaj ri chiri\'wi kik\'aslemaj.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Xk\'utunlaj chik\'ajaj chi ri b\'i\' k\'utunlaj.</li>
    <li> B\'i\' xk\'utunlaj kik\'aslemaj chi ri k\'utunlaj.</li>
    <li> Chak k\'utunlaj kik\'aslemaj chi ri k\'ut k\'utunlaj.</li>
    <li> Xk\'utunlaj chi ri b\'i\' kik\'aslemaj chi ri k\'utunlaj.</li>
    <li> Xk\'utunlaj chi ri b\'i\' kik\'aslemaj chi ri chik\'aslemaj.</li>
  </ul>
  <p><strong>Su origen:</strong> Tijax <strong>destino:</strong> I’x</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Xk\'utunlaj chi ri k\'ut.</li>
    <li> Nimla\' ri b\'i\' k\'utunlaj.</li>
    <li> Ajchaj chik\'ajaj k\'utunlaj.</li>
    <li> Xk\'utunlaj chi ri chak.</li>
    <li> Nimla\' ajk\'in kik\'aslemaj chi ri k\'utunlaj.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Nimla\' kik\'aslemaj chi ri k\'utunlaj.</li>
    <li> Xk\'utunlaj chi ri k\'ut.</li>
    <li> Kik\'aslemaj chi ri chak.</li>
    <li> Xk\'utunlaj chi ri k\'ut.</li>
  </ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (12, 7, 'Kej', null, 'Venado', '<p>
    <strong>Características:</strong>
    El nawal del Kej es muy masculino y si una mujer nace en este día, tiene el carácter y voz fuertes y es de alguna manera varonil.
  </p>
  <p>
    Simboliza venado, los cuatro sostenes, los cuatro pilares, es decir los cuatro puntos cardinales.
    Es el día fuerte y bueno.  Es un día que aplasta.   Es un día que demuestra su fuerza y su poder.
  </p>
  <p>
    Los que nacen en este día:  son de carácter fuerte y poseen fortaleza física.  Son buenos defensores de otras personas,
    pero no pueden defenderse a sí mismos.  pueden ser ricos y poseer muchos bienes. generalmente gozan de buena salud pues no se enferman con facilidad.
  </p>
  <p>
    Son los cuatro puntos cardinales que sostienen el mundo; sostiene  la vida del hombre.  Los que nacen en este día son caminantes y tienen  suerte en el negocio.
  </p>
  <p>
    Es el día en que se pide fuerza, fortalecimiento, endurecimiento, para que uno sea duro, aguantador en caso de enfermedades, golpes, críticas,
    que uno aguante lo duro de la vida. Los que nacen en Kej podrían ser buenos guías espirituales mayas.
  </p>
  <p>
    <strong>Significado:</strong>
  </p>
  <ul>
    <li> La cruz maya.</li>
    <li> Los cuatro puntos cardinales.</li>
    <li> Los cuatro sostenes de la tierra.</li>
    <li> Nawal de los defensores.</li>
    <li> Los cuatro colores de las energías.</li>
    <li> Caballo, fuerza, aguantador.</li>
  </ul>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Buenos defensores</li>
    <li> Poseen riquezas</li>
    <li> Gozan de buena salud</li>
    <li> Son buenos guías espirituales</li>
    <li> Son muy sociables</li>
    <li> Son fuertes, inteligentes, responsables, positivos y triunfadores.</li>
    <li> En el matrimonio son muy equilibrados</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede hacer el mal con su pensamiento</li>
    <li> Tiene un carácter fuerte</li>
    <li> Pueden ser muy compulsivos</li>
    <li> Les gusta la popularidad y el poder</li>
    <li> Podrían ser autocráticos, manipuladores etc.</li>
    <li> Les gusta la comodidad</li>
    <li> Son muy reservados</li>
    <li> Autoritarios</li>
    <li> Suelen ser exigentes</li>
    <li> Les gusta hundir y aplastar a las personas.</li>
    <li> Podrían ser necios</li>
  </ul>', 'Nahual_12', 'Es el nawal de toda clase de animales cuadrúpedos. Día para pedir fuerza para cargar con nuestras penas.
Nawal de las cuatro esquinas del mundo.
Día de los Ajqíjab´ o sacerdotes mayas.
Personas líderes, dominantes con su pareja, les gusta la fama.', 'src/imagenesNahuales/7.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ri nawal ri Kej k’o jun ruwäch ri achi\' ch’uqa\', k’o jun ixoq xpe chi ri q’ij, k’o ri k’a\' ri ri achi\' k’ax xaq jun ruwäch ri achi\'.
  </p>
  <p>
    Xb’an ri kej, ri kaj ch’ab’al, ri kaj ch’akulil, k’o jun ri kaj ch’akulil.
    Ja ri q’ij ri k’ax xaq k’otem. Ja ri q’ij ri xkojik k’ax. Ja ri q’ij ri xkojik ri k’ax xaq ri k’aslemal.
  </p>
  <p>
    Ri xpe chi ri q’ij: k’o jun k’ax ri xkax xaq xb’an chi jun ruwäch k’aslemal. K’o jun ch’akulil ri xb’an chi jun winaq,
    rumal man xb’an chi xb’ano pa jun k’ax. xb’an jun ruwäch k’ax xaq xb’an jun taq k’aslemal. Ronojel xkik’ulik jun k’ax ri man xb’anol k’ax chi jun k’aslemal.
  </p>
  <p>
    Ri kaj ch’akulil xb’an chi xb’ano ri q’ij; xb’an chi k’as ri winaq. Ri xpe chi ri q’ij k’ax xaq xb’an jun ruwäch xb’in ri q’ij.
  </p>
  <p>
    Ja ri q’ij xb’an chi k’as chi jun ruwäch, xb’an chi ruwäch k’aslemal, xb’an chi ruwäch k’aslemal, rumal ja ri xb’an chi xb’ano, xkik’ulik jun ri xb’in xb’an chi k’as, xb’an chi xb’an jun ruwäch k’aslemal. Ri xpe chi Kej jun ri xb’an chi Ajq’ij pa ri k’aslemal mayab’.
  </p>
  <p>
    <strong>Ruwäch:</strong>
  </p>
  <ul>
    <li> Ri Cruz Maya.</li>
    <li> Ri kaj ch’akulil.</li>
    <li> Ri kaj ch’ab’al ri q’aq’al.</li>
    <li> Nawal ri ajq’ij.</li>
    <li> Ri kaj saqil chi k’aslemal.</li>
    <li> Ri q’aq’al, k’ax, ri aj.</li>
  </ul>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> K’o jun ajq’ij</li>
    <li> K’o jun ruwäch k’aslemal</li>
    <li> K’ik’ulik chi k’as</li>
    <li> K’o jun ajq’ij</li>
    <li> Xkik’ulik chi jun ajq’ij</li>
    <li> K’ax, k’aslemal, ajq’ij, ajq’ij xaq ajq’ij.</li>
    <li> Pa ri achi\' k’o jun k’a’ k’aslemal</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> K’ax k’ax ri k’ax xb’an chi xb’an</li>
    <li> K’o jun k’ax xb’an</li>
    <li> Xk’ax xb’an</li>
    <li> K’o jun xb’an chi k’as xb’an xb’an</li>
    <li> K’o jun k’as xb’an xb’an</li>
    <li> K’o jun xb’an xb’in xb’an xb’an chi xb’an xb’an xb’an.</li>
    <li> K’o jun xb’an xb’in chi xb’an xb’in xb’an xb’an xb’an.</li>
    <li> K’o jun xb’an xb’in xb’an xb’an xb’an xb’an.</li>
    <li> K’o jun xb’an xb’in xb’an xb’an xb’in xb’an xb’in xb’an xb’an xb’in xb’an.</li>
    <li> K’o jun xb’an xb’in xb’an xb’in xb’an xb’in xb’an xb’in xb’an.</li>
    <li> K’o jun xb’an xb’in xb’an xb’in xb’in xb’an xb’in.</li>
  </ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    “Kej” u nawal le nuxiʼ, síimboloʼil chan píʼisiin chʼabʼal – le kajtalil kʼéetel le kajaʼanal. Máaxoʼob kúuchilil le kʼiʼin jach kʼáankun; siʼijil u puksiʼikʼalil tu meyaj. Jach sáamalilil kʼáanal u kʼáajtal, mix kʼíin xakáaj.
</p>
<p>
    Le keej’ob ku sìisaj le kóokay: le kan tuunich, cheʼ, ja yéetel lúum  le cuatro báalamilil joʼojol. Táan u xikin yéetel u kúuchilil.
</p>
<p>
    Máaxoʼob tu kʼiʼin “Kej” ku kʼáat bejlaʼeʼ kʼáanalilil, juntúul kʼáancheʼlen máan u tsol – baʼax máax káajkunsaj baʼax yáanal. Icham yáantik u ajmejen tsʼíib.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Le kúuchilil pilas yéetel jach kʼáanant.</li>
    <li>Yaantal u táanilil túumben tsʼáak.</li>
    <li>Meyajon u máan táanilil balam ku chʼakmah bolon bejlae.</li>
    <li>Ku tsʼáajtik puksiʼikʼal ichil kaxanchaj.</li>
    <li>Meyajnoʼob ichil kʼáatchilil kaajal.</li>
</ul>
<p><strong>Tsol maaya:</strong> Chʼaik kʼeʼex – le kúuchilil jóokʼol.</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Ajkʼach wíinklilil.</li>
    <li>Yaantal u tsʼaaikpajalilil.</li>
    <li>Jach takpʼáal, naj túukul, kinsikbal, wíil.</li>
    <li>Túukulilil balanceado ichil nup.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Yaantal u túukulilil xpaʼak u jeʼel.</li>
    <li>Jach kʼáankun u puksiʼikʼal.</li>
    <li>Jach bolon tiʼ puksiʼikʼalil maayaʼ.</li>
    <li>Ch íibtik kajaʼanal.</li>
    <li>Kúunsaj jach xaʼak.</li>
    <li>U kúuchililil óol autoritario.</li>
    <li>Kúuchililil kʼáat tʼaan u maayaʼiʼl.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    The nawal of Kej is very masculine, and if a woman is born on this day, she has a strong character and voice and is somewhat masculine in some way.
</p>
<p>
    It symbolizes the deer, the four supports, the four pillars, that is, the four cardinal points.
    It is a strong and good day. It is a day that crushes. It is a day that demonstrates its strength and power.
</p>
<p>
    Those born on this day: they have strong character and physical strength. They are good defenders of others,
    but they cannot defend themselves. They may be rich and possess many belongings. They generally enjoy good health as they do not get sick easily.
</p>
<p>
    They are the four cardinal points that support the world; they sustain the life of man. Those born on this day are walkers and have luck in business.
</p>
<p>
    It is the day when strength, fortification, hardening are asked for, so that one can be tough, enduring in case of illnesses, blows, criticisms,
    enduring the hardness of life. Those born in Kej could be good Maya spiritual guides.
</p>
<p>
    <strong>Meaning:</strong>
</p>
<ul>
    <li> The Mayan cross.</li>
    <li> The four cardinal points.</li>
    <li> The four supports of the earth.</li>
    <li> Nawal of defenders.</li>
    <li> The four colors of energies.</li>
    <li> Horse, strength, enduring.</li>
</ul>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Good defenders</li>
    <li> Possess wealth</li>
    <li> Enjoy good health</li>
    <li> They are good spiritual guides</li>
    <li> They are very sociable</li>
    <li> They are strong, intelligent, responsible, positive, and triumphant.</li>
    <li> They are very balanced in marriage</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Can do evil with their thoughts</li>
    <li> Have a strong character</li>
    <li> Can be very compulsive</li>
    <li> They like popularity and power</li>
    <li> They could be autocratic, manipulative, etc.</li>
    <li> They like comfort</li>
    <li> They are very reserved</li>
    <li> Authoritarian</li>
    <li> They tend to be demanding</li>
    <li> They like to sink and crush people.</li>
    <li> They could be stubborn</li>
</ul>
', '<p>
    <strong>Características:</strong>
    Ri nawal Kej kaj b\'anoj ruwi\' k\'ub\'anoj chi ri k\'ut, chi ri winaq k\'ut. K\'ajolom chiri\'wi xk\'utunlaj ri chiri\'wi chiri\'wi chiri\'wi chiri\'wi chiri\'wi chiri\'wi kik\'aslemaj chik ri k\'ut kik\'aslemaj, xk\'utunlaj chi chiri\'wi xk\'utunlaj.
  </p>
  <p>
    Ri k\'ub\'anoj kik\'aslemaj xko\'jolom b\'i\' k\'ut, ri meyajilal xko\'jolom xch\'uti\' xk\'utunlaj, ri meyajilal xko\'jolom xwaj xa\'ib\', ri meyajilal xko\'jolom xamaj.
    Chi ri kik\'in ta chakaj, ri kik\'in ta chiri\'wi chakaj. Chi ri kik\'in ta xko\'jolom rutz\'ijajal, ri kik\'in ta xko\'jolom b\'i\' xko\'jolom. Chi ri kik\'in ta ri k\'ut kik\'aslemajal b\'i\' xk\'utunlaj xko\'jolom kik\'aslemajal.
  </p>
  <p>
    Ri kik\'in ta xko\'jolom ri chiri\'wi k\'ut kik\'aslemaj: chakaj ri b\'i\' chiri\'wi kik\'aslemaj, chiri\'wi ri q\'ijilal kik\'aslemaj. Kaj ri winaq chiri\'wi k\'utunlaj kik\'aslemaj chik ri winaq chiri\'wi kik\'aslemaj chi\' b\'i\' xk\'utunlaj chiri\'wi kik\'aslemaj.
  </p>
  <p>
    Ri kik\'in ta chi ri b\'i\' xk\'utunlaj kik\'aslemajal: kik\'aslemajal ri k\'ut chik ri kik\'in ta, kik\'aslemajal ri k\'ut chiri\'wi kik\'aslemaj. Kaj ri kik\'in ta chiri\'wi kik\'aslemaj chi ri b\'i\' xk\'utunlaj.
  </p>
  <p>
    <strong>Significado:</strong>
  </p>
  <ul>
    <li> La cruz maya.</li>
    <li> Ri chiri\'wi chiri\'wi xk\'utunlaj.</li>
    <li> Ri chiri\'wi xk\'utunlajal chiri\'wi xk\'utunlajal.</li>
    <li> Nawal chi ri k\'ut chak b\'i\' kik\'aslemaj.</li>
    <li> Ri chiri\'wi meyajilal chiri\'wi.</li>
    <li> Winaq, k\'utunlaj, kaj k\'utunlaj.</li>
  </ul>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Ajchaj chiri\'wi kik\'aslemaj</li>
    <li> Nimla\' re b\'i\' k\'utunlaj kik\'aslemaj</li>
    <li> Nimla\' ri chak k\'ub\'anoj chiri\'wi kik\'aslemaj</li>
    <li> Ajchaj kik\'aslemajal ri chiri\'wi chupamaj k\'ub\'anoj</li>
    <li> Nimla\' ajk\'in chiri\'wi</li>
    <li> Nimla\' ajk\'in, ajawal, chi\'kaj, ri\'chak, tajri\'.</li>
    <li> Chi ri winaq k\'utunlaj kik\'aslemaj b\'i\' chiri\'wi chupamaj</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> K\'utunlaj kik\'aslemajal chi ri b\'i\' kik\'aslemaj</li>
    <li> Nimla\' kik\'aslemajal ri chak k\'ub\'anoj chiri\'wi kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemaj ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemaj ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemaj ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
  </ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (13, 8, 'Q\'anil', null, 'Semilla, simiente o conejo', '<p>
    <strong>Características:</strong>
    Este es un día propicio para las rogativas que se hacen con relación al maíz y para darle gracias a la divinidad de la tierra, por la cosecha de maíz.
  </p>
  <p>
    Es el nawal de las cosechas. El que nace en este día es buen agricultor. Hay que buscar este tanto para la siembra como para la cosecha del maíz.
  </p>
  <p>
    Simboliza los cuatro colores del maíz existentes en Meso América: rojo, negro, blanco y amarillo. Los cuatro colores de la piel de la humanidad.
    Los cuatro puntos cardinales del universo. En este día se pide buena cosecha. Es el día del agricultor.
  </p>
  <p>
    <strong>Significado:</strong>
  </p>
  <ul>
    <li> Nawal de la semilla.</li>
    <li> germinación de todos los seres vivientes.</li>
    <li> Día de la construcción de los primeros abuelos del maíz.</li>
  </ul>
  <p><strong>Día de:</strong> La Fecundación y de La Germinación.</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Afortunados en las siembras o crianza de animales</li>
    <li> Muy fértiles en tener hijos</li>
    <li> Son buenos comerciantes</li>
    <li> suelen tener Signos de intensa energía en su cuerpo</li>
    <li> Extremadamente inteligentes</li>
    <li> Les gusta hablar, debatir, leer, escribir</li>
    <li> Aficionados al ejercicio físico o la danza</li>
    <li> Mente compleja</li>
    <li> Se interesan de detalles</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Padecen de dolor de cabeza, resfriados</li>
    <li> Podrían destruir su propio hogar</li>
    <li> Incrédulos</li>
    <li> Creen en su imaginación</li>
    <li> Regularmente son nerviosos</li>
    <li> Pueden ser cobardes</li>
    <li> Autodestructivos</li>
    <li> Evitan las grandes  responsabilidades</li>
    <li> Propensos a adquirir vicios relacionados con estimulantes</li>
    <li> Muy agresivos, enojados</li>
    <li> A veces son obsesivos, compulsivos</li>
    <li> Llegan a donde no son llamados</li>
    <li> Orgullosos</li>
    <li> Suelen ser egoístas</li>
  </ul>', 'Nahual_13', 'Significa semilla, simiente,  conejo. El planeta Venus.
Es el Nawal de toda clase de semillas animales y vegetales. Día de la fertilidad y las cosechas,  propicio para iniciar cualquier siembra o negocio.
Significa los cuatro colores del maíz,  rojo, negro, blanco y amarillo.
Personas de mano ¨caliente¨ a quienes todo lo que siembran les florece.', 'src/imagenesNahuales/8.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ja ri q’ij ri xb’an chi b’ixan chi jun b’ix ri xa xb’an richin ri saq’il ri xb’an richin ya’, ch’aqa’ jun q’aq’al xa k’ax xa xb’an ri saq’il.
  </p>
  <p>
    Ja ri nawal ri q’aq’al. Ri xpe chi ri q’ij jun aj q’aq’al ri k’ax. K’o jun k’ax ri q’aq’al chi saq’il chi xa b’ix chi saq’il chi k’ax.
  </p>
  <p>
    Xb’an ri kaj ch’ol ri q’aq’al ri xb’an chi ri Mesoamérica: k’aq, q’eq, saq’ xaq q’an. Ri kaj ch’ol ri xk’ay ri xb’an chi ri winaq.
    Ri kaj ch’ol ri El k’aslemal. Pa ri q’ij xb’an chi jun q’aq’al k’ax. Ja ri q’ij ri aj q’aq’al.
  </p>
  <p>
    <strong>Ruwäch:</strong>
  </p>
  <ul>
    <li> Nawal ri saq’il.</li>
    <li> Xikik’ ri ronojel ri k’aslemal.</li>
    <li> Ja ri q’ij ri xb’an chi k’ax chi qati’t qamama’ ri jun q’aq’al.</li>
  </ul>
  <p><strong>Q’ij ri:</strong> Ri Fecundación y ri Xikik’.</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> K’otem pa ri saq’il o chi jun q’aq’al chi winaq</li>
    <li> K’ax pa jun ri xb’in winaq</li>
    <li> Aj q’ax chi winaq</li>
    <li> K’o jun ri k’ax xb’in xb’in chi ruwäch k’aslemal</li>
    <li> K’ax k’aslemal xb’in</li>
    <li> K’ax xb’in, xb’ano, ch’ab’äl, tzij, ri k’aslemal</li>
    <li> Xk’at jun xb’in chi q’aq’al xaq ri xikot</li>
    <li> Jun k’as ch’aq</li>
    <li> K’ul ri ch’ij</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> K’ax chi q’ax chi xpan ri q’ax</li>
    <li> K’ax chi xb’in ri chi xki</li>
    <li> Xkik’ pa xb’ano</li>
    <li> Xkik’ pa ri k’ax xb’in</li>
    <li> Ronojel xkik’ik</li>
    <li> K’o ri xkojik k’ax</li>
    <li> Xkik’ik xb’in</li>
    <li> K’o ri jun k’ax chi xq’aq’al</li>
    <li> K’ax chi k’ax xaq xb’ano</li>
    <li> K’ax k’ax xb’in</li>
    <li> K’o ri xb’in xb’in xb’ano xb’in chi xb’ano chi xb’ano xb’in chi xb’ano</li>
    <li> K’ax k’ax xb’in xb’an xb’in</li>
    <li> Man xb’in xb’in xb’an xb’an xb’in xb’an xb’in xb’an xb’in xb’an xb’in</li>
  </ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    Leloʼ u nawalilil kʼan, u síimboloʼil semilla yéetel k’ajóoltaʼal. Iikʼ tu yóokʼol le náajtal kʼaanal kaʼaj tushkaʼal le cuatro báalamilil kʼan, sak, boox yéetel chak ixiʼim. Ichil le bejlaʼeʼ píib kʼáat u jáatsʼ u meyaj – ja le qʼanil ku jantaj juntúul naj máakoʼ.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Nawalilil semilla.</li>
    <li>Sujetlilil taanilil tuláakal kuxtal.</li>
    <li>Kʼáat kʼáatchil kʼajóoltaʼal: uts jumpʼéel bej chi baach.</li>
</ul>
<p><strong>Kʼíinil:</strong> Fecundación yéetel Germinación</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Meyajnoʼob yéetel jóokʼol kʼáach chak kaajal.</li>
    <li>Jach yámil kaaj máaloʼob kuxtaloʼob ichil in will.</li>
    <li>Ajmísitaʼanoʼob.</li>
    <li>Yaantal u chaambalilil jumpʼéel kʼáax óol.</li>
    <li>Jach kʼáanantun túukul.</li>
    <li>Yaantal u tsʼíibtalil, kʼáat tsol kʼaabaʼ.</li>
    <li>Ajkʼáansamal ichil jatsʼutsililil.</li>
    <li>Túukulilil inwáantaj nojoch.</li>
    <li>Naʼatsiloʼob.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Koxol, xanej, tsʼutsʼ.</li>
    <li>Tsʼéeloʼob kaxankaboʼ.ʼ</li>
    <li>Tsʼáaj u beelil káajtalil.</li>
    <li>Maʼ tu puksiʼik\'al inwáantaj.</li>
    <li>Táankum tsol kaxanqu.</li>
    <li>Tsʼíibtunkiʼikʼ máan.</li>
    <li>Chokoj óol, pʼaach óol.</li>
</ul>', '<p>
    <strong>Characteristics:</strong> This is a favorable day for petitions related to corn and for giving thanks to the earth divinity for the corn harvest.
</p>
<p>
    It is the nawal of harvests. Those born on this day are good farmers. It is essential for both planting and harvesting corn.
</p>
<p>
    Symbolizes the four colors of corn existing in Mesoamerica: red, black, white, and yellow. The four colors of human skin. The four cardinal points of the universe. On this day, a good harvest is requested. It is the day of the farmer.
</p>
<p>
    <strong>Meaning:</strong>
</p>
<ul>
    <li> Nawal of the seed.</li>
    <li> Germination of all living beings.</li>
    <li> Day of the construction of the first grandparents of corn.</li>
</ul>
<p><strong>Day of:</strong> Fertilization and Germination.</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Fortunate in farming or animal husbandry</li>
    <li> Very fertile in having children</li>
    <li> Good traders</li>
    <li> Often have signs of intense energy in their bodies</li>
    <li> Extremely intelligent</li>
    <li> Enjoy speaking, debating, reading, writing</li>
    <li> Fond of physical exercise or dance</li>
    <li> Complex mind</li>
    <li> Interested in details</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Suffer from headaches, colds</li>
    <li> They could destroy their own home</li>
    <li> Skeptical</li>
    <li> Believe in their imagination</li>
    <li> Regularly nervous</li>
    <li> Can be cowardly</li>
    <li> Self-destructive</li>
    <li> Avoid major responsibilities</li>
    <li> Prone to acquiring stimulant-related vices</li>
    <li> Very aggressive, angry</li>
    <li> Sometimes obsessive, compulsive</li>
    <li> Go where they are not called</li>
    <li> Proud</li>
    <li> Tend to be selfish</li>
</ul>
', '<p>
    <strong>Características:</strong>
    Ri kik\'in ta jun winaq chik\'ama\' b\'i\' xk\'utunlaj kik\'aslemaj ri k\'iche\', chi\' chiri\'wi chiri\'wi chiri\'wi chiri\'wi kik\'aslemaj chi ri\' k\'otz\'ijaj kik\'aslemaj b\'i\' jun ri b\'i\' xk\'utunlaj chiri\'wi k\'otz\'ijaj kik\'aslemaj.
  </p>
  <p>
    Kik\'in ta jun nawal chi ri k\'otz\'ijaj kik\'aslemaj. Chiri\'wi kik\'aslemajal ri winaq q\'ijilal chiri\'wi kik\'aslemaj. Chiri\'wi k\'utuj chi ri k\'otz\'ijaj kik\'aslemaj chi\' ri b\'i\' xk\'utunlaj chiri\'wi kik\'aslemaj.
  </p>
  <p>
    Ri kik\'aslemaj k\'ub\'anoj ri meyajilal chi ri b\'i\' xk\'utunlaj kik\'aslemaj b\'i\' meso América: xik\'ojolom, tzutzuk, ch\'uti\' chiri\'wi. Ri meyajilal b\'i\' chiri\'wi kik\'aslemaj chi ri winaq k\'iche\'. Ri meyajilal k\'ub\'anoj ri\' xk\'utunlaj. Chi kik\'in ta chi ri b\'i\' xk\'utunlaj kik\'aslemaj chiri\'wi kik\'aslemaj.
  </p>
  <p>
    <strong>Significado:</strong>
  </p>
  <ul>
    <li> Nawal chi ri b\'i\' semilla.</li>
    <li> Chiri\'wi q\'ijilal chi jun chiri\'wi k\'utuk k\'utuj winaq.</li>
    <li> Winaq chi ri winaq chak b\'i\' q\'ijilal k\'utuk chiri\'wi kik\'aslemaj.</li>
  </ul>
  <p><strong>Día de:</strong> La Fecundación y de La Germinación.</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Ajchaj chi ri chakaj chi ri chiri\'wi chik\'ama\' chupamaj</li>
    <li> Nimla\' re b\'i\' k\'utunlaj chik\'ama\' ch\'uti\' xk\'utunlaj</li>
    <li> Nimla\' ri chak k\'ub\'anoj chiri\'wi kik\'aslemajal ri chiri\'wi</li>
    <li> Ajchaj kaj kik\'aslemajal ri k\'utuk k\'utuj kik\'aslemaj ri\' xk\'utunlaj</li>
    <li> Nimla\' ajk\'in</li>
    <li> Nimla\' kik\'aslemaj ri q\'ijilal, chupamaj, q\'atb\'anoj, chweq\', k\'utunlaj</li>
    <li> Ajchaj ajk\'in chik ri\' chi ri winaq k\'utunlaj</li>
    <li> Q\'atb\'anoj chik ri b\'i\' k\'utunlaj</li>
    <li> Chiri\'wi b\'anoj kik\'aslemajal ri chiri\'wi chupamaj chi kik\'aslemajal ri xk\'utunlaj</li>
    <li> Ajchaj ri kik\'aslemaj chi\' ri b\'i\' kik\'aslemaj k\'utunlaj</li>
    <li> Nimla\' xk\'utunlaj, b\'i\' k\'utunlaj</li>
    <li> Chiri\'wi b\'anoj chik ri winaq ch\'uti\' b\'i\' chiri\'wi k\'utunlaj</li>
    <li> Q\'atb\'anoj kik\'aslemajal ri chiri\'wi chupamaj chiri\'wi k\'utunlaj</li>
    <li> Nimla\' ri chak k\'ub\'anoj chik ri winaq ch\'uti\' b\'i\' k\'utunlaj</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> K\'utunlaj chi ri b\'i\' kik\'aslemaj, k\'utunlaj chi ri q\'ijilal</li>
    <li> K\'utunlaj kik\'aslemaj ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
  </ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (14, 9, 'Toj', null, 'Ofrenda, pago o lluvia', '<p>
    <strong>Características:</strong>
    Significa pago, ofrenda y agradecimiento. Se ponen presentes para el pago de alguna culpa o para enmendar algún error.
  </p>
  <p>
    Es el día especial de las ofrendas. Se agradece el sol, el agua, el aire, el alimento y todo lo que nos rodea y lo que hemos recibido de la Madre Tierra.
    Los que nacen en Toj, algunas veces, son los que pagan la deuda de la familia, por eso es que pueden sufrir problemas de salud.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Agradecimiento a Ajaw por los beneficios recibidos.</li>
    <li> Día para ponerse en paz con Ajaw, con los abuelos y abuelas y con el prójimo.</li>
    <li> Se hacen ceremonias para lograr el equilibrio, moral y espiritual.</li>
    <li> Día para retirar los sufrimientos, accidentes y enfermedades.</li>
  </ul>
  <p><strong>Su origen:</strong> Imox <strong>destino:</strong> No\'j</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> De grandes virtudes.</li>
    <li> Es creativo, comunicativo y dinámico.</li>
    <li> Practica la sinceridad.</li>
    <li> Es analista, imaginativo e intuitivo.</li>
    <li> De carácter abierta.</li>
    <li> Es romántico.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede sufrir enfermedades.</li>
    <li> Puede caer en la miseria.</li>
    <li> Puede tener inestabilidad mental.</li>
    <li> Puede estar expuesto a accidentes.</li>
    <li> Puede caer en el orgullo y la vanidad.</li>
    <li> Vicioso y orgulloso</li>
  </ul>', 'Nahual_14', 'Es el Nawal de los cuatro señores del fuego,  Tojil, Awilix, Jakawitz´ y  Nikajtakaj. Día propicio para nivelar o pagar cualquier deuda. Día en que se agradece todo lo que recibimos en nuestra vida,  lo bueno y lo malo.
Personas con mucha sensibilidad para las artes y que lloran con', 'src/imagenesNahuales/9.jpg', '<p>
    <strong>Ruwäch:</strong>
    Xb’an ri jun q’ax, q’aq’al, k’ulik. Xkojik ri q’ax ri jun q’aq’al o xb’an chi q’aq’ jun k’ax.
  </p>
  <p>
    Ja ri q’ij ri jun q’aq’al ri q’aq’al. Xkojik ri q’aq’al ri q’ij, ri ya’, ri ya’, ri ch’ich’ xaq ri jun ri xkamix xa xb’an ri Jun Iximulew.
    Ri xpe chi Toj, xb’an xb’an chi jun q’ax ri xb’an chi jun q’aq’al ri winaq, rumal ri xb’an xb’an chi xb’ano jun k’ax ri k’aslemal.
  </p>
  <p>
    <strong>Ruwäch Ajaw:</strong>
  </p>
  <ul>
    <li> K’ulik chuchi Ajaw pa jun q’aq’al xb’an chi xb’ano.</li>
    <li> Ja ri q’ij xb’an chi q’ax chi Ajaw, chi qati’t qamama’ xaq ri winaq.</li>
    <li> Xb’an ri jun q’aq’al chi jun k’a’, k’ax xaq ch’ab’äl k’aslemal.</li>
    <li> Ja ri q’ij xb’an chi xb’ano jun ruwäch, q’ax xaq k’aslemal.</li>
  </ul>
  <p><strong>Ruwäch:</strong> Imox <strong>ru tz’i’:</strong> No\'j</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> K’o jun ri ruwäch k’aslemal.</li>
    <li> Xk’otemab’äl, xkitzij xaq jun k’ax xb’in.</li>
    <li> Xb’an ri k’a’ k’ax xb’an.</li>
    <li> K’o jun ruwäch k’aslemal, xb’ano xaq xk’otemab’äl.</li>
    <li> K’o jun k’a’ xb’an.</li>
    <li> Xkitzij ri xb’an.</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> K’ax chi xb’ano.</li>
    <li> Xb’an chi jun xb’ano.</li>
    <li> K’ax chi xb’in ri jun ruwäch k’aslemal.</li>
    <li> Xkik’ik ri jun ruwäch k’aslemal.</li>
    <li> Xkik’ik xb’an xaq ri xk’ax xb’an.</li>
    <li> Xk’ax xb’an.</li>
  </ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    Le máakoʼob antiguamente tu tʼàan kʼicheʼ tʼaan “Tepescuintle”. Tu maayaʼ yucateco u kʼáabaʼ “Péekʼ”. U guardiánililil u jaʼatsʼilil kʼaax yéetel ixiʼim ka Ixmukane’ tu ts’íib. Síimboloʼil le ley, fidelidad yéetel autoridad.
</p>
<p>
    Ku túukultik u beelilil meyaj u tʼaʼanilil le máakoʼob. Maan uts ku kʼaʼankuntik e jach chaambalil suud; tóop ku tsel u tsʼíib le distaancia tʼaanoʼob.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Kʼáat pachililil yéetel orden.</li>
    <li>Máan u chaikbijil táan tuláakal baʼax muktan.</li>
    <li>Kʼáat píib u jeʼelil u beelil, u xíimbal.</li>
    <li>Kúuchilil tsol ajatsʼ sáastʼ séenbaʼal yéetel chichan a táan.</li>
    <li>U tuukulilil protection tʼaanoʼob.</li>
</ul>
<p><strong>Jóokʼol:</strong> Iqʼ   <strong>Ichil:</strong> Tijax</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Atento, ch\'ich\'il, jelaʼan tiʼ justiciaʼ.</li>
    <li>Aj defendéetikoʼob.</li>
    <li>Yumtsil yéetel sáast.</li>
    <li>Aj a wilik baax ku kaxankuntik.</li>
    <li>Bíin tʼaʼanoʼob yéetel maʼanáats.</li>
    <li>Aj óoltaj óolilil.</li>
    <li>U kʼíinil aj abogados.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Aak’ab, infiel.</li>
    <li>Tzʼíibtun, mayaj.</li>
    <li>Talan u puksiʼikʼalililil tu síipil kʼaʼam.</li>
    <li>Kʼáankun u kʼíinil yushaj óolil.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    It means payment, offering, and gratitude. Offerings are made to pay for a fault or to amend a mistake.
</p>
<p>
    It is the special day for offerings. Thanks are given for the sun, the water, the air, the food, and everything that surrounds us and all we have received from Mother Earth.
    Those born under Toj are sometimes the ones who pay the family debt; therefore, they may suffer health problems.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Gratitude to Ajaw for the benefits received.</li>
    <li> Day to make peace with Ajaw, with the grandfathers and grandmothers, and with one’s neighbor.</li>
    <li> Ceremonies are performed to achieve moral and spiritual balance.</li>
    <li> Day to remove suffering, accidents, and illnesses.</li>
</ul>
<p><strong>Origin:</strong> Imox&nbsp; <strong>destination:</strong> No&#39;j</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Possesses great virtues.</li>
    <li> Creative, communicative, and dynamic.</li>
    <li> Practices sincerity.</li>
    <li> Analytical, imaginative, and intuitive.</li>
    <li> Open-minded.</li>
    <li> Romantic.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> May suffer illnesses.</li>
    <li> Can fall into poverty.</li>
    <li> May experience mental instability.</li>
    <li> Prone to accidents.</li>
    <li> Can lapse into pride and vanity.</li>
    <li> Vicious and proud.</li>
</ul>', '<p>
    <strong>Características:</strong>
    Ri kik\'in ta k\'otz\'ijaj, ri kajch\'ibal ri k\'otz\'ijaj ri k\'ub\'anoj. Chi\' kik\'in ta ri kik\'aslemaj rutz\'ijaj chi ri q\'ijilal ri winaq k\'otz\'ijajal chi ri kik\'aslemaj rutz\'ijaj chi ri kik\'aslemaj rutz\'ijaj.
  </p>
  <p>
    Kik\'in ta jun winaq la\' chi ri kik\'aslemaj rutz\'ijaj. Chi ri k\'ik\'aslemaj ri chakaj, ri chay, ri k\'uxlejal, ri taj chik, ri utz\'ij chiri\', chupamaj chi ri q\'ijilal chi chiri\'wi k\'otz\'ijaj.
    Chiri\'wi k\'otz\'ijajal Toj, chi\' ri b\'i\' chiri\'wi kik\'aslemaj ri ri q\'ijilal, chi\' ri winaq q\'ijilal chik ri chik\'ama\' ch\'uti\' k\'utunlaj ri q\'ijilal.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Rutz\'ijaj chi Ajaw chupamaj ri winaq rutz\'ijaj chi ri k\'ut</li>
    <li> Chi\' kik\'in ta chiri\'wi kik\'aslemaj ri winaq kik\'aslemaj ri k\'ajawab\', ri ajawo\' re ri chik\'ama\' kik\'aslemaj ri q\'ijilal</li>
    <li> Chi\' kik\'in ta k\'otz\'ijajal b\'i\' kik\'aslemaj chi ri chakaj, chiri\'wi chiri\'wi k\'otz\'ijajal chiri\'wi kik\'aslemaj</li>
    <li> Chiri\'wi kik\'aslemaj chi kik\'aslemajal ri b\'i\' kik\'aslemaj, chik\'ama\' chik ri winaq k\'utunlaj, k\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj</li>
  </ul>
  <p><strong>Su origen:</strong> Imox <strong>destino:</strong> No\'j</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Nimla\' re chiri\' wi.</li>
    <li> Ajchaj, ch\'utu\'aj, chak chiri\'wi.</li>
    <li> Ri kik\'aslemaj k\'otz\'ijaj</li>
    <li> Ajchaj analista, imaginativo, intuitivo.</li>
    <li> Ri ch\'uti\' wi chik ri k\'otz\'ijaj</li>
    <li> Ajchaj romántico</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj.</li>
    <li> K\'utunlaj kik\'aslemaj ri b\'i\' kik\'aslemaj.</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj.</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj.</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj.</li>
    <li> K\'utunlaj kik\'aslemajal ri b\'i\' kik\'aslemaj.</li>
  </ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (15, 10, 'Tz\'i\'', null, 'Perro o mapache', '<p>
    <strong>Características:</strong>
    El antiguo significado de Tz’i’ es tepescuintle. En idioma k’iche’ es Lalo. Guardián de la milpa de la abuela Ixmukane de donde Ixk’ik’
    trajo la red llena de mazorcas, y que le ayudó a cumplir con su tarea de una manera mágica. En el Popol Wuj significa Jun Ajpu Wuch’,
    cazador tacuacín y Jun Ajpu Utiw, cazador coyote. También es guardián de los cerros, las montañas, las veredas y los barrancos.
  </p>
  <p>
    Es la fidelidad, la autoridad y la ley. Por tanto, es el guardián de la ley natural y espiritual. Hace los papeles de secretario.
  </p>
  <p>
    Puede influir en excesivas conductas sexuales. Por eso, algunos Guías Espirituales le atribuyen como símbolo del pecado, especialmente de impureza sexual.
    El que nace en este día puede resultar muy sexual, sea hombre o mujer. La intensidad de esta conducta dependerá del numeral que acompaña al Tz’i’
    como día de nacimiento.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Invocar por el orden y la exactitud.</li>
    <li> Puede interpretar lo conocido y lo desconocido.</li>
    <li> Se invoca el día para que guíe y cuide el camino.</li>
    <li> Día para contrarrestar calumnias y ofensas.</li>
    <li> Día de protección ante la ley.</li>
  </ul>
  <p><strong>Su origen:</strong> Iq\' <strong>destino:</strong> Tijax</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Atento, valiente, respetado, justo.</li>
    <li> Es defensor de otras personas.</li>
    <li> Es cordial.</li>
    <li> Logra lo que busca.</li>
    <li> Buen investigador y presiente las cosas o actos.</li>
    <li> Enamorado.</li>
    <li> Es el día de los abogados</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede resultar vicioso e infiel.</li>
    <li> Puede caer en la mentira.</li>
    <li> Puede tener mucha tendencia sexual.</li>
    <li> Puede resultar con temperamento fuerte.</li>
  </ul>', 'Nahual_15', 'Es el Nawal de la justicia, la autoridad material y espiritual, el orden. Día para pedir la solución a los problemas ante los tribunales. Día para  alejar los vicios. Son las personas que hablan por otros.  Los dueños de las leyes. Juzgan a los demás.', 'src/imagenesNahuales/10.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ri nim ruwäch ri Tz’i’ xib’ij tepescuintle. Pa rutzij ri k’iche’ ri Lalo. Ajtz’i’ ri ajawaxel ri k’ul re qati’t Ixmukane ch’aqa’ ri Ixk’ik’
    xkiq’ab’ ri q’ax jun ch’aji’ ri q’ax ri xa xeq’ani pa ri xb’an jun nima xb’an. Pa ri Popol Wuj xb’an ri Jun Ajpu Wuch’,
    ri tijaq tacuacín xaq Jun Ajpu Utiw, ri tijaq coyote. Xaq ajtz’i’ ri k’otemab’äl ri juyub’, ri juyub’, ri riya’ xaq ri ya’ tzam.
  </p>
  <p>
    Ja ri ch’ab’äl, ri tzij xaq ri q’ax. Rumal, ja ri ajtz’i’ ri q’ax k’aslemal xaq ch’ab’äl. Xb’an chi xb’an ri aj ruwäch.
  </p>
  <p>
    Xb’an chi ri k’a’ ri ch’aq chi xtan pa jun b’ixan. Rumal, ri ajq’ijab’ xib’an chi k’ut chi ruwäch ri xkik’ pa jun k’a’, k’ax pa ch’aq chi xb’an.
    Ri xpe chi ri q’ij xkiq’ax jun k’a’ xb’in, ri achi’ o ri ixoq. Ri k’ax chi xb’an xb’in xb’an k’a’ pa jun xb’an xb’in ri Tz’i’
    ch’aqa’ ri q’ij ri xpe pa ri q’ij.
  </p>
  <p>
    <strong>Ruwäch Ajaw:</strong>
  </p>
  <ul>
    <li> Xtanik chi k’ax xaq xojik’.</li>
    <li> Xk’atzij chi jun ruwäch xaq jun ruwäch xb’in.</li>
    <li> Xtanik pa ri q’ij xa xb’an xa xb’ano ri b’isonel xaq xb’in xb’an chi xb’an ri xb’in xb’an.</li>
    <li> Ja ri q’ij xb’an chi xb’ano chi xb’an xaq xb’an.</li>
    <li> Ja ri q’ij xb’an chi xb’an xaq ri q’ax.</li>
  </ul>
  <p><strong>Ruwäch:</strong> Iq\' <strong>ru tz’i’:</strong> Tijax</p>
  <p>
    <strong>Ruwäch K’otem:</strong>
  </p>
  <ul>
    <li> Nimalaj, k’ax, k’otem, ch’ab’äl.</li>
    <li> Ajq’ij ri jun winaq.</li>
    <li> Xak’ax chi xb’ano.</li>
    <li> Xkikot chi jun xb’an.</li>
    <li> Ajaw chi xtanik ri xb’an xaq xb’an ri xb’in ri xb’in.</li>
    <li> Ajb’ix.</li>
    <li> Ja ri q’ij ri ajb’i chi xb’an.</li>
  </ul>
  <p>
    <strong>Ruwäch K’ul:</strong>
  </p>
  <ul>
    <li> Xb’an xb’in xb’in xb’an xaq xb’an xb’an xb’an xb’an.</li>
    <li> Xk’ax chi xb’ano.</li>
    <li> Xk’ax chi jun xb’in xb’an xb’an xb’an xb’an xb’an.</li>
    <li> K’ax xb’an xb’an xb’an xb’in.</li>
  </ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    “B’atzʼ” u nawalilil wáay kʼuchil, ku representik le hiloʼil kʼáanil tiʼ u beelil kʼáajal. Kuyuch le historia cuando se tuʼux wéet, bey jun hilo kʼuch tu ja\'atsʼ. Taaʼalilil le waktik u lúum.
</p>
<p>
    Pa le nuptialililil, le kʼiʼin B’atz’ kʼuchulilil kajpʼeekʼ ka le ich kool Ajtzʼiib – le máax ku náajtajoʼob u tumen tiʼ Maayaʼ tsol. Kʼuchililil 8 B’atzʼ kʼuch u náaj pʼúuts\'il, yéetel 40 kʼiin despues u meyaj.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Nawalilil k’oja’an k’aas óolililil tuxpej beelil máaxoʼob.</li>
    <li>Tsʼíibtunilil kaajoʼob, k\'aaxo\'ob, ajt’aan u tsol.</li>
    <li>Máax ka batabʼen tu báalamilil múuch’.</li>
    <li>Meyajnoʼob ichil artesanía: tʼaanoʼ, báaleʼ, pʼeekʼtsol </li>
</ul>
<p><strong>Jóokʼol:</strong> Representación yéetel talento artístico</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Kʼáanantúul, atʼanil, chʼíibaloʼob.</li>
    <li>Chéen u bin yaʼax.</li>
    <li>Reservados.</li>
    <li>Leloʼob ku k\'aansik baʼax ku yilik.</li>
    <li>Muxan yaantal u naʼatsil.</li>
    <li>Rickoʼob bey tsoliloʼob.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Maʼatsʼilaʼ, kʼáankun.</li>
    <li>Tʼupid, k’áanal mak.</li>
    <li>Chíikbesaj kʼaax, kaxanchaj.</li>
    <li>Jach kexel óol, slanderoso.</li>
    <li>Máax ma yúuyaj yéetel mix túukulilil.</li>
    <li>Takpʼáal yuʼum snaaʼ.</li>
    <li>Débil óolilil.</li>
</ul>', '<p>
    <strong>Características:</strong>
    The ancient meaning of Tz’i’ is tepescuintle. In the K\'iche\' language, it is Lalo. Guardian of grandmother Ixmukane\'s cornfield from where Ixk’ik’
    brought the net full of corncobs, which helped her fulfill her task in a magical way. In the Popol Wuj, it means Jun Ajpu Wuch’,
    tepescuintle hunter, and Jun Ajpu Utiw, coyote hunter. It is also the guardian of hills, mountains, trails, and ravines.
</p>
<p>
    It represents fidelity, authority, and law. Therefore, it is the guardian of natural and spiritual law. It plays the roles of secretary.
</p>
<p>
    It can influence excessive sexual behavior. Therefore, some Spiritual Guides attribute it as a symbol of sin, especially sexual impurity.
    Those born on this day can be very sexual, whether male or female. The intensity of this behavior depends on the numeral accompanying
    the Tz’i’ as the day of birth.
</p>
<p>
    <strong>Función Espiritual:</strong>
</p>
<ul>
    <li> Invoke for order and accuracy.</li>
    <li> Can interpret the known and the unknown.</li>
    <li> The day is invoked to guide and protect the path.</li>
    <li> Day to counteract slander and offenses.</li>
    <li> Day of protection under the law.</li>
</ul>
<p><strong>Origin:</strong> Iq\' <strong>destination:</strong> Tijax</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Attentive, brave, respected, fair.</li>
    <li> Defender of other people.</li>
    <li> Cordial.</li>
    <li> Achieves what he seeks.</li>
    <li> Good investigator and has premonitions of things or actions.</li>
    <li> In love.</li>
    <li> It is the day of lawyers.</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Can be vicious and unfaithful.</li>
    <li> May fall into lies.</li>
    <li> May have a strong sexual tendency.</li>
    <li> May have a strong temperament.</li>
</ul>
', '<p>
    <strong>Características:</strong>
    Ri kik\'in ta k\'otu\'xik tz\'i\' k\'ub\'anoj. Ri k\'iche\' kaj taj, Lalo. Ri aj tz\'i\' ri winaq q\'ijilal Ixmukane ta milpa\', chi\' ri Ixk\'ik\' ri winaq k\'ul xk\'amachike\' chi jun winaq chik\'ama\' chupamaj k\'ik\'aslemaj. Chi Popol Wuj kaj chik ri Jun Ajpu Wuch\', tz\'ikin ruwi\' ch\'uti\' ri Jun Ajpu Utiw, tz\'ikin chupamaj.
    Chik ri\' ri q\'ijilal aj tz\'i\' chi\' tz\'utujil, ri tz\'utujilal, ri wajxaqib\'al chik ri winaq kik\'aslemaj.
  </p>
  <p>
    Ri kik\'in ta ri chiri\'wi, ri k\'ajolom k\'ik\'al ri ri\' chupamaj ri\' q\'ijilal. Chi kik\'in ta, ri aj tz\'i\' kaj winaq k\'otz\'ijaj b\'i\' b\'anoj, chi ri Guías Espirituales chik\'ama\' chi ri k\'otz\'ijaj kik\'aslemaj, xk\'utx\'ij chi ri chiri\'wi k\'otz\'ijaj.
    Ri k\'ajolom chi\' tz\'i\' chi\' la jun winaq chik ri chiri\'wi k\'otz\'ijaj kik\'aslemaj.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> K\'otz\'ijaj chi\' ri chiri\'wi k\'otz\'ijaj chik ri k\'otz\'ijaj</li>
    <li> Chi\' kik\'in ta k\'otz\'ijaj chi\' k\'otz\'ijaj</li>
    <li> Ajchaj chi chiri\'wi chik ri oromaj</li>
    <li> Chi kik\'in ta chi k\'otz\'ijaj chi\' q\'ijilal chik\'ama\'</li>
    <li> Chi kik\'in ta chi k\'otz\'ijaj b\'i\' chi k\'otz\'ijajal ri q\'ijilal</li>
  </ul>
  <p><strong>Su origen:</strong> Iq\' <strong>destino:</strong> Tijax</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Nimla\', ajk\'in, chuwach, ri\'chiri\'</li>
    <li> Chik ri k\'iche\' chik\'ama\' chupamaj</li>
    <li> Nimla\' re chiri\' wi</li>
    <li> K\'otz\'ijaj chik\'ama\' chupamaj</li>
    <li> Ajchaj investigador chik ri chiri\'wi b\'anoj q\'ijilal</li>
    <li> Ri\' rutz\'ijaj</li>
    <li> Chi kik\'in ta k\'otz\'ijajal ri oromaj</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Chik\'ama\' k\'iche\' ri k\'ut</li>
    <li> Chik\'ama\' k\'iche\' ri q\'ijilal</li>
    <li> Chik\'ama\' k\'iche\' ri q\'ijilal</li>
    <li> Chik\'ama\' k\'iche\' ri winaq ch\'uti\' b\'i\' k\'utunlaj</li>
  </ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (16, 11, 'B\'atz\'', null, 'Mono o hilo', '<p>
    <strong>Características:</strong>  Es el símbolo del hombre y de la humanidad, de la realización del hombre.
  </p>
  <p>
    Símbolo de continuidad con el pasado, como se ha englobado dentro del ritual. “Un buen día,  de la perpetración de las  ceremonias y costumbres de nuestros antepasados.
  </p>
  <p>
    Es el día  en  que se realiza aquella parte del matrimonio en que se pide la novia, y el casamiento cuarenta días después, en un día B’atz’ con un número más alto.
    En 8 B’atz’ se presenta públicamente el aprendiz de sacerdote maya, y cuarenta días después se realiza el agradecimiento.
  </p>
  <p>
    Simboliza el tiempo.  Nuestros antepasados, los mayas representaron el tiempo imaginándolo como un hilo enrollado a un carrizo que se encuentra debajo de la tierra.
    Este hilo se va desenrollando a medida que el tiempo pasa. La  historia se teje con el tiempo, así como el hilo  teje los vestidos. El ciclo Nuevo Maya,
    Wajxaqib’ B’atz’, en la ceremonia se ameniza con marimba y se baila alrededor del fuego.  El  B’atz’ amarra y desata.  Se le dice B’atz’ porque gira.   Y es el talento del ser humano.
  </p>
  <p>
    <strong>Significa:</strong>
  </p>
  <ul>
    <li>Enlace matrimonial</li>
    <li> Mono, hilo, amarrador</li>
    <li> El tiempo. desarrollo de la evolución  humana, dándonos la vida</li>
    <li> Nawal de medidor del tiempo y de toda clase de tejidos</li>
    <li> Es un buen día para recibir el destino como sacerdote Maya</li>
    <li> Orador, escultor, tallador y artista, música, flauta, deporte y siembra.</li>
  </ul>
  <p><strong>Significado Clave:</strong> La representación y el talento artístico</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Inteligente, astuto </li>
    <li> Amable</li>
    <li> Reservado </li>
    <li> Suelen imitar lo que ven</li>
    <li> Tienen buenas señales</li>
    <li> Adinerados (Ricos)</li>
    <li> Maestros de todas las artes</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Inseguro </li>
    <li> Haragán</li>
    <li> Enojado, agresivo </li>
    <li> Envidioso, calumniador</li>
    <li> Mala imaginación, incrédulo</li>
    <li> Ambicioso de cualquier cosa </li>
    <li> Débil de voluntad</li>
  </ul>', 'Nahual_16', 'Es el Nawal de todas las artes, de los tejidos, de los artistas. Es un día propicio para pedir pareja, amarrar o desatar cualquier asunto.
Son maestros de todas las artes.
', 'src/imagenesNahuales/11.jpg', '<p>
    <strong>Taqajilal:</strong>  Re ri q\'ij b\'atz\' chi jun ruk\' ri man utz re ri k\'utb\'altzij, re ri utzilal ri q\'ij.
</p>
<p>
    Ruk\' ri utzilal b\'atz\' chi ri k\'utb\'altzij chi qab\'ixik, re b\'antaj ri chi wi\' ri ch\'ab\'äl. "Jun ruk\' q\'ij, re ri ati\'aj chi q\'ij chi chikibal ri atzi\'ib\'äl re ri b\'antaj,
    yik\'ot chik chikibal ri chi ch\'ut ch\'um a\' junuk b\'antaj ri chi chikibal ch\'um a\' ruk\' q\'ij.
</p>
<p>
    Re ri ch\'ab\'äl b\'atz\' chi chikibal ch\'um a\' b\'antaj ri ch\'um a\' ruk\' q\'ij ri chikibal ch\'um a\' ri ati\'aj chi q\'ij chi aq\'a\' re ri utzilal.
    Chi 8 B\'atz\' ri q\'ij chikibal chik ri q\'uix e ma\'a\' che\' k\'ik\' mo\' chi ati\'aj chi q\'ij, yik\'ot chik chikibal ri chi utz re ri q\'ij.
</p>
<p>
    Ruk\' ri q\'ij chi re ri utzilal. Re ri chikibal re ri atzi\'ib\'äl, ri maya, chikibal chik ri atzi\'ib\'äl re ri utzilal ti\'j ri q\'ij ri jun ri muk\' ch\'um ri qach\'abaj.
    Ri muk\' ch\'um re q\'ij re ri utzilal k\'ik\'ob\' ri q\'ij. Ri muk\' ch\'um ruk\'ob\' ri atzi\'ib\'äl chi re q\'ij, k\'ik\' ri muk\' ch\'um chikibal re ri chi atzi\'ib\'äl.
    Ruk\' ri q\'ij k\'ik\' ri k\'utb\'altzij, Wajxaqib\' B\'atz\', chi ri chikibal ch\'um a\' ri q\'ij chikibal chi ri awirik\'ib\'al, yik\'ot chik chikibal chik ri k\'akawal.
    B\'atz\' ruk\'oj chik ri B\'atz\', chik ri q\'ij chi chikibal ch\'um a\' ri ati\'aj re ri q\'ij.
</p>
<p>
    <strong>Taqajilal:</strong>
</p>
<ul>
    <li>Q\'ij chi utzilal chi ri ch\'ab\'äl</li>
    <li> Ba\'alam, muk\' ch\'um, b\'antaj</li>
    <li> Re q\'ij. wi\' ri q\'ij, xk\'ok\'ol chikibal re ri utzilal utz ri q\'ij</li>
    <li> Ba\'q\', utz re ri waj, chikibal chik ri q\'ij chikibal chi ri k\'utb\'altzij re ri atzi\'ib\'äl</li>
    <li> Chikibal chik ri ruk\' chi ri chikibal ch\'um a\' re ri q\'ij chi ri atzi\'ib\'äl re ri chi chikibal ch\'um a\'</li>
    <li> Rajawal, sij, ch\'utu, xul, q\'ib\'äl, flauta, chi ri chikibal ch\'um a\' ri utzilal</li>
</ul>
<p><strong>Taqajilal Chikibal:</strong> Utzilal chi ri atzi\'ib\'äl re ri ri chikibal</p>
<p>
    <strong>Utzilal:</strong>
</p>
<ul>
    <li> Utzilal, amate\'</li>
    <li> Utz re ri q\'ij</li>
    <li> Utzib\'äl</li>
    <li> Chikibal chik ri q\'ij</li>
    <li> Utzilal ri ri nawal</li>
    <li> Q\'utujilal (q\'ab\')</li>
    <li> Ki\'k\'ajib\' re ri k\'utb\'altzij ri ri chi atzi\'ib\'äl</li>
</ul>
<p>
    <strong>B\'antaj:</strong>
</p>
<ul>
    <li> Chiqibal</li>
    <li> Cholch\'ij</li>
    <li> Uyub\'.</li>
    <li> Tz\'i\', chujik\'</li>
    <li> K\'olomu\', muk\'ulib\'.</li>
    <li> Ki\'k\'ab\'aj</li>
    <li> Ri chikibal ch\'um a\' k\'utb\'altzij</li>
</ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    “E” síimboloʼil beel yéetel destino. Max ku naʼatik u beel tiʼ máaxoʼob; guardiánil óoltaj u xíimbal. Kuxtalilil, trabajo yéetel puksiʼikʼal ku jach saʼasik tiʼ letiʼ.
</p>
<p>
    Toj kʼáat saʼasik u beelilil jun máax, tu xikin ka maʼ tu kʼajóolt a kaʼajal. Le nawal ku páajtalik taʼan tu xikin yaantal a yil ajkʼab sáamal.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Tuumben beelil, paakatililil, chaan meyaj.</li>
    <li>Saastik maʼaloʼob ooxlah kʼiʼin.</li>
    <li>Kʼáat koʼolel óoltajoʼob tiʼ jumpʼéel puksiikal.</li>
    <li>Protección tu xíimbalil pilótaloob.</li>
    <li>Káat meyaj tsol tukultakav destino.</li>
</ul>
<p><strong>Jóokʼol:</strong> Kʼat   <strong>Ichil:</strong> Ajpu</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Koolel, meyajiloʼob.</li>
    <li>Yaan u puksiʼikʼal tuʼux kʼeekʼen kajoʼl.</li>
    <li>Jáajil, xikin.</li>
    <li>Aj viajero yéetel ajkojoʼob.</li>
    <li>Máan pʼeekʼ, tuukul naʼats.</li>
    <li>Cuidadosoʼob.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Táan u tʼaʼanoʼ yéetel mix tu kʼáat u yaraj.</li>
    <li>Weensik u puksiʼikʼal tu yáanalil.</li>
    <li>Jach chaach óol.</li>
    <li>Nervioso, frágil.</li>
    <li>Maʼ chʼíibal u bensaj u yaantal.</li>
</ul>', '<p>
    <strong>Características:</strong>  It is the symbol of man and humanity, of human accomplishment.
</p>
<p>
    Symbol of continuity with the past, as it is encompassed within the ritual. "A good day, the perpetration of the ceremonies and customs of our ancestors.
</p>
<p>
    It is the day when that part of the marriage is performed in which the bride is requested, and the wedding takes place forty days later, on a day B’atz\' with a higher number.
    On 8 B’atz\', the apprentice Maya priest is publicly presented, and forty days later, the gratitude is performed.
</p>
<p>
    Symbolizes time. Our ancestors, the Maya, represented time by imagining it as a thread rolled up on a reed that is found beneath the earth.
    This thread is unwound as time passes. History is woven with time, just as thread weaves clothes. The New Maya cycle, Wajxaqib’ B’atz’, in the ceremony is enlivened with marimba and danced around the fire. B’atz\' ties and unties. It is called B’atz\' because it spins. And it is the talent of the human being.
</p>
<p>
    <strong>Significa:</strong>
</p>
<ul>
    <li>Marital link</li>
    <li> Monkey, thread, binder</li>
    <li> Time. development of human evolution, giving us life</li>
    <li> Nawal of time measurer and all kinds of weaving</li>
    <li> It is a good day to receive destiny as a Maya priest</li>
    <li> Speaker, sculptor, carver and artist, music, flute, sport and sowing.</li>
</ul>
<p><strong>Key Meaning:</strong> Representation and artistic talent</p>
<p>
    <strong>Fortalezas:</strong>
</p>
<ul>
    <li> Intelligent, cunning </li>
    <li> Kind</li>
    <li> Reserved </li>
    <li> They tend to imitate what they see</li>
    <li> They have good signs</li>
    <li> Wealthy (Rich)</li>
    <li> Masters of all arts</li>
</ul>
<p>
    <strong>Debilidades:</strong>
</p>
<ul>
    <li> Insecure </li>
    <li> Lazy</li>
    <li> Angry, aggressive </li>
    <li> Envious, slanderous</li>
    <li> Poor imagination, incredulous</li>
    <li> Ambitious for anything </li>
    <li> Weak-willed</li>
</ul>
', '<p>
    <strong>Características:</strong>  Ri kik\'in ta jun aj winaq ri k\'iche\' q\'amane\', jun aj ri kik\'in ta jun chupamaj kik\'aslemaj ri k\'iche\'.
  </p>
  <p>
    Ri kik\'in ta chik ri qijab\'al re ruwi\', chi ri uk\'aj ojer k\'ajolom ri kik\'aslemaj. "Jun chik\'ama\' ri k\'otewal, ri k\'ajolom k\'ik\'al ri ab\'aj winaq ri ch\'umilal ri kik\'aslemaj.
  </p>
  <p>
    Ri kik\'in ta jun chik\'ama\' chi\' ojer k\'ab\'echik re ruwi\' ri k\'otewal, chi\' ri k\'otz\'ijaj winaq ri k\'umatz\', y ojer k\'ajolom, k\'ik\'al chik\'ama\' wuj re ruwi\' b\'atz\' chi\' winaq ojer k\'ajolom.
    Chi\' ri b\'atz\' ojer chik\'ama\' ri\' ri kik\'in ta jun winaq k\'amachike\' k\'iche\' chi\' ri kik\'in ta jun chupamaj chik\'ama\'.
  </p>
  <p>
    Ri kik\'in ta ri k\'ajolom. Ri k\'otz\'ijaj winaq, ri k\'iche\' ri k\'umatz\' k\'ik\'al ri k\'ajolom chi k\'aslemaj ri k\'ajawab\' ri winaq chupamaj chik\'ama\' chi\' ri winaq ri k\'iche\'.
    Ri k\'ajolom k\'ik\'al chi\' k\'otz\'ijaj winaq, chi k\'otz\'ijaj k\'ik\'ojolom ri k\'ik\'in ta jun winaq. Ri kik\'in ta\' ruwi\' winaq chi ri winaq k\'otz\'ijajaj. Ri kik\'in ta q\'ij chi\' ri winaq b\'atz\', Wajxaqib\' B\'atz\', k\'ab\'echike\' k\'iche\' chi k\'ik\'ojolom ri\' ri b\'atz\' chi chik\'ama\' chi ri oromaj.
    Ri b\'atz\' ri k\'ab\'echik k\'utuk k\'ab\'anoj. Chi kik\'in ta b\'atz\' k\'ab\'echike\' k\'iche\' chi\' k\'otz\'ijaj k\'ik\'ojolom. Y ri k\'ajolom ri k\'iche\' jun aj winaq.
  </p>
  <p>
    <strong>Significa:</strong>
  </p>
  <ul>
    <li>Ri\' wi na k\'ab\'echik chik ri q\'ijilal ri k\'otewal</li>
    <li> Ruwi\', chak ik\'ojolom, chupamaj k\'utuk</li>
    <li> Ri k\'ajolom. ch\'uti\' wi k\'ijlajb\'al k\'umatz\' chik ri k\'iche\', ri k\'amachike\' k\'utuk k\'ab\'echik chik</li>
    <li> Nawal chi chik\'ama\' k\'otz\'ijaj re k\'ajolom chik ri winaq ri ch\'utu\' k\'ijlajb\'al chik</li>
    <li> Ri kik\'in ta\' jun winaq k\'utuk kajolom k\'amachike\' ri k\'ab\'echik chik ri q\'ijilal ri k\'otewal</li>
    <li> Ajchaj, chuch\'el, chutamaj ri k\'ik\'in ta\' q\'ijilal ri k\'otewal</li>
  </ul>
  <p><strong>Significado Clave:</strong> Ri\' ch\'uti\' wi k\'otz\'ijaj chik ri k\'ajolom ajchaj</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Nimla\', taq\'el </li>
    <li> Chirij, chuwach</li>
    <li> Q\'ij</li>
    <li> Ri chik\'ama\' ch\'uti\' ri k\'otz\'ijaj</li>
    <li> K\'axa\' winaq, k\'ab\'echik</li>
    <li> Ajchaj chik chak winaq</li>
    <li> Ajchaj ri k\'otz\'ijaj re chiri\' wi chik\'ama\'</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> K\'utunlaj</li>
    <li> Ajb\'ix</li>
    <li> Raxas, xik\'ojolom</li>
    <li> K\'axchik\', k\'utunlaj</li>
    <li> Chik\'ama\' k\'iche\' chik ri chik\'ama\' k\'iche\'</li>
    <li> Nimla\' re jun k\'utuk</li>
    <li> K\'utunlaj k\'amachike\' ri chiri\' wi</li>
  </ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (17, 12, 'E\'', null, 'Camino o diente', '<p>
    <strong>Características:</strong>
    Simboliza el camino y el destino. Es el guía. Es el que nos lleva a un punto fijo. Uno de los Cargadores del Tiempo. Es la protección de los viajeros y caminantes. Conduce la vida espiritual y material.
  </p>
  <p>
    Es el que hace posible la realización humana en todos los órdenes y en todas las manifestaciones.
    Pero también puede simbolizar los obstáculos con que los seres humanos se tropiezan en la continua búsqueda de esa realización.
  </p>
  <p>
    Es un día bueno para desplazarse en cualquier lugar. En caso de peligro, el Ajaw E es el que da la protección.
    También es día bueno para agradecer el bienestar físico, la vida misma de las personas y el trabajo. Es un día muy sagrado.
    Por esta razón, se puede pedir su protección, como dice el Popol Wuj “que no se caigan en la bajada ni en la subida del camino.
    Que no encuentren obstáculos ni detrás ni delante de ellos, ni cosa que los golpee. Concédeles buenos caminos, hermosos caminos planos…”.
  </p>
  <p>
    Es el viaje, la travesía y el trayecto.  Se ofrecen ceremonias o invocaciones para que limpie el camino de los peligros y de los accidentes.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Protección ante las tentaciones</li>
    <li> Protección ante los peligros del camino</li>
    <li> Día para iniciar un proyecto</li>
    <li> Día de protección de los pilotos</li>
    <li> Día para encauzar mejor el destino</li>
  </ul>
  <p><strong>Su origen:</strong> K\'at <strong>destino:</strong> Ajpu</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Es amable y trabajador</li>
    <li> Es guía y consejero</li>
    <li> Es cariñoso y alegre </li>
    <li> Es viajero y puede ser comerciante</li>
    <li> Afortunado, decidido, comprensivo</li>
    <li> Cuidadoso en las cosas</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Desconfiado e inseguro</li>
    <li> Algunas veces se puede resentir</li>
    <li> Es variable con su carácter</li>
    <li> Es nervioso y frágil</li>
    <li> Impaciente en algunas ocasiones</li>
  </ul>', 'Nahual_17', 'Es el Nawal de todos los caminos y dirigentes. Del sistema nervioso y sanguíneo.
Día propicio para iniciar cualquier viaje o negocio.
Son líderes naturales.', 'src/imagenesNahuales/12.jpg', '<p>
    <strong>Taqajilal:</strong>
    Chikibal chik ri ati\'aj chi ri chikin chi ri atzi\'ib\'äl. Utz re ri nawal. Utzilal chikibal chi jun winaq ch\'ak\'ab\'äl. Ri chikibal re ri ri atzi\'ib\'äl ch\'um a\' re ri q\'ij. Utz re ri wachajik utzilal chikibal chikibal chi ri chikin ri ri q\'ij chikibal.
  </p>
  <p>
    Utz re ri nawal ri chikibal chikibal chikibal chi ri q\'ij chikibal chikibal ri ri chikibal ri ri ri atzi\'ib\'äl. Pero chikibal chikibal utz re ri nawal chi ri chikibal ri chikibal chikibal re ri winaq chikibal chikibal chikibal re ri ri atzi\'ib\'äl.
  </p>
  <p>
    Utz re ri q\'ij chikibal chi k\'o\'n ri winaq ch\'ak\'ab\'äl re ri chikibal chikibal. Chikibal chikibal chikibal chikibal re ri utzilal chikibal ri ri ri k\'itxib\'äl, re ri wi\' utzilal chikibal re ri winaq.
    Kik\'ot chik chikibal ri chikibal utz re ri winaq. Utz re ri q\'ij chikibal k\'ik\'ot chik chikibal chi ri winaq.
    Chi ri utzilal chikibal chikibal. Chikibal chikibal chikibal chikibal, xk\'ut chik chikibal k\'ut xk\'ut chikibal, xk\'ut chikibal k\'ut k\'ut, xk\'ut chikibal, xk\'ut k\'ut k\'ut.
  </p>
  <p>
    <strong>Ri ri q\'ij Ulew:</strong>
  </p>
  <ul>
    <li> Utzilal chi k\'utb\'altzij re ri chi chakaj</li>
    <li> Utzilal chi k\'o\'n re ri wi\' utzilal chikibal chikibal chikibal</li>
    <li> Chikibal chikibal chi ri atzi\'ib\'äl</li>
    <li> Utzilal chi ri piloto chi ri ri k\'utb\'altzij</li>
    <li> Chikibal chikibal chi ri q\'ij chikibal k\'ut xk\'ut chikibal chikibal</li>
  </ul>
  <p><strong>Ri ri ulew:</strong> K\'at <strong>k\'itxib\'äl:</strong> Ajpu</p>
  <p>
    <strong>Utzilal:</strong>
  </p>
  <ul>
    <li> Utzilal y k\'utb\'altzij</li>
    <li> Utz re ri nawal y chikibal</li>
    <li> Utz re ri chikibal y ri ri k\'utb\'altzij</li>
    <li> Utz re ri nawal y chikibal</li>
    <li> Utz re ri nawal, utz re ri nawal, chikibal k\'ut xk\'ut chikibal chikibal</li>
    <li> Utz re ri nawal re ri chikibal</li>
  </ul>
  <p>
    <strong>K\'utxib\'äl:</strong>
  </p>
  <ul>
    <li> Utz re ri nawal re ri chikibal</li>
    <li> K\'ik\'ot chik chikibal chikibal chi ri k\'utb\'altzij</li>
    <li> Utz re ri nawal re ri k\'utb\'altzij</li>
    <li> Utz re ri nawal re ri nawal</li>
    <li> Utz re ri nawal re ri k\'utb\'altzij chikibal</li>
  </ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    Aj síimboloʼil nohoch kool kʼaax – u jeʼelilil ixiʼim. Xook u tsʼíibnikaʼaj Jun Ajpu yéetel Ixbalamkeʼ tu jaatsʼililil kajaay Ixmukaneʼ. Bey juntúul tsíiminilil kʼíin – triúnfoʼil máaxoʼob kontra u kʼaaxilil.
</p>
<p>
    8 Aj u kʼíin tu juntalilil u destinoʼ. Ku siʼijil tu kʼíinil u páajtalilil máaxoʼob ku yhdziltik bejlaeʼ.
</p>
<p>
    Ku representik le kʼaaxal ixiʼim – u chʼíinbaliloʼob. U kʼíin táan wíilkajal u tsʼáajililoʼob paalaloʼob; juntúul jaatsʼililil kʼáat kʼáat u káas tiʼ u jelajkʼab.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Nawalik kajay yéetel ko’oleloʼob.</li>
    <li>Kaanantik kajaay yéetel joʼolnaj.</li>
    <li>U báalamilil kʼáanant u puksiʼikʼal tiʼ paalal.</li>
    <li>Nawalilil úuchben artes tukuch.</li>
</ul>
<p><strong>Jóokʼol:</strong> Integridadil kuváaj</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Autoritario yéetel jatsʼuts.</li>
    <li>Inteligenteʼ.</li>
    <li>Strictoʼob.</li>
    <li>Yáantal u nüupalilil yéetel paalaloʼob.</li>
    <li>Fuerteʼ leéxico yéetel moral.</li>
    <li>Atraído por filosofíaʼ yéetel teología.</li>
    <li>Meyajiloʼob.</li>
    <li>Joʼoy.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Katsʼuk.</li>
    <li>Cháansamal pʼáas óol.</li>
    <li>Nervioso.</li>
    <li>Le gusta polémika.</li>
    <li>Yáanal u beel, mix túukulilil.</li>
    <li>Extremista.</li>
    <li>Chʼichʼ jokes.</li>
    <li>Mix constante tu kuváaj.</li>
    <li>Variable.</li>
    <li>Ku síijil tu paal.</li>
    <li>U sáamalilil kʼúuchil.</li>
    <li>Tʼaanil yéetel suutsʼil.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    Symbolizes the path and destiny. It is the guide. It leads us to a fixed point. One of the Time Carriers. It is the protection of travelers and walkers. It guides spiritual and material life.
</p>
<p>
    It makes human realization possible in all orders and manifestations. But it can also symbolize the obstacles that humans stumble upon in the continuous search for that realization.
</p>
<p>
    It is a good day to move anywhere. In case of danger, Ajaw E provides protection.
    It is also a good day to be grateful for the physical well-being, the life itself of people, and work. It is a very sacred day.
    For this reason, its protection can be requested, as the Popol Wuj says "that they do not fall on the descent or ascent of the road.
    May they not find obstacles behind or in front of them, nor anything that strikes them. Grant them good paths, beautiful flat paths...".
</p>
<p>
    It is the journey, the crossing, and the route. Ceremonies or invocations are offered to clear the path of dangers and accidents.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Protection against temptations</li>
    <li> Protection against dangers of the road</li>
    <li> Day to start a project</li>
    <li> Day of protection for pilots</li>
    <li> Day to better channel destiny</li>
</ul>
<p><strong>Origin:</strong> K\'at <strong>Destination:</strong> Ajpu</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Kind and hardworking</li>
    <li> Is a guide and counselor</li>
    <li> Affectionate and cheerful</li>
    <li> Is a traveler and can be a merchant</li>
    <li> Lucky, decisive, understanding</li>
    <li> Careful in things</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Distrustful and insecure</li>
    <li> Can sometimes resent</li>
    <li> Is variable in character</li>
    <li> Is nervous and fragile</li>
    <li> Impatient on some occasions</li>
</ul>
', '<p>
    <strong>Características:</strong>
    K\'aslemalaj q\'ij kaq\'ij le k\'axlemalaj k\'ij ulew. Ri k\'aslemalaj q\'ij kaq\'ij ulew, jun k\'aslemalaj kaq\'ij le chik. Le k\'aslemalaj kaq\'ij le,
    rumaq k\'ux puch k\'aslemalaj k\'ij ulew. Jun k\'aslemalaj kaq\'ij le paq\'isaq.  Q\'ijaw k\'aslemalaj ulew re naq\' chik.
  </p>
  <p>
    Ri k\'axin ulew le k\'aslemalaj kaq\'ij, wal k\'axin ajk\'inaqil ulew, jun k\'aslemalaj kaq\'ij le. Naq\' k\'aslemalaj kaq\'ij re naq\' wal k\'axin k\'aslemalaj,
    re naq\' wal k\'axin kaq\'ij le ulew. Chik\'ajab\' k\'aslemalaj k\'axin naq\' rutz\'ij chi k\'aslemalaj kaq\'ij le ulew.
    Rumaq chik ri k\'axin kaq\'ij k\'aslemalaj le ulew, rumaq chik ri k\'axin k\'aslemalaj k\'ij ulew, chik ri q\'ij k\'aslemalaj k\'ij ulew.
  </p>
  <p>
    Ri k\'axin k\'aslemalaj kaq\'ij, ri winaq ulew kaq\'ij k\'aslemalaj k\'axin, wal k\'axin ulew.
  </p>
  <p>
    <strong>Q\'ajawal Ulew:</strong>
  </p>
  <ul>
    <li> Q\'ajaw k\'aslemalaj k\'axin ulew.</li>
    <li> Q\'ajaw k\'aslemalaj k\'ij ulew kaq\'ij chik\'ij re naq\'.</li>
    <li> Q\'ajaw k\'aslemalaj k\'ij ulew chik\'ij naq\' k\'axin re naq\' kaq\'ij.</li>
    <li> Q\'ajaw k\'aslemalaj k\'axin ulew chik\'ij naq\' wal k\'axin re naq\' kaq\'ij.</li>
    <li> Q\'ajaw k\'aslemalaj k\'ij ulew chik\'ij naq\' k\'axin re naq\' kaq\'ij.</li>
  </ul>
  <p><strong>Q\'ajoj ulew:</strong> K\'at <strong>q\'ajawal ulew:</strong> Ajpu</p>
  <p>
    <strong>Q\'ajawal ulew:</strong>
  </p>
  <ul>
    <li> K\'ajol winaq q\'ij kaq\'ij k\'axin ulew.</li>
    <li> K\'ajol k\'aslemalaj k\'ij ulew kaq\'ij chik\'ij.</li>
    <li> K\'ajol wal k\'axin ulew kaq\'ij k\'ij.</li>
    <li> K\'ajol ulew k\'ij chik\'ij kaq\'ij k\'axin.</li>
    <li> K\'ajol k\'aslemalaj k\'axin ulew chik\'ij re naq\' kaq\'ij.</li>
    <li> K\'ajol k\'aslemalaj k\'ij ulew chik\'ij re naq\' kaq\'ij.</li>
  </ul>
</p>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (18, 13, 'Aj', null, 'Caña o cañaveral', '<p>
    <strong>Características:</strong>
    Simboliza caña veral y milpa. Todo lo que se relaciona al hogar y la familia. Es el símbolo que dejó Jun Ajpu Ixb’alamkej de su vida,
    cuando sembró la caña en medio del patio de la casa de la abuela Ixmukane. Aj es símbolo de la resurrección de Jun Ajpu e Ixb’alamkej,
    quienes no murieron en manos de los señores de Xib’alb’a. Es el triunfo del bien sobre el mal.
  </p>
  <p>
    Es el destino representado por el Nawal o los Nawales. 8 Aj es el día en el cual se establece el destino de uno, para llamarlo y reconocerlo.
  </p>
  <p>
    también es elote, maíz tierno.  Día relacionado con todo lo que concierne a los niños.
    Es día bueno y sobre todo para rezar por las criaturas.
  </p>
  <p>
    También es el día de la enfermedad debilidad en el tejido óseo, pero de mucha energía espiritual.
    Es el hogar, la casa, todo lo que se relaciona con la casa. Los que nacen en Aj pueden ser sacerdotes mayas.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> El hogar y la familia de todas las generaciones tiernas; 8 Aj se celebra el día del niño.</li>
    <li> El bastón del poder de las virtudes divinas, sensatez, la palabra sagrada.</li>
    <li> Caña, símbolo que dejó Jun Ajpu Ixbalanke de su vida, cuando sembró la caña en el patio, dueño del Hogar, y ternura.</li>
    <li> Nawal de las artes.</li>
  </ul>
  <p><strong>Significado Clave:</strong> La integridad de la fe</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Autoridad</li>
    <li> Inteligente</li>
    <li> Estricto</li>
    <li> Es respetado por sus amigos</li>
    <li> Principios sólidos en el terreno moral y ético</li>
    <li> Atraído por la religión o los estudios filosóficos y teológicos</li>
    <li> Trabajador</li>
    <li> Bromista</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Regaña</li>
    <li> Celoso</li>
    <li> Nervioso</li>
    <li> Expuesto  a discutir y  juzgar</li>
    <li> Hace lo que le plazca</li>
    <li> Extremista, no es de moderación</li>
    <li> Hace bromas pesadas</li>
    <li> No es constante en la fe</li>
    <li> Variable</li>
    <li> Sufre con frecuencia, se enferma en la niñez</li>
    <li> Alcohólico</li>
    <li> Destructor</li>
    <li> Una vida variable, de dolor</li>
    <li> tristeza y alegría</li>
  </ul>', 'Nahual_18', 'Es el Nawal de la casa y de los niños, día propicio para el hogar y la salud de los niños.
Nawal de las generaciones tiernas.
Personas que no pueden negarse ante otros.', 'src/imagenesNahuales/13.jpg', '<p>
    <strong>Ruwäch:</strong>
    Ke ri Aj, ruwäch q\'ak\'ik (caña de azúcar) chuqa\' ri mex (milpa). Tok pa ri tinamit chuqa\' ri ruwi\' ab\'aj. Ja ri Aj ruwäch xk\'isaj Jun Ajpu chuqa\' Ixbalamke\' chi pa ri patio ri ri qati\'t Ixmukane\' xse\' ri q\'ak\'ik. Aj ruwäch k\'amik q\'ij re, k\'amik kachi\' Jun Ajpu chuqa\' Ixbalamke\' man xmirisaj ta pa ruk\'ux ri Ajawab\' Xib\'alb\'a. Ri k\'aslemal q\'atal ri pa ruwäch ri e k\'ax ri utzil chi ruk\'ux ri nimaq\'ij pa rub\'ey.
</p>
<p>
    Aj xk\'ut ri awach pa ri nawales. Pa 8 Aj xkib\'e pa ri nimaläj q\'ij ri ruq\'ij ri ch\'ob\'ej rech nuwak\'axik.
</p>
<p>
    Ri Aj chuwäch k\'iwon chi jun aj ixim k\'ïs. Q\'ij ri okel pa ronojel achijab\'. Utz q\'ij richin ya\' k\'utem ri ch\'uti\' ak\'wala\'.
</p>
<p>
    Kij ri q\'ij ri ruwäch ach\'och\' chuqa\' ruwäch tijoxel; k\'äq pa ruwäch q\'och\'. E b\'anïk ri e k\'ay pas ch\'awiq, rumal jun aj xjan ri Aj.
</p>
<p>
    <strong>Samajel Ajaw:</strong>
</p>
<ul>
    <li> Ruxaq chuqa\' ach\'och\' ri ronojel k\'ejowab\'; pa 8 Aj nuk\'samaj Q\'ij ri Ak\'wala\'.</li>
    <li> Ri B\'astón qamaya\' qak\'ichel: ajawalil, ajilab\'al, tzijob\'äl q\'ajom.</li>
    <li> Ri q\'ak\'ik ruwäch xk\'isaj Jun Ajpu chi pa patio, ruwäch ru-ach\'och\' chuqa\' ch\'uti\' ruk\'u\'x.</li>
    <li> Nawal ri aj xik\'oj, aj rach\'och\' chuqa\' aj tzijob\'äl.</li>
</ul>
<p><strong>Ruwäch K\'amal:</strong> Chajinel ruwäch ajawil</p>
<p>
    <strong>Ajilab\'äl:</strong>
</p>
<ul>
    <li> K\'ïch, nim b\'i\'aj, q\'atal ri ach\'och\'.</li>
    <li> Na\'ojel, aj nimaläj tzij.</li>
    <li> Ruwi\' tzij, rub\'ey ch\'awil.</li>
    <li> Ajk\'amöl, aj b\'ey.</li>
</ul>
<p>
    <strong>Ch\'awem:</strong>
</p>
<ul>
    <li> Nïm ruk\'i\' ri nutzij, ruq\'ij ri ajsik\'ij.</li>
    <li> Jach toq\'ob\'ej, jalonïk.</li>
    <li> Xk\'amäj pa q\'axik taq rumar ri ach\'och\'.</li>
    <li> B\'inel ruk\'ux, k\'ay jun taq ch\'utaq.</li>
</ul>', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    Ix u síimboloʼil kaambalil káak yéetel Túumben kiinil Ku. Representa le túumben kaaj chul bejlaʼeʼ tiʼ ich kooliloob, juyúuloob yéetel kabáaloob. Síimboloʼil báalam.
</p>
<p>
    Representa le altár maaya – le <em>tabʼal</em>. Kʼuch kʼíin sáastaj kʼáat u kʼáatchilil kuxtal wáayiloʼob tu lúum, tanto domésticoʼob bey silvestreʼob. Kʼáat Ajaw jumpʼéel nichpabal yaʼax kúuchil u meyajiloʼob. Tiaʼal u kʼíin ku sáansamal u taal u jáalilil yaʼax velas.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Káat u yuumtalil puksiʼikʼal yéetel baah.</li>
    <li>Invokaciónilil jáal.</li>
    <li>Invokaciónilil kuxtal wáayiloʼob.</li>
    <li>Kʼíin tsol baatsilil koʼoleloʼob.</li>
    <li>Invokaciónilil pʼáatalilil ixiʼim u puxlukʼililoʼob.</li>
</ul>
<p><strong>Jóokʼol:</strong> Keme   <strong>Ichil:</strong> Iqʼ</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Patsaj, koʼox, tsʼíin, nojoch óol, yaʼan óoltaj.</li>
    <li>Tsʼíibtun, nojoch tʼáan.</li>
    <li>U puksiʼikʼalilil jach sáast.</li>
    <li>Inwáantaj kajaay.</li>
    <li>Potbil inwáantaj ku máan u chʼochʼ.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Jach kʼáankun puksiʼikʼal.</li>
    <li>Ten páajtalilil u tsʼáaj a óolil yéetel u chʼíin curt.</li>
    <li>Joʼok u chiʼibaloʼob jaatsʼuts kʼax, koʼok.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    Symbolizes sugar cane and cornfield. Everything related to home and family. It is the symbol left by Jun Ajpu Ixb’alamkej of his life,
    when he planted the sugar cane in the middle of his grandmother Ixmukane\'s courtyard. Aj is a symbol of the resurrection of Jun Ajpu and Ixb’alamkej,
    who did not die at the hands of the Lords of Xib’alb’a. It is the triumph of good over evil.
</p>
<p>
    It represents destiny through the Nawal or the Nawales. 8 Aj is the day on which one\'s destiny is established, to call it and recognize it.
</p>
<p>
    It is also young corn, tender maize. A day related to everything concerning children.
    It is a good day, especially to pray for the little ones.
</p>
<p>
    It is also the day of illness, weakness in bone tissue, but of great spiritual energy.
    It is home, the house, everything related to the house. Those born in Aj can be Maya priests.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> The home and family of all tender generations; 8 Aj celebrates Children\'s Day.</li>
    <li> The staff of the power of divine virtues, prudence, sacred word.</li>
    <li> Sugar cane, symbol left by Jun Ajpu Ixbalanke of his life, when he planted the sugar cane in the courtyard, owner of the Home, and tenderness.</li>
    <li> Nawal of the arts.</li>
</ul>
<p><strong>Key Meaning:</strong> The integrity of faith</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Authority</li>
    <li> Intelligent</li>
    <li> Strict</li>
    <li> Respected by friends</li>
    <li> Solid principles in moral and ethical grounds</li>
    <li> Attracted to religion or philosophical and theological studies</li>
    <li> Hardworking</li>
    <li> Jovial</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Scolds</li>
    <li> Jealous</li>
    <li> Nervous</li>
    <li> Prone to argue and judge</li>
    <li> Does as he pleases</li>
    <li> Extremist, not moderate</li>
    <li> Plays heavy-handed jokes</li>
    <li> Not consistent in faith</li>
    <li> Variable</li>
    <li> Frequently suffers, gets sick in childhood</li>
    <li> Alcoholic</li>
    <li> Destructive</li>
    <li> A variable life, of pain</li>
    <li> sadness and joy</li>
</ul>
', '<p>
    <strong>Características:</strong>
    K’aslemalaj kaq’ij raq’ ulew q’u’k’um, milpaj. Ri ulew tx’anaqil taq k’aslemalaj k’uxa. Aj k’aslemalaj, Jun Ajpu Ixb’alamkej k’axin aq’ab’äl ulew,
    rumaq chikatz’aqatz’i’ kaq’ij pa nimaq chwi’. Jun Ajpu e Ixb’alamkej, jun uq’ijil jujumab’äl k’axin k’aslemalaj Xib’alb’a. K’ajol winaq q’u’k’um.
</p>
<p>
    K’aslemalaj uk’u’x k’aslemalaj Nawal taq chi k’uq’alaj k’aslemalaj. 8 Aj k’uq’alaj k’aslemalaj rumaq xik’oq’alaj k’uq’alaj uwach.
</p>
<p>
    Ri k’u’x k’aslemalaj elote, winaq k’aslemalaj k’uq’alaj.  K’uq’alaj chi k’axin winaq ulew chik’ul ulew ki’.  Winaq ulew, ja’ chik’ul ulew k’axin
    q’atatachik’ul ulew.
</p>
<p>
    <strong>Q’ajawal Ulew:</strong>
</p>
<ul>
    <li> K’aslemalaj ulew rumaq winaq k’aslemalaj k’axin; 8 Aj k’axin chik’ul ulew.</li>
    <li> Rumaq winaq chik’oq’alaj k’aslemalaj ulew.</li>
    <li> Uk’u’x k’aslemalaj, ulew kaq’ij k’axin kaq’ajk’oq’alaj winaq.</li>
    <li> Nawal taq chik’ul ulew ri ajtz’aqib’äl k’uq’alaj.</li>
</ul>
<p><strong>Q’alakam:</strong> Chirib’alal q’u’k’um k’axin</p>
<p>
    <strong>Q’oq’olol:</strong>
</p>
<ul>
    <li> K’oq’ol k’oq’ol.</li>
    <li> K’aslemalaj winaq uj y achi k’axin.</li>
    <li> Q’ij b’atz’, q’oq’ol, tz’aqol, tziq’opaj.</li>
</ul>
');
INSERT INTO tiempomaya.nahual (idweb, iddesk, nombre, nombreYucateco, significado, htmlCodigo, categoria, descripcion, rutaEscritorio, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (19, 14, 'I\'x', null, 'Jaguar', '<p>
    <strong>Características:</strong>
    Es el símbolo y energía de la Madre Tierra. Representa los lugares o centros ceremoniales donde se llevan a cabo las ceremonias.
    Son los cerros, las montañas, las planicies. Significa Jaguar.
  </p>
  <p>
    Representa el altar maya o sea el tab’al. Es un día especial para pedir la vida de los animales tanto domésticos como salvajes.
    Se le pide a Ajaw una buena cosecha de cualquier cultivo, en especial el de las verduras.
    En este día se encienden candelas de color verde, ya que simbolizan el color de la Madre Tierra.
  </p>
  <p>
    Representa el altar maya o sea el tab’al. Es un día especial para pedir la vida de los animales tanto domésticos como salvajes.
    Se le pide a Ajaw una buena cosecha de cualquier cultivo, en especial el de las verduras. En este día se encienden
    candelas de color verde, ya que simbolizan el color de la Madre Tierra.
  </p>
  <p>
    <strong>Función Espiritual:</strong>
  </p>
  <ul>
    <li> Propicia energía espiritual y física.</li>
    <li> Invocación por la lluvia.</li>
    <li> Invocación por la vida de los animales.</li>
    <li> Día de invocación por la salud de toda la humanidad.</li>
    <li> Día para realizar invocaciones para que las siembras estén protegidas de los animales.</li>
  </ul>
  <p><strong>Su origen:</strong> Keme <strong>destino:</strong> Iq\'</p>
  <p>
    <strong>Fortalezas:</strong>
  </p>
  <ul>
    <li> Es paciente, fuerte, responsable, valiente, respetuoso, vigoroso y atrevido.</li>
    <li> Es decisivo y realista.</li>
    <li> Es de buen corazón.</li>
    <li> Buen padre de familia.</li>
    <li> Puede ser líder y famoso si sabe encauzar sus energías.</li>
  </ul>
  <p>
    <strong>Debilidades:</strong>
  </p>
  <ul>
    <li> Puede llegar a tener un carácter fuerte.</li>
    <li> Algunas veces se enoja y se impacienta.</li>
    <li> Su carácter le puede hacer prepotente, orgulloso, colérico, serio y vengativo.</li>
  </ul>', 'Nahual_19', 'Es el Nawal de la naturaleza y los altares mayas, día para pedir fortaleza física y mental.
Es el Nawal de las siete vergüenzas humanas: orgullo, ambición, envidia, mentira, crimen, ingratitud, ignorancia por pereza.
Personas de razonamiento interno a las que les gusta la naturaleza y la soledad.', 'src/imagenesNahuales/14.jpg', '<p>
    <strong>Taqajilal:</strong>
    Utzilal chi ri q\'ij re ri kaj kaj. Chikibal chi ri ri k\'ut re ri q\'ij chi ri kaj chikibal kaj chikibal. Chikibal chikibal chikibal kik\'ot k\'utun, ri k\'utun, ri tzaq\'ol.
    K\'ik\'ot chikibal Kame.
  </p>
  <p>
    Chikibal ri ri ri tab\'al maya chi ri Tab’al. Utz re ri q\'ij chi ri ch\'ab\'äl chikibal re ri wi\' ulew re ri utz re ri animales chi ri ch\'ab\'äl chikibal kaj ri kaj.
    Utz re ri chikibal k\'ik\'ot ri ri Ajaw chi ri utz re ri q\'ij chikibal chikibal chikibal, xk\'ut chikibal k\'utun ri ri k\'ut re ri kaj.
    Chi ri chikibal chikibal k\'utun chikibal chikibal chikibal k\'utun, k\'ik\'ot k\'utun k\'ik\'ot k\'utun chikibal k\'utun.
  </p>
  <p>
    <strong>Ri ri q\'ij Ulew:</strong> Keme <strong>k\'itxib\'äl:</strong> Iq\'
  </p>
  <p>
    <strong>Ri ri q\'ij Ulew:</strong>
  </p>
  <ul>
    <li> Utzilal utz re ri q\'ij y k\'ut re ri q\'ij.</li>
    <li> Kik\'ot re ri k\'ut re ri k\'utun.</li>
    <li> Kik\'ot re ri k\'utun chi ri ri k\'ut re ri ch\'ab\'äl.</li>
    <li> Q\'ij re ri k\'utun chi ri ri k\'ut re ri chi winaq chikibal kaj.</li>
    <li> Q\'ij kik\'ot chikibal chikibal chikibal k\'utun k\'utun re ri chi k\'ut re ri ch\'ab\'äl.</li>
  </ul>
  <p><strong>K\'itxib\'äl k\'utun:</strong> Utzilal chi ri ajawilal re ri ri k\'itxib\'äl</p>
  <p>
    <strong>Utzilal:</strong>
  </p>
  <ul>
    <li> Utz re ri nawal, utz re ri nawal, utz re ri nawal, utz re ri nawal, utz re ri nawal, utz re ri nawal, utz re ri nawal.</li>
    <li> Utz re ri nawal y k\'ut re ri nawal.</li>
    <li> Utz re ri wi\' re ri nawal.</li>
    <li> Utz re ri nawal chi ri nawal chikibal chikibal re ri k\'utun.</li>
    <li> Utz re ri nawal re ri nawal re ri nawal chi ri chi nawal chikibal chikibal re ri k\'utun.</li>
  </ul>
  <p>
    <strong>K\'itxib\'äl:</strong>
  </p>
  <ul>
    <li> Utz re ri nawal chi ri nawal k\'utun.</li>
    <li> Kik\'ot chik kik\'ot chikibal chikibal kik\'ot k\'utun kik\'ot k\'utun kik\'ot k\'utun.</li>
    <li> Utz re ri nawal re ri k\'utun k\'utun.</li>
    <li> Utz re ri nawal re ri nawal.</li>
    <li> Utz re ri nawal re ri k\'utun kik\'ot chikibal.</li>
  </ul>
', '<p>
    <strong>Tsʼáaniloʼob:</strong><br>
    Leloʼ u síimboloʼil kaambalil yéetel yaantal luʼum kaambal. Representa le tuʼux oʼokolil kajaay; altaroʼob maaya’ túumben jaatsʼil. U juyú, u witz yéetel u joʼop. Síimboloʼil báalam, baax tʼaʼan “Iʼx”.
</p>
<p>
    Kʼuch kʼíin, kʼáat u kuxtal wáayiloʼob. Ajaw kʼáat nichpabalil ich ixiʼim, pakʼaloʼob, yaʼax velas – yaantal u puksiʼikʼalilil túumben luum. Kʼáat bʼuutsʼ puksiʼikʼalil máaxoʼob.
</p>
<p>
    <strong>Takpʼakalil:</strong>
</p>
<ul>
    <li>Kʼáat pakabal kʼáanant túukul yéetel baah.</li>
    <li>Invokaciónilil jáal.</li>
    <li>Invokaciónilil kuxtal wáayiloʼob.</li>
    <li>Kʼáat baatsililil jaats máax.</li>
    <li>Tu kʼíin ku kuxtal u puxlukʼil ixiʼim.</li>
</ul>
<p><strong>Jóokʼol:</strong> Keme   <strong>Ichil:</strong> Iqʼ</p>
<p>
    <strong>Chʼaikʼiloʼob:</strong>
</p>
<ul>
    <li>Patsaj, chʼíin, puksiʼikʼalilil koʼolel, nojoch óol.</li>
    <li>Sáast túukul.</li>
    <li>Máax yóokʼoltik jun kúuchililil puksiʼikʼal.</li>
    <li>Kʼáat a yúuyaj.</li>
    <li>Pájtalil líder maaya\'.</li>
</ul>
<p>
    <strong>Kʼulil:</strong>
</p>
<ul>
    <li>Jach kʼáankun puksiʼikʼal.</li>
    <li>Méeyaʼan, kolerosoʼob.</li>
    <li>Tsʼíibtun, yeʼetsʼik.</li>
</ul>', '<p>
    <strong>Characteristics:</strong>
    It is the symbol and energy of Mother Earth. Represents the places or ceremonial centers where ceremonies are held.
    They are the hills, the mountains, the plains. Signifies Jaguar.
</p>
<p>
    Represents the Mayan altar or tab’al. It is a special day to ask for the life of animals, both domestic and wild.
    Ajaw is asked for a good harvest of any crop, especially vegetables.
    On this day, green candles are lit, as they symbolize the color of Mother Earth.
</p>
<p>
    <strong>Spiritual Function:</strong>
</p>
<ul>
    <li> Provides spiritual and physical energy.</li>
    <li> Invocation for rain.</li>
    <li> Invocation for the life of animals.</li>
    <li> Day of invocation for the health of all humanity.</li>
    <li> Day to make invocations so that crops are protected from animals.</li>
</ul>
<p><strong>Origin:</strong> Keme <strong>Destination:</strong> Iq\'</p>
<p>
    <strong>Strengths:</strong>
</p>
<ul>
    <li> Patient, strong, responsible, brave, respectful, vigorous, and daring.</li>
    <li> Decisive and realistic.</li>
    <li> Good-hearted.</li>
    <li> Good family man.</li>
    <li> Can be a leader and famous if he channels his energies well.</li>
</ul>
<p>
    <strong>Weaknesses:</strong>
</p>
<ul>
    <li> Can have a strong character.</li>
    <li> Sometimes gets angry and impatient.</li>
    <li> His character can make him arrogant, proud, choleric, serious, and vengeful.</li>
</ul>
', '<p>
    <strong>Ulew:</strong> Wuj
</p>
<p>
    <strong>Xinaxik:</strong>
    Ulew k’aslemalaj k’uxa taq ja’. Q’uk’umaraj taq k’ichejil chi atz’ij, ulew tx’anaqil tz’i’ che ajawil k’aslemalaj.
    Chi witzaj, chi pitzamaj, chi patachaj. Winaq k’axij.
</p>
<p>
    Ulew maya taq a xub’al. Rumaq chikatz’a taq laq te k’aslemalaj k’uxa taq, ja’ chik’ul chik’anwach k’ichej k’aslemalaj.
    Q’uk’umaraj Ajaw uchi q’anel k’aslemalaj uwach chi ajajil taq k’usamalaj. Chi ulew k’aslemalaj chi taq k’aslemalaj
    uchawi ajk’u’lan q’ak’al ja’ ulew ulew chik’ul chik’anwach k’aslemalaj uchawi.
</p>
<p>
    <strong>Q’ajawal Ulew:</strong>
</p>
<ul>
    <li> Winaq k’axij ulew chik’ul taq ja’ ulew.</li>
    <li> Kaq’ujal chik’ul taq ja’ winaq ulew.</li>
    <li> Kaq’ujal chik’anwach k’aslemalaj ulew.</li>
    <li> Chik’ul ulew winaq ki’kotaj k’axij tzij.</li>
    <li> Q’uk’umaraj taq ja’ q’ab’alaj k’usamalaj k’aslemalaj taq chik’ul taq.</li>
</ul>
<p><strong>Qaleta’wi:</strong> Keme <strong>utijonik:</strong> Iq’</p>
<p>
    <strong>K’anal:</strong>
</p>
<ul>
    <li> Winaq k’axij, q’ij b’atz’, b’atz’, q’ajaw, q’aq’aj, aq’aslemalaj, q’axa’laj ulewin.</li>
    <li> Winaq k’u’k’ul, k’u’b’i’.</li>
    <li> Winaq k’oxb’al ulew.</li>
    <li> Ajtziqatz’ib’äl ajaw.</li>
    <li> Uwinaj jun ki’kotaj chik’ul k’axij ulew.</li>
</ul>
<p>
    <strong>Xojom:</strong>
</p>
<ul>
    <li> Winaq winaq b’atz’, q’ij k’oq’ y r’uq’i’ ulew.</li>
    <li> Algunas veces winaq aq’ij ukaq’ xuk’aslemalaj.</li>
    <li> Ajtziqatz’ib’äl q’ij tz’aqol chik’ul, q’uk’umaraj, q’oq’ol, ajk’u’lan, tziq’opaj.</li>
</ul>
');

