-- kin
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 1, 'Imix\'', 'Dragon', 'Es el guardián fiero de la vida, de las ideas y proyectos que pone en marcha. Es el gestor, el productor, el iniciador. Goza de una gran sensibilidad existencial y una creatividad única. Si no está en armonía consigo mismo puede tener muchas ideas pero no realizar ninguna por no saber por dónde empezar o también dedicarse a tantos proyectos al mismo tiempo que no logra entregarse por entero a ninguno. Dejar lo que empiece sin terminar lo retrasa energéticamente. Espiritualmente representa la memoria ancestral y si está despierto logra integrarla en todo lo que hace.', 'Kin_0', 'Imix', 'The fierce guardian of life, of the ideas and projects that he sets in motion. He is the manager, the producer, the initiator. He enjoys a great existential sensitivity and a unique creativity. If he is not in harmony with himself, he may have many ideas but not carry out any of them because he does not know where to start, or he may also dedicate himself to so many projects at the same time that he cannot fully commit to any of them. Leaving what he starts unfinished energetically delays him. Spiritually, he represents ancestral memory, and if awakened, he manages to integrate it into everything he does', 'X\'ak\'bal ri ch\'utinamit, ri yab\'al rech le k\'ux rech k\'utb\'al, ri keb\'anoj rech k\'utb\'al rech li rach\'b\'al. Ri utz awäch, ri ch\'ob\'an, ri ch\'aaj rech rach\'b\'al. K\'ut loq\' ri ruk\'u ri kib\'al ri ulew k\'ay k\'ulaj, xawal li chuxab\' ri k\'ut rech k\'o tzijok ulew chi\' k\'o jun. La ri q\'ij loq\' rech tz\'ijol ri ka\'atzib\'al, ri q\'aik\'atzib\'al, yäqatzib\'al. Xa ri utzawäch ri k\'ut rech wi\', chik\'al ri junan li wi\' q\'ajol rech loq\' rech tzijol', '<span>Ja ri tata’ k’aslemal ri b’anob’äl, ri tzijob’äl yal b’an pa jalojil. Ja ri b’anol, ri xeb’anoxib’al, ri xerujil. Kuxo jun ch’umilal kik’aslemal chiqamik yal kikotemab’äl. Man xkikotem ke wach’ik ri tinamit k’o man xkikotem junam ruwäch xujchaj jun tzij ruwäch pa yalan ya’ ru ruk’ wäch pa k’ut. Xb’ano pa yalan xujchaj wi yal k’o yujunam rumal k’o, man xb’ano wi pa tajin k’o ruwäch ri tinamit. Ri k’aslemal k’o yal kik’aslemal rumal man xb’ano xutikij junam. Ruwi’ ri nimalaj k’aslemal yal kik’aslemal chik.</span>
', '<span>Es u ajkʼaan kuxtal, le túukul yéetel le proyectoʼob ku kaʼantaj. Letiʼ u naʼataal, u meyajoʼol yéetel u tsʼaʼat beetaal. Gózaʼ u naʼatsʼ óotsil kuxtal yéetel jumpʼeʼel jach kʼátun meyaj tsol. Wa maʼ ku tsʼáasik tu yóokʼol letiʼ, yaan u yaʼalaʼaloʼob túukuloʼob, baʼaleʼ maʼ uts u tsʼaabal tu beetik juntúul, tumen maʼ sáastal tu beetaj kʼáajalil; wa xan, ku jatsʼik u pool ichil jaajil proyectoʼob ku yaantal tu tuláakal kʼáajal, beyoʼ maʼ uts u juntal óol. Ku máan tu paach baʼax ku betsʼantal, tsuʼutsʼkintaj u kʼáabaʼ yéetel u kʼinamil óol. Ichil u kúuchil espiritual, letiʼ u síimboloʼil najil núukbʼal; tu wakaj, ku tsʼeʼen u kʼáajtal tiʼ tuláakal baʼax ku betik.</span>
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (1, 2, 'Ik\'', 'Viento', 'Es la comunicación, el aliento divino, la flexibilidad y el cambio. Tiene el don de la palabra, así que deberá usarla estratégicamente y con bondad. Necesita de novedades todo el tiempo, suele ser sumamente social aunque en sombra puede guardar mucho de sí mismo aún rodeado de gente y hablando sin decir nada. A nivel espiritual puede canalizar mensajes del más allá. Necesita focalizarse y decir todo lo que siente en lo más profundo de sí, sabiendo también cuándo guardar silencio. ', 'Kin_1', 'Ik', 'It is communication, divine breath, flexibility, and change. It has the gift of speech, so it should be used strategically and with kindness. It needs novelty all the time, tends to be extremely social, although in shadow it can keep much of itself even when surrounded by people and speaking without saying anything. At a spiritual level, it can channel messages from beyond. It needs to focus and express everything it feels deep inside, knowing also when to remain silent.', 'Ri kech rech tzij, ri kech rech rutz\'ijal, ri kech rech tz\'olilal rech k\'ak\'oj. Q\'at k\'utinamit rutz\'ijal, xawi\' ri k\'ut chik\'al tz\'ijol rech wi\' q\'ajol, ti\' k\'utinamit q\'at loq\' rech k\'utinamit la k\'utinamit chik\'al chi\', chi\' rech k\'ut tz\'olilal loq\' rech wi\' ka\' chik\'al ri tz\'ijol. Ri chik\'al ri q\'ajol q\'at chi\' b\'antiox rech utzil, q\'at k\'utinamit chik\'al chik\'al k\'utinamit loq\' chi\' chi\' ri wi\' qajol rech wi\', xawal chi\' xawi\' q\'at chutz.', '<span>Ri k’ulb’il, ri q’aq’alal k’aslemal, ri xub’an yal ri tajin k’o. K’o jun nima’j b’anik, re xkojik k’ul ri b’an pa b’ixan yal ri tzalu’. Kik’in ronojel ri jalojil, k’o jun chik’aj wi chi keb’ix k’ulik. Man xkotzij ke wach’ik ri k’aslemal, man xub’i’ ke wach’ik pa taq jay, man xb’ano ri k’aslemal, k’o junam ri ruwi’ ri nimel xb’an chik, xb’ano pa ka ri tinamit yal b’an pa jalojil jas. A ri ruk’u’x ruwi’ xb’ano pa k’ul ri tzij pa jun nimaq’ij. Kik’in pa ka ri k’aslemal yal kik’otem ri b’anob’äl k’o xuk’u’x pa ka k’as, kikotemik man xb’ano ri xaqan ri tzalu’.</span>
', '<span>Es u tʼaan, u ikʼil kʼu yéetel u leentsil kensaj. Yaan u najil tʼaʼan; tumen leloʼ ku kʼáat ku tsʼeʼen estrategicamente yéetel nuxibʼ túukul. Táan u kʼáat joʼokʼ sáamal túumben baʼaxoʼob, jach social letiʼ; pero tu utsʼil ku chanaj tiʼ suutsʼukoʼob, ku tʼaʼan baʼaleʼ maʼ tsʼeʼen baʼax yano. Ichil u kúuchil espiritual páajtal chananel tʼaan tu weʼ kʼáajil; kʼáat u naʼatschik u túukul yéetel ku tʼan tuláakal u óoliloʼob, yéetel xan ku kʼaʼat kʼah máax kʼáat maʼ tʼaʼan.</span>
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (2, 3, 'Ak\'bal\'', 'Noche', 'Es el sol de la oscuridad. Representa nuestro inconsciente, el mundo onírico y la capacidad de realizar nuestros sueños. Tiene el potencial de recibir mensajes en sueños, solo hay que hacerles caso. Necesita descansar mucho y estar solo por periodos. Es importante saber salir también y relacionarse con el mundo, con la espontaneidad que la caracteriza. Suelen ser histriónicos, sumamente intuitivos y más bien estancar su abundancia si no creen en sí mismos. Es importante estar atento a las posibles locuras, impulsividades,  deseos sin resolver, y a un ego desmedido, para poder equilibrarse.', 'Kin_2', 'Akbal', 'It is the sun of darkness. It represents our unconscious, the dream world, and the ability to realize our dreams. It has the potential to receive messages in dreams; we just have to pay attention to them. It needs a lot of rest and solitude for periods. It is important to know how to also go out and relate to the world, with the spontaneity that characterizes it. They tend to be histrionic, extremely intuitive, and rather stagnate their abundance if they do not believe in themselves. It is important to be attentive to possible craziness, impulsiveness, unresolved desires, and an inflated ego, in order to balance oneself.', 'Ri k\'olb\'al che rutz\'ijal. Xawi\' ri k\'utinamit, ri mundo wuj, rech ri ruk\' ri wi\' tajib\' la\' k\'utinamit chi\'. Q\'at wi\' q\'atatz\'in chi\' rutz\'ijal, k\'u\'wi\' chik ri wi\' la q\'at chawon. Tz\'ib\'itak chik\'al k\'a ri utzil, k\'at ri\' lachinamit la jun chik\'al chik\'ulaj, chik\'al wi\' tz\'a\' k\'utinamit rech ri ruk\' la k\'utinamit. K\'atam chik chik\'al histriónicos, sumamente intuitivos, rech rech ruk\' k\'ut chi\' chik\'ulaj k\'utinamit chik ri\' k\'i\' chi\' ri wi\' rech q\'at loq\' rech k\'utinamit. Utz k\'utinamit wi\' utzij k\'atam rech jun posibles locuras, impulsividades, k\'utinamit k\'i\' loq\' chi\' k\'utinamit, rech chik\'al e\' k\'utinamit, chik jun q\'i\' xkib\'al, k\'u\'wi\' chik ri equilibrarse.', '<span>Ri q’ij ri k’aslemal. Xb’anob’äl ri kik’aslemal ch’umil, ri nimanel pa tzijob’äl yal ri k’o ri saqch’ool k’o ri b’anob’äl. K’o jun nima’j k’ul pa ka xb’ano ri tzij pa tzijob’äl, k’o pa k’ulik xkojik. Kik’in pa k’as k’ulil yal kik’otem ri k’aslemal. Ri k’ulik xkotzij pa k’ul k’o yal b’anob’äl, kik’ul ri xak’amowik kik’inomik. Xb’an pa ka kikotemik jay, xb’an xik’ulik jun ch’umil k’ul, yal ri kik’aslemal xkojik. K’o jun nima’j tzijonemil, jun ch’ab’äl junam xb’ano chik, man xkojik ri kik’aslemal pa ka ri kik’as. Ri k’ulik xkotzij pa k’ul jun nimel chi k’amik, chi kik’in chik, jun nimel chi ruwäch tzij, yal jun q’aq’al k’aslemal pa ka k’o xajo’ chik.</span>
', 'Es u k’iinil tu k’iin tu ka’anal. U yantal jump’éel ts\'o\'ok ti’ u noj u ts\'o\'onotil, le k’iin tu p\'áatalil yéetel u k’iinil u beetik le máak’ab yaan u paktike’ex. Ts’o’oksaj u potencial u k’a’atal ts\'iibo\'ob ti\' le k’iinil, tu láak’ k’a’ana’an u ts\'aabal tu beetike’ex. Ts’áabal tu yook’ol k\'iin yéetel ka\'anal ti\' yáaxakilo\'ob. Jump’éel ba’al u ts\'ookik ti’ ku ts\'aabal u beetik yéetel u beetik tu yilaje’ex yéetel u chichanil u beetik, bey ma\'ax u ts\'áabal tsikbalil. Yaan u chúumukil tu chi\'ibal, ts\'o\'ok ts\'áabal tu beetik ti’ u yil ti’ ka’ab yéetel tu paachakil u ka’anal yéetel ma’ u yaantal u yóolil. Jump’éel ba’al u ts\'ookik ti’ ku ts’aabal tu yaantal u k\'áatilo\'ob tu beetil, le k\'íinsajo\'ob, yáaxajo\'ob yéetel jump’éel chi\'ibil ego, ba\'ax u yaantal ti’ jump’éel ba’al ti’ ku ts\'aabal u yaantal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (3, 4, 'K\'an', 'La Semilla', 'Es la capacidad de inyectarle vida a todo lo que nos propongamos para que florezca, para que tenga resultados, para que se materialice y sea exitoso. En primer lugar la Semilla debe sentir, identificar sus pasiones, aquello que ama hacer, para que pueda dedicarse a eso y no desbalancearse entregando toda su infinita energía en proyectos ajenos o en aquellos a los que se ha acostumbrado por presión social o solo porque funcionan. También es la danza, el gozo, el placer, la curiosidad y el saber atinar, saber esperar al momento correcto para actuar', 'Kin_3', 'Kan', 'It is the ability to inject life into everything we propose so that it flourishes, so that it yields results, so that it materializes, and becomes successful. First, the Seed must feel, identify its passions, what it loves to do, so that it can dedicate itself to that and not become unbalanced by expending all its infinite energy on external projects or those it has become accustomed to due to social pressure or just because they work. It is also about dance, joy, pleasure, curiosity, and knowing how to hit the mark, knowing how to wait for the right moment to act.', 'Utzeri wi\' utz\'inb\'el k\'a tz\'ikin ri jun chik chi ri tz\'ak, k\'a k\'umalajal, k\'a b\'anxk\'akal, k\'a wach ri utz\'ijol, chi ri k\'a q\'ij k\'utinamit, chi ri q\'ij k\'u\' xtz\'ib\' wi\' pa k\'u\'k\'axb\'altzi\', chi ri k\'a chi\' xtz\'ikinik chi ri k\'a k\'utinamit, k\'a k\'u\'ri\' rech tz\'ib\'ajil wi\' wi\' tzij. Utz wi\' xtz\'ib\' ri k\'u\'ri\', ri xkik\'inb\'el, ri k\'aq\'ijinb\'el, ri rujwach k\'a wuj wi\' jun, k\'a utz q\'ij k\'aq\'ijinb\'el, k\'a wach ri wi\' winaq k\'ut kik\'ijol.', '<span>Ri k’ulik pa k’o xajo’ chik ri b’anob’äl pa k’ul ri k’o yal kik’in jaloj, pa k’o yal kik’o ri k’o, pa k’o yal kik’ul yal kik’ulunem. Ri jaloq’ij kik’in pa k’o chik’aj, kikotem ri b’an pa ka ri kik’in yal kik’o, ri k’o yal kik’aj k’o, pa k’o yal kik’in ri k’o yal kik’otem chik, man kik’o ri k’aslemal pa ka kik’o jun nima’j b’anob’äl ri jun ruwäch kik’aslemal, man kik’o chik pa ka kik’in chik ri kik’aslemal ri kik’in yal kik’o ri nimqak’ij xajonem pa tajin yal kik’o junaj. Xb’an pa ka kik’o ri b’i, ri k’a’ k’ul, ri k’aslemal, ri xik’in yal kik’otem, yal kik’in ch’ab’äl pa k’o jun xuk’u’x pa k’ul k’o ri qak’altäq chi k’amik pa k’ul k’o.</span>
', 'Es u k’iinil u yaantal le kuxtal ti’ jump’éel le máak’ab tu yilaj ti’ u k’a’ab, ba\'ax u ts\'áabal u tsool, ba\'ax u beetik yéetel ba\'ax u ts\'aabal u kuxtal. Tu yáaxo\'ob, le Nojoch K\'aax ts\'o\'ok u yantal, u k\'a\'anal ti\' u yantal le k\'iinilo\'obe\', le k\'iinil u ts\'aabal u beetik, ba\'ax u ts\'aabal u yaantal ti\' le ba\'ax yéetel ma\' u yaantal ti\' jump\'éel ku\'uxtal yéetel ka\' u ts\'ook u k\'áat u yantal jump\'éel u nojoch kuxtal ti\' máak\'ab máak\'ab tu ts\'o\'okole\' yo\'osal o tu ts\'o\'okol yéetel u k\'áatil ti\' le máak\'ab ma\' u ts\'ook u yaantal ti\' jump\'éel. Tu ka\'a yéetel, jump\'éel ka’ansaj, jump’éel k\'uxub, jump’éel k\'iin, jump\'éel k\'áat yéetel jump’éel tu k\'áat u yantal ti’ le k\'iino\'ob tu beetik, u k\'áat u yaantal ti\' le k\'iin ku beetik ti\' u ts\'ookik.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (4, 5, 'Chikchan', 'La Serpiente', 'Es la fuerza vital, la astucia para vivir en el mundo material, así como la sabiduría para entender que no hay espiritualidad sin equilibrio físico. La Serpiente se dedica a reunir los recursos necesarios para tener una buena vida, en sombra ese será su único objetivo, en luz, sabrá que ese es solo el medio para poder evolucionar a este plano. Suele ser dominante, territorial y austera, pero también muy culta y noble.', 'Kin_4', 'Chicchan', 'It is the life force, the cunning to live in the material world, as well as the wisdom to understand that there is no spirituality without physical balance. The Serpent is dedicated to gathering the necessary resources to have a good life; in shadow, that will be its only goal, in light, it will know that this is just the means to evolve in this plane. It tends to be dominant, territorial, and austere, but also very cultured and noble.', 'Ri wi\' aq\'ij, ri xub\'anil pa utzil ri q\'ijil k\'u\'xanik, xcha\' ri q\'ij pa juyub\'el ri wi\' k\'u\'xanik. Utz xub\'anil chi ri wuj, ri q\'ij rech k\'a wi\' utz rech tzijol k\'u\'xanik q\'ij, chi tz\'ib\'al, k\'a wi\' che rech jun q\'ij rech kik\'ijol pa k\'ik\' xkik\'inb\'el k\'u\'xanik. K\'a k\'utb\'altzij wi\' k\'a q\'ijinb\'el, k\'a paqarab\'al, k\'a xeb\'xk\'utinb\'el, chiq\'echaj, k\'a xchik\'ayutinb\'el rech winaq chi utzijol.', '<span>Ri k’aslemal k’ul, ri xajo’ yal kik’in pa ri nimanel k’aslemal, xkib’an yal kik’in pa k’o ri k’aslemal pa k’ul ri nimaj ch’ab’äl kik’ul pa k’aslemal. Ri Kuk’ se k’o pa k’ulik ri q’aq’alal yal kik’otemik ri k’o yal kik’ulunem, pa ruk’u’x kik’in ri ja’ ri xkojik pa k’ul ri k’ulik, pa k’o, kik’in yal kik’o ri ja’ ri xkojik ri k’ul pa k’ulik k’o ri nimanel. Xb’an pa ka kik’o jay, xb’an jun chik’aj junam yal ch’umil chik, xaq kikotemik yal kik’in pa ri nimaj k’ul yal ri nimaj tzijonemil.</span>
', 'Es u k’iinil tu kuxtal, u chichanil tu k’iin ti’ le k’iinil k’áak’nal, beyo’o’ u nojochil tu k’iinil u yantal ti’ ma’ yaan u kuxtalil tu chik’in chichan yéetel u ts\'ookikil. Le Kaan ts’o’ok u k’a’atal u tsikbal u kuxtalil k’iino’ob ku yantal ti’ u ts\'o\'ok jump’éel kuxtal tu ka\'anal, ti’ k’iin kaanil u beyo’ ti’ob jump’éel u nojoch k’iinil, ti’ k’iin ku yaantal u beyo’ tu yilaj ti’ le ba\'ax u ts\'aabal u k\'áat u beetik ti’ le k’iin. Ts\'o\'okol ka\'anal, kaan u nojoch yéetel k’iinob, bey xan ts\'o\'oksaj jump\'éel tu kuxtal yéetel najil.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (5, 6, 'Kimi', 'El enlazador de mundos', 'Es el puente entre diferentes dimensiones. En este plano domina la capacidad de ser como un relacionista público, de crear contactos, de saber cómo relacionarse con los demás para generar redes y oportunidades. En el plano espiritual es el mensajero de los espíritus y, aunque lo suela bloquear por miedo, puede recibir información para sí mismo o para ser transmitida a los demás como forma de ayuda. Su  misión es entender la muerte como parte de la vida, profundizar en su conocimiento espiritual sobre la misma para saber dejar ir cuando corresponda.', 'Kin_5', 'Cimi', 'It is the bridge between different dimensions. In this plane, it masters the ability to be like a public relations specialist, to create contacts, to know how to relate to others to generate networks and opportunities. In the spiritual plane, it is the messenger of spirits and, although it may block it out of fear, it can receive information for itself or to be transmitted to others as a form of help. Its mission is to understand death as part of life, to deepen its spiritual knowledge about it to know when to let go when necessary.', 'Ri k\'ab\'al ri k\'utu\'l kik\'otemal chikib\'al ri q\'ij ri juyub\'el. Chik wuj, ri wi\' xkik\'otemal chik ri winaq rech k\'inaqil ri k\'utb\'al, chik chakawil q\'ij, chik xchik\'ay ri winaq chikib\'ij ri awasik chik rech k\'utb\'atz\'ib\' rech utzibalal. Chik wuj k\'u\'xanik, k\'a wi\' k\'u\'xanik rech kik\'otemal ri winaq k\'aq\'alajil, chik ka\'q kik\'otemal ri k\'utu\'l ri q\'ij q\'ab\'ijal k\'u\'xanik k\'a ri k\'utu\'l rech rutz\'in ri winaq k\'a wi\' chik\'ayibalal k\'u\'xanik rech atiq chik ta kiwi k\'ij.', '<span>Ri xajo’ pa ka ruq’ij pa junam ruk’u’x ruwi’. Pa ri ruwi’ kik’in kikotemik ri k’ulik yal kik’in jun ch’ab’äl junam ri xak’amowik tzij, ri xb’anob’äl ri xak’am, ri kik’in pa ka kik’in yal ri k’ulik pa ka kik’ul yal kik’o junam ri tzij yal kik’ulunem. Pa ri ruwi’ k’aslemal ri jun nimalaj xkib’ij ri ruwäch k’aslemal yal, xkib’anol kik’in rumal kik’in ri ruchi’, kik’in kik’ul yal kik’in ri tzij pa ka ri k’o pa ri kik’aslemal o pa ka ri kik’ul ri b’anob’äl pa k’ul yal kik’in ri k’o. Ri xb’an kik’in ri k’o yal kik’in ri ruwäch k’ulik kik’in ri qak’altäq pa ri k’aslemal, kik’otemik ri kik’in ri k’ulik k’aslemal pa ri qak’altäq pa ka kik’in yal kik’o ruwäch.</span>
', 'Es u bejil ti’ le k’iino’ob xíimbal u tuuch\'. Tu le k’iin u yantal u k’iinil u béeytal u máaxo’ob tu yilaje’ex tu ts\'íibat kaambal, u k’a’atal ts\'íibat, u k’áatil u yantal ti’ le máak’ab ku yantal u k’áatil ti’ jump’éel u ts’aabal u kuxtal yéetel u yoochel k\'iinob. Tu k’iinil kuxtalil, es u k\'áatil ti\' le k\'iino\'obe\', yéetel beyo\'ob tu k’iin ka’anal máak u k\'áat u yantal, ts’o’ok u béeytal u k’a’atal u ts\'íibatil ti’ u yóolil o ti’ u yantal ti’ le máak’ab bey jump’éel nojochil u ya\'abkach. U ts’ook u yantal u k\'áat u k’iinil ka’a yanak u kuxtal ti’ k’iin, u ts\'ookik u k’iinilil kuxtalil tu ka\'anal ti’ u yantal u yaantal tu ts’áabal ku yantal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (6, 7, 'Manik\'', 'La mano', 'Representa el servicio, la sanación y la realización. Es el poder de llevar a cabo todo lo que uno se proponga. En sombra, la Mano hace por hacer, es adicto al trabajo, pero no se arriesga a dedicarse a lo que más sueña. En luz, todo lo que haga además estará conectado con su capacidad de ayudar y de sanar. Debe tener mucho cuidado con control y aprender a poner límites sanos entre lo que le da a los demás y a sí mismo.', 'Kin_6', 'Manik', 'It represents service, healing, and fulfillment. It is the power to carry out everything one sets out to do. In shadow, the Hand acts just for the sake of doing, addicted to work, but unwilling to risk dedicating itself to what it dreams of the most. In light, everything it does will also be connected to its ability to help and heal. It must be very careful with control and learn to set healthy boundaries between what it gives to others and to itself.', 'Ri awäch ri k\'ik, ri q\'ij, y ri xk\'ajol. K\'a wi\' ri q\'ij rech tikonel ri chik\'ajol k\'a winaq rutzijil kub\'anoq. Chik wuj, ri awäch rech tikonel xk\'ik ri k\'ik kub\'anoq, kiwäch rech xqatäqil ri chik\'ajol, b\'e ri chik\'inb\'al ri a xk\'utij kiwi\'. Chik winaq ruk\' ri k\'ik rech ri ri\' xk\'utij kub\'anoq ri\' ri q\'ij, rech ri ri chik\'ajol chik\'ayij k\'a k\'olal chik\'ajol k\'a winaq rech k\'at sachat.', '<span>Xb’anob’äl ri b’anoj, ri k’ulik yal kik’in ri b’anob’äl. Ri k’ulik pa k’o junam ri b’anik ri kik’in pa ka kik’in pa ri kik’otem. Pa ruk’u’x kik’in, ri Xb’an k’o ri k’o yal k’o, k’o junam ri ruwäch k’ulik, xaq man kikotemik pa ka kik’in ri kik’o ri kik’in yal kik’aj k’o. Pa k’o, junam ri kik’in yal kik’o xkojik junam xb’an pa ka ri kik’in yal kik’in ri b’an yal kik’ul ri b’anob’äl. Kik’in ri k’ulik xkojik pa ka kik’o ruwi’ yal kik’in ri k’ulik yal kik’in ruwäch ri b’anob’äl yal kik’in ruwäch ri q’aq’al pa ka ri kik’ul ri k’aslemal ri kik’in yal ri kik’aslemal chik.</span>
', 'U yantal u k\'áatil, u ts\'akbal yéetel u ts\'ookil. Es u chúumukil u ts\'aabal jump\'éel ba\'ax u ts\'o\'ok u yantal. Ti’ le k’iin ka’anal, le K’ex tu beetike’ex tu yilaj tu beetik, u máano’ob tu tsikbal, beyo’ ma’ u ts’o’ok tu yantal ti’ le ba\'axo\'ob u k’áat u ts\'ook. Ti’ le k’iin ku, jump’éel ba\'ax u ts\'aabal yéetel u yantalil u béeytal u k\'a\'atal yéetel u ts\'akbal. Ts’áabal u k\'áat yéetel u k\'áatil u beetik yéetel u ts\'o\'ok u yaantal le kuxtal kaajil yéetel u ts\'ook u yantal tu yilaje’ex.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (7, 8, 'Lamat', 'La estrella', 'Representa el arte, la belleza, la elegancia, la armonía, la creatividad, pero también el pensamiento abstracto, el mundo de las ideas y la producción intelectual. Las personas Estrella gozan hasta de un garbo natural, y si bien su misión es desarrollar su gran creatividad pueden perderse fácilmente en el plano racional. En sombra buscan el perfeccionismo, dañando su sistema nervioso. En luz pueden llegar a ser grandes y virtuosos artistas. Es importante que dejen la terquedad de lado, la necesidad de relativizarlo todo y de querer encontrar la verdad en la mente conceptual.', 'Kin_7', 'Lamat', 'It represents art, beauty, elegance, harmony, creativity, but also abstract thinking, the world of ideas, and intellectual production. Star people enjoy a natural grace, and while their mission is to develop their great creativity, they can easily get lost in the rational realm. In shadow, they seek perfectionism, damaging their nervous system. In light, they can become great and virtuous artists. It is important for them to set aside stubbornness, the need to relativize everything, and the desire to find truth in conceptual thought.', 'Ri ri ak\'awal, ri winaq, ri ak\'aslemal, ri armonía, ri q\'ijalaj, käch ri ajch\'isal kub\'anoq, b\'e k\'a ri ri q\'ij ri chik ri k\'ut winikaj chikin chik\'ajol, chi k\'ut k\'aslemal ri le k\'i\'ix ri k\'u\'l ri k\'i\'ix q\'ijalaj, b\'antä chi rech ri k\'u\'l k\'o ri xkib\'al rech ri ak\'aslemal rech ri q\'ij. Chik winaq ujun wi\' ri winaq q\'ij, ri winaq chik\'ajol, b\'antä rech chik k\'u\'l k\'o k\'olal chi rech k\'i\'ix, ri winaq chik\'ajol rech k\'ut b\'anoj. K\'a tijox winaq chik ulew chi\' chi\' k\'o\'olal, ri k\'i\'ix ri k\'o ri q\'ijalaj, b\'e ri chik\'ajol ri wi\' ri k\'u\'l.', '<span>Xb’anob’äl ri ruq’ab’äl, ri k’aslemal, ri xajo’ k’aslemal, ri ch’ab’äl k’ul, ri k’otemab’äl, xaq xb’anik ri tijob’äl chi k’amik, ri nimanel pa tzijob’äl yal ri k’o yal kik’in ri b’anob’äl chik. Ri qach’ab’äl Q’ij kikotemik pa ka xb’anol jun k’ul yal kik’o yal kikotemik, xaq man xkojik pa ka kik’in chi k’amik. Pa ruk’u’x kik’in xb’anol kik’in ri k’amol k’ul, xb’anik ri k’ulik ri ch’ich’ yal kik’aslemal. Pa k’o kikotemik pa ka kik’in junam chi ruq’ab’äl yal kikotemik. Ri k’ulik xkotzij pa ka kik’o ri k’aslemal pa ka kik’o ri k’ulil, ri xk’o pa ka kik’o junam ri tzij pa ka ri kik’in chi k’amik ri nimaj tzij.</span>
', 'U yantal le k’iin, le naj, le tsool, le noj k’iin, le chi’ibal, beyo’o’ jump’éel ka’anal tu k’aay, le k’iinil máako’ob yéetel u ts’ookililil kaambalil. Le máako’ob Xanab ku yantal tu yilaj ti’ jump’éel ka’anal najil, yéetel bey xan u ts’ook u yantal u chi’ibalil chi’ibalo’ob ku yaantal tu ka’anal ti’ le ba’axil, ku yaantal u beetik tu yáaxil k’iin. Ti’ le k’iin kaanil ku k’aat u yaantal u yáaxilo’ob k’iino’ob, u ch’íibalil u noj kuxtalil. Ti’ le k’iin ku ts’o’ok u yaantal yéetel u ts\'ook u ts’ookilil yéetel tu nojoch k’iin. Jump’éel ba’al u ts\'ookik ti’ ku ts’aabal tu k’íinsajil u kuxtal, u k’áat u yantal jump’éel le ba’axil yéetel u k’aatal u yantal u beetik tu yilaj le k’iinil tu chik’in tu k’iin.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (8, 9, 'Muluk', 'La luna', 'Es el mundo de las emociones. La Luna lo siente todo, su sensibilidad es vasta y todo le impacta profundamente. De hecho es capaz de saber cómo se siente cada persona a su alrededor, tendiendo a querer acobijar a todo el que sufra. Esto puede traerle muchos problemas ya que se cargará de cosas que no le corresponden. En este sentido goza de una poderosa intuición y de una gran imaginación. Representa la energía de lo femenino, el poder de las aguas y la maestría en relación a los elementos de la naturaleza. Necesita trascender el drama ahí donde lo ve, purificarse de todo lo que sienta y dejarse fluir.', 'Kin_8', 'Muluc', 'It\'s the world of emotions. The Moon feels everything; her sensitivity is vast, and everything deeply impacts her. In fact, she\'s capable of sensing how everyone around her feels, often wanting to comfort anyone who\'s suffering. This can bring her many problems as she\'ll carry burdens that aren\'t hers to bear. In this regard, she enjoys a powerful intuition and a vivid imagination. She represents the energy of the feminine, the power of the waters, and mastery in relation to the elements of nature. She needs to transcend the drama where she sees it, purify herself of all she feels, and let herself flow.', 'E li ri k\'aslemal ri awäch. Ri Ruk\'uk\'ulew chik ri k\'aslemal, xk\'ux kib\' chik, b\'antä xk\'ux wäqil chik. Chik ajanel ri k\'aslemal rech k\'ut wan taq k\'o ri winaq k\'utäj, chi riwäch ta\' achawäch ri k\'ot. Xkib\'aj chik tijox chi\' rech winaq, chi winaq chik ajch\'umal ri kib\'äl che\' ri b\'anoj ri xk\'ux kib\'äl. Chik nimaq tijox ri energia k\'ak\'ik\', ri winaq che\' ri poder ri k\'ak\'ik\', b\'e ri k\'aslemal rech k\'ut kib\'äl ri jun ch\'umil rech ri le k\'i\'ix ri chik\'ajol. K\'utz xuquje\' taq k\'o ri tijox k\'ot, chi purificar k\'u\'l chik\'ajol rech k\'ut nimaj tz\'ikin, b\'e xche\' ri tijox xkib\'aj.', '<span>Ri nimanel pa ri k’aslemal yal b’anob’äl. Ri Iximulew kik’in pa ka xb’ano yal b’anob’äl, ri k’ulik yal kik’in ch’umil yal kik’ulik. Ronojel xb’ano pa ka kik’o junam ri kik’in yal kik’in k’o jun ri kik’in k’ulik, xkojik pa ka kik’in yal kik’ulik ri xib’ano yal kik’o. Ri xb’anol pa ka ri kik’in ri k’ulik ri q’aq’alal ri kik’in pa ka ri kik’o, kik’otemik chi k’ul ri k’ulik ri k’ulik. Xb’anob’äl ri ruwäch k’ulik ri ch’ab’äl kik’in, ri k’ulik ri ya’ yal kik’in yal ri k’otemab’äl pa ka ri nimanel yal ri tz’aqol ri k’aslemal. Kik’in ri k’ulik xkojik pa ka ri kik’o ri tukel ri kik’in yal ri kik’in, pa ka kik’o ri kik’ulik ri kik’in yal kik’in ruwi’ yal kik’in.</span>
', 'Es u k’iinil le sáasilo’ob. U tsukbal u yantal jump’éel ba\'ax, u ts’o’oksaj jump’éel tu k’aay yéetel jump’éel ba\'ax u k’áat u yantal tu yóok’ol k’iin. Tu yáaxo’ob, u k’a’atal u yantal beyo’ u yil u máako’ob yéetel u béeytal u yantal u ts\'ook ti\' jump’éel u yaantal jump’éel. Le ba’ax u ts\'o\'ok u yóok\'ol ti’ jump’éel ba’alo’ob u ts\'ookil, beyo’ob u ts\'ook u yilaj jump’éel ka’analil tu tsikbal yéetel jump’éel nojochil tu chi’ibal. U yantal u kuxtalil le ka’anal, u chúumukil le cha’ako’ob yéetel le ts’aakaj tu yilaj le k’iino’ob le k’áak’nal. Ts’áabal u k\'áatil u k’iinil le k’iinil ti’ u yil u ts\'ook ti’, u beetik ts’ook ti’ jump’éel ba\'ax u yantal yéetel u yantal tu ka\'anal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (9, 10, 'Ok', 'El perro', 'Es la energía del amor incondicional. El Perro representa la fidelidad, la lealtad y el compañerismo, es el guardián de sus seres queridos. En sombra tiene problemas de autoestima, dando siempre demás a quienes no le corresponden y exigiendo en consecuencia. En luz es capaz del máximo altruismo, sabiéndose amar a sí mismo primero, poniendo límites sanos a todo lo que no le haga bien en sus relaciones afectivas y amando sin aprehensión. Tenderá a dedicarse de alguna u otra manera a proyectos sociales, a hacer el bien por la humanidad. En este sentido tendría que tener cuidado con inconscientemente actuar como el salvador de los demás.', 'Kin_9', 'Oc', 'It\'s the energy of unconditional love. The Dog represents loyalty, fidelity, and companionship; it\'s the guardian of loved ones. In shadow, it has self-esteem issues, always giving too much to those who don\'t reciprocate and demanding in return. In light, it\'s capable of utmost altruism, knowing how to love oneself first, setting healthy boundaries with anything that doesn\'t serve its well-being in relationships, and loving without attachment. It tends to dedicate itself in one way or another to social projects, doing good for humanity. In this sense, it should be careful not to unconsciously act as the savior of others.', 'E ri k\'utb\'altzij ri k\'amor ch\'uti\'. Ri Tz\'i\' ri b\'anoj, riqaj laj b\'a\' k\'ut, ri q\'ij, y riqaj laj k\'ut. Rech xk\'utemajol re, chi k\'utal ri winaq chiq\'ui\' chi k\'ulew, chi akajol k\'ut ri winaq ri wach, che\' winaq k\'u\'nimal rech k\'ut. Rech chi wi, k\'utemajol k\'ulew chik, k\'utemajol chik ri k\'amor ri wi k\'ut chik, ri\'aj chi\'ut k\'utab\'äl ri b\'a ri xcha\' ri wi k\'amor ch\'uti\' chi rech taqajol re ri winaq xk\'utik. Q\'eqetaj rech xk\'ulew xkatun re ri\' winaq xewaq. Rech chi wi, q\'eqetaj rech xk\'utijonik chik la q\'ij ulew k\'utb\'altzij chik.', '<span>Ri k’ulik ri b’anob’äl ri k’a’ tzij. Ri Tz’i’ xb’anob’äl ri k’a’ k’ul, ri k’a’ ch’ab’äl yal ri tzijonik, k’o ri k’ajolaj ri nimaj k’o pa ri kik’aslemal. Pa ruk’u’x kik’in kik’in pa ka ri kik’o ri q’aq’alal yal kik’in, xb’anol pa ka kik’in yal kik’in ri k’o yal kik’in ri man kik’o junam yal kik’in, xkojik pa ka ri kik’o ri k’ul ri kik’in. Pa k’o kik’in pa ka xb’ano jun nima’j xajo’ kik’in, xb’anol ri kik’in yal kik’in ri k’o yal kik’in chik, xkojik pa ka kik’in ri k’ulik yal kik’in ri kik’in pa ri kik’in pa ka kik’in ri nimaj k’a’ yal kik’in, xb’anol yal kik’in man xajo’ chik. Xkotzij pa ka kik’in yal kik’in ri kik’otemik chi k’amik pa ri nimaj k’a’ yal kik’in, pa ka xb’ano chi k’a’ yal ri b’anob’äl. Pa ri k’ulik kik’in kik’in pa ka kik’o ri kik’in yal ri kik’in xb’anol k’o ri k’aslemal pa ka ri kik’o.</span>
', 'Es u kuxtalil u k’áatal jump’éel bix u yantal u ya’abachil. U Peek’ u yantal u ka’analil, u nojochil yéetel u ts’ookil kaajil, es u chúumukil ti’ u máako’ob u yilak u k’a’abachil. Ti’ le k’iin ka’analil u yáaxalil tu tsikbalililil ka’anal, u beetik yaan jump’éel ba’ax ma’ u yantal ti’ u yóok’ol k’iin yéetel u ts\'ookil ti’ le ba’ax u ts\'ook. Ti’ le k’iin ku u béeytal jump’éel ka’ansaj kaambal, u yantal u beetik tu yóok’ol k’iin beyo’ob, u ka’ansaj tu tsikbalil ka’anal ti’ jump’éel ba\'ax ma’ u ts’aabal u beetik yéetel u yaantal ts’ook ti’ u yóok’ol k’iin yéetel ts’ook ti’ u yóok’ol k’iin. U k’áat u yantal jump’éel beetil tu ka’anal yéetel le k’iino’obil kaambalil, u beetik le k’áatil tu kaambalil tu kuxtal. Tu le ba’axil u ts\'o\'ok u k\'áat yéetel jump’éel k\'iin tu yilajil u yantal beyo\'ob u nojoch u ts\'ookil ti\' u yóok\'ol kaajo\'ob.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (10, 11, 'Chuwen', 'El mono', 'Es el niño interior que con su sabiduría ilumina la vida de los demás. En luz es el sentido del humor, lo lúdico, la irreverencia que cuestiona todo como jugando. En sombra suele tender a tomarse todo demasiado en serio y actuar como el abogado defensor de las causas justas. No se permite relajarse y guarda situaciones de la infancia por resolver. Su misión será mostrarle al mundo que nada es tan sólido como parece y que a veces es necesario confrontarnos desde la risa para lograr soltar el ego.', 'Kin_10', 'Chuen', 'It\'s the inner child who, with its wisdom, illuminates the lives of others. In light, it\'s the sense of humor, the playful spirit, the irreverence that questions everything as if playing. In shadow, it tends to take everything too seriously and act as the defender of just causes. It doesn\'t allow itself to relax and holds onto unresolved childhood situations. Its mission will be to show the world that nothing is as solid as it seems and that sometimes it\'s necessary to confront ourselves through laughter to let go of the ego.', 'E ri\' q\'ij b\'i k\'ut rech chi k\'utemajol chik la ri b\'anoj xchiq\'ui\'. Rech chi wi, k\'utemajol rech k\'ut la yala\' ri chik, la awa\'l, la chwäch\' k\'ut xch\'upk\'ij ri b\'i chi rech chwäch\'oj chik. Rech chi winaq taqi\', k\'utemajol xk\'utk\'uch ri b\'i ri xcha\' chiq\'ui\' la xch\'utk\'uch. Rech chi b\'anoj chi\' wi, chi b\'i\' taq k\'ut q\'eqetaj k\'ut la wachaj chi\'ut chik y chi winaq la winaq chiq\'ui\' chi awa\'l. Ri\'aj chi chik chik chik k\'ut rech k\'utemajol chik ulew xchiq\'ui\' ulew chik ri b\'i xcha\' ulew.', '<span>Ri nim q’ij ri k’aslemal ri kik’aslemal chi k’amik ri k’ulik ri nimaj k’o. Pa k’o ri k’ulik ri xajo’ k’ul, ri nimanel ri tijob’äl, ri k’ulik ri man kikotem yal kik’o chi k’amik ri tzij. Pa ruk’u’x kik’in xb’anol chi k’amik pa kik’in yal kik’in, xkojik pa ka ri kik’in ri ruwi’ yal kik’in ri b’anob’äl chi k’amik ri nimaj k’a’ yal kik’in. Man xkib’anol chi k’amik yal kik’in ri nimanel ri kik’in pa ri nimaj tzij. Ri xb’an kik’in ri kik’o yal kik’in chi k’amik ri nimanel pa ka ri kik’in ri nimaj k’a’ man xajo’ chik ri ja’ yal kik’in k’o, yal ri kik’in pa ka ri kik’in ri kik’otem ri tukel chi k’amik pa ka ri kik’o ri q’aq’al k’ul pa kik’o kik’in ri k’aslemal.</span>
', 'Es u ts’o’ok ti’ u máak’ab tu yóok’ol k’iin u yantal u yáaxil tu kuxtalil u máako’ob. Ti’ le k’iin ku es u tsikbalil tu tsikbal, u k’aay, u najil u beetik tu yaantal u yóok’ol kaajil bey jump’éel k’iin. Ti’ le k’iin ka’analil u ts\'o\'oksaj tu yaantal u tsikbal u tsikbal tu yaakuntik yéetel u yantal u beetik jump’éel abogado tu beetil le k’iino’ob ka’ansaj. Ma’ u yantal u chokoj yéetel u yaantal tu tsikbalil ti’ u máak’ab ti’ u tsikbal. U ts’ook u yantal u yóok’ol k’iin bey jump’éel ba’ax ma’ tu yilaj jump’éel tu chichan yéetel u ts’o’oksaj u beetik ti’ u yilaj tu tsikbal ti’ le k’áatal ti’ u yaantal u chi’ u ts\'ook.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (11, 12, 'Eb\'', 'El humano', 'Representa el más alto estándar de integridad. Es el sabio que defiende las causas justas, habitualmente sacrificándose en el proceso. En luz está en conexión profunda con su libertad y sabrá equilibrar su gran necesidad de generar armonía alrededor suyo con el camino que quiera elegir. En sombra, se pospondrá por el resto o caerá en la indecisión aguda de no saber qué decisiones tomar, por tener un concepto rígido del deber ser.', 'Kin_11', 'Eb', 'It represents the highest standard of integrity. It\'s the wise one who defends just causes, often sacrificing themselves in the process. In light, they are deeply connected to their freedom and will know how to balance their strong need to generate harmony around them with the path they choose to take. In shadow, they may defer to others or fall into acute indecision, not knowing which decisions to make, due to having a rigid concept of what should be.', 'Rech taq k\'ut k\'utb\'alaj chik taq awal rech chi q\'eqemajal b\'i\'. Rech chi winaq k\'utemajol rech chi k\'o\'j wi, xecha\' chi b\'anoj chik b\'i chik, k\'ut qach\'ab\' chik rech chi b\'i. Rech chi wi, taqi\' rech b\'i\' xk\'utk\'uch k\'ut wi k\'utemajol chik k\'u rech winaq chik xk\'utk\'uch ulew chi\'ut chik rech k\'utemajol chik b\'i ri\'. Rech chi b\'anoj, rech qach\'ab\' k\'u xkib\'äl rech b\'i k\'u rech xk\'utb\'äl ajinaj rech chi k\'utemajol b\'i\', b\'i\' ri k\'ut taq xkib\'äl k\'u chi k\'u\'x chi rech k\'utemajol k\'ut chi.', '<span>Xb’anob’äl ri nima’j nimaj k’ulik ri kik’aslemal. K’o ri ajq’ij xb’anob’äl ri nimaj k’a’ yal kik’in, xaq k’o ch’ab’äl ri nimaj ri kik’in pa ri k’o. Pa k’o ri k’ulik ri kik’o pa jun nima’j xajo’ yal kik’in ri kik’ul yal kik’in yal kik’o ri kik’in pa ka ri kik’in ri k’ulik ri tzijonemil xajo’ ri k’o ri kik’in yal kik’in chik. Pa ruk’u’x kik’in, kik’in ri kik’o pa ka kik’in ri kik’aslemal o kik’in ri kik’in pa ka kik’o ri junam ri kik’in pa ka kik’in ri nimaj tzijonemil, rumal kik’in ri kik’in ri nimaj k’a’ yal kik’in chi k’o.</span>
', 'U yantal le najilil u chi\'ibal kuxtal. Es u nojoch u ts\'aabal u k\'iino\'obil ka\'ansajil, ti\' jump\'éel tu yo\'osal ku yaantal u ya\'abachil ti\' le k\'iinil. Ti\' le k\'áanalil ku yaantal jump\'éel nojoch u yantal ti\' u yóok\'ol k\'iin yéetel u k\'áatal u yantal u ts\'ookil u kuxtal u yáaxal u yantal u tsikbal tu yóok\'ol k\'áak\'nal ti\' jump\'éel ba\'ax u ts\'aabal u beetik. Ti\' le k\'áanalil ku ts\'ookik tu yóok\'ol yéetel ku yaantal u béeytal u ma\'alobil ti\' u yilaj u béeytal u yaantalil u beetikil, bey ma\' u ts\'ookik u k\'áatil tu yilaj jump\'éel tu yilaje\'ex chichan tu beetike\'ex.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (12, 13, 'B\'en', 'El caminante del cielo', 'Es el explorador, el buscador del sentido último de la existencia. Su principal motivación es conocer, conocerlo todo, sobre todo otras culturas, otros territorios, otros saberes, otras idiosincrasias. En luz, sabrá dejarse guiar por su intuición y todo lo que conozca logrará transformarlo, para luego compartirlo con el mundo. En sombra, el escepticismo le jugará malas pasadas, y solo buscará que conocer hacia fuera, sin tener el coraje de viajar dentro suyo ni de encontrar un camino espiritual.', 'Kin_12', 'Ben', 'It\'s the explorer, the seeker of life\'s ultimate meaning. Their main motivation is to know, to know everything, especially about other cultures, territories, knowledge, and idiosyncrasies. In the light, they will know how to be guided by their intuition, and everything they learn will be transformed, to then be shared with the world. In the shadow, skepticism will lead them astray, and they will only seek to know outwardly, lacking the courage to journey within themselves or to find a spiritual path.', 'Rech chi k\'ajolaj, rech chi q\'eqemajol ri b\'i\' chik wi k\'ut rech ri b\'i\' ri\'. Ruk\'u\'x k\'ut b\'i\' k\'ajolaj wi k\'ut, k\'ajolaj chik taq b\'i\' k\'u rech k\'utemajol, k\'u xkib\'äl, k\'u xk\'ajolaj, chik k\'u xk\'utemajol ri b\'i\'. Rech chi wi, taqi\' k\'utemajol rech chi\'uk\' ri k\'ut k\'ut k\'u wi k\'ut, chik taq k\'ut xkib\'äl b\'i\' k\'u k\'u xkib\'äl, b\'i\' ri rech k\'utemajol ri chik. Rech chi b\'anoj, rech b\'i\' qach\'ab\' k\'u rech xkib\'äl ajinaj k\'ut ri b\'i\' chik wi k\'ut chik, xewitzel k\'u ri k\'utemajol b\'i\' chik wi k\'ut chi b\'anoj.', '<span>Ri nimanel pa ri k’ulik, ri k’otemaj pa ka xb’ano ri nimaj tzij pa ri k’aslemal. Ri k’ulik ri kik’in yal kik’in chi k’amik pa kik’in ri kik’in, kik’in ri kik’in, xaq junam ri nimaj qach’ab’äl, ri nimaj ya’ yal kik’in, ri nimaj ruwi’ yal kik’in, ri nimaj qach’ab’äl chi k’amik. Pa k’o ri k’ulik kik’in ri kik’o yal kik’in pa ka xb’anol yal kik’in ri kik’in pa ka ri kik’in yal kik’in chi k’amik, yal kik’o chi k’amik ri kik’in yal kik’in pa k’ul k’o yal kik’in. Pa ruk’u’x kik’in, ri k’aslemal chi k’amik kik’in ri kik’o junam ri kik’in yal kik’in chi k’amik ri kik’in, yal kik’in kik’in pa ka kik’in ri kik’in chi k’amik pa k’ul k’o yal kik’in, man xb’anob’äl chi k’amik ri kik’in pa kik’in ri kik’in chi k’amik yal kik’in ruwi’ yal ri kik’in k’ul.</span>
', 'Es u máax u tsikbalil, u yaantal u kuxtalil u yáaxil tu ka’analil kuxtal. U nojoch u ts\'ookil u k\'áatal u yantal, u yantal jump\'éel ba\'ax, bey xan jump’éel tu tsikbalo\'ob tu yaanal, tu ka’ano\'ob, tu tsikbalo\'ob, tu ya\'abalo\'ob. Ti\' le k\'áanalil u béeytal u yaantal ti\' u chi’ibalil yéetel jump’éel ba\'ax u yantal u béeytal u ts\'aabal u k\'áatal, ti\' jump\'éel k\'iin u béeytal u yantal ti\' le k’iin. Ti\' le k\'áanalil, u kuxtal u k\'a\'atal jump\'éel chi’ibalil ya\'abachil, yéetel jump\'éel u yaantal u k\'áatal ti\' jump\'éel, ma\' u ts\'ookik u k\'áatil u tsikbalil ti\' u yóok\'ol k\'iin ni\' u yantal u tsikbalililil ti\' u yantal u ts\'ook.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (13, 14, 'Ix', 'El mago', 'Es el que con su encanto natural logra transformarlo todo. Artista, performer, alquimista, sanador, brujo, ingeniero, consejero, orador. En luz, podrá cumplir con su misión de ser fuente de inspiración para los seres humanos, en sombra la soberbia lo llevará a preocuparse solo por la valoración externa, por los aplausos.', 'Kin_13', 'Ix', 'It\'s the one who, with their natural charm, manages to transform everything. Artist, performer, alchemist, healer, wizard, engineer, counselor, speaker. In the light, they can fulfill their mission of being a source of inspiration for human beings; in the shadow, pride will lead them to worry only about external validation, about applause.', 'Rech ri k\'ut ri\' k\'utemajol rech ri ri\' ta k\'u xk\'utemajol ri b\'i\' chik. Ri\'atz\'ib\'al, ri\'malaj, ri\'k\'utnäch, ri\'xk\'ajolaj, ri\'maj b\'i\', ri\'winaq, ri\'tz\'utuj, ri\'jak\'aq. Rech chi wi, chi k\'u\'xk\'utemajol ri rech b\'i\' ta k\'u ri k\'ut ri\' k\'u\'xk\'utemajol ri winaq, chik taq chi\'uk\' chik wi k\'u k\'u k\'ut b\'i\' k\'u b\'anoj.', '<span>Ri xkojik ri k’ulik ri k’aslemal yal kik’in ri nimanel chi k’amik ri nimaj. Ri ajq’ij, ri q’ijob’äl, ri k’ulchi’ k’ul, ri k’ulik yal kik’in ri b’anob’äl, ri k’aslemal, ri k’ulchi’ k’ul, ri q’aq’alal, ri xb’anob’äl. Pa k’o ri k’ulik kik’in ri kik’o yal kik’in pa kik’in ri kik’o junam ri k’ul pa ka xb’ano yal kik’in ri nimaj k’o, pa ruk’u’x kik’in ri q’aq’al kik’in ri kik’o junam ri kik’in yal kik’in chi k’amik ri kik’in pa k’ul kik’in ri b’anol yal kik’in, ri nimaj xajo’ chi k’amik.</span>
', 'Es u ts\'ookil u yantal u k\'uxubil najil u béeytal u ts\'aabal jump\'éel ba\'ax. Artista, performer, alquimista, ts\'akab, x\'men, k\'áak\'naab, nojoch k\'aayil, orador. Ti\' le k\'áanalil, u béeytal u yaantal u ts\'ook u yantal u yáaxal u yantal u yilaj tu máako\'ob tu kuxtal, ti\' le k\'áanalil u ka\'anal u yantal tu yilaj jump\'éel tu yaanal u beetik yéetel u yaantal ti\' le k’iino\'ob.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (14, 15, 'Men', 'El aguila', 'Representa la visión panorámica, la agudeza analítica y la creatividad de vanguardia. Es visionaria y muy profunda, sintiéndose siempre responsable del bienestar ajeno. En luz logrará creer en sí misma para emprender el vuelo y evolucionar, en sombra se quedará procastinando distrayéndose con todo lo que su mente es capaz de vislumbrar, y poniendo el bien común adelante de sus prioridades como pretexto.', 'Kin_14', 'Men', 'It represents the panoramic vision, analytical acumen, and cutting-edge creativity. It\'s visionary and very profound, always feeling responsible for the well-being of others. In the light, she will believe in herself to take flight and evolve; in shadow, she will procrastinate, distracting herself with everything her mind can envision, and putting the common good ahead of her priorities as a pretext.', 'Rech ri xk\'otik ri\'chiq\'aj, ri\'wak\'ib\' ri\'wi\' ri\'k\'utemajol ri b\'i\' chik. Ri\'k\'otikaj wi, chiri ch\'umil, chi winaq chik k\'u ri q\'ij k\'ot xk\'otikaj, chik ri\' ch\'umil rech chik chi k\'utemajol ri b\'i\' rech winaq, chik taq ri\' k\'u ri\' xk\'otikaj, chi rech b\'i\' rech ri\'wi\', chik k\'ajol ri\'xk\'utemajol ri k\'i k\'ut ri\' yinak.', '<span>Xb’anob’äl ri xajo’ k’ul pa ri nimanel, ri xajo’ chi k’amik yal kik’in yal ri k’otemab’äl chi q’ij. K’o jun ch’ab’äl yal kik’in, xb’anol pa ka kik’in ri kik’ul yal kik’in, kik’in pa ka kik’in ri kik’ul yal kik’in ri b’anob’äl chi k’amik. Pa k’o ri k’ulik kik’in ri kik’o yal kik’in pa kik’in kik’in pa ka kik’o ri kik’in yal kik’in kik’otemik, pa ruk’u’x kik’in kik’in pa ka kik’in ri kik’in ri kik’o chi k’amik ri kik’in yal kik’in kik’o pa ri nimaj k’a’ yal kik’in, yal kik’in ri kik’o chi k’amik ri b’anob’äl k’ul pa ri nimaj ri kik’in pa ka ri nimaj k’a’ chi k’amik.</span>
', 'U yantal le ts’ookbilil xíimbal, le chi’ibalil analítico yéetel le chi’ibalil tu yóok’ol kaajil. Es u ts’ookbilil yéetel jump’éel najil tu tsikbal, u yantal jump’éel ba’ax u yantal u k’iino’obil ti’ u tsikbalil le kaajo’ob. Ti’ le k’áanalil u ts’o’okol u yantal ti’ u yóok’ol k’iin u béeytal u béetbilil yéetel u tsikbalil, ti’ le k’áanalil u béeytal u tsikbal u ts’áabal ti’ jump’éel k’iin yéetel jump’éel ba’ax u tsikbalil yéetel u yantal ti’ jump’éel u tsikbalil tu ka’anal, yéetel u yantal le kuxtalil kaajil tu chik’ul ti’ u yaantal tu tsikbalo’ob bey jump’éel tsikbal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (15, 16, 'Kib\'', 'El guerrero', 'Es el samurai, el que con disciplina y entrega se entrena para ir a la batalla a ganar. Pero la batalla no es el conflicto, es la posibilidad de transformar la realidad, aquello que es injusto, de manera estratégica, intrépida, frontal y sobre todo humilde. Un Guerrero en sombra lo cuestiona todo solo por ego, incluso a sí mismo, autoboicoteándose. En luz es el maestro espiritual, perfil bajo, que ilumina con sus acciones.', 'Kin_15', 'Cib', 'He is the samurai, who with discipline and dedication trains himself to go into battle to win. But the battle is not the conflict; it is the possibility of transforming reality, that which is unjust, in a strategic, fearless, frontal, and above all humble manner. A Warrior in shadow questions everything only out of ego, even himself, sabotaging himself. In the light, he is the spiritual master, low-profile, who illuminates with his actions.', 'Ri\'k\'iche\' k\'ot, ri\' re k\'ot samurai, chi ch\'ajij k\'u ri tijonel chik taq ri k\'otol, k\'u chiri k\'otol, k\'u b\'i\' ri xk\'otol rech k\'u ri k\'otol, b\'i\' ri k\'otol k\'u chi xk\'otol xk\'utinaj, xk\'ulew, xa k\'i\'wi\', xa k\'i\'ikaj k\'ab\'ajel ri k\'u\' rech k\'u xk\'utinaj. Ti rej k\'otol ri\'xk\'utinaj chiri k\'ot, ti ch\'ab\'ab\' k\'u ri k\'ot, xk\'utinaj k\'u k\'i\', xk\'utinaj k\'u aj ch\'utemajal, k\'u aj k\'ajol k\'u tijonel chik.', '<span>Ri samurai, ri k’o pa k’ulik yal kik’in ri nimanel chi k’amik ri kik’otemik pa ka ri k’ul chi k’amik. Xaq ri k’ul man xb’ano ri tzij, xb’ano ri nimanel pa ka xb’ano ri nimanel chi k’amik, ri ja’ chi k’amik, pa jun nima’j nimaj k’ul, xajo’ k’ul, xajo’ chi k’amik yal ruwi’ yal kik’in k’a’. Jun Ajchajil pa ruk’u’x kik’in xb’anol chi k’amik junam ri tzij ri kik’in yal kik’in chi k’amik, xaq xb’anol ri kik’in yal kik’in, xb’anolik chi kik’in. Pa k’o ri k’ulik kik’in ri k’o jun nima’j ajq’ij k’aslemal, xajo’ ruwi’ chi k’amik, xb’anob’äl pa kik’in ri nimaj k’o chi kik’in yal kik’in.</span>
', 'Es u samurai, le máak’ ku beetik tu ka’anal yéetel u ts’ook ti’ k’áat u xook ti’ jump’éel k’iin ku ya’abil. Ba\'ale\' le k’iin ma’ u ts\'ook, es le ku ka’analil u ts’aabal u ka’anal, le ba\'axil ku k\'a\'atal u yáaxil tu tsikbal, le ba\'ax ma\' u nojoch, ti’ u chi\'ibalil, u k’a’analil, yéetel jump’éel ch’aak’ yéetel u yantaj tu ka\'anal. Jump’éel B’a’alam tu k’iin ma’ ts’aabal u tsikbalil le ku ya’abil tu yóok’ol u kuxtal, ti’ jump’éel ego, beyo’ xan ti’ u bey, ku ya’anal u yaabil tu tsikbalil. Ti’ le k’áanalil es u nojoch k’aay, najil, le máak’ ku yáantal tu ya’abil yéetel u ts’ook ti’ jump’éel le ba\'ax ku beetik.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (16, 17, 'Kab\'an', 'La tierra', 'Representa la estabilidad suprema. Es la dadora de base, de estructura, tanto en el plano físico como en el emocional, psíquico o espiritual. Suelen ser personas bastante fuertes que logran impulsar, con su gran empuje, a que se genere aquello que hace falta para salir adelante. En sombra caen en la sobre interpretación, en ser retadoras, creando argumentos solo para validar aquello con lo que se han entercado. En luz, saben que la verdadera estabilidad es fluir con lo que la realidad les propone, sin presionar, sin recurrir a la fuerza.', 'Kin_16', 'Caban', 'She represents supreme stability. She is the giver of foundation, of structure, both in the physical and in the emotional, psychic, or spiritual plane. They tend to be quite strong individuals who manage to propel, with their great drive, the generation of what is needed to move forward. In shadow, they fall into over-interpretation, being challengers, creating arguments only to validate what they have set their minds on. In light, they know that true stability is to flow with what reality proposes, without pressuring, without resorting to force.', 'Ri rutz\'ij ri e wach chiwäch. Chi ri taqawäch, ri wuj, xk\'utinaj ri wäch, ki\' rej k\'a ri tzukub\'aj chi k\'otol chik ri k\'otol wi, xk\'utinaj ki\' rej k\'a ri tak\' k\'u k\'otol, ri uq\'ijil, utz\'ijil, k\'u k\'otol k\'ajol k\'u wuj. Ti chiri\' xk\'utinaj, chi k\'otol wuj, chiri ta chik k\'ajolaj k\'u rech, ta k\'u ch\'ok ri k\'otol rech, xk\'utinaj ujol wi\' chi wakax ri k\'u ch\'ok. Ti wi\' chiri, chi ri k\'otol xk\'utinaj k\'u q\'eqi\', k\'u ri k\'otol tzukub\'aj rech wi\', ta\' wi\' k\'a\' ri k\'i\' ri k\'otol k\'u wach, k\'u utz\'ijil.', '<span>Xb’anob’äl ri nimaj tzijonemil ruwi’. K’o ri k’ulik yal kik’in ri k’o pa ri nimanel, pa ri ruwi’ yal kik’in, xaq junam ri k’aslemal yal kik’in, ri k’aslemal chi k’amik yal kik’in o ri k’aslemal k’ul. Xb’an pa ka kik’o ri kik’in yal kik’in chi ruwi’ yal kik’in chi k’amik, kik’otemik pa ka kik’in ri kik’in chi k’amik ri kik’in yal kik’in kik’o. Pa ruk’u’x kik’in, kik’in ri kik’in pa ka kik’in ri kik’in ri kik’in chi k’amik, xb’anol chi k’amik, xb’anol ri tzij yal kik’in kik’in ri kik’in pa ka kik’in ri nimaj ri kik’in yal kik’in. Pa k’o ri k’ulik kik’in kik’in ri kik’in chi k’amik ri nimaj tzijonemil k’ul xb’anol pa ka kik’in ri nimaj ri kik’in yal kik’in pa kik’in, man xajo’ chi k’amik, man xb’anol yal kik’in chi k’amik.</span>
', 'U yantal le nojoch ts\'o\'okil. Es u beelil u nojoch k\'iin, le estructura, tu yáaxil tu k’iin, ti’ u yóok’ol kuxtal yéetel tu yóok’ol yóok\'oltik, tu yóok’ol k’iin yéetel tu ka’anal. Ku ya’abil jump’éel máako’ob ku ts’ook u kuxtalil, ku yáantaj tu ts\'ookil, u k’a’atal u ya’abil le ba’ax ku k’a’atal u kuxtal. Ti’ le k’áanalil u yantal tu ya’abilil u beetik, ti’ u k’áatal u beeytil u ts\'ook tu ya’abil le ba’ax u ts\'ook. Ti’ le k’áanalil, ku ya’abil u nojoch k’aay, u ka’analil ku yáantaj tu k\'iin yéetel u ts\'ook le ba’ax ku ya’abil, ma\' ts\'ook, ma\' ku ya’abil u ya’abilil. Ti’ le k’áanalil ku ya’abil ku ka’anal tu kuxtal, ku ts\'ook yéetel le ba’ax ku ya’abil, ma\' ku ya’abil u ya’abil.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (17, 18, 'Etz\'anab\'', 'El espejo', 'Es el equilibrio perfecto, la ecuanimidad, la paz interior que brota gracias a una verdadera aceptación de todo tal y como es. En luz el Espejo fluye con todo sin filtros ni reparos, generando una gran armonía entre quienes lo rodean. Es uno de los sellos que se suele llevar mejor con la gente. En sombra sin embargo tiende al juicio extremo, no encuentra orden nada, menos en sí mismo, y termina en crisis por criticarlo todo. No es capaz de verse y suele proyectar sus defectos en los demás. En el calendario maya tradicional se le asocia al cuchillo de obsidiana, cualidad espiritual para cortar de raíz con todo lo que no nos sirve en nuestra vida', 'Kin_17', 'Etznab', 'It is the perfect balance, the equanimity, the inner peace that arises thanks to a true acceptance of everything as it is. In light, the Mirror flows with everything without filters or reservations, generating great harmony among those around it. It is one of the seals that usually gets along well with people. In shadow, however, it tends towards extreme judgment, finding no order in anything, least of all in itself, and ends up in crisis by criticizing everything. It is not capable of seeing itself and tends to project its defects onto others. In the traditional Maya calendar, it is associated with the obsidian knife, a spiritual quality to cut off everything that does not serve us in our lives.', 'Ri b\'anojil wi\', ri k\'akajay, ri wäch k\'i\' ri kajib\' wi\' xk\'utinaj ta ch\'ut ri xk\'ot ri wuj chik ri k\'otol k\'u q\'eqi\' rech. Ti wi\' ri k\'u q\'eqi\' ta\' xk\'utinaj ri Xb\'alamuk\' wi\' chi wach wuj wi\' rech ri\' k\'u q\'eqi\' rech xk\'utinaj utz\'ijilaj k\'u utz\'ijil rech chik ri k\'otol k\'u chik. Ta k\'u wach uwi\' rech xk\'utinaj k\'u k\'i\' ri k\'otol k\'u wach. Ta\' ri k\'otol uqijil chik ri k\'u q\'eqi\' rech k\'u utz\'ijilaj k\'u k\'i\' ri k\'otol k\'u wach, chik ri q\'eqi\' rech. Ta\' ri wuj k\'u k\'otol maya k\'i\' xk\'utinaj uch\'ab\'al xk\'ajolol, ki ri\' q\'eqi\' rech ta\' utz\'ijilaj k\'u wuj chik ri wach k\'u k\'otol rech', '<span>Ri k’ulik ri nimaj k’ul, ri nimaj k’a’ ch’ab’äl, ri nimaj k’a’ k’ul pa ri k’aslemal xb’anol pa ka kik’in ri nimaj k’a’ chi k’amik ri ja’ yal ri kik’in. Pa k’o ri k’ulik ri Tz’aqal xb’anol yal kik’in ri nimaj yal kik’in man xajo’ chi k’amik yal kik’in, xb’anolik ri nimaj ch’ab’äl chi k’amik pa ri kik’in yal kik’in kik’in ri kik’in chi k’amik. K’o junam ri b’ix yal kik’in xb’ano chi k’amik yal kik’in chi kik’in. Pa ruk’u’x kik’in, xaq kik’in ri kik’in xb’anol chi k’amik yal kik’in, man kik’o ri k’ul pa ka ri kik’in ri nimaj, xaq pa ri kik’in chi k’amik, yal kik’in pa ka ri kik’in yal kik’in xb’anol ri nimaj ri kik’in yal kik’in. Man xb’ano chi k’amik pa kik’in yal kik’in chi k’amik yal kik’in xb’anol ri q’aq’al yal kik’in pa ri kik’in. Pa ri ruwi’ ri k’aslemal Q’ij xb’anob’äl ri k’ulik ri q’aq’al chi k’amik pa ka kik’in ri nimaj k’a’ pa ka ri kik’in ri man kik’in yal kik’in ri nimaj chi k’amik.</span>
', 'Es u ts’ookilil perfecto, u nojoch yéetel u nojoch ts’ookilil, le ka’analil ti’ yóok’ol k’iin u yáantaj tu ts\'ookilil le ba’axil yéetel u ts’a’abal. Ti’ le k’iin ku, le Lool ku ts’ook yéetel jump’éel ba’ax ma’ u yilaj yéetel ma’ ku yáantaj, u yáantaj tu nojoch k’iin ti’ le máako’ob ku ya’abil. Es jump’éel le ba’ax ku ya’abil u k’iinil máako’ob yéetel le máako’ob. Ti’ le k’iin ka’analil ku ya’abil u nojoch k’iinil, ma’ ku ya’abil u k’iin yéetel jump’éel, ku ya’abil u ya’abilil ti’ u k’a’analil, ma’ ku ya’abil u kuxtal yéetel ku ya’abil tu ya’abilil tu beetik u yáantal u nojoch yáaxil ti’ jump’éel. Ma’ ku ya’abil u ya’abil yéetel ku ya’abil u nojoch máako’ob tu kaambalil. Ti’ le k’iin ti’ jump’éel k’iin maya tradicional ku ya’abil u ts’ookilil u chi’ibalil, u nojoch yaabilil ka’analil ku ya’abil tu kaanal jump’éel ba’ax ku ya’abil tu kuxtal.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (18, 19, 'Kawak', 'La tormenta', 'Es la fuerza transformadora de la realidad. Cuando aparece la tormenta es momento de cambios radicales, no hay de otra. En general es una energía poderosa de creación, suele pasar perfil bajo pero cuando llega el momento se manifiesta con una gran fiereza. En sombra se estacan y no se permiten cambiar, o al revés, generan cierta adicción a los movimientos fuertes permanentes. Pueden también quedarse en la extrema introspección, son muy sensibles, y no mostrarse. En luz logran generar situaciones límites para dejar ir aquello que ya le tocaba irse y poder volver a empezar en un nuevo nivel de evolución.', 'Kin_18', 'Cauac', 'It\'s the transformative force of reality. When the storm appears, it\'s time for radical changes, there\'s no other way. In general, it\'s a powerful creative energy, it tends to keep a low profile, but when the time comes, it manifests with great fierceness. In shadow, they stagnate and don\'t allow themselves to change, or conversely, they develop a certain addiction to constant strong movements. They can also remain in extreme introspection, they are very sensitive, and they don\'t show themselves. In light, they manage to create boundary situations to let go of what needed to go and start again at a new level of evolution', 'E ri k\'anal ch\'ut ch\'oy. Rech xk\'atun ri tempestad, chi wi xk\'ot xchinku\' chi k\'u\'j, ma chik xewaq k\'ulew. Xecha wi k\'utb\'altzij q\'ij, chi ajk\'ub\' ri b\'anoj, chik\'a chik\'uxul, ba\'q\'ij xk\'ot xchinku\' chi winaq xk\'ot, che\' chik\'uxul. Rech xk\'ut re ri b\'anoj, k\'atunajol chik, k\'utemajol chik, jok\'ojol k\'utu\'x. Rech chi wi, che\' chik\'ajol ri xtreme k\'umal, ma chik. Ma k\'ulew, chik b\'a ri ki\'che ch\'umil k\'utuj ri chik ri aq\'ab\'äl rech a\' ri aq\'ab\'äl rech a\' chik\'ajol ri wi kib\'äl.', '<span>Ri k’ulik ri xb’ano chi k’amik ri nimanel. Xa ri taq’anom xb’ano, ri kik’in pa ka xb’ano ri nimaj k’a’ chi k’amik, man xb’anol jun ri xajo’ chi k’amik. Xaq pa junam k’o ri nimaj k’ulik yal kik’in ri k’ulik, xb’anol chi k’amik pa ka ri kik’in ri q’aq’al chi k’amik yal kik’in kik’o ri nimaj k’a’ chi k’amik. Pa ruk’u’x kik’in, kik’in ri kik’in xb’anol chi k’amik yal kik’in, man xb’anol pa ka kik’in ri kik’in chi k’amik, o pa ka xb’ano ri nimaj k’a’ pa ka kik’in ri nimaj ri kik’in xb’anol ri nimaj k’a’ yal kik’in chi k’amik. Xaq xb’anol pa ka kik’in ri nimaj ri xajo’ chi k’amik, xb’ano yal kik’in, yal man xb’anol chi k’amik. Pa k’o ri k’ulik kik’in kik’in xb’ano ri nimaj k’a’ chi k’amik pa ka xb’ano ri kik’in pa ka kik’in ri kik’in pa ka kik’in chi k’amik yal kik’in xb’anol chi k’amik pa ri nimaj k’a’ yal kik’in xb’anol yal kik’in.</span>
', 'Es u yáantaj tu kaanalil kuxtal. Tu ka’analil ku ya’abil le k’áankin es jump’éel k’iinil u ts’a’abal ku xíimbal, ma’ yaan jump’éel k’iino’obil. Tu yáax kuxtal ku yáabil u chúumukil u yantal, ku ts’ook u yaantal, ba’ale’ ku ya’abil u nojoch k’iin ti’ jump’éel k’iinil u k’a’ab. Ti’ le k’áanalil, ku ya’abil ku k’a’atal yéetel ma’ ku ya’abil u ts’a’abal, o ku ya’abil jump’éel k’a’ansaj tu kuxtal yéetel ma’ ku ya’abil u ya’abilil. Ku ya’abil xan tu yaanalil kuxtalil, ku yáantaj jump’éel tu yóok’ol k’iin, yéetel ma’ ku ya’abil u ya’abil. Ti’ le k’iin ku ku ya’abil ku k’a’atal yéetel jump’éel tu ts’ookil, u k’áatal ku ts’ook jump’éel ba’ax u yáabil tu ts’a’abal yéetel ku ts’ook ti’ jump’éel u ts’a’abal u yáax k’iinil tu ya’abil.
');
INSERT INTO tiempomaya.kin (id, iddesk, nombre, significado, htmlCodigo, categoria, nombreYucateco, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (19, 20, 'Ajaw', 'El sol', 'Es la energía de mayor evolución. Representa la luz generadora de vida, la sabiduría, la verdad, las cosas tal y como son. Cuando aparece el Sol es momento de brillar, de confiar en quienes ya somos y en lo que ya sabemos de manera intrínseca, y asumir los roles de autoridad, de liderazgo que nos correspondan. Es momento de afrontar la realidad como se presente, así nos cueste. El problema con el Sol es que al ser la verdad puede tornarse intransigente, radical con la ética, con los paradigmas, con lo que considera correcto o cierto, así, debe trabajar por sobre todas las cosas la humildad. La verdadera sabiduría no se anda mostrando, defendiendo o convenciendo, es un estado del alma, de conexión permanente con nuestro ser auténtico.', 'Kin_19', 'Ahau', 'It\'s the energy of higher evolution. It represents the life-generating light, wisdom, truth, things as they are. When the Sun appears, it\'s time to shine, to trust who we already are and what we already know intrinsically, and to assume roles of authority, of leadership that correspond to us. It\'s time to face reality as it presents itself, no matter how challenging it may be. The issue with the Sun is that being the truth, it can become uncompromising, radical with ethics, with paradigms, with what it considers right or true, so humility must be worked on above all else. True wisdom isn\'t about showing off, defending, or convincing; it\'s a state of the soul, a permanent connection with our authentic self.', 'E ri energia k\'anal ch\'ut a\' k\'ulew. Chik ri ruk\'ux k\'utuj, ruk\'ux, k\'utb\'altzij, a\'b\'anel ri kib\'äl che\' ri q\'ij. Rech xk\'atun ri q\'ij, chi wi k\'ab\'ij, chik ri a\' winaq chikaj chi wi a\' kib\'äl rech chi wi a\' kib\'äl, che\' kib\'äl che\' chik\'ajol, chib\'äl chik\'ajol ri xub\'inal. Rech xk\'atun ri realidad chi k\'ot xchinku\' chi k\'u\'j, chi xti\' taq xkoj rech. Ri problema xk\'ut b\'e ri ruk\'ux chi ri q\'ij, chi k\'ulew rech winaq chik ajanel ri k\'u\'xul, k\'u\'xul chi wi, k\'u\'xul che\' a\' che\' b\'anel ri aq\'ab\'äl, ri chik\'ajol ri b\'anoj che\' ri q\'ij ri k\'o ri a\' wi che\' k\'ut. Ri b\'anel ri k\'utb\'altzij ma k\'utuleje\', ma chik\'ajol, ma k\'utwalij, xechawin taq, ri q\'ij rech ajk\'ub\' chikaj ri wi a\' kib\'äl.', '<span>Ri k’ulik ri nimaj k’a’ chi k’amik. Xb’anob’äl ri q’ij xb’ano chi k’amik ri k’aslemal, ri nimaj tzij, ri nimaj k’a’, ri nimaj ja’ yal ri kik’in. Xa ri Q’ij xb’ano, ri kik’in pa ka xb’anolik, pa ka kik’otemik ri kik’in yal kik’in xb’anol yal kik’in ri ja’ yal kik’in pa ri k’ulik, yal xb’ano ri qach’ab’äl yal kik’in, ri k’ulik yal kik’in ri kik’in chi k’amik. Ri kik’in pa ka xb’ano ri nimanel chi k’amik ri ja’, xaq kik’in pa ka kik’in ri kik’in. Ri xaqik’ pa ri Q’ij k’o kik’in ri nimaj k’a’ xb’ano chi k’amik, xb’ano yal kik’in ri nimaj tzij, xb’ano chi k’amik yal ri nimaj tzij, yal ri ja’ xb’anol ri kik’in xb’ano chi k’amik o ri nimaj, xaq, xb’anol pa ka kik’in ri kik’in ri k’ulik yal kik’in. Ri nimaj tzij ri ja’ xb’anol chi k’amik, man xb’ano chi k’amik, xb’anol yal kik’in chi k’amik, k’o jun q’aq’al chi k’amik yal ri k’aslemal, ri xb’anol chi k’amik yal ri nimaj k’a’ yal kik’in ri kik’in chi k’amik.</span>
', 'Es u yáantaj tu nojoch ka’analil. U yantal u k’iin generadora kuxtal, le ts’ookbilil, le yáanal, le ba’axil jump’éel k’a’at. Tu k’iin ku ya’abil le K’iin es k’iinil u jáas, u k’a’atal ti’ u ya’abil yéetel le ba’ax ku ya’abil u ya’abil tu yóok’ol kaajil, yéetel u ts’ookil ti’ u ya’abilil. Es k’iinil u xok k’a’anal, u k’a’atal ku ts’a’abal ti’ jump’éel ba’ax ku ya’abil, bey xan ku ya’abil jump’éel bejo’ob yéetel le ku ya’abil u ya’abilil ti’ u kaambal. Le nojoch k’iin le K’iin es ku yáantaj ti’ jump’éel, ku ya’abil ku ya’abilil tu kuxtal, ku yantal u ya’abilil u k’iin yéetel le ba’ax ku k’a’atal ku ya’abil. Bey xan, le nojoch k’iin le K’iin ku k’a’atal u ya’abilil, ku ya’abil ku k’a’atal u ya’abilil yéetel le ts’ookbilil, yéetel le ba’ax ku ya’abil u k’a’atal ku ya’abil. Le nojoch ts’ookbilil ma’ ku ya’abilil tu tsikbal, ma’ ku ya’abilil, ma’ ku ya’abilil ti’ le yáanal, es jump’éel k’iinil u yóok’ol kuxtal, u nojoch k’a’analil yéetel le ts’ookbilil tu kuxtal.
');

-- lugar
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (1, 'Tikal', 'Tikal es un destino turístico muy popular y concurrido, esto ya dice que es una de las mejores ruinas mayas de Guatemala. Es muy visitado por personas de todo el mundo. De hecho, muchos vienen al país exclusivamente a visitar Tikal. Fue una ciudad importante para la civilización maya ya que su poderío socio-político era decisivo para el desarrollo económico de las poblaciones de la región. Su templo IV es el más alto: mide 70 metros de altura. Y encuentras una gran cantidad de estelas, tumbas y altares.<> El Parque Nacional Tikal está situado en el corazón de la selva tropical de Petén, en el norte de Guatemala. A unos 65 kilómetros al noreste de la ciudad de Flores y el aeropuerto internacional de Mundo Maya, Tikal es fácilmente accesible por carretera y aire, lo que lo convierte en un destino imprescindible para los amantes de la arqueología y la naturaleza.', 'Q200.00 a Q600', '8:00 a 18:00', './img/turismo/inicio1.jpg', 'lugar01');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (2, 'Iximché', 'Situado en las tierras altas de Guatemala, el sitio arqueológico de Iximché se encuentra a aproximadamente 90 kilómetros al oeste de la Ciudad de Guatemala, cerca de la moderna ciudad de Tecpán, Chimaltenango. Este impresionante sitio es de fácil acceso por carretera y es una excelente opción para una excursión de un día desde la capital.<> La ciudad de Iximché tiene 6 plazas y el área del Gran Palacio. En este sitio sucedió una de las más grandes alianzas entre los españoles y los kaqchikeles. Este vínculo servía para unificar fuerzas en contra de la etnia Quiché.', 'Q50 a Q100', '8:00 a 16:00', './img/turismo/iximche.jpg', 'lugar02');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (3, 'Zaculeo', 'Las ruinas de Zaculeu se encuentran en el departamento de Huehuetenango, en el altiplano occidental de Guatemala, a unos 5 kilómetros de la ciudad de Huehuetenango. Este sitio arqueológico es fácilmente accesible por carretera desde la ciudad, lo que lo convierte en una excelente opción para los viajeros que desean explorar la rica historia de la región.<> Zaculeu, cuyo nombre significa "Tierra Blanca" en el idioma Mam, fue la capital del reino Mam. La ciudad alcanzó su apogeo durante el período posclásico (900-1525 d.C.) y es conocida por su papel en la resistencia contra la conquista española liderada por Gonzalo de Alvarado en 1525. El sitio sirvió como una fortaleza defensiva y refugio para los Mam durante el asedio, lo que subraya su importancia estratégica y cultural.', 'Q5 a Q50', '8:00 a 16:00', './img/turismo/zaculeu.jpg', 'lugar03');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (4, 'Takalik Abaj', 'Takalik Abaj se encuentra en el departamento de Retalhuleu, en la costa sur de Guatemala. Situado aproximadamente a 190 kilómetros al suroeste de la Ciudad de Guatemala, este sitio arqueológico es accesible por carretera, lo que lo convierte en un destino ideal para una excursión de un día desde la ciudad capital o desde los destinos turísticos costeros.<> Takalik Abaj, que significa "Piedra Parada" en el idioma K\'iche\', es un sitio arqueológico excepcional que floreció durante el período preclásico (800 a.C. - 300 d.C.) y continuó siendo ocupado hasta el período clásico. Este sitio es notable por su mezcla de influencias olmecas y mayas, lo que lo convierte en un punto crucial para comprender la transición y la interacción entre estas dos grandes culturas mesoamericanas.', 'Q5 a Q50', '7:00 a 17:00', './img/turismo/takalik.jpg', 'lugar04');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (5, 'Mixco Viejo', 'Mixco Viejo se encuentra en el departamento de Chimaltenango, en el altiplano central de Guatemala, a unos 50 kilómetros al noroeste de la Ciudad de Guatemala. Este sitio arqueológico está ubicado en una meseta rodeada de profundos barrancos, lo que lo convierte en una fortaleza natural y un destino fascinante para los amantes de la historia y la arqueología.<> Mixco Viejo, conocido también como Jilotepeque Viejo, fue la capital del reino Poqomam durante el período posclásico (1200-1525 d.C.). La ciudad jugó un papel importante en la resistencia contra la conquista española liderada por Pedro de Alvarado en 1525. A pesar de su eventual caída, Mixco Viejo sigue siendo un símbolo de la resistencia y la rica herencia cultural de los Poqomam.', 'Q50 a Q100', '8:00 a 16:00', './img/turismo/mixco.jpeg', 'lugar05');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (6, 'Quiriguá', 'Quiriguá fue una pequeña ciudad en la que divergían rutas comerciales gracias a su cercanía al río Motagua. Su importancia reside en las estelas que posee. Fueron erigidas cada cinco años y narran en jeroglíficos los eventos socio-políticos de ciudad como por ejemplo, los cambios de mando de sus gobernantes. Además, aquí en Quiriguá verás la estela maya más alta del mundo.<> El Parque Arqueológico Quiriguá se encuentra en el departamento de Izabal, en el oriente de Guatemala. Ubicado a unos 205 kilómetros de la Ciudad de Guatemala y a 75 kilómetros de la ciudad portuaria de Puerto Barrios, este sitio es accesible por carretera, lo que lo convierte en un destino ideal para los viajeros que desean explorar la historia maya en un entorno exuberante.', 'Q80 a Q350', '8:00 a 17:00', './img/turismo/quirigua.png', 'lugar06');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (7, 'El Mirador', 'El Mirador se encuentra en el departamento de Petén, en el norte de Guatemala, en medio de la densa selva tropical. Este sitio arqueológico es uno de los más grandes y antiguos de la civilización maya, y se encuentra a unos 55 kilómetros al norte de la ciudad de Flores. Debido a su ubicación remota, el acceso a El Mirador es una aventura en sí misma, generalmente realizado a pie o en helicóptero desde Flores o Carmelita.<> Su importancia para la civilización maya fue su función de captación de agua y manejo de sistema de drenajes para el área. A 20 km de El Mirador se encuentra la segunda ciudad maya más grande: El Tintal. Estas antiguas ciudades mayas tuvieron su apogeo económico, social y político de la mano con Tikal. Su mayor atractivo es la Pirámide de La Danta. Es la pirámide maya más alta con sus 72 metros de altura.', 'Q450 a Q700', 'Depende del tour', './img/turismo/mirador.jpg', 'lugar07');
INSERT INTO tiempomaya.lugar (idLugar, nombre, descripcion, precio, horario, imagen, categoria) VALUES (8, 'Uaxactún', 'Uaxactún es la ruina maya vecina de Tikal. Se encuentra a 23 km de distancia hacia el norte. La importancia de Uaxactún era su potencia política, según investigaciones, más antigua que Tikal. Estas dos ciudades mayas mantuvieron conflicto territorial durante el apogeo de Tikal, hasta que Uaxactún terminó perdiendo la independencia.', 'Q50 a Q150', '6:00 a 18:00', './img/turismo/uaxactun.jpg', 'lugar08');

-- pagina
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (2, 'Energia', 'Calendario Cholquij', 'Elementos', '<p>El calendario Cholq\'ij utiliza las energías del 1 al 13 pero su ciclo es de meses y días.</p>

<p> La relación del 13 con los ciclos de la vida es múltiple, entre ellas se pueden mencionar:</p>
<ul>
	<li>Las 13 energías en el nacimiento</li>
	<li>Los 13 ciclos de 20 días de un año Cholq’ij.</li>
</ul>
<p>
El 13 es una cantidad importante en el pensamiento maya. Se utiliza para indicar el nivel de
energía y al combinar con el significado de los nawales construye la personalidad.		Este número
tiene influencia en toda la vida, marca la niñez, juventud, madurez y ancianidad.
</p>
', '<p>The Cholq\'ij calendar uses energies from 1 to 13, but its cycle consists of months and days.</p>

<p>The relationship of 13 with the cycles of life is manifold, among them can be mentioned:</p>
<ul>
    <li>The 13 energies at birth</li>
    <li>The 13 cycles of 20 days in a Cholq\'ij year.</li>
</ul>

<p>Thirteen is an important quantity in Mayan thought. It is used to indicate the level of energy and when combined with the meaning of the nawales, it constructs personality. This number influences all of life, marking childhood, youth, maturity, and old age.</p>', '<p>Cholq\'ij k\'ajkunab\'ij re ru k\'iche\' pa q\'ij aj q\'ij re li\', xan xatz\'ib\'ij ri ajawab\' re li.</p>

<p>Ri\' 13 chi xan q\'ijab\' ru re ronojelaj kajibalaj, xan chi\' chwe ri:</p>
<ul>
    <li>Ri\' 13 k\'ajkunab\' k\'ichpanik</li>
    <li>Ri\' 13 kajibalaj chi 20 q\'ij re Cholq\'ij winaq.</li>
</ul>

<p>Ri\' 13 chi chi\' re ri Jun ulew ri k\'iche\'. Xan chwe ri k\'ajkunab\' re ri nawales, xan xkib\'ab\'ij re aatinamit re. Ri ronojelaj kajibalaj chi konojelaj, xan ka\'nin, xapalaj, kiq\'ajil, xan ruk\'uxaj.</p>', '<p>Ri q’ijob’äl Cholq\'ij xub’ij ruwäch ri k’aslem pa ri’ jun chikaxik b’i’aj 1 pa 13 chawe runuk’ k’ak’a’ taq tz’ijöj k’aslem rech ulew.</p>

<p> Ri nab’eyal xub’ij 13 chi ri k’aslem rech qak’aslem b’anwa’ jun ik’ütal, rumal xatz’e jun paq’orb’äl:</p>
<ul>
<li>Ri 13 ch’ob’äl pa ri ala’</li>
<li>Ri 13 tz’ijöj rech wuj q’iij taq 20 k’aslem junab’ Cholq’ij</li>
</ul>
<p>
Ri jun 13 jun ch’ob’äl k’aslem pa ri Maya’ qatzij. Xub’ij chi ruq’a’ k’aslem chikaxik jun ch’ob’äl pa junal
nawal rumal xk’olb’e’ jun taqanel. Ri junab’ xub’ij qak’aslem, xub’ij chub’än chi ri ala’, yo’kom, xe’ k’axik, e k’ay taq ch’ab’.
</p>
', '<p>Le calendario Cholq\'ij ku ts\'o\'ok le yáantajo\'ob tu 1 ti\' 13 pero u ciclo es jump\'éel u k\'iino\'ob yéetel u k\'iino\'ob.</p>

<p> Le relación le 13 yéetel le ciclos tu kuxtal es múltiple, ti\' jump\'éel u k\'a\'ato\'ob:</p>
<ul>
<li>Le 13 yáantajo\'ob tu k\'i\'ix</li>
<li>Le 13 ciclos tu 20 k\'iino\'ob tu jump\'éel ja\'ab Cholq’ij</li>
</ul>
<p>
Le 13 es jump\'éel cantidad importante tu ts\'ookbilil maya. Ku t\'aano\'ob u k\'iin tu yáantaj le nivelil u
yáantaj yéetel ku t\'aano\'ob yéetel le significado le nawales ku t\'aan yéetel ku yaantal u máak\'. Le número
ya\'abil u yáantaj tu jump\'éel kuxtal, ku ts\'a\'abal le chi\'ich, ka\'ansaj, ka\'anal yéetel nojoch ka\'anal.
</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 'Forma de Contar', 'Calendario Cholquij', 'Informacion', '<h2>Forma de contar</h2>
<p> Una manera de contar el Cholq’ij para los maya k’iche’ de la actualidad es iniciar el conteo en Waqxaqib’ B’atz’ (8 B’atz’), repitiendo así cada 260 días ese número y fecha (Aj Xol Ch’ok, 2008). Cada día del calendario se combina con un numeral que va del 1 al 13, hasta completar 260 días. El mismo día en que inicia la cuenta vuelve a repetirse cada 260 días. En la antigüedad se acostumbraba a empezar el calendario en 1 Imox y se seguía el mismo proceso de multiplicación de los numerales con los días para alcanzar el total de 260 (Aj Xol Ch’ok, 2008). La construcción del ciclo de 260 días del calendario Cholq’ij tiene como base la disciplina vigesimal maya (13X20); “esta relación organiza una frecuencia matemática del movimiento natural lunar de 13:20 que se determina en base a las gravitaciones, principalmente de la Luna–Tierra, las cualidades del ser en la madre Tierra de acuerdo a su día de engendración, día del nacimiento y su proyección o misión en la vida” (García, Curruchiche & Taquirá, 2009, p. 234). Los días de este calendario “son representados también en los 10 dedos superiores de las manos, más los 10 dedos inferiores de los pies, lo que suma 20, que representa los días del Cholq’ij”, pues la construcción matemática del sistema vigesimal maya “se fundamenta en el Jun Winaq de 20 dedos” (García, Curruchiche & Taquirá, 2009, p. 47 y 234).</p>
', '<h2>Way of Counting</h2>
<p>One way to count the Cholq’ij for present-day Maya K\'iche\' is to start the count on Waqxaqib’ B’atz’ (8 B’atz’), thus repeating every 260 days that number and date (Aj Xol Ch’ok, 2008). Each day of the calendar is combined with a numeral ranging from 1 to 13, until reaching a total of 260 days. The same day the count begins repeats every 260 days. In ancient times, it was customary to start the calendar on 1 Imox and follow the same process of multiplying the numerals with the days to reach the total of 260 (Aj Xol Ch’ok, 2008). The construction of the 260-day cycle of the Cholq’ij calendar is based on the Mayan vigesimal discipline (13X20); "this relationship organizes a mathematical frequency of the natural lunar movement of 13:20 determined based on gravitations, mainly from the Moon-Earth, the qualities of being in Mother Earth according to its day of conception, day of birth, and its projection or mission in life" (García, Curruchiche & Taquirá, 2009, p. 234). The days of this calendar "are also represented on the 10 upper fingers of the hands, plus the 10 lower fingers of the feet, which adds up to 20, representing the days of the Cholq’ij", as the mathematical construction of the Mayan vigesimal system "is based on the Jun Winaq of 20 fingers" (García, Curruchiche & Taquirá, 2009, p. 47 and 234).</p>', null, '<h2>Ri Uwachib’il</h2>
<p> Jun k’ak’a’ utz’ib’äl ri q’ijob’äl Cholq’ij chike ri maya k’iche’ wachib’äl xuquje’ xul pe ruk’ ri Waqxaqib’ B’atz’ (8 B’atz’), tziya’ chi utz’ k’a ri tz’ib’äl xpe jun b’elejeb’ tz’ijöj (Aj Xol Ch’ok, 2008). Jun chikaxik ri q’ij pa q’ijob’äl xub’an jun ruk’ k’aslem chike 1 pa 13, chi xpe ri b’elejeb’ tz’ijöj. Ri jun q’ij xpe pe chi k’a jun chikaxik chi jun b’elejeb’ tz’ijöj. Pa ri e qama’ chik xq’a jun chi jun q’ij pa 1 Imox xa xe ruk’ jun chikaxik pa utz’ib’äl chi jun tz’iib’ej b’a q’ij ri xpe jun b’elejeb’ tz’ijöj (Aj Xol Ch’ok, 2008). Ri utz’ib’äl jun chikaxik jun b’elejeb’ tz’ijöj pa ri q’ijob’äl Cholq’ij xub’ij pa k’aslem chikij ri mayab’ pa utz’ib’äl (13X20); “ri nab’eyal xub’ij jun k’aslem saqirkachoqil ri ruk’ jun pa jun chi’ k’aslem ri ya’ ri 13:20 ri xub’ij pa ruk’ jun xna’oj, chuqa’ ri yuwe’ ri’ ch’ab’, ri’ ri ch’akul ri’ rech qa ch’ab’ pa ri ch’ab’il ri ruka’ jun chikaxik, jun q’ij pa q’ij ri’ xub’ij ruk’ pa jun b’anab’il richin qak’aslem” (García, Curruchiche & Taquirá, 2009, p. 234). Ri q’ijob’äl pa ri q’ijob’äl xub’an pa ri 10 ruxo’chi’ ri saqi’ wachb’il, k’a ri 10 ruxo’chi’ ri saqi’ xak’ab’il, ri’ chi pa jun jun b’anab’il ri’ xub’an jun q’ijob’äl Cholq’ij”, rumal ri utz’ib’äl jun b’anab’il richin jun utz’ib’äl ri mayab’ xub’ij pa Jun Winaq ri 20 ruxo’chi’ (García, Curruchiche & Taquirá, 2009, p. 47 y 234).</p>
', '<h2>Forma de contar</h2>
<p> Jump’éel manera tu ts\'ook le Cholq’ij ti’ le maya k’iche’ tu k’iino’ob es in k’a’ato’ tu Waqxaqib’ B’atz’ (8 B’atz’), ts’ook u ts’ook tu jump’éel 260 k’iino’ob u número yéetel le k’iin (Aj Xol Ch’ok, 2008). Jump’éel k’iin le calendario ku ts’ook u ts’a’bal tu jump’éel número ku xíimbal ti’ 1 ti’ 13, tu ts’a’bal u 260 k’iino’ob. Le jump’éel k’iin tu ka’anal le cuenta ku ya’abil u ts’ook tu jump’éel 260 k’iino’ob. Tu nojoch ka’analil ku xíimbal tu in k’a’ato’ le calendario tu 1 Imox yéetel ku ts’ook u mismo proceso tu yáantaj u número yéetel le k’iino’ob tu ts’a’bal u 260 (Aj Xol Ch’ok, 2008). Le nojoch ts’ookil le ciclo 260 k’iino’ob le calendario Cholq’ij ku t’aano’ob tu disciplina vigesimal maya (13X20); “le relación ku nojoch tu yáantaj matemática tu k’iinil u nojoch 13:20 ku ya’abil tu yáantaj u gravitacióno’ob, ti’ nojochil le Nojoch K’iin–Lu’um, le ku ts’ookil le máak’ tu Nojoch Lu’um ti’ u k’iino’obil tu k’iino’obil u nojoch, k’iinil u ya’abil yéetel le proyecto o misión tu kuxtal” (García, Curruchiche & Taquirá, 2009, p. 234). Le k’iino’ob le calendario “ku t’aano’ob xan tu 10 mejen yéetel ku 10 mejen yéetel ku nojoch k’iin, ku ts’ook 20, ku t’aano’ob le k’iino’ob le Cholq’ij”, tu ya’abil matemática le sistema vigesimal maya “ku t’aano’ob tu Jun Winaq le 20 mejen” (García, Curruchiche & Taquirá, 2009, p. 47 y 234).</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 'Informacion', 'Calendario Cholquij', 'Informacion', '<p>El Cholq´ij deriva su nombre de los términos maya-k´iche´:</p><ul><li>Chol: Contar cosas puestas en orden</li><li>Q´ij: el sol o día</li></ul><p>El Cholq’ij es un calendario sagrado del pueblo Maya, compuesto por 260 días divididos en 13 meses. También recibe el nombre de calendario ritual o calendario sagrado o Tzolkin (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p><p>“El Cholq´ij es uno de los instrumentos que los Abuelos del Pueblo maya crearon; tiene dos aplicaciones principales, la primera: ubica momentos para actividades colectivas; la segunda: tiene una aplicación individual para identificar la conducta natural o la forma de ser de las personas por medio de su nawal, es decir, los rasgos psicológicos básicos, positivos y negativos.</p><p>Este calendario fue configurado a partir de los movimientos que la Luna realiza en su órbitta alrededor de la Tierra. Así como el calendario AB’ agrícola o solar de 365 días está configurado en base al movimiento de traslación de la Tierra alrededor del Sol y es identificado como energía masculina.</p><p>Por otra parte, el Choloq’ij o calendario sagrado es considerado energía femenina, por su relación con los movimientos de la Luna y por la influencia que este cuerpo celeste ejerce sobre los organismos femeninos de la naturaleza y los seres humanos.”</p><h2>Forma de contar</h2><p>Una manera de contar el Cholq’ij para los maya k’iche’ de la actualidad es iniciar el conteo en Waqxaqib’ B’atz’ (8 B’atz’), repitiendo así cada 260 días ese número y fecha (Aj Xol Ch’ok, 2008). Cada día del calendario se combina con un numeral que va del 1 al 13, hasta completar 260 días. El mismo día en que inicia la cuenta vuelve a repetirse cada 260 días. En la antigüedad se acostumbraba a empezar el calendario en 1 Imox y se seguía el mismo proceso de multiplicación de los numerales con los días para alcanzar el total de 260 (Aj Xol Ch’ok, 2008). La construcción del ciclo de 260 días del calendario Cholq’ij tiene como base la disciplina vigesimal maya (13X20); “esta relación organiza una frecuencia matemática del movimiento natural lunar de 13:20 que se determina en base a las gravitaciones, principalmente de la Luna–Tierra, las cualidades del ser en la madre Tierra de acuerdo a su día de engendración, día del nacimiento y su proyección o misión en la vida” (García, Curruchiche & Taquirá, 2009, p. 234). Los días de este calendario “son representados también en los 10 dedos superiores de las manos, más los 10 dedos inferiores de los pies, lo que suma 20, que representa los días del Cholq’ij”, pues la construcción matemática del sistema vigesimal maya “se fundamenta en el Jun Winaq de 20 dedos” (García, Curruchiche & Taquirá, 2009, p. 47 y 234).</p>', '<p>The Cholq´ij derives its name from the Maya-K´iche´ terms:</p>
<ul>
	<li>Chol: Counting things placed in order</li>
	<li>Q´ij: the sun or day</li>
</ul>

<p>The Cholq’ij is a sacred calendar of the Maya people, consisting of 260 days divided into 13 months. It is also known as the ritual calendar or sacred calendar or Tzolkin (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p>

<p>“The Cholq´ij is one of the instruments that the Grandparents of the Maya People created; it has two main applications, the first: locating moments for collective activities; the second: it has an individual application to identify the natural behavior or the way of being of people through their nawal, that is, the basic, positive and negative psychological traits.</p>

<p>This calendar was configured based on the movements that the Moon makes in its orbit around the Earth. Just as the AB\' agricultural or solar calendar of 365 days is configured based on the Earth\'s translational movement around the Sun and is identified as masculine energy.</p>

<p>On the other hand, the Choloq’ij or sacred calendar is considered feminine energy, due to its relationship with the movements of the Moon and the influence that this celestial body exerts on the female organisms of nature and humans.”</p>', '<p>Cholq´ij ri\' chi\' na\' ri maya-k´iche´ chi´:</p>
<ul>
	<li>Chol: Ri\' k\'ajkunab\' k\'iche\' chuqaqilaj</li>
	<li>Q´ij: ri ronojelaj q\'ij</li>
</ul>

<p>El Cholq’ij k\'u k\'ajlal winaq ri ri\' maya, k\'u chwe ri 260 ronojelaj chi\' k\'u chwe. Xkib\'ij chi\' k\'ajkunab\' k\'iche\' k\'uj winaq k\'ajlal winaq, wuj winaq k\'ajlal winaq k\'ij winaq k\'utu\'un (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p>

<p>“El Cholq´ij k\'u k\'ajlal kaj chikawil ri ri\' ulew maya, chikawil chwe ri jun kub\'ij ri\', kaj konojelaj kajibalaj re ru\' chikawil winaq re k\'iche\', xkib\'ij chawal ri\': k\'u nimalaj ri chikawil winaq; kaj winaq k\'ajlal kajibalaj re konojelaj chikawil ri kaj.</p>

<p>Chi\' ri\' k\'ajkunab\' chikawil kib\'ij chi\' na\' re ruq\'ij kib\' chi\' Q\'ij chik\'ut ri k\'u\'xajik ri ruk\'uxik chik\'ut xq\'ij, xq\'ij kib\'ij k\'ij ronojelaj k\'ij, k\'ajibalaj konojelaj.</p>

<p>Ri jun konojelaj, ri Choloq’ij k\'u k\'ajlal q\'ij kajibalaj kub\' re konojelaj, xchawe xq\'ij k\'ij chik\'ut ch\'aj juyub\' chik\'ut konojelaj xq\'ij k\'ij k\'aj chik\'ut kub\'.</p>
', '<p>
El Cholq´ij xub’anik pa ri saq tzij ri maya-k´iche´:
<ul>
<li>Chol: Utz’ib’an taq b’anob’ chike jun na’oj</li>
<li>Q´ij: Ri q’ij pa ri q’ij</li>
</ul>
</p>

<p> Ri Cholq’ij jun k’ak’a’ q’ijob’äl chike ri ch’ab’il Maya, xub’ij chi jun junab’ k’aslem chike jun b’elejeb’ q’ij chi xkix na jun k’ak’a’. Xa xa jun taqib’äl ruk’a jun q’ijob’äl rech k’aslem chike jun b’elejeb’ q’ij xub’anik taq ri’ chi jun kal. Ri Cholq’ij xub’an chi k’ak’a’ jun ch’ab’il richin jun taqib’äl richin ch’ab’il chike Tzolkin (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p>

<p>“Ri Cholq´ij jun taqib’äl ri xk’ul chi ri Ajaw rech ri ch’ab’il maya xutz’ub’ chike; pa junb’ey junab’ ri’ xub’ij jun kaqib’äl jun k’ak’a’ richin jun k’aslem; ri junab’ xub’ij k’aslem chike jun ch’akul; junab’ xub’ij jun taqib’äl rech junq’ij ri utz’ib’äl chi jun chi ruk’a’ ch’akul, chike jun nawal, xub’ij jun qak’aslem chiq’a jun, jun nab’eyal pa jun chikaxik, jun k’aslem chikaxik.”</p>

<p>Ri jun q’ijob’äl xub’anik chi jun tzij ri’ ri xub’ij chi ri q’ij pa jun chikaxik pa ri’ ri xe’ chi q’ij pa ri ch’ab’il ri xkiwach chi jun junab’ wachib’il chi k’aslem chike ri ajaw xak’ab’il pa ri ch’ab’il jun k’ak’a’ pa jun ch’ab’il pa 365 q’ij xub’anik chi jun junab’ k’aslem chi ri q’ij pa jun taqib’äl ri xub’an chi jun q’ij ri xutik xib’an chi jun nab’eyal chik pa k’aslem. Ri’ xub’ij chi ri jun q’ijob’äl AB’ jun q’ijob’äl rech xutik pa ch’ab’il chike jun k’aslem pa ri k’aslem, pa ri ch’ab’il xax q’ijob’äl jun utz’ib’äl richin ch’akul qitzij chi ri k’aslem chike jun na’oj. </p>

<p> Ri Cholq’ij chike jun q’ijob’äl ch’ab’il xub’ij jun k’aslem chi k’aslem jun ch’akul pa qitzij chi ri k’aslem, ri’ xub’ij chi jun q’ijob’äl jun k’ak’a’ rech ch’akul chike ri k’aslem chike jun k’aslem chike ri jun utz’ib’äl chikaxik jun ch’ab’il pa ch’akul, chike jun ajaw ri xub’an pa ri k’aslem chike jun chikaxik.”
</p>
', '<p>
El Cholq\'ij deriva su nombre de los términos maya-k’iche’:
<ul>
<li>Chol: Ts’ook le ba’ax ku ya’abil tu nojoch</li>
<li>Q’ij: le k’iin o k’iinil</li>
</ul>
</p>

<p> Le Cholq’ij es jump’éel calendario nojoch le máak’ab Maya, ku ya’abil tu 260 k’iino’ob ku ts’o’ok tu 13 meses. Bey xan ku t’aano’ob jump’éel calendario ritual o calendario nojoch o Tzolkin (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p>

<p>“Le Cholq’ij es jump’éel le ba’ax le Nojoch Máak’ab le máak’ab ku ya’abil; yaan jump’éel ka’analil ku beetik, le yáaxil: ku ts’ook u k’iinil yéetel jump’éel tu tsikbal; le ka’a: yaan jump’éel yáantaj ti’ u ka’analil ku ya’abil u k’iin yéetel u ya’ab jump’éel máak’ab ku ka’anal tu ya’ab jump’éel, u yáanal le ku nojoch máako’ob, le ts’o’okil tsikbalil, ts’ookilil yéetel ma’ nojoch.</p>

<p>Le calendario ku ya’abil tu yáantaj le ka’analil u k’iinil le Nojoch ku ximbal ti’ u yóok’ol le Nojoch Lu’um tu yóok’ol Nojoch Lu’um. Bey xan le calendario AB’ nojochil o k’iinil de 365 k’iino’ob ku ya’abil tu yáantaj le ka’analil u ximbalil le Nojoch Lu’um tu yóok’ol le K’iin yéetel ku t’aano’ob le kuxtalil masculino.</p>

<p>Tu láak’, le Cholq’ij o calendario nojoch ku ya’abil ku t’aano’ob kuxtalil femenino, le ba’ax ku yáantaj le ka’analil le Nojoch yéetel le ts’a’abal ku ya’abil ku ya’abil ti’ le máako’ob femeninos tu yóok’ol k’iin yéetel le máak’ab.”
</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 'Informacion', 'Calendario Haab', 'Informacion', '<p>El calendario solar maya, llamado Haab\', es una cuenta de 365 días y por lo tanto se aproxima al año solar es el calendario civil, agrícola Maya, es el calendario de los reyes Mayas.</p>    <p>La palabra <strong> "HAAB\'" </strong> significa <strong> "AÑO" </strong> en el idioma maya yucateco.</p>    <p>El Haab está compuesto por 18 meses de 20 días cada uno, más un mes que consta de 5 días. Cada mes de 20 días, conocido como uinal, tiene su propio nombre. Todos estos 18 meses juntos suman 360 días.</p>    <p>El último mes, compuesto de 5 días, se conoce como Wayeb. Los 19 meses en su totalidad suman 365 días.</p>    <p><strong>18 x 20 + 5 = 365 </strong></p>    <p> </p>    <figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" />  <figcaption></figcaption>  </figure>    <p>Fue elaborado por los astrónomos y matemáticos Mayas para dar respuesta a la necesidad de las personas para su abastecimiento de alimento con la siembra y cosecha del sagrado maíz, el frijol, y toda clase de productos agrícolas indispensable para la buena alimentación del ser humano; y en la necesidad de establecer el tiempo de duración del mando y cambio de autoridades imperiales, comunales y civiles del pueblo.</p>    <p>Este calendario, según los expertos, se estima que se utilizó por primera vez alrededor del solsticio de invierno de 550 ANE (Antes de Nuestra Era) y fue creado para ser utilizado en conjunto con el <strong> Tzolkin </strong>. En operación conjunta, el <strong> Haab </strong> y el <strong> Tzolkin </strong> crean un ciclo más grande de 52 años llamado como la <strong> Rueda Calendárica </strong> o <strong> Calendario Redondo</strong> que fue utilizado no solo por los mayas sino también por el resto de las culturas en Mesoamericanas.</p>    <p> </p>    <h3>Utilidad</h3>    <hr />  <p>El calendario <strong> Habb\' </strong> sirve para el control de los fenómenos astronómicos y estacionales del año solar como lo son:</p>    <ul>  <li>Equinoccios</li>  <li>Solsticios</li>  </ul>    <p>También sirve para el establecimiento de nuevas autoridades de los pueblos, marca los ritos ceremoniales colectivos y las temporadas para la siembra de cultivos, aparte de definir el temperamento de las personas de acuerdo a la fecha de su nacimiento</p>    <h3>Exactitud</h3>    <hr />  <p>Debido a que el tiempo real que tarda nuestro Sol en reaparecer exactamente en las mismas posiciones que se ve desde la Tierra es un poco más largo que 365 días (365.2421897 días), se necesitan ajustes periódicos para mantener una acumulación de los recuentos anuales del calendario en alineación con la Tierra girando alrededor del sol.</p>    <p>Los antiguos mayas abordaron este problema de manera diferente a lo que hacemos hoy. En lugar de agregar un año bisiesto cada 4 años, restaron 13 días cada 52 años.</p>    <p>Es muy interesante saber que el calendario Haab\' tiene un error de solo 1 día en 6729 años, mientras que nuestro calendario “moderno” tiene un error de solo 1 día en 3236 años.</p>   ', '<p>The Maya solar calendar, called Haab\', is a count of 365 days and therefore approximates the solar year. It is the civil, agricultural calendar of the Maya, and it is the calendar of the Mayan kings.</p>
<p>The word <strong>"HAAB\'"</strong> means <strong>"YEAR"</strong> in the Yucatec Maya language.</p>
<p>The Haab\' consists of 18 months of 20 days each, plus a month consisting of 5 days. Each 20-day month, known as a uinal, has its own name. All of these 18 months together add up to 360 days.</p>
<p>The last month, composed of 5 days, is known as Wayeb. The 19 months in total add up to 365 days.</p>
<p><strong>18 x 20 + 5 = 365 </strong></p>
<figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" /><figcaption></figcaption></figure>
<p>It was elaborated by Maya astronomers and mathematicians to respond to people\'s need for food supply with the planting and harvesting of sacred corn, beans, and all kinds of agricultural products indispensable for human nutrition, as well as the need to establish the duration of imperial, communal, and civil authorities\' rule and change.</p>
<p>According to experts, this calendar is estimated to have been used for the first time around the winter solstice of 550 BCE (Before Common Era) and was created to be used in conjunction with the <strong>Tzolkin</strong>. In joint operation, the <strong>Haab</strong> and the <strong>Tzolkin</strong> create a larger cycle of 52 years called the <strong>Calendar Round</strong> or <strong>Round Calendar</strong>, which was used not only by the Maya but also by the rest of the cultures in Mesoamerica.</p>
<h3>Utility</h3>
<hr />
<p>The <strong>Haab\' calendar</strong> serves for the control of astronomical and seasonal phenomena of the solar year such as:</p>
<ul>
<li>Equinoxes</li>
<li>Solstices</li>
</ul>
<p>It also serves for the establishment of new authorities of the towns, marks the collective ceremonial rites and the seasons for crop planting, apart from defining the temperament of people according to their birth date.</p>
<h3>Accuracy</h3>
<hr />
<p>Because the actual time it takes our Sun to reappear exactly in the same positions as seen from Earth is a little longer than 365 days (365.2421897 days), periodic adjustments are needed to keep an accumulation of the calendar\'s annual counts in alignment with Earth revolving around the sun.</p>
<p>The ancient Maya addressed this problem differently from what we do today. Instead of adding a leap year every 4 years, they subtracted 13 days every 52 years.</p>
<p>It is very interesting to know that the Haab\' calendar has an error of only 1 day in 6729 years, while our "modern" calendar has an error of only 1 day in 3236 years.</p>', '<p>K\'alendario solar maya, tunichil Haab, u chi\'bil 365 kin a katún le jun pa le tunich. U k\'alendario civil le maya u chikin, u k\'alendario sakbe\' le maya, le k\'alendario le reyes le maya.</p>
<p>U t\'aan "<strong>HAAB\'</strong>" ti\' le yukatek maya wíinik ti\' <strong>ch\'a\'aj</strong>.</p>
<p>Haab\' u ch\'a\'bil kaaj 18 ti\' ik\'al le ja\' u k\'aaba\', ka\' 5 k\'iin b\'a\'alche\'. K\'u\' u k\'iino\' 20 k\'iin ka\' 10 k\'iin, k-iik\'p\'ajal u uinal, le ja\' 360 k\'iin.</p>
<p>Le chikin ja\', ku 5 k\'iin kaaj, le wil kab\' wayeb. Le chikin ja\' ku suut u yuum 365 k\'iin.</p>
<p><strong>18 x 20 + 5 = 365 </strong></p>
<figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" /><figcaption></figcaption></figure>
<p>U junilo\'ob le ch\'a\'bil le maya u biino\' u yóok\'olil ti\' u paalen kaj, k\'íiwiko\'ob ti\' le ujelil u yo\'osal maíz u sak, u k\'úuntul, yéetel kuxtal sak lu\'umo\'ob tsakaj ti\' k\'íiwiko\'ob u tsolikil chíik\'al yuumo\'ob, le káajil u chéen yéetel u ts\'o\'okil tumen le wáayel kab le meyaj, bejo\'ol k\'íiwiko\'ob yéetel le ts\'o\'okil tumen le ajawo\'ob le maya.</p>
<p>Ti\' expertos, u k\'alendario k\'u ya\'ab tení ti\' yéetel le katún k\'iin ti\' invierno 550 ANE (Antes le Era Utsil), yéetel xooko\'obo\' ku núuch le chíik\'al u k\'áat u k\'u\'ukul le <strong>Tzolkin</strong>. Ti\' jun k\'a\'atil le Tzolkin yéetel le Haab\', ku k\'áaxal u bíino\'ob kaab le 52 ja\', ku ya\'ab ts\'oon u <strong>Rueda Calendárica</strong> ka ts\'aaj le <strong>Calendario Redondo</strong>, ku yéetel ti\' le maya, tsikbal le k\'ultúuras ti\' Mesoamérica.</p>
<h3>Tsilbil</h3>
<hr />
<p>U k\'alendario <strong>Haab\'</strong> ku yik\'áayi\' u k\'íiwiko\'ob ti\' u ki\'ik\'el ma\' jach tumen k\'íiwiko\'ob yéetel k\'úuntules tuunichilo\'ob ti\' u kuxtalil wáayilo\'ob yéetel le kajtal lu\'umil ka\'aj:</p>
<ul>
<li>Ch\'aajits\'íijil</li>
<li>Uk\'ijil</li>
</ul>
<p>Ku yik\'áayi\' u bejla\'e\' ts\'a\'ak tuunichilil yéetel u yo\'osalil wil lu\'umo\'ob, yéetel xan tsikbal u bejla\'e\'il no\'oj, u k\'ajlayil u no\'oj yóok\'ol k\'íiwik tsakaj.</p>
<h3>Bin k\'áak\'al</h3>
<hr />
<p>Tu ja\' chíik\'al le ts\'íib k\'iin wáy u kaab u wil lu\'umil tsikbal tuunichilo\'ob t\'aano\' ya\'abtuun wa\'íitil le ts\'íib k\'iin kaab u wil lu\'umil tsikbal tuunichilo\'ob u t\'áano\' ti\' wáay. U k\'u\'ultúuril maya, k\'atik noj kaaj túun ti\' ka\'achila\'alo\' u k\'abkunilo\'ob k\'iin k\'iin wáy, xooko\'obo\' ku wiik chúumukil kaaj tuunichilo\'ob k\'u wiik chúumukilo\'ob.</p>
<p>Le maya wíiniko\'ob ka\'achile\' táanil u t\'an chíik\'al le ch\'a\'bil Haab\' táan, tumeen le wíinik chi\' kiin j-pajal k\'abkunilo\'ob u tsikbal tuunichilo\'ob u t\'aano\' le ja\' tuunichilo\'ob tumen tsikbal tuunichilo\'ob tu ja\' ki\'in wáay.</p>
<p>U k\'alendario Haab', '<p>Ri q’ijob’äl rech ch’akul maya, xub’an pa ri Haab\', jun utz’ib’äl chi 365 q’ij chi xub’an k’aslem jun junab’ k’aslem chi junab’ pa ch’akul ri q’ijob’äl rech ri reyob’ Maya.</p>
<p>Ri saq tzij <strong>"HAAB\'"</strong> xub’an chi <strong>"JUNAB\'"</strong> pa ri saq tzij maya yucateco.</p>
<p>Ri Haab’ xub’an chike 18 k’ak’a’ taq 20 q’ij jun k’ak’a’, jun taq chike jun k’ak’a’ ri’ xub’an 5 q’ij. Jun k’ak’a’ taq 20 q’ij, xub’an pa uinal, xub’an chik jun ch’ob’äl. Ri e 18 k’ak’a’ chi jun chikaxik jun 360 q’ij.</p>
<p>Ri ruwi k’ak’a’, xub’an pa 5 q’ij, xub’an chi Wayeb. Ri’ xub’anik 19 k’ak’a’ xub’an 365 q’ij.</p>
<p><strong>18 x 20 + 5 = 365</strong></p>

<figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" />  <figcaption></figcaption>  </figure>
<p>Ri xub’an pa k’aslem chike ri k’aslem chi junab’ ri’ ri’ xub’an chi ruxq’a’ jun ch’o’wa’ jun, ri b’on, chike e ch’akul rech taq xuti’, chike ri k’ak’a’ ri k’aslem chi junab’ ri ya’ xub’an pa ri rutzil q’ij chi pa ch’akul rech e reyob’, rech taqik ri ch’ak q’ij ri junab’ chike jun ajaw jun na’oj.</p>
<p>Ri’ xub’an chike jun xb’an chi jun q’ij pa ri ya’ xub’an pa e cholta’ ch’akul xub’an chike ri rux b’elejeb’ saqi’ k’aslem ANE (Antes de Nuestra Era) chi jun xub’an pa jun b’e chike junb’il chike <strong>Tzolkin</strong>. Pa chi junab’ chike <strong>Haab\'</strong> chike <strong>Tzolkin</strong> xub’an junab’ chi jun chikaxik chike 52 junab’ xub’an pa jun saq tz’ij chi xub’an chi <strong>Rueda Calendárica</strong> chike <strong>Calendario Redondo</strong> ri xub’an chi xkiwach chi jun pa Mesoamérica chike jun ch’akul.</p>

<h3>Uwachib’il</h3>
<hr />
<p>Ri q’ijob’äl <strong>Haab\'</strong> xub’an chi jun taqib’äl rech junab’ chik chi jun chikaxik pa ri junab’ chike ri’ xub’an pa jun:</p>
<ul>
<li>Equinoccios</li>
<li>Solsticios</li>
</ul>
<p>Xub’an chike jun ub’ikib’il rech ri ajawib’ jun junab’ chike junab’ chik jun ch’ub’ chike jun junab’ rech taq xuti’ chike jun nab’eyal chike jun ch’ikub’ chi jun utz’ib’äl chik pa jun chikaxik ri k’aslem.</p>

<h3>K’aslem rech junab’</h3>
<hr />
<p>Rumal ri ya’ xub’an pa jun k’aslem rech q’ij ri xub’an pa q’ij pa ri jun k’aslem chi 365 q’ij (365.2421897 q’ij), xub’an jun q’ijob’äl chi junab’ chi jun chikaxik chi junab’ pa ch’akul ri xutux ri jun chikaxik pa junab’ chi jun k’aslem chike jun junab’ pa ch’akul chi ri’ xub’an chi jun junab’ pa junab’ chi xq’a jun q’ij chi junab’ chike ri xub’an pa jun junab’ chi jun chikaxik chi ri ch’akul chi jun junab’ chi xab’ jun junab’ chi xkaq’ej chi ri ch’akul pa jun junab’ 13 q’ij chi junab’ chi jun chikaxik chi 52 junab’.</p>

<p>Ri junab’ xub’an pa ri q’ijob’äl Haab’ jun xkab’an pa jun q’ij 1 q’ij pa junab’ 6729 junab’, ri junab’ xub’an pa jun q’ijob’äl <em>moderno</em> jun xkab’an pa jun q’ij 1 q’ij pa 3236 junab’.</p>
', '<p>Le calendario solar maya, ku t\'aano\'ob Haab\', es jump\'éel cuenta de 365 k’iino’ob yéetel bejo’ ku ya’abil tu ja’ab solar, es le calendario civil, agrícola maya, es le calendario le nojoch máak’ab Mayas.</p>
<p>Le t\'aan <strong> "HAAB\'" </strong> ku t\'aano\'ob <strong> "AÑO" </strong> tu t\'aan maya yucateco.</p>
<p>Le Haab’ ku ya’abil tu 18 meses de 20 k’iino’ob jump’éel, más jump’éel mes ku t’aan 5 k’iino’ob. Jump’éel mes de 20 k’iino’ob, ku t’aan uinal, ku ya’abil u propio t’aan. Le nojoch 18 meses ku ya’abil 360 k’iino’ob.</p>
<p>Le último mes, ku ya’abil tu 5 k’iino’ob, ku t’aano’ob Wayeb. Le 19 meses tu ya’abil ku ts\'ook 365 k’iino’ob.</p>
<p><strong>18 x 20 + 5 = 365 </strong></p>
<p></p>
<figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" />
<figcaption></figcaption>
</figure>
<p>Fue elaborado por los astrónomos y matemáticos mayas para dar respuesta a la necesidad de las personas para su abastecimiento de alimento con la siembra y cosecha del sagrado maíz, el frijol, y toda clase de productos agrícolas indispensables para la buena alimentación del ser humano; y en la necesidad de establecer el tiempo de duración del mando y cambio de autoridades imperiales, comunales y civiles del pueblo.</p>
<p>Este calendario, según los expertos, se estima que se utilizó por primera vez alrededor del solsticio de invierno de 550 ANE (Antes de Nuestra Era) y fue creado para ser utilizado en conjunto con el <strong> Tzolkin</strong>. En operación conjunta, el <strong> Haab</strong> y el <strong> Tzolkin</strong> crean un ciclo más grande de 52 años llamado la <strong>Rueda Calendárica</strong> o <strong>Calendario Redondo</strong> que fue utilizado no solo por los mayas sino también por el resto de las culturas en Mesoamérica.</p>
<p></p>
<h3>Utilidad</h3>
<hr />
<p>Le calendario <strong>Haab\'</strong> ku yáantaj ti’ le nojoch ka’analil yéetel le ka’analil tu ja’ab solar bey jump’éel:</p>
<ul>
<li>Equinoccios</li>
<li>Solsticios</li>
</ul>
<p>Ku yáantaj xan ti’ le ka’analil ti’ jump’éel nojoch máak’ab le kaajo’ob, ku ya’abil le ritos ceremoniales nojoch yéetel le k’iino’ob para la siembra de cultivos, yéetel ku yáantaj le temperamento le máak’ab tu ja’ab u k’iino’obil le k’iino’obil u ya’abil.</p>
<h3>Exactitud</h3>
<hr />
<p>Ti’ jump’éel k’iin ku ya’abil le nojoch ka’analil ku yant u K’iin tu ya’abil tu ya’ab nojoch posiciones ku ya’abil tu yóok’ol Nojoch Lu’um es un poco más largo que 365 k’iino’ob (365.2421897 k’iino’ob), ku ya’abil ajustes periódicos para mantener jump’éel nojoch cuenta le ja’abil le calendario tu ya’abil tu Nojoch Lu’um ximbal tu yóok’ol le K’iin.</p>
<p>Le nojoch máak’ab mayas ku t’aan jump’éel jump’éel manera diferente ti’ le ku t’aan ti’ le k’iino’ob. En lugar de agregar jump’éel ja’ab bisiesto cada 4 ja’ab, restaron 13 k’iino’ob cada 52 ja’ab.</p>
<p>Es muy interesante saber que le calendario Haab’ ku ya’abil jump’éel error de solo 1 k’iin tu 6729 ja’ab, bey jump’éel le calendario “moderno” ku ya’abil jump’éel error de solo 1 k’iin tu 3236 ja’ab.</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 'Informacion', 'Rueda Calendarica', 'Informacion', '<p>El nombre completo de cualquier fecha en el sistema de calendario maya consiste de una fecha Tzolk’in y una fecha Haab. La Rueda Calendárica es el entretejido de los calendarios Tzolk’in y Haab. En la Rueda Calendárica, una combinación del Tzolk’in y el Haab no se repetirán hasta que hayan pasado 52 períodos de 365 días. Esto está basado en el concepto matemático de “el mínimo común denominador” y “el mínimo común múltiplo”. Ambos números, 260 y 365, son divisibles por 5, y 260 dividido por 5 es igual a 52, mientras que 365 dividido por 5 es igual a 73. Por lo tanto, el mínimo común múltiplo de 260 y 365 es 5 x 52 x 73 = 18,980.</p><p>De este modo, la Rueda Calendárica es igual a 18,980 días, 52 x 365 o 52 años Haab. Los mayas creen que cuando una persona alcanza los 52 años de edad, ellos atienen la sabiduría especial de un anciano. Una fecha de la Rueda Calendárica, con componentes tanto del calendario Tzolk’in como el Haab, puede marcar de forma única un evento dentro de un período de 52 años. Sin embrago, cualquier evento que abarque más de 52 años requiere un calendario adicional, el calendario de Cuenta Larga.</p><img src="../img/ruedaCalendarica.gif" style="width: 100%"><p>El círculo más pequeño está conformado por 13 números; el círculo mediano por los 20 signos de los veinte días mayas del calendario Tzolkin, y el círculo más grande por el calendario haab con sus 365 días (dieciocho meses de veinte días y el mes corto de cinco días). En este conteo, los mayas consideraban que el día de la creación fue el 4 ahau 8 cumkú.</p><p>Cada cíclo de 18.980 días equivale a 52 vueltas del haab (calendario solar de 365 kines) y a 73 vueltas del tzolkin (calendario sagrado de 260 kines), y al término ambos vuelven al mismo punto. Cada 52 vueltas del haab se celebraba la ceremonia del fuego nuevo, analógicamente era un "siglo maya".</p>', '<p>The complete name of any date in the Maya calendar system consists of a Tzolk’in date and a Haab date. The Calendar Round is the interweaving of the Tzolk’in and Haab calendars. In the Calendar Round, a combination of the Tzolk’in and the Haab will not repeat until 52 periods of 365 days have passed. This is based on the mathematical concept of "the least common denominator" and "the least common multiple". Both numbers, 260 and 365, are divisible by 5, and 260 divided by 5 equals 52, while 365 divided by 5 equals 73. Therefore, the least common multiple of 260 and 365 is 5 x 52 x 73 = 18,980.</p>

<p>Thus, the Calendar Round is equal to 18,980 days, 52 x 365 or 52 Haab years. The Maya believe that when a person reaches 52 years of age, they attain the special wisdom of an elder. A date from the Calendar Round, with components of both the Tzolk’in and the Haab calendar, can uniquely mark an event within a 52-year period. However, any event spanning more than 52 years requires an additional calendar, the Long Count calendar.</p>

<img src="../img/ruedaCalendarica.gif" style="width: 100%" />

<p>The smallest circle is composed of 13 numbers; the medium circle by the 20 signs of the twenty Maya days of the Tzolkin calendar, and the largest circle by the Haab calendar with its 365 days (eighteen months of twenty days and the short month of five days). In this count, the Maya considered that the day of creation was 4 ahau 8 cumkú.</p>

<p>Each cycle of 18,980 days is equivalent to 52 turns of the Haab (365-day solar calendar) and 73 turns of the Tzolkin (260-day sacred calendar), and at the end, both return to the same point. Every 52 turns of the Haab, the ceremony of the New Fire was celebrated, analogously it was a "Maya century".</p>', '<p>Ti xaqachal ri nawal chi ri winäq ri maya, kach’ij pa k’iche’, xkanarik xolotaj wi na kawok K’iche’. Chich’an chi atinamit pa chuchqaj wi’, xk’utaj winaq pa chuwachab’, kiq’achawaj, xk’utaj winaq kitz’alaj chi xkik’ajol winaqab’, kiq’achawaj nawal chuwachab’. Chi xkinanok ri tzij pa chikam winaqil, yumi’ chikeje wi’ chiri k’ut chicach chi naj, kiwäch chi nawal kitzij winaq. Kutzij k’ut nawal kitzij chwäch chi nuk’uj.</p>

<p>Xkanarik xolotaj xk’aslemal kawo’ Pa chuwachab’ ri nahualil ri winäq, xkik’ajol winaq kiq’achawaj, xk’utaj winaq xq’aje’ chi ri uk’u’x winaq pa nawal kitzij winaq chi wachaj wi’ chiri k’ut chicach, kiq’achawaj xpe nawal chi ri winäqil xq’axikab’. Chuchqaj winaq chwäch chi winäqil, xk’utaj winaq xk’utaj nawal kiq’achawaj, yumi’ xkik’ajol winaq xkinanok ri k’ut kitzij winaq, yumi’ xkik’ajol kitzij chwäch chi nuk’uj, yumi’ xk’utaj kitzij winaq chi k’ut chwäch chi chuwachab’ chi winäqil. Xk’utaj kitzij winaq chi kawok wi’ chiri chwäch chi nawal kitzij winaq chuwachab’.</p>

<p>Xwakamiq’ij winaq k’iche’ xkawok k’iche’, xkanarik xolotaj xkik’ajol winaq chi quixkamab’ej nab’ey k’ut, xk’utaj winaq xpe kitzij k’ut chi nawal k’iche’ chi kib’ey, xkanarik xolotaj xkinanok ri nawal kitzij winaq chuwachab’ ri chuwachab’ chi quixkamab’ej nab’ey. Xpe winaq k’ut kawok k’iche’ xkik’ajol nawal chwäch chi chuwachab’ chiri k’ut chicach, xpe kitzij k’ut chi nawal kitzij winaq, yumi’ xk’utaj winaq chwäch chi nuk’uj, yumi’ xkinanok winaq chwäch chi k’ut, yumi’ xkinanok winaq chwäch chi quixkamab’ej nab’ey k’ut.</p>
', '<p>Ri saq b’i’ik ri taq q’ij pa jun utz’ib’äl rech jun q’ijob’äl maya xub’an chik jun q’ij Tzolk’in chike jun q’ij Haab’. Ri Rueda Calendárica xub’an jun chikawach ri q’ijob’äl Tzolk’in chike Haab’. Pa ri Rueda Calendárica, jun chiq’aq’ jun Tzolk’in chike jun Haab’ maj k’oyi chi jun chikaxik jun 52 taq q’ij junab’ taq 365 q’ij. Ri’ xub’an chi jun q’ij richin utz’ib’äl ri’ xub’an chik "jun chik q’ij richin ri’ jun chik xkalem" chike "jun chik xk’oy q’ij richin xkalem." E junab’ junab’ jun xkiwach 5, chike 260 k’a ch’ab’il chike 5 xa 52, xk’i 365 k’a ch’ab’il chike 5 xa 73. Ri’ xub’an chi jun chik xkalem richin jun 260 chike 365 jun 5 x 52 x 73 = 18,980.</p>

<p>Ri’ xub’an, ri Rueda Calendárica xub’an chi 18,980 q’ij, 52 x 365 chike 52 junab’ Haab’. Ri Maya xkiwach chi kaqal chi jun 52 junab’ chi jun ch’ab’il chi jun q’ij. Jun q’ij pa ri Rueda Calendárica, chike jun saq b’i’ik rech ri q’ijob’äl Tzolk’in chike ri Haab’, xub’an chi k’aslem jun q’aq’ jun 52 junab’. Xa jun q’aq’ xub’an chi jun 52 junab’ xub’an chi utz’ib’äl jun ch’akul, ri q’ijob’äl rech Utz’ib’äl Chik.</p>

<img src="../img/ruedaCalendarica.gif" style="width: 100%" />

<p>Ri jun xq’aq’ chi xub’an pa 13 nab’eyal; ri jun xq’aq’ chi xub’an 20 b’i’ik ri jun 20 q’ij ri q’ijob’äl Tzolk’in, chike ri jun xq’aq’ chiki ri q’ijob’äl Haab’ chike junab’ chi 365 q’ij (jun k’ak’a’ taq 20 q’ij chike jun k’ak’a’ chik pa 5 q’ij). Pa ri wachib’il, ri Maya xub’an chi jun q’ij pa ri xutz’ub’ chi jun 4 ahau 8 cumkú.</p>

<p>Jun chikaxik taq 18,980 q’ij xub’an chi 52 junab’ ri haab’ (q’ijob’äl ch’akul rech 365 q’ij) chike 73 junab’ ri tzolk’in (q’ijob’äl ch’ab’il rech 260 q’ij), chi xk’oyi k’a jun chi jun chikaxik jun q’ij. Jun chi 52 junab’ ri haab’ xub’an jun jun q’aq’ chi junab’ ri q’aq’ nuevo, xuquje’ xub’an jun "siglo maya."
</p>
', '<p>Le t\'aan completo tu jump\'éel k’iin tu sistema calendario maya ku ya’abil tu jump’éel k’iin Tzolk’in yéetel
jump’éel k’iin Haab’. Le Rueda Calendárica es le nojoch máak’ab le calendarios Tzolk’in y Haab’. Tu le Rueda
Calendárica, jump’éel combinación le Tzolk’in y le Haab’ ma’ ku ts’ook hasta ku ya’abil 52 períodos
de 365 k’iino’ob. Le t’aan ku yáantaj tu concepto matemático de “le mínimo común denominador” y “le mínimo
común múltiplo”. Le ka’a números, 260 y 365, ku ya’abil divisibles por 5, yéetel 260 dividido por 5 ku ya’abil igual a 52, mientras 365 dividido por 5 ku ya’abil igual a 73. Bey, le mínimo común múltiplo de 260 y 365 es 5 x 52 x 73 = 18,980.</p>

<p>Tu bejil, le Rueda Calendárica ku ya’abil igual a 18,980 k’iino’ob, 52 x 365 o 52 ja’ab Haab’. Le máak’ab maya ku ya’abil ku ya’abil jump’éel 52 ja’ab yéetel ku ya’abil u ts’ookbilil u nojoch máako’ob. Jump’éel k’iin le Rueda Calendárica, ku ya’abil componentes le calendario Tzolk’in yéetel le Haab’, ku ya’abil ti’ jump’éel nojoch jump’éel evento tu jump’éel período de 52 ja’ab. Ba\'ale’, jump’éel evento ku ya’abil más de 52 ja’ab ku ya’abil jump’éel calendario adicional, le calendario de Cuenta Larga.</p>

<img src="../img/ruedaCalendarica.gif" style="width: 100%" />

<p>Le círculo más pequeño ku ya’abil tu 13 números; le círculo mediano ku ya’abil tu 20 signos le veinte k’iino’ob maya le calendario Tzolk’in, yéetel le círculo más grande ku ya’abil le calendario Haab’ ku 365 k’iino’ob (dieciocho meses le veinte k’iino’ob yéetel le mes mejen le cinco k’iino’ob). Tu le ts’ookil, le máak’ab maya ku ya’abil ku le k’iin le creación ku ya’abil le 4 ahau 8 cumkú.</p>

<p>Jump’éel ciclo de 18,980 k’iino’ob ku ya’abil igual a 52 vueltas le Haab’ (calendario solar de 365 kines) yéetel 73 vueltas le Tzolk’in (calendario nojoch le 260 kines), yéetel ku ya’abil le ts’ook ku ya’abil le mismo punto. Cada 52 vueltas le Haab’ ku ya’abil le ceremonia del nuevo fuego, ku ya’abil un "siglo maya".</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (1, 'Kin', 'Calendario Haab', 'Elementos', '<p>La escritura maya era un sistema logosilábico cuyo significado es discutido. Los símbolos individuales ("glifos") podían representar bien una palabra (normalmente un morfema) o una sílaba; a decir verdad, el mismo glifo con frecuencia podía usarse de las dos formas.</p>    <figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" />  <figcaption></figcaption>  </figure>    <p> </p>', '<p>Maya writing was a logosyllabic system whose meaning is debated. Individual symbols ("glyphs") could represent either a word (usually a morpheme) or a syllable; indeed, the same glyph could often be used in both ways.</p>
<figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" /> <figcaption></figcaption> </figure>
<p> </p>', '<p>Ri riwächil maya xq’ijib’äl k’iche’, xkanarik xolotaj xkik’ajol winaq chi rutz’ij tz’ikin; rutz’ij tz’ikin xwäch’aj wi’ chiri k’ut chicach chi nawal kitzij winaq, xk’utaj winaq xk’utaj nawal chwäch chi nawal k’iche’, yumi’ xkik’ajol nawal chwäch chi chuwachab’ chiri k’ut chicach. </p>
<figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" />  <figcaption></figcaption>  </figure>
<p> </p>', '<p>Ri utz’ib’äl maya xub’an jun sistema logosilábico ri jun k’aslem xaya utzib’ej. Ri junb’il saq b’i’ik ("glifos") xub’an chi jun chik richin ri jun saq b’i’ik (xaja jun morfema) o jun sílaba; pa k’aslem, ri jun chik saq b’i’ik xub’an chi jun richin ri chike jun chi xk’oyi taq ri jun b’i’ik.</p>
<figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" /> <figcaption></figcaption> </figure>
<p> </p>
', '<p>Le ts\'íib maya ku ya\'abil jump\'éel sistema logosilábico le ku t\'aano\'ob ku ya\'abil discusiones. Le símbolos individuales ("glifos") ku ya\'abil representar jump\'éel t\'aan (tu láak\' le morfema) o jump\'éel sílaba; tu t\'aanil, le mismo glifo ku ya\'abil usarse jump\'éel bejil ku nojoch jump\'éel dos formas.</p>
<figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" />
<figcaption></figcaption>
</figure>
<p></p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (1, 'Mecanismo', 'Rueda Calendarica', 'Informacion', '<h2>Mecanismo</h2>

<p>De la Rueda del Calendario, se dice que el ciclo de 52 años es más importante que el año.</p>

<p>Un ejemplo de fecha en la rueda calendárica, 8 Cauac 13 Zip, se referiría al octavo día de la trecena Cauac en el Tzolkin, que coincide con el día 13 de Zip en el Haab.</p>

<p>La diferencia entre los 52 años de 365 días cada uno y los 52 años de 360 días, es de 260 días exactamente; así se puede llevar el cálculo de sus coincidencias a través de ciclos de 260 días, ya que</p>

<ul>
	<li>18 980 = 73 x 260</li>
	<li>18 720 = 72 x 260</li>
	<li>5 256 = 72  x 73 = 9 x 584.​</li>
</ul>

<p>También debe ser tomado en cuenta que 13 x 360 = 18 x 260 = 4 680.</p>

<p> 	Es decir, si los 5 días de Uayeb\' son omitidos (como debe haber sido el caso en los orígenes del calendario), los períodos de 360 y de 260 días coincidirían después de, respectivamente, 13 y 18 ciclos (13 "años" de 360 días).</p>
	Cuatro de esos ciclos de 13 "años" abarcan 52 "años" de 360 días.
	Ahora, 52 veces esos 5 adicionales días de Wayeb\' resultan en exactamente uno más de los ciclos de 260 días.</p>
	<p>El sistema de la rueda calendárica, sirve para interpretar una sucesión infinita de períodos de 52 años. Se desconoce su nombre en lenguas mayenses, pero el nombre en idioma náhuatl utilizado por los mexicas era "Xiuhnelpilli", aunque es más usual encontrarlo escrito como Xiuhmolpilli, forma gramaticalmente incorrecta; cuyo significado es anudación de los años.</p>

	<p>Cada 52 años las culturas mesomericanas realizaban importantes ceremonias. Para el caso de los mexicas era la llamada "ceremonia del fuego nuevo".
</p>
', '<h2>Mechanism</h2>

<p>From the Calendar Wheel, it is said that the 52-year cycle is more important than the year.</p>

<p>An example of a date on the calendar wheel, 8 Cauac 13 Zip, would refer to the eighth day of the Cauac trecena in the Tzolkin, which coincides with the 13th day of Zip in the Haab.</p>

<p>The difference between the 52 years of 365 days each and the 52 years of 360 days is exactly 260 days; thus the calculation of their coincidences can be carried out through cycles of 260 days, since</p>

<ul>
    <li>18,980 = 73 x 260</li>
    <li>18,720 = 72 x 260</li>
    <li>5,256 = 72 x 73 = 9 x 584.</li>
</ul>

<p>It should also be noted that 13 x 360 = 18 x 260 = 4,680.</p>

<p>That is, if the 5 days of Uayeb\' are omitted (as must have been the case in the origins of the calendar), the periods of 360 and 260 days would coincide after, respectively, 13 and 18 cycles (13 "years" of 360 days).</p>
<p>Four of these cycles of 13 "years" encompass 52 "years" of 360 days. Now, 52 times those 5 additional days of Wayeb\' result in exactly one more cycle of 260 days.</p>

<p>The system of the calendar wheel serves to interpret an infinite succession of periods of 52 years. Its name in Mayan languages is unknown, but in the Nahuatl language used by the Mexicas it was called "Xiuhnelpilli," although it is more commonly written as Xiuhmolpilli, a grammatically incorrect form; which means bundling of years.</p>

<p>Every 52 years, the Mesoamerican cultures performed important ceremonies. In the case of the Mexicas, it was the so-called "ceremony of the new fire."</p>', '<h2>K’ut</h2>

<p>Chi k’oxajil Winaq’ ronojelaj 52 k’ajkunab’ chuqa ri le k’aj.</p>

<p>Umukajil che ri ajb’i Winaq’ ronojelaj, 8 Cauac 13 Zip, xkanarik xolotaj xkik’ajol wi’ chiri k’ut chicach ri c’i Winaq’ ronojelaj, chiwicha ri ajb’i 13 Zip ri c’i Winaq’ k’aj.</p>

<p>Chiri wi’ chi’ 52 ronojelaj winaq chuqa kitzij 365 k’ajkunab’, chiri wi’ 52 ronojelaj winaq chuqa kitzij 360 k’ajkunab’ chiwa’ 260 k’ajkunab’ chiwi’; chiqa kitzij ronojelaj winaq rutz’ij tz’ikin, chi’.</p>

<ul>
    <li>18,980 = 73 x 260</li>
    <li>18,720 = 72 x 260</li>
    <li>5,256 = 72 x 73 = 9 x 584.</li>
</ul>

<p>Ko’xaj kitzij q’atin ri 13 x 360 = 18 x 260 = 4,680.</p>

<p>Winaq chuwächik, chi ri 5 k’ajkunab’ re Uayeb’ chi’ xkib’aj ri q’atin k’aj kitzij q’atin, chi’.</p>

<p>Q’ati’ chuwächik ronojelaj winaq chuqa k’aj kitzij kitzij kitzij chuwächik kitzij re 52 chuwächik re xolabaj k’aj.</p>

<p>Tajin, 52 q’atin kitzij ri kitzij q’atin k’aj kitzij chuwächik kitzij kitzij kitzij kitzij chuwächik.</p>

<p>Yumi’ ri, 52 chuwächik kitzij ri 5 taqaj q’atin ri’i’ Wayeb’ chi’ xkib’aj ri q’atin k’aj kitzij q’atin.</p>

<p>Q’ati’ chuwächik ronojelaj winaq xkik’ajol wi’ chi’, xwäch’aj wi’ chi’ ri k’iche’ kitzij junan chi k’aj xik’in chi’, xwäch’aj wi’ chi’ ri k’iche’ kitzij junan chi kitzij q’atin winaq chi c’i, xkanarik xi’ q’atin xolabaj tz’ikin kitzij.</p>

<p>Ri c’i 52 chuwächik kitzij ronojelaj winaq, chuwächik winaq chiqa chuwächik q’atin wi’ junan. Chiri chi mexica\';', '<h2>Mecanismo</h2>

<p>Chi ri Rueda ri Q’ijob’äl, xub’an chi ri chikaxik taq 52 junab’ ri jun chik k’aslem chi junab’.</p>

<p>Jun ruwäch richin ri q’ij pa ri rueda calendárica, 8 Cauac 13 Zip, xub’an chi ri ruwäch q’ij pa ri trecena Cauac pa ri Tzolkin, ri jun chik ri xel 13 pa Zip pa ri Haab.</p>

<p>Ri xub’an chi jun chik pa ri 52 junab’ ri 365 q’ij chi ri 52 junab’ ri 360 q’ij, xub’an chi 260 q’ij taq pa ri; chi ke ri xub’an chi jun chik richin ri xka’iqil chi e pa junab’ ri 260 q’ij, chi ke:</p>

<ul>
<li>18 980 = 73 x 260</li>
<li>18 720 = 72 x 260</li>
<li>5 256 = 72 x 73 = 9 x 584</li>
</ul>

<p>Xujunila chi jun chik xub’an chi 13 x 360 = 18 x 260 = 4 680.</p>

<p>Ri xub’an chi, chi ri ri 5 q’ij ri Uayeb’ xub’an chi jun saq b’i’ik (chi jun chiq ri jun chik pa ri q’ijob’äl), ri chikaxik taq 360 chi 260 q’ij xub’an chi jun jun chi, respectivamente, 13 chi 18 chikaxik (13 "junab’" ri 360 q’ij).</p>
<p>Ri ri’, ri 4 ri jun chik chi 13 "junab’" xub’an chi 52 "junab’" ri 360 q’ij. Ri xub’an chi 52 xujunila ri 5 q’ij ri Wayeb’ xub’an chi jun chik chi 260 q’ij.</p>
<p>Ri sistema ri rueda calendárica xub’an chi jun jun saq b’i’ik richin jun chik pa jun chikaxik taq 52 junab’. Xaya saq b’i’ik pa ri k’iy taq chi maya’, chi ri k’iy pa ri náhuatl xub’an chi xiuhnelpilli, xub’an jun chik chi xiuhmolpilli, xub’an chi jun k’aslem richin ri anudación ri junab’.</p>

<p>Ri 52 junab’ xub’an chi jun k’aslem taq saq ch’akul. Chi ri mexicas xub’an chi chi ruwäch "ceremonia del fuego nuevo".</p>
', '<h2>Mecanismo</h2>

<p>Tu Rueda del Calendario, ku t’aano’ob que le ciclo de 52 ja’ab es ma’ importante que le ja’ab.</p>

<p>Jump’éel ejemplo de k’iin tu rueda calendárica, 8 Cauac 13 Zip, ku ya’abil ku tsikbal le octavo k’iin de la trecena Cauac tu Tzolkin, le ku ts’ook ku jump’éel k’iin 13 de Zip tu Haab.</p>

<p>Le diferencia entre le 52 ja’ab de 365 k’iino’ob yéetel le 52 ja’ab de 360 k’iino’ob, es de 260 k’iino’ob exactamente; beyo’ ku ya’abil ku xook le nojoch u ya’abil u coincidencias tu ciclos de 260 k’iino’ob, ya’ax ku ya’abil:</p>

<ul>
<li>18,980 = 73 x 260</li>
<li>18,720 = 72 x 260</li>
<li>5,256 = 72 x 73 = 9 x 584</li>
</ul>

<p>Bey xan ku ya’abil ku yaantal tu cuenta que 13 x 360 = 18 x 260 = 4,680.</p>

<p>Es t’aan, si le 5 k’iino’ob de Uayeb’ ku omitidos (como ku ya’abil le caso tu los orígenes del calendario), le períodos de 360 y de 260 k’iino’ob ku ya’abil después de, respectivamente, 13 y 18 ciclos (13 "ja’ab" de 360 k’iino’ob).</p>

<p>Kuatro de le ciclos de 13 "ja’ab" ku ya’abil 52 "ja’ab" de 360 k’iino’ob.
Ahora, 52 veces le 5 k’iino’ob adicionales de Wayeb’ ku ya’abil tu exactamente jump’éel más de le ciclos de 260 k’iino’ob.</p>

<p>Le sistema de le rueda calendárica, ku ya’abil ku t’aan jump’éel nojoch suceso de períodos de 52 ja’ab. Ku t’aan ku ya’abil su t’aan tu t’aan mayenses, ba’ale’ le t’aan tu t’aan náhuatl ku ya’abil por le mexicas ku "Xiuhnelpilli", ba’ale’ es ma’ usual ku ya’abil ku yaan escrito como Xiuhmolpilli, forma gramaticalmente incorrecta; le significado es anudación de los ja’ab.</p>

<p>Cada 52 ja’ab le culturas mesomericanas ku ya’abil importantes ceremonias. Ti’ le caso de los mexicas es la llamada "ceremonia del fuego nuevo".</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (1, 'Nahual', 'Calendario Cholquij', 'Elementos', '<p>Nahual, también llamado <strong>nagual</strong> o <strong>nawal​</strong> (en náhuatl: nahualli ‘oculto, escondido, disfraz’), dentro de las creencias mesoamericanas, es una especie de brujo o ser sobrenatural que tiene la capacidad de tomar forma animal. El término refiere tanto a la persona que tiene esa capacidad como al animal mismo que hace las veces de su alter ego o animal tutelar.

<p>De acuerdo con la tradición y cosmovisión de los pueblos Mesoamericanos los Nahuales son espíritus y energías protectoras que acompañan a todos los elementos de la naturaleza, incluyendo a los humanos y animales a lo largo de toda su existencia.</p>

<p>Para la civilización Maya el nahual de cada persona era de suma importancia. Era algo que todos debían conocer y aprender a manejarlo. Debían saber cuándo se fue engendrado, la fecha de nacimiento, el año, la energía que le protege y su misión.</p>

<p>Dentro de la cultura maya se dice que cada uno está relacionado con un animal  que es quién le dirige, como un ángel guardián, alguien con quien se identifica, con quien se encuentra conectado espiritualmente. Se dice también que cada persona incluso nace con el espíritu de un animal, y este se encarga de protegerlo y guiarlo.</p>

<h2 class="text-center"> conoce los nahuales:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>', '<p>Nahual, also called <strong>nagual</strong> or <strong>nawal</strong> (in Nahuatl: nahualli \'hidden, concealed, disguised\'), within Mesoamerican beliefs, is a kind of sorcerer or supernatural being that has the ability to take animal form. The term refers both to the person who has that ability and to the animal itself that serves as their alter ego or tutelary animal.</p>

<p>According to the tradition and worldview of Mesoamerican peoples, Nahuales are protective spirits and energies that accompany all elements of nature, including humans and animals throughout their existence.</p>

<p>For the Maya civilization, the nahual of each person was of utmost importance. It was something that everyone should know and learn to handle. They needed to know when they were conceived, their date of birth, the year, the energy that protects them, and their mission.</p>

<p>Within Mayan culture, it is said that each person is related to an animal that guides them, like a guardian angel, someone they identify with, with whom they are spiritually connected. It is also said that each person is even born with the spirit of an animal, and this spirit is responsible for protecting and guiding them.</p>

<h2>Meet the nahuales:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>
', '<p>Nahual, ronojel k\'iche\' nahualli \'sobrevivir, k\'ajolil, ronojel\' (chi\' náhuatl: nahualli \'tajak, tajak, tajak\'), wi\' jun chimalaj tz\'ikin uta ronohel matalaj chik, nimat xk\'utij ti ri nahual. Wi\' xu\'na\'ab\' wi\' k\'utinon kib\'ajil achi wi\' k\'iche\' uk\'uxaj awach matalaj jun ajmaqik tu\'bil achi tu\'bil nuk\'ayaj.</p>

<p>Xek\'onojel uk\'uxa\' ki\'wikalajaj achi ajuach ki\'wi\' ri uk\'uxa\' xik\'al wi\' chik, ki\'wi\' uk\'uxa\'xik\'alil k\'ajolilejil chi kaj chuunil ronojelajil k\'iche\', k\'ajol, u yax b\'antaj ta xk\'utij awachilaj.</p>

<p>Ta chi k\'iche\' k\'ajol, xu\'na\'ab\' wi\' tz\'akb\'aliwi\' achi uk\'uxa\' chik\'alil ut achi k\'iche\' chi ta\' wach kib\'ajil, ri winaq chik ri tu\'bil, ri k\'ajol, achi ri uk\'uxa\' xik\'alil k\'ajol chik ri wi\' chik\'alilejil. Ta wi\' chik ri k\'utinon awach wi\' k\'iche\' chik\'ajil, achi ta ri ajmaqik ronohel ruk\' ri awach xk\'utij ta ronohel uta xk\'utijil.</p>

<h2> Tunajel ri nahual:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>', '<p>Nahual, xub’an chik ri <strong>nagual</strong> chi <strong>nawal</strong> (pa ri náhuatl: nahualli \'oculto, escondido, disfraz\'), xub’an chi ri k’aslem ri nahuales mesoamericanos, chi ri junab’ saq ch’akul chi chi ri chiwäch chike chi chiwi\' chik ri aqi\' pa ri chikop, chiwäch xub’an chi ri jun chik ri chi k\'utk\'axik chik ri q\'ij ri laq\' taq ri ri kaj wi.

<p>Taq saq xcha\'ib\'al chi ri tradición y cosmovisión ri ri chikop Mesoamericanos ri Nahuales wi saq ch’akul ri ri chikop ri chi ri rutz\'ib\'äl, ki\' ri saq k\'o ri chirutz\'ib\'äl chike, xub\'an chi ri chiwi\' chik chik ch\'akul rutz\'ib\'äl k\'utk\'axik ri q\'ij ri lalaki\' ri chirutz\'ib\'äl k\'i\'.</p>

<p>Chi ri chiwäch Maya wi ri nahual pa ri wi\' ki\'xik chike wi. Ri xka\'it ri wi\' chike aq\'ijik ri ri chik q\'ij, ri b\'i\'ik, ri rutz\'ib\'äl chike chirutz\'ib\'äl k\'utk\'axik ri chik ri q\'ij.</p>

<p>Chi ri chirutz\'ib\'äl maya xub\'an chi ri chik chike ri jun k\'o taq k\'i\' ri chiwäch chike, xub\'an chik ri chikop chirutz\'ib\'äl, chib\'an q\'ij chikop taq ri q\'ij k\'utk\'axik ri junab\', yul pa taqib\'äl chirutz\'ib\'äl k\'utk\'axik.</p>

<h2>Conoce ri nahuales:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>
', '<p>Nahual, bey xan ku t’aano’ob <strong>nagual</strong> o <strong>nawal</strong> (tu náhuatl: nahualli ‘oculto, escondido, disfraz’), tu le kuxtal ku ya’abil mesoamericanas, ku ya’abil jump’éel máak’ o máak’ nojoch le ku ya’abil u k’áat ku ya’abil forma le ba’al. Le t’aan ku t’aano’ob tanto tu jump’éel máak’ ku ya’abil le k’áat como tu ba’al ku ya’abil jump’éel alter ego o ba’al tutelar.</p>

<p>Tu yáantaj ku t’aano’ob yéetel le cosmovisión le máak’ob Mesoamericanos le Nahuales ku ya’abil pixano’ob yéetel yáantajo’ob nojoch ku ya’abil tu yáaxil jump’éel le ba’alilo’ob le yaan yéetel le máak’ob yéetel ba’alo’ob tu ts\'ook u kuxtal.</p>

<p>Tu le kuxtal Maya le nahual tu jump’éel máak’ ku ya’abil nojoch importancia. Ku ya’abil jump’éel ba’ax ku yaan u t’aan yéetel ku ts’o’okol ku ya’abil. Ku ya’abil ku ya’abil jump’éel ka’anal yéetel ku ya’abil. Ku ya’abil ku ya’abil ku ya’abil jump’éel u k’iin le ya’abil, le k’iin u ya’abil, le ja’ab, le yáantaj ku ya’abil yéetel le misión ku ya’abil.</p>

<p>Tu le kuxtal maya ku t’aano’ob ku ya’abil jump’éel tu ka’anal yéetel jump’éel ba’al ku yaan ku ku ya’abil, bey jump’éel ángel guardián, ku máako’ob ku ya’abil ku t’aano’ob, ku ya’abil ku ya’abil nojoch yéetel tu pixanil. Ku t’aano’ob xan ku jump’éel máak’ incluso ku ya’abil tu pixan le jump’éel ba’al, yéetel le ba’al ku ya’abil u ya’abil yéetel ku ya’abil ku ya’abil.</p>

<h2> conoce los nahuales:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (3, 'Uayeb', 'Calendario Haab', 'Elementos', '<p>Los últimos cinco días del ciclo de Haab son el mes 19, llamado Uayeb. Estos son días impredecibles, no para planificar eventos importantes o viajar fuera de casa.</p>', '<p>The last five days of the Haab cycle are the 19th month, called Uayeb. These are unpredictable days, not suitable for planning important events or traveling away from home.</p>
', '<p>Ri\' uk\'uxaj taq k\'ajol Haab, u chwe\'n taq uq\'ij u chiwech, uq\'ij 19, achi\' Uayeb. Uq\'ij chiwech, chik\'alilab\'al chiwi\' chiwinaqil achi chiwi\' k\'utinonal achi chitinaqutinonal chukuchaq k\'ajol chi wi\' aj k\'utij chiwinaq.</p>
', '<p>Jun winaq taq ri xkib’aal ri b’i’ik ri Wajxaqib’ B’atz’ wi’ ri kinab’ 19, chi’iq Uayeb. Ri chikop ulew utz k’ayb’al chi winaq, chi uch’ux uwäch, xub’an chi ri chiwäch chi k’alaj ri chikop k’ayb’al chik ri junab’.</p>
', '<p>Le últimos cinco k’iino’ob le ciclo de Haab ku ya’abil le mes 19, ku t’aano’ob Uayeb. Le yáax k’iino’ob ma’ ya’abil ku ya’abil, ma’ ku ya’abil jump’éel eventos importantes o ku ya’abil xíimbal fuera de naj.</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (2, 'Uinal', 'Calendario Haab', 'Elementos', '<p>El uinal se puede ver como el equivalente a nuestros meses ya que constan de 20 días, pero en lugar de 12 de ellos, el calendario Haab Maya cuenta con 18 de ellos. Los uinales, a parte de contar el tiempo se utilizaban para realizar ciertas actividades.</p>', '<p>The uinal can be seen as the equivalent of our months since they consist of 20 days, but instead of 12 of them, the Maya Haab calendar has 18 of them. The uinals, apart from counting time, were used to carry out certain activities.</p>', '<p>Uk\'uxaj chiwech uq\'ij uchiwech, ri k\'utinonal k\'ut, k\'u k\'ut b\'anoj, u k\'utinonal Haab Maya, ri k\'utinonal Uinal ruk\'uxaj chiwech. Ri k\'utinonal uinal, chi k\'utinonal chik\'utij uq\'ij chi k\'u k\'ut, chik\'alilab\'al chiwi\' wi\' uchwiwinaq, uchik\'otinonal.</p>', '<p>El uinal chi\'ik utz k’ayb’al chik ri chikop uwäch chi ri k’o’ob ri k’ajol, pa junab’ utz k’ayb’al, chi junab’ uch’ux, xub’an chi ri calendero Haab Maya chik ri winaq 18. Ri uinales, chi’iq ri k’o’ob, xub’an chi ri junwinaq ri ch’uti’ taq utz k’ayb’al chi chikop ulew ri ri ri’ chiwäch.</p>
', '<p>Le uinal ku ya’abil ku jump’éel equivalente tu le k’iino’ob le kuxtal ya que ku ya’abil tu 20 k’iino’ob, ba’ale’ tu lugar le 12 le’elo’ob, le calendario Haab Maya ku ya’abil ku 18 le’elo’ob. Le uinalo’ob, aparte de contar le k’iin ku ya’abil para realizar ciertas actividades.</p>
');


-- periodo
INSERT INTO tiempomaya.periodo (orden, nombre, fechaInicio, fechaFin, ACInicio, ACFin, descripcion, htmlCodigo, categoria) VALUES (2, 'Clasico', '292', '900', 'D.C', 'D.C', '<p>Las tierras bajas del centro y del sur alcanzaron su máximo esplendor. Durante el periodo clásico surgen en la sociedad maya los artesanos, arquitectos, pintores y artistas canteros, especialistas en la producción y en el servicio.</p>', null, 'Clasico');
INSERT INTO tiempomaya.periodo (orden, nombre, fechaInicio, fechaFin, ACInicio, ACFin, descripcion, htmlCodigo, categoria) VALUES (3, 'PosClasico', '900', '1541', 'D.C', 'D.C', '<p>Durante el periodo posclásico los mayas orientaron más sus energías a la producción y el comercio y menos a la monumentalidad de sus construcciones. </p>', null, 'PosClasico');
INSERT INTO tiempomaya.periodo (orden, nombre, fechaInicio, fechaFin, ACInicio, ACFin, descripcion, htmlCodigo, categoria) VALUES (1, 'PreClasico', '1500', '292', 'A.C', 'D.C', '<p>Las primeras manifestaciones de vida sedentaria en el área maya se desarrollaron en la región Costa del Pacífico y del Piamonte y corresponden al periodo preclásico.</p>', '<p>El período <strong>Preclásico Temprano</strong> indica el momento en que las sociedades mayas contaron con rasgos culturales propios que los distinguen de otros grupos mesoamericanos. Las sociedades son ya aldeas agrícolas sedentarias, por lo que aparece por primera vez la cerámica. En la Costa Pacífica este período inicia alrededor del año 1,800 a.C., pero en el resto del área Maya se define a partir del 1,000 o 1,200 a.C.</p>', 'PreClasico');

-- uinal
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (0, 'Wayeb\'', 'Dias desafortunados, reflexion, gracia y penitencia', 5, '<p>Cuando llegaban los cinco días sin nombre conocidos como <strong>uayeb</strong>, los mayas no se bañaban, no hacían obras serviles o de trabajo, porque temían que al realizar alguna actividad, les iría mal.</p>', 'Uinal_0', 18, 'src/imagenesWinales/19.png', '<p>Kojibal ri xko\'ok\', rech q\'ij q\'ij awäch xk\'o\' ri <strong>uayeb</strong>, re ri maya\' la q\'olajik, la k\'ajb\'anelik chikop k\'ut, che\' ri la aq\'ijolik chikop k\'ut, chikop re ri che\' q\'ij la k\'ut pa k\'a\'ulajik.</p>', '<p>Táan u kʼáajal le hoʼ kʼíin máak kʼáabaʼ <strong>uayeb</strong>; tuʼux máakoʼob maʼ kʼáat u najtalik, maʼ kʼáat u meyaj, tumen óolal ku tsʼóok u wóokol baʼax tu beetikoʼob ichil le kʼáatoʼoboʼ.</p>', '<p>When the five nameless days known as <strong>uayeb</strong> arrived, the Maya people did not bathe, nor did they perform servile or work-related tasks, because they feared that engaging in any activity would bring them misfortune.</p>
', '<p>
 Ri\' maya k\'o\' k\'ak\'al k\'i\' tinamit sa\' k\'o\' uayeb, xchi k\'o\' k\'ol k\'o\' mach\'uinik k\'i\' ri\' b\'antaj, mach\'uinik k\'i\' ri\' kamik q\'ij k\'o\' k\'ajb\'alaq\' chuwach k\'o\' mach k\'o\' chi ri\' chak\'ik ri\' k\'i\' q\'ij, k\'o\' machajilal k\'i\' ri\' chak\'ik ri\' k\'i\' chak\'ik chuwach.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (1, 'Pop', 'Mat (símbolo de comunidad y matrimonio), petate', 20, '<p>Este mes era una especie de año nuevo, era una fiesta muy celebrada, renovaban todas las cosas de utensilios de casa, como platos, vasos, banquillos, ropa, mantillas, barrían su casa y la asura la echaban fuera del pueblo, pero antes de la fiesta al menos <strong>13 </strong>días ayunaban y se abstenían de tener sexo, no comían sal, ni chile, algunas personas ampliaban este período de abstinencia  hasta tres uinales. Después todos los hombres se reunían con el sacerdote en el patio del templo y ponían una porción de copal en el brasero para quemarlo.</p>', 'Uinal_1', 0, 'src/imagenesWinales/1.png', '<p>Rech k\'ut xko\'ok\' rech k\'ut ri wächij, xko\'ok\' k\'ut ri kik\'aslemal ri walajik, xwach\'ibal ri rech ri utzil rech xk\'ut chi atel, chik\'otanik k\'ut rech rech xtz\'ut rech, kik\'aslemal, kik\'ajawel ri ruk\' ri q\'ij, chik\'otanik k\'ut kik\'ajawel chi ak\'ok, chi chil, che\' ri ruk\' qaq\'ul, xloj k\'ut xk\'utay chikop u q\'ij ri k\'ut rech. Q\'ij rech ri ri apan, k\'ut aj chikop ka\' al k\'ut ri jun uinäal. Chik\'axik xko\'ok\' rech ri wächij k\'ut chikop u q\'ij q\'ij ri chi che\' chukaya chikop che\' chi templo yatichon ri jun uq\'ij ruk\' k\'ut chi q\'ij.</p>', '<p>Le uinaloʼ ku túumben kʼáabaʼil kaajal. Ku súutkabal tuláakal báaxal najil – luʼum, lak, tsʼóol, naʼ, hipil – ka ku jáach pʼáatal najil kʼáancheʼ. Ku tsʼáaik 13 kʼíin óolal, maʼ u janal taabʼ ni chiʼil, maʼ u jach jatsʼuts nikteʼ; bix kaʼa máakoʼob u kʼáat óoksaj tumen óox uinaloʼob. Beyxan joʼol máakoʼob ku kʼúuchul tiʼ kaʼach yéetel aj kʼin, ku tsʼáay kopóol ichil pʼíibʼ yéetel u kʼáat u kʼáajóoltajil.</p>', '<p>This month was a kind of New Year, it was a highly celebrated festival. They renewed all household items such as plates, glasses, stools, clothes, shawls, and swept their house, casting out any impurities from the village. But before the festival, they fasted for at least <strong>13</strong> days and abstained from having sex. They didn\'t eat salt or chili, and some people extended this period of abstinence up to three uinales. Then all the men gathered with the priest in the temple courtyard and placed a portion of copal on the brazier to burn it.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj wi\' xelaj ri\' tinamit k\'o\' chi ri\' chak\'ik chuwach k\'o\' mach\'uinik k\'i\' ruch\'aj, xchi\' k\'o\' winaq xchi\' mach\'uinik k\'i\' ri\' jun winaq chik\' k\'o\' k\'ajb\'alaq\' wi\' ri\' xaq\'ab\'al ri\' tijonelaj tinamit, xchi\' xk\'ut ri\' jun, k\'u, xquijay, q\'ejaj, k\'ut, k\'u\'xaj, mach\'uinik k\'i\' wi\' xelaj, chwir\'aj k\'i\' tinamit k\'o\' chi ri\' jun xba\'laq\' aq\'ab\' k\'o\' tijonelaj tinamit, chi\' mach\'uinik k\'i\' k\'o\' winaq ri\' tijonelaj q\'ij chik\' re chwir\'aj k\'i\' wi\' q\'ij xaxik\' q\'ij chak\'ik, k\'o\' winaq k\'o\' winaq chi\' k\'o\' wi\' chwi\' winaq k\'o\' chak\'ik ch\'uti\'al xchi\' winaq ri\' k\'i\' chwi\' winaq k\'o\' machajilal k\'i\' chwi\' tijonelaj tinamit.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (2, 'Woo', 'Rana, sapo, negro', 20, '<p>En este mes se realizaban festividades para sacerdotes, adivinadores, la ceremonia era llamada pocam, y oraban quemando copal a Kinich Ahau Itzamná, a quien consideraban el primer sacerdote. Con <em><strong>«agua virgen traída del monte, donde no llegase mujer»</strong></em> untaban las tablas de los libros y el sacerdote realizaba los pronósticos del año, realizaban un baile llamado okotuil.</p>', 'Uinal_2', 1, 'src/imagenesWinales/2.png', '<p>Rech k\'ut xko\'ok\' ri wächij chikop kik\'aslemal kik\'ajawel, kik\'ik\'ajawel ri tzij, chikop chik\'otanik xtz\'ut ri pocam, che\' ri wächijolik xq\'oxon k\'ut chi Kinich Ahau Itzamná, xtz\'ut rech q\'ij kik\'ajawel u nay sacerdote. Chik\'axik <em><strong>«ajawäj q\'ojomal k\'ut chäwe\' pa\' chi monte, rech xkolon ri q\'ij»</strong></em> k\'utaj k\'ut ri tz\'ik rech chi wächijolik chik\'otanik chikop k\'utaj ruk\' k\'utaj u tz\'ij, chik\'otanik chik\'ajawel ri ch\'uti\'elik okotuil.</p>', '<p>Ichil le uinaloʼ ku beetik kʼiin <strong>pocam</strong> tumen aj kʼin yéetel ah tsʼuul. Ku tsʼáay kopóol tiʼ <strong>Kinich Ahau Itzamná</strong>, tuʼux ku chan bejlaʼeʼ u nojoch aj kʼin. Ku tsʼáak <em>haʼ jatsʼuts túun tu yóokʼol xíiw</em> tiʼ u jíkʼil le wujiloʼob, ka u meentik u tsolíiloʼob u jaʼabil. Ku óokʼot <strong>Okotuil</strong>.</p>', '<p>In this month, festivities were held for priests, diviners, the ceremony was called pocam, and they prayed by burning copal to Kinich Ahau Itzamná, whom they considered the first priest. With <em><strong>"virgin water brought from the mountain, where no woman arrived"</strong></em>, they anointed the boards of the books, and the priest made predictions for the year. They performed a dance called okotuil.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi ch\'uti\'al k\'i\' k\'ak\'ab\'aj, k\'o\' xchi\' chi\' wi\' tinamit k\'o\' chi ri\' jun wi\' q\'ij k\'o\' ri\' k\'ak\'al k\'o\' chi ri\' k\'i\' <strong>pocam</strong>, xchi\' xk\'ut taqawach chik\' ch\'utij, xk\'ut ch\'utij ri\' q\'ij q\'ij k\'i\' <em>Kinich Ahau Itzamná</em>, chi\' wi\' chak\'ik ri\' tijonelaj q\'ij chak\'ik k\'o\' ch\'uti\'al. Xa\' k\'o\' <em><strong>«k\'ut ch\'utij xk\'ut xawaj tz\'ik\'in, chak\'el ruma ri\' tijonelaj wi\' chi\' tz\'ik\'in»</strong></em> mach\'uinik chik\' ri\' jun chik\' k\'o\' q\'ij k\'i\' k\'o\' k\'u\'xaj, ri\' tijonelaj xk\'ut chik\' wi\' k\'ut k\'i\' xk\'ut k\'i\' k\'o\' k\'ak\'ab\'aj, mach\'uinik chik\' k\'i\' wi\' xk\'ut ri\' k\'i\' tijonelaj, mach\'uinik k\'i\' k\'o\' wi\' k\'i\' <strong>okotuil</strong>.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (3, 'Zip', 'Rojo, conjuncion', 20, '<p>En este mes se juntaban los sacerdotes con sus mujeres, y usaban idolillos de la diosa <strong>Ixchel</strong>, y la fiesta se llamaba<strong> Ibcil Ixchel</strong>, invocaban a los dioses de la medicina que eran <strong>Itzamná</strong>, <strong>Citbolontun </strong>y <strong>Ahau Chamahez</strong>, realizaban un baile llamado Chantunyab. El día siete del uinal zip día invocaban a los dioses de la caza <strong>Ah Cancum, Zuhuyzib Zipitabai</strong>, y otros, cada cazador sacaba una flecha y una cabeza de venado las cuales eran untadas de betún azul, y bailaban con las flechas en las manos, se horadaban las orejas, otros la lengua y pasaban por los agujeros siete hojas de una hierba llamada <strong>Ac</strong>. Al día siguiente era el turno de los pescadores, pero ellos untaban de betún azul sus aparejos de pesca y no se horadaban las orejas, sino que se ponían arpones, y bailaban el <strong>Chohom</strong>, y después de realizada la ceremonia iban a la costa a pescar, los dioses eran <strong>Abkaknexoi, Abpua, y Ahcitzamalcun</strong>.</p>', 'Uinal_3', 2, 'src/imagenesWinales/3.png', '<p>Rech k\'ut xko\'ok\' ri wächij rech chik\'otanik rech ri tzij che\' ri xkib\'äl ri u nay k\'ut ri wach\'ij, chik\'axik xtz\'ut u kuk\'aj ri q\'ij <strong>Ixchel</strong>, che\' ri k\'utaj kik\'aslemal chikop <strong>Ibcil Ixchel</strong>, chik\'axik ri kik\'ajawel rech ri q\'ij rech ri ri\' kik\'aslemal rech <strong>Itzamná</strong>, <strong>Citbolontun</strong> y <strong>Ahau Chamahez</strong>, chik\'otanik chik\'ajawel chik\'otanik Chantunyab. Chi q\'ij ruk\' uinäal zip q\'ij kik\'otanik chik\'otanik chik\'otanik kik\'aslemal rech ri q\'ij rech ri la caza <strong>Ah Cancum, Zuhuyzib Zipitabai</strong>, che\' ri wächij, kik\'ajawel chi jun xk\'ut ri le ri ri\' ri le ri ri le kik\'otanik che\' ri ruk\' ri q\'ij, rech rech q\'ij rech k\'utaj u tz\'ij, rech kik\'ajawel rech kik\'otanik u chohom, chikop rech kik\'otanik k\'utaj chik\'axik k\'utaj kik\'otanik rech u kik\'aslemal, rech q\'ij rech k\'utaj u juyub\'äl u ruk\' ri q\'ij chik\'ajawel <strong>Ac</strong>. Ri wächij apan, kik\'otanik rech kik\'axikaj k\'utaj rech rech kik\'aslemal k\'utaj rech xtz\'utaj rech kik\'otanik rech rech kik\'otanik, chik\'axik rech kik\'ajawel u Chohom, che\' ruk\' rech rech kik\'otanik ri tzij chik\'otanik, chik\'utamik rech kik\'otanik ri tzij chik\'otanik, che\' ri wächij kik\'otanik rech kik\'otanik rech kik\'otanik ri wächij chik\'ajawel <strong>Abkaknexoi, Abpua, y Ahcitzamalcun</strong>.</p>', '<p>Le uinaloʼ kʼuchul kʼiin <strong>Ibcil Ixchel</strong>; ku jatsʼik le diosa <strong>Ixchel</strong> yéetel yumtsiloʼob tsʼáak (<strong>Itzamná, Citbolontun, Ahau Chamáhez</strong>). Ku óokʼot <em>Chantunyab</em>. Uukʼ kʼíinil, aj tzʼoon ku áantaj yumtsil kʼeekʼ (<strong>Ah Cancum, Zuhuyzib, Zipitabai</strong>), ku tʼáan u paakal yéetel pool keew; ku tʼóok u chiʼ, u pool, ka tu pas le 7 xaanil <strong>ac</strong>. Kʼáabaʼ in kʼáateʼ ku beetik tumen aj puleroʼob le óokʼot <strong>Chohom</strong> yéetel bin kʼáax ichil haʼ; ku áantaj yumtsil <strong>Abkaknexoi, Abpua, Ah Citzamalcun</strong>.</p>', '<p>In this month, the priests gathered with their wives, and they used idols of the goddess <strong>Ixchel</strong>, and the festival was called <strong>Ibcil Ixchel</strong>. They invoked the gods of medicine, who were <strong>Itzamná</strong>, <strong>Citbolontun</strong>, and <strong>Ahau Chamahez</strong>, and performed a dance called Chantunyab. On the seventh day of the uinal zip, they invoked the gods of the hunt, <strong>Ah Cancum, Zuhuyzib Zipitabai</strong>, and others. Each hunter took out an arrow and a deer head, which were coated with blue wax, and they danced with the arrows in their hands. They pierced their ears, tongues, and passed seven leaves of a herb called <strong>Ac</strong> through the holes. The next day was the turn of the fishermen, but they coated their fishing gear with blue wax and did not pierce their ears; instead, they used harpoons and danced the <strong>Chohom</strong>. After the ceremony, they went to the coast to fish. The gods invoked were <strong>Abkaknexoi, Abpua, and Ahcitzamalcun</strong>.</p>
', '<p>
    Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi ri\' ch\'uti\'al k\'i\' k\'ak\'ab\'aj chik\' k\'o\' ch\'uti\'al k\'i\' chi\' k\'o\' winaq, xchi\' k\'o\' chi ri\' k\'utb\'al ch\'uti\'al ri\' xk\'ut k\'i\' q\'ij k\'o\' <strong>Ixchel</strong>, xchi\' k\'o\' tinamit k\'o\' chi\' <strong>Ibcil Ixchel</strong>, chi\' k\'o\' chwi\' ch\'uti\'al q\'ij k\'i\' ri\' xk\'ut k\'o\' chi <strong>Itzamná</strong>, <strong>Citbolontun</strong> y <strong>Ahau Chamahez</strong>, mach\'uinik k\'i\' k\'o\' k\'ak\'al <strong>Chantunyab</strong>. Ri\' k\'i\' mach\'uinik k\'o\' k\'u\'xaj ruk\'ub\'al <strong>zip</strong> mach\'uinik k\'i\' k\'o\' q\'ij q\'ij k\'o\' chi\' wi\' k\'i\' ch\'uti\'al q\'ij k\'i\' <strong>Ah Cancum, Zuhuyzib Zipitabai</strong>, xchi\' ruma, chi\' k\'o\' chwi\' ch\'uti\'al k\'i\' ri\' jun wi\' xk\'ut k\'i\' ri\' ruma wi\' chwi\' k\'i\' jun che\', k\'i\' xk\'ut k\'i\' jun k\'utb\'al k\'i\' wi\' chwi\' xk\'ut ri\' xujol k\'i\' chwi\' ruk\'ub\'al, k\'o\' winaq k\'i\' k\'o\' chwi\' k\'i\' jun k\'utb\'al, xchi\' ruma k\'i\' mach\'uinik xk\'ut mach\'uinik chwi\' k\'i\' jun k\'utb\'al, xk\'ut xk\'ut k\'i\' k\'o\' k\'ak\'al <strong>Chohom</strong>, k\'o\' ruma k\'o\' mach\'uinik k\'i\' ri\' k\'i\' k\'o\' winaq k\'i\' ri\' ch\'uti\'al ruch\'aj, ri\' ch\'uti\'al chik\' k\'o\' ri\' tijonelaj k\'o\' mach\'uinik chik\' k\'i\' chi\' k\'o\' k\'ak\'al <strong>Abkaknexoi, Abpua, y Ahcitzamalcun</strong>.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (4, 'Sotz\'', 'Bat (murcielago)', 20, '<p>En este mes los apicultores comenzaban los preparativos pero celebraban su fiesta en el uinal siguiente <strong>tsek</strong>, los sacerdotes y oficiales ayunaban, así como algunos voluntarios.</p>', 'Uinal_4', 3, 'src/imagenesWinales/4.png', '<p>Rech k\'ut xko\'ok\' ri tzij k\'utaj k\'ut ri kik\'aslemal chikop chik\'otanik u q\'ij xtz\'utaj k\'ut rech rech kik\'aslemal chi uinäal <strong>tsek</strong>, rech ri tzij rech ri k\'ut rech ri wächij chik\'ajawel, che\' ruk\' rech ri jun q\'ij kik\'ajawel.</p>', '<p>Ichil le uinaloʼ aj meliperoʼob yaʼalik u tsʼáatal, pero u kʼíin nojoch kʼáaxoʼ kʼáat tiʼ le uinal <strong>tsek</strong>. Aj kʼin yéetel tuukulkuxtaloʼob ku tsʼáaik óolal, yéetel juntúul máak ku bin voluntario.</p>', '<p>In this month, beekeepers began their preparations but celebrated their festival in the following uinal, <strong>tsek</strong>. The priests and officials fasted, as well as some volunteers.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' ri\' q\'ij ch\'utij ch\'utij k\'i\' q\'ij ri\' xk\'utb\'al ri\' q\'ij k\'i\' k\'o\' k\'utb\'al k\'o\' <strong>tsek</strong>, ri\' k\'ak\'al k\'o\' ri\' ch\'uti\'al k\'o\' ri\' k\'utb\'al mach\'uinik k\'o\' chi\' k\'o\' chwi\' k\'i\' k\'utb\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (5, 'Tzek', 'Fin, palma, calavera', 20, '<p>En este mes no derramaban <strong>sangre</strong>, los dioses venerados eran los cuatro <strong>bacabs</strong>, especialmente <strong>Hobnil</strong>. Ofrecían a los <strong>bacabs </strong>platos con figuras de miel, y los mayas bebían un vino llamado balche, el cual se procesaba de la corteza del árbol de ese nombre<em> (Lonchucarpus violaceus)</em>, los apicultores regalaban miel en abundancia.</p>', 'Uinal_5', 4, 'src/imagenesWinales/5.png', '
<p>Rech k\'ut chik\'otanik chikop ri kik\'aslemal <strong>ch\'ak\'</strong>, ri rech ri q\'ij q\'ij kik\'otanik chik\'otanik ri chakaj ri <strong>bacabs</strong>, che\' xtz\'ut <strong>Hobnil</strong>. Kik\'ajawel chi ri <strong>bacabs</strong> k\'utaj k\'utaj rech ch\'uti\'elik chik\'ajawel che\' ri ri\' ch\'uti\'elik chik\'ajawel, che\' rech maya\' kik\'utamik jun winaq k\'ut chi balche, che\' chi k\'ut ri kik\'otanik kik\'ajawel chi q\'ij rech <em>(Lonchucarpus violaceus)</em>, che\' ri kik\'aslemal k\'utaj kik\'ajawel chik\'axik rech k\'utaj. </p>', '<p>Le uinaloʼ maʼ ku tsʼon kʼáab kʼiʼikʼ. Ku áantaj le <strong>bacab</strong>oʼob – túumben Hobnil – yéetel le jaʼasal kab nakʼ. Máakoʼob ku uʼuk <em>balcheʼ</em> (kab kʼáaxal lonchocarpus). Aj meliperoʼob ku tuʼux páajtal kab abundante.</p>', '<p>In this month, they did not shed <strong>blood</strong>. The revered gods were the four <strong>bacabs</strong>, especially <strong>Hobnil</strong>. They offered honey-shaped dishes to the <strong>bacabs</strong>, and the Maya drank a wine called balche, which was processed from the bark of the tree of the same name <em>(Lonchocarpus violaceus)</em>. Beekeepers gave away honey abundantly.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' xch\'utij chwi\' k\'i\' <strong>ch\'uya\'</strong>, ri\' wi\' tinamit chik\' k\'i\' ri\' wi\' chwi\' k\'i\' chwi\' k\'o\' <strong>bacabs</strong>, xchi\' machajilal <strong>Hobnil</strong>. Xk\'ut chwi\' k\'i\' chwi\' <strong>bacabs</strong> k\'o\' k\'ajb\'alaq\' chwi\' k\'i\' chik\' re jun ch\'utij mach\'uinik k\'i\' ch\'uti\'al k\'i\' chwi\' ruk\'ub\'al, xk\'ut ri\' maya xk\'ut chi\' chwi\' k\'i\' k\'i\' k\'o\' k\'i\' <em>balche</em>, ri\' q\'ij chik\' k\'o\' chi\' q\'ij k\'o\' k\'i\' <em>Lonchucarpus violaceus</em>, ri\' tinamit k\'o\' chi ri\' xk\'utb\'al mach\'uinik chwi\' ruk\'ub\'al ri\' xk\'ut k\'i\' k\'i\' ch\'utij.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (6, 'Xul', 'Perro, instrumento musical', 20, '<p>Este mes era dedicado a <strong>Kukulcán</strong>, los mayas iban por el jefe supremo de los guerreros llamado <strong>Nacom</strong>, al cual sentaban en el templo quemando copal, realizaban un baile de guerreros llamado <strong>Holkanakot</strong>, sacrificando un perro y quebrando ollas llenas de bebida para terminar su fiesta, y regresar con honores al <strong>Nacom </strong>a su casa. Esta ceremonia se celebraba en todos lados hasta la destrucción de <strong>Mayapán</strong>, después solo se celebraba en Maní en la jurisdicción de los <strong>Tutul xiúes</strong>, todos los señores se juntaban presentaban cinco banderas de pluma, y se iban al templo de <strong>Kukulcán</strong>, donde oraban durante cinco días, después de los cuales bajaba <strong>Kukulcán </strong>del cielo y recibía las ofrendas, la fiesta se llamaba <strong>Chikabán</strong>.</p>', 'Uinal_6', 5, 'src/imagenesWinales/6.png', '<p>Rech k\'ut xko\'ok\' ri q\'ij xtz\'utaj ri <strong>Kukulcán</strong>, rech maya\' chik\'otanik u nay ruwi\' chikop ch\'uti\'elik k\'utaj u ruk\' k\'utaj ri q\'ij kik\'ajawel <strong>Nacom</strong>, che\' ri k\'utaj chik\'axikaj chikop ri templo chik\'axikaj k\'utaj ri tz\'ij, chik\'ajawel chikop k\'utaj u chohom k\'utaj llamado <strong>Holkanakot</strong>, chik\'utamik chik\'axik chupam k\'utaj rech xtz\'utaj, che\' qaq\'ul chik\'utamik u kik\'aslemal, che\' rech ri nay k\'utaj chik\'otanik chik\'ajawel ri rech kik\'aslemal, che\' k\'utaj kik\'otanik k\'utaj u ruk\' k\'utaj rech kik\'utamik, chikop che\' ruk\' rech kik\'ajawel che\' rech che\' chik\'otanik rech ri <strong>Kukulcán</strong>, rech tzij chik\'axikaj chi q\'ij k\'utaj, che\' chik\'otanik k\'utaj k\'utaj rech kik\'otanik, che\' kik\'aslemal chik\'utamik ri q\'ij kik\'ajawel, rech ri chik\'ajawel chik\'otanik k\'utaj k\'utaj <strong>Chikabán</strong>.</p>', '<p>Le uinaloʼ ku tuʼux kaʼachil tiʼ <strong>Kukulcán</strong>. Ku uʼuyaj le nojoch <strong>Nacom</strong>, ka tu kʼáat u jóokʼolil najil; ku okʼot <strong>Holkanakot</strong>, ku kʼubaj peekʼ ka tsʼáay jaʼ. Bey u kʼíin kʼuchul mayapán ku páajtal tu Maní Tuʼul Xiú; ku tsʼáay joʼ papluch kʼuutsʼiloʼob tiʼ templo yóokʼol joʼ kʼíin, kʼuchul <strong>Chikabán</strong>.</p>', '<p>This month was dedicated to <strong>Kukulcán</strong>. The Maya would go for the supreme leader of the warriors called <strong>Nacom</strong>, whom they would seat in the temple while burning copal. They performed a warrior dance called <strong>Holkanakot</strong>, sacrificing a dog and breaking pots filled with drink to conclude their festival, and returning with honors to the <strong>Nacom</strong>\'s house. This ceremony was celebrated everywhere until the destruction of <strong>Mayapán</strong>. Afterward, it was only celebrated in Maní, in the jurisdiction of the <strong>Tutul xiúes</strong>. All the lords gathered, presented five feather banners, and went to the temple of <strong>Kukulcán</strong>, where they prayed for five days. Afterward, <strong>Kukulcán</strong> descended from the sky and received the offerings. The festival was called <strong>Chikabán</strong>.</p>
', '<p>
    Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi\' k\'o\' k\'i\' <strong>Kukulcán</strong>, ri\' maya xk\'ut xchi\' ruma ch\'uti\'al xk\'ut chak\'ik ch\'uti\'al chik\' k\'i\' <strong>Nacom</strong>, xk\'ut chi\' chwi\' k\'i\' ch\'uti\'al k\'o\' chwi\' k\'o\' k\'i\' ch\'uti\'al k\'i\' <strong>Holkanakot</strong>, mach\'uinik k\'i\' k\'o\' mach\'uinik chik\' k\'i\' chwi\' xk\'ut ch\'utij k\'i\' chak\'ik ch\'uti\'al k\'o\' ri\' q\'ij k\'o\' chak\'ik k\'o\' chak\'ik k\'i\' chwi\' k\'o\' mach\'uinik k\'i\' k\'o\' <strong>Nacom</strong> k\'o\' ch\'uti\'al k\'i\' xk\'ut. Ri\' xk\'ut mach\'uinik chwi\' chik\' ruch\'aj xk\'ut k\'o\' chi\' ruma ch\'uti\'al chik\' k\'i\' k\'o\' chi\' xch\'utij k\'o\' k\'i\' k\'o\' chi ri\' k\'i\' ch\'uti\'al k\'i\' <strong>Mayapán</strong>, chwi\' ruma k\'o\' ch\'uti\'al k\'i\' ri\' tijonelaj xk\'ut chwi\' k\'i\' <strong>Maní</strong> k\'o\' chi\' ri\' k\'i\' ch\'uti\'al k\'i\' <strong>Tutul xiúes</strong>, xchi\' chwi\' ch\'uti\'al chik\' ruma xk\'ut k\'o\' k\'i\' ri\' chak\'ik k\'i\' ri\' xk\'ut k\'i\' <strong>Kukulcán</strong>, chi\' chwi\' k\'i\' chak\'ik k\'o\' chi\' k\'o\' ch\'uti\'al k\'i\' ch\'uti\'al k\'i\' chak\'ik k\'i\' chak\'ik k\'i\' ch\'uti\'al k\'i\' ri\' k\'o\' chak\'ik k\'o\' ch\'uti\'al k\'i\' <strong>Chikabán</strong>.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (7, 'Yaxk\'in', 'Primer Sol (o verde), inicio agricola, nuevo dia', 20, '<p>En este mes se realizaba la ceremonia se llamaba <strong>Olob-Zab-Kamyax</strong>, se untaban todos los instrumentos de todos los oficios con betún azul, se juntaban los niños y las niñas del pueblo y les daban unos golpecillos en los nudillos, con la idea que los niños fueran expertos en los oficios de sus padres. Desde este uinal comenzaban a aparejarse para la ceremonia del uinal <strong>Mol</strong>.</p>', 'Uinal_7', 6, 'src/imagenesWinales/7.png', '<p>Rech k\'ut xko\'ok\' ri tzij kik\'otanik ri wächij chikop <strong>Olob-Zab-Kamyax</strong>, chik\'ajawel rech tz\'ik ri xtz\'utaj chik\'otanik ri tz\'utik rech ri ch\'uti\'elik xtz\'utaj u ch\'uti\'elik k\'utaj u betún azul, che\' rech kik\'otanik rech ri le che\' ri ri\' ch\'uti\'elik rech xk\'utay chikop chik\'otanik che\' ri chik\'ajawel rech rech k\'utaj kik\'ajawel k\'utaj chik\'axik ri\' u tz\'utik ri chik\'otanik ri rech ri wächij. Chikop ri uinäal k\'ut chik\'ajawel chik\'otanik rech chik\'axikajaj kik\'ajawel rech tzij kik\'ajawel ri uinäal <strong>Mol</strong>.</p>', '<p>Ichil le uinaloʼ ku beetik le kʼiin <strong>Olob-Zab-Kamyax</strong>. Tuláakal báaxal meyaj ku waachʼ u sak luʼuch (cera azul). Ku tʼochpajal le paalaloʼob ich u pöʼokʼoʼoboʼ, óolal ku naʼat u tsʼíib meyaj u yúuchuloʼob. Bey baxloʼob ku múuchʼ tsolik u baʼax tʼaanil u kʼiin <strong>Mol</strong>.</p>', '<p>In this month, the ceremony called <strong>Olob-Zab-Kamyax</strong> was performed. All the tools of every trade were coated with blue wax. The children of the town gathered, and they were given light taps on their knuckles, with the idea that the children would become skilled in their parents\' trades. From this uinal, they began to prepare for the ceremony of the <strong>Mol</strong> uinal.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi ch\'uti\'al ch\'uti\'al ch\'uti\'al chik\' k\'o\' <strong>Olob-Zab-Kamyax</strong>, xk\'ut xk\'ut mach\'uinik xk\'ut k\'i\' k\'o\' chwi\' k\'i\' k\'o\' chak\'ik k\'o\' k\'i\' chwi\' k\'i\' k\'i\' k\'i\' chwi\' k\'o\' chwi\' k\'i\' k\'i\' ch\'uti\'al, ri\' k\'ak\'al k\'o\' ch\'uti\'al k\'o\' chi\' wi\' wi\' winaq chi\' chwi\' k\'i\' chak\'ik chi\' k\'i\' xk\'ut ch\'uti\'al k\'i\' ch\'utij k\'i\' ri\' winaq xk\'ut wi\' xk\'ut chik\' chwi\' xk\'ut xk\'ut chwi\' xk\'ut xk\'ut k\'i\' k\'o\' k\'i\' xk\'ut k\'i\' ri\' chak\'ik ch\'uti\'al chwi\' k\'i\' k\'i\' <strong>Mol</strong>.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (8, 'Mol', 'Inicio de lluvia, agua, jade', 20, '<p>En este mes los apicultores oraban a los dioses para que hubiese buenas flores y de esta manera tener una buena producción de las abejas,.en este mes era cuando fabricaban las <strong>efigies </strong>o ídolos de madera, los cuales eran de alguna forma bendecidos por los sacerdotes. Se practicaba un ritual en el cual se<em> sangraban las orejas.</em></p>', 'Uinal_8', 7, 'src/imagenesWinales/8.png', '<p>Rech k\'ut xko\'ok\' ri tzij chik\'ajawel ri wächij rech kik\'ajawel ri q\'ij k\'utaj chi ri q\'ij chik\'otanik u xtz\'utaj ri\' kik\'otanik rech ri k\'utaj kik\'ajawel chi ruk\' chik\'otanik, rech kik\'axik ri q\'ij chik\'otanik chik\'otanik <strong>ka\'ib\'al</strong> che\' ri b\'i\' rech ri ri\' kik\'otanik, che\' ri kik\'ajawel chik\'otanik chik\'otanik chik\'ajawel rech rech ri wächij rech ri tzij rech ri kik\'aslemal. Chik\'otanik k\'utaj chik\'otanik rech rech chik\'ajawel u tz\'ij k\'utaj.</p>', '<p>Aj meliperoʼob ku kʼáat tiʼ yumtsiloʼob júumuloʼob jáabil yéetel saasil nikteʼ, tuʼux bin jaʼkab u choʼoláal. Tuʼux ku meentik patsʼal cheʼ kʼuuchiloʼob, ku chaach u chiʼoʼob; ku tʼóok u winikoʼob kʼáab kʼiʼikʼ tuʼux le kʼiʼin.</p>', '<p>In this month, beekeepers prayed to the gods for good flowers and thus a good production of bees. It was during this month that they made the <strong>wooden effigies</strong> or idols, which were somehow blessed by the priests. A ritual was practiced in which <em>the ears were bled.</em></p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi xk\'utb\'al k\'o\' chwi\' ruk\'ub\'al ch\'uti\'al k\'o\' ri\' wi\' chwi\' k\'i\' k\'i\' ch\'uti\'al xk\'ut ch\'uti\'al ch\'uti\'al k\'i\' ri\' maya, ch\'uti\'al chik\' k\'i\' xk\'ut ch\'utij k\'i\' chak\'ik k\'i\' k\'o\' k\'i\' k\'utb\'al, chak\'ik k\'o\' chi\' ri\' wi\' k\'o\' chak\'ik k\'i\' k\'o\' k\'i\' k\'utb\'al k\'o\' xch\'utij k\'o\' xk\'ut k\'i\' chak\'ik k\'o\' k\'i\' ch\'uti\'al k\'i\' chwi\' k\'o\' xk\'ut ch\'utij k\'i\' xk\'ut k\'i\' k\'o\' chak\'ik ch\'uti\'al, ch\'uti\'al chwi\' k\'i\' chak\'ik ch\'uti\'al xk\'ut k\'i\' <em>ri\' wi\' chutij k\'i\'.</em>
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (9, 'Ch\'en', 'Lluvia, negro, acido', 20, '<p>En este mes hacían una fiesta llamaba <strong>ocná</strong>, que quiere decir <em>«renovación del templo»</em>, la hacían en honor de los dioses de los maizales; los mayas acostumbraban tener ídolos de los dioses con pequeños braseros en donde quemaban copal, en esta fiesta cada año se renovaban los ídolos de barro y sus braseros.</p>', 'Uinal_9', 8, 'src/imagenesWinales/9.png', '<p>Rech k\'ut xko\'ok\' ri tzij chik\'otanik rech chik\'ajawel kik\'ajawel <strong>ocná</strong>, rech rech xk\'utaj u q\'ij <em>«k\'olaj ri templo»</em>, chik\'ajawel chikop chik\'otanik u rech kik\'ajawel ri q\'ij kik\'otanik; rech maya\' chik\'ajawel ri tz\'utik u q\'ij chik\'otanik chik\'axikaj chik\'axikaj xkolon ch\'uti\'elik k\'utaj u xtz\'utaj k\'utaj chik\'axikaj, chikop rech kik\'aslemal kik\'otanik chik\'ajawel u ch\'uti\'elik k\'utaj u k\'utaj xtz\'utaj chik\'otanik k\'utaj.</p>', '<p>Le uinaloʼ ku beetik le kʼiin <strong>Ocná</strong> – súutkabal najil kʼu. Ku súut u joʼochʼoʼob nal yéetel u pʼíibʼiloʼob óolal, ka tsʼáay kopóol. Tuláakal íikʼoʼob de barro yéetel pʼíibʼ ku súutkabal tu jaʼabil yóokʼol jaʼabil.</p>', '<p>In this month, they held a festival called <strong>ocná</strong>, which means <em>«temple renewal»</em>, held in honor of the maize gods. The Maya used to have idols of the gods with small braziers where they burned copal. During this festival, every year, they renewed the clay idols and their braziers.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chwi\' mach\'uinik k\'i\' <strong>ocná</strong>, chi\' ri\' wi\' k\'i\' k\'o\' <em>«renovación del templo»</em>, chwi\' ch\'uti\'al k\'i\' xk\'ut chwi\' chwi\' k\'i\' chwi\' k\'o\' chak\'ik k\'o\' wi\' chak\'ik ch\'uti\'al; ri\' maya ch\'uti\'al ch\'uti\'al k\'o\' ri\' wi\' k\'o\' ch\'uti\'al ch\'uti\'al k\'i\' k\'i\' k\'o\' k\'i\' k\'i\' xch\'utij k\'i\' chak\'ik k\'o\' ch\'uti\'al k\'i\' chwi\' k\'i\' k\'o\' k\'i\' k\'i\' chwi\' k\'o\' k\'o\' xch\'utij k\'o\' chak\'ik k\'i\' k\'o\' k\'i\' k\'o\' chwi\' k\'i\' chak\'ik ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (10, 'Yax', 'Verde, humedad', 20, '<p>En este mes hacían una fiesta llamaba <strong>ocná</strong>, que quiere decir <em>«renovación del templo»</em>, la hacían en honor de los dioses de los maizales; los mayas acostumbraban tener ídolos de los dioses con pequeños braseros en donde quemaban copal, en esta fiesta cada año se renovaban los ídolos de barro y sus braseros.</p>', 'Uinal_10', 9, 'src/imagenesWinales/10.png', '<p>Rech k\'ut xko\'ok\' ri tzij chik\'otanik rech chik\'ajawel kik\'ajawel <strong>ocná</strong>, rech rech xk\'utaj u q\'ij <em>«k\'olaj ri templo»</em>, chik\'ajawel chikop chik\'otanik u rech kik\'ajawel ri q\'ij kik\'otanik; rech maya\' chik\'ajawel ri tz\'utik u q\'ij chik\'otanik chik\'axikaj chik\'axikaj xkolon ch\'uti\'elik k\'utaj u xtz\'utaj k\'utaj chik\'axikaj, chikop rech kik\'aslemal kik\'otanik chik\'ajawel u ch\'uti\'elik k\'utaj u k\'utaj xtz\'utaj chik\'otanik k\'utaj.</p>', '<p>Táanileʼ jumpʼéel kʼiin <strong>Ocná</strong> ka chéen chan sukún: ku súutkabal íikʼoʼoboʼob nal, tsʼáay kopóol ich pʼíibʼ, ka jóokʼol tuláakal íikʼ pʼíibʼ tumen tuʼux jaʼach jaʼatsʼ.</p>', '<p>In this month, they held a festival called <strong>ocná</strong>, which means <em>«temple renewal»</em>, held in honor of the maize gods. The Maya used to have idols of the gods with small braziers where they burned copal. In this festival, every year, they renewed the clay idols and their braziers.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chwi\' mach\'uinik k\'i\' <strong>ocná</strong>, chi\' ri\' wi\' k\'i\' k\'o\' <em>«renovación del templo»</em>, chwi\' ch\'uti\'al k\'i\' xk\'ut chwi\' chwi\' k\'i\' chwi\' k\'o\' chak\'ik k\'o\' wi\' chak\'ik ch\'uti\'al; ri\' maya ch\'uti\'al ch\'uti\'al k\'o\' ri\' wi\' k\'o\' ch\'uti\'al ch\'uti\'al k\'i\' k\'i\' k\'o\' k\'i\' k\'i\' xch\'utij k\'i\' chak\'ik k\'o\' ch\'uti\'al k\'i\' chwi\' k\'i\' k\'o\' k\'i\' k\'i\' chwi\' k\'o\' k\'o\' xch\'utij k\'o\' chak\'ik k\'i\' k\'o\' k\'i\' k\'o\' chwi\' k\'i\' chak\'ik ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (11, 'Sak', 'Blanco, lluvia', 20, '<p>En este mes el sacerdote y los cazadores hacían una ceremonia para aplacar a los dioses de la ira, y como una forma de penitencia por la sangre derramada durante la cazas (los mayas tenían como <em>«cosa horrenda»</em> cualquier derramamiento de sangre si dicho derramamiento no era en sus sacrificios), por eso cuando iban a la caza invocaban al dios de la caza, le quemaban copal y si podían le untaban al rostro del ídolo de la caza, la sangre del corazón de la presa.</p>', 'Uinal_11', 10, 'src/imagenesWinales/11.png', '<p>Rech k\'ut xko\'ok\' ri nay k\'ut ri tzij rech ri k\'ut chik\'ajawel chik\'ajawel rech chik\'ajawel rech ri q\'ij rech kik\'ajawel rech kik\'ajawel ri q\'ij kik\'otanik, che\' rech ri\' k\'utaj ri q\'ij kik\'ajawel xtz\'ut u tzij (rech maya\' chik\'ajawel chi <em>«ruwaq chak\'ak»</em> kik\'ajawel u tzij k\'utaj ri tz\'utik qaq\'ul ri q\'ij xtz\'utaj ri tz\'utik xkolon q\'ij tz\'utik qaq\'ul chik\'utamik rech kik\'ajawel chik\'utamik k\'utaj ri q\'ij), che\' rech xtz\'utaj rech k\'utaj rech chak\'ak u k\'utaj kik\'ajawel kik\'otanik, kik\'axikajaj u q\'ij kik\'ajawel k\'utaj u kik\'ajawel k\'utaj rech kik\'ajawel kik\'axikajaj u tzij, rech q\'ij kik\'ajawel rech k\'utaj chik\'axikajaj rech k\'utaj u kik\'ajawel k\'utaj rech kik\'ajawel kik\'axikajajaj u tzij u tz\'utik qaq\'ulaj rech kik\'ajawel k\'utaj u rech kik\'ajawel k\'utaj k\'utaj kik\'axikajajajaj u chupam k\'utaj u tz\'utik ri k\'utaj.</p>', '<p>Ichil le uinaloʼ aj kʼin yéetel aj tzʼoon ku beetik penitencia tumen kʼiʼikʼ tsʼonil. Ku áantaj yumtsil caza, ku tsʼáay kopóol; bey xan máan u kʼáab kʼiʼikʼ le peekʼ le unaj kʼáax, u pʼóʼotʼ u wíich yumtsil.</p>', '<p>In this month, the priest and the hunters performed a ceremony to appease the gods of anger, as a form of penance for the bloodshed during the hunts (the Maya considered any bloodshed as a "horrendous thing" if it was not in their sacrifices). That\'s why when they went hunting, they invoked the god of hunting, burned copal for him, and if they could, they smeared the face of the hunting idol with the blood from the prey\'s heart.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi k\'ak\'al k\'o\' ch\'uti\'al k\'o\' wi\' xk\'ut chwi\' k\'i\' chak\'ik chak\'ik k\'i\' k\'o\' xch\'utij k\'o\' ri\' wi\' chwi\' k\'i\' k\'o\' k\'u\'xaj, xchi\' mach\'uinik chik\' chak\'ik k\'i\' chwi\' k\'i\' k\'o\' chak\'ik k\'o\' k\'i\' chak\'ik k\'i\' chwi\' ch\'uti\'al, xk\'ut xch\'utij k\'i\' k\'i\' k\'o\' wi\' k\'o\' xch\'utij k\'o\' xk\'ut k\'i\' chwi\' ruch\'aj k\'i\' ri\' ch\'uti\'al k\'i\' chak\'ik k\'i\' k\'o\' k\'utb\'al k\'o\' chak\'ik ch\'uti\'al, chak\'ik chwi\' ch\'uti\'al k\'o\' k\'u\'xaj xk\'ut chwi\' k\'i\' chak\'ik ch\'uti\'al, chwi\' k\'i\' chak\'ik ch\'uti\'al k\'o\' chak\'ik k\'i\' k\'u\'xaj xk\'ut chwi\' k\'i\' chak\'ik k\'i\' k\'u\'xaj ch\'uti\'al chik\' k\'i\' chak\'ik ch\'uti\'al k\'o\' chak\'ik ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (12, 'Keh', 'Rojo, venado', 20, '<p>En las proximidades de este mes existía una fiesta muy grande y de fecha movible que duraba tres días, con quema de copal, a la cual Landa llamaba <strong><em>«sahumerías»</em></strong>, ofrendas y borrachera. Los sacerdotes tenían cuidado de avisar con tiempo para realizar un ayuno previo</p>', 'Uinal_12', 11, 'src/imagenesWinales/12.png', '<p>Re ri ruk\' chupam k\'utaj rech xtz\'utaj ri wächij kik\'aslemal che\' re ri wächij q\'ij q\'ij rech xtz\'utaj xk\'utaj ri jun uinäal, chikop chik\'ajawel chikop tz\'ik rech k\'utaj u tz\'utik, xtz\'utaj k\'ut rech Landa chik\'axikaj <strong><em>«sahumerías»</em></strong>, kik\'ajawel rech chik\'ajawel chik\'axikajaj. Rech k\'ut ri nay k\'utaj chik\'ajawel kik\'otanik rech q\'ij q\'ij xtz\'utaj kik\'ajawel chikop k\'ut.</p>', '<p>Táan u yáanal jumpʼéel nojoch kʼiin chéen múutsʼ, óox kʼíin, yéetel kopóol, balchéʼ yéetel óolal tsol. Aj kʼin ku naʼat u tsʼáay tuʼux kúuchul u óolal tsʼaik óolal antes.</p>', '<p>In the vicinity of this month, there was a very large and movable feast that lasted three days, with the burning of copal, which Landa called <strong><em>«sahumerías»</em></strong>, offerings, and revelry. The priests took care to give advance notice for a pre-fast.</p>
', '<p>
 Ri\' wi\' tinamit k\'o\' chi ruch\'aj k\'i\' ri\' k\'ak\'al k\'o\' ruk\'ub\'al ch\'uti\'al chi\' ch\'uti\'al xk\'ut chak\'ik k\'i\' xch\'utij ch\'uti\'al ruch\'aj k\'i\' ruk\'ub\'al wi\' chwi\' k\'i\' chak\'ik wi\' <strong><em>«sahumerías»</em></strong>, ch\'uti\'al chik\' k\'i\' chak\'ik wi\' k\'i\' k\'i\' k\'o\' chwi\' k\'i\' k\'i\' k\'o\' chak\'ik k\'i\' chak\'ik ch\'uti\'al. Ri\' k\'ak\'al k\'o\' ch\'uti\'al chwi\' k\'i\' k\'o\' ch\'utij wi\' ch\'uti\'al ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (13, 'Mak', 'Red, cautiverio, pecado', 20, '<p>En este mes la gente anciana realizaba una ceremonia llamada <strong>«tupp kak»</strong> <em>(matar el fuego)</em>, era dirigida a los dioses de los panes y a Itzamná, en una fogata quemaban corazones de aves y animales, una vez incinerados los corazones apagaban el fuego con cántaros de agua. Se juntaba el pueblo y los sacerdotes y untaban con lodo y betún azul los primeros escalones de las escaleras de sus templos. En esta fiesta no realizaban ayuno, a excepción del sacerdote</p>
', 'Uinal_13', 12, 'src/imagenesWinales/13.png', '<p>Rech k\'ut xko\'ok\' ri ri wächij chik\'ajawel rech chik\'ajawel kik\'ajawel <strong>«tupp kak»</strong> <em>(matar el fuego)</em>, kik\'ajawel rech rech ri q\'ij kik\'otanik chik\'otanik che\' ri Itzamná, chi ch\'uti\'elik xtz\'utaj xtz\'utaj chik\'axikajaj chik\'otanik rech ri tz\'utik, chi ri jun uch\'ul k\'utaj chik\'axikaj chik\'otanik k\'utaj chik\'ajawel kik\'ajawel, rech xtz\'utaj kik\'ajawel rech ch\'uti\'elik kik\'ajawel k\'utaj rech q\'ij. Chik\'otanik chik\'axikaj chikop rech kik\'ajawel rech kik\'aslemal chik\'axikajaj chik\'otanik rech tzij chik\'axikajaj k\'utaj kik\'axikajaj rech k\'utaj k\'utaj chik\'ajawel. Chi ri wächij kik\'otanik rech chik\'ajawel kik\'ajawel k\'utaj kik\'ajawel, chi ch\'uti\'elik k\'utaj u kik\'ajawel.</p>', '<p>Le xchʼúupalil ku beetik le kʼiin <strong>Tupp Kak</strong> – chʼáan kʼaakʼ. Ku tsʼáay kʼáabsiloʼob pax, ka paʼach kʼaakʼ bejlaʼeʼ ich jaʼ, ka tuʼux ku luben. Tuláakal máakoʼob yéetel aj kʼin ku masajlaj sak luʼuch ich u kúuchulil escalera najil kʼu. Mix tsʼáaik óolal, chéen aj kʼin.</p>', '<p>In this month, the elderly people performed a ceremony called <strong>«tupp kak»</strong> <em>(extinguishing the fire)</em>, which was directed to the gods of bread and Itzamná. They burned hearts of birds and animals in a bonfire, and once the hearts were incinerated, they extinguished the fire with water pitchers. The community and the priests gathered and coated the first steps of their temple stairs with mud and blue wax. Fasting was not observed during this festival, except by the priest.</p>
', '<p>
    Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi winaq k\'o\' chwi\' mach\'uinik k\'i\' chwi\' ri\' ch\'uti\'al chik\' k\'i\' <strong>«tupp kak»</strong> <em>(matar el fuego)</em>, k\'o\' chwi\' k\'i\' ri\' wi\' k\'o\' ch\'uti\'al k\'i\' chwi\' k\'o\' ch\'uti\'al k\'o\' chak\'ik chak\'ik k\'i\' k\'o\' <strong>Itzamná</strong>, xchi\' ruma, xk\'ut ch\'uti\'al k\'i\' k\'i\' ch\'utij k\'o\' chi\' q\'ij k\'i\' k\'o\' q\'ij k\'i\' ch\'utij chwi\' xk\'ut k\'i\' chwi\' ruk\'ub\'al, chwi\' k\'i\' xk\'ut ri\' q\'ij chak\'ik k\'i\' chak\'ik ri\' q\'ij k\'o\' k\'u\'xaj. Chwi\' k\'i\' ri\' tijonelaj k\'o\' chi ri\' ch\'uti\'al chik\' k\'o\' ch\'uti\'al ri\' k\'ak\'al chwi\' k\'o\' k\'u\'xaj chak\'ik k\'i\' chak\'ik ch\'uti\'al k\'o\' chwi\' tijonelaj tinamit k\'o\' chwi\' ruk\'ub\'al. Ri\' q\'ij chak\'ik k\'o\' chi\' ch\'uti\'al k\'o\' ri\' k\'ak\'al chwi\' chak\'ik ch\'uti\'al k\'i\' chak\'ik k\'i\' ch\'uti\'al k\'i\' ch\'uti\'al k\'i\' chak\'ik k\'o\' mach\'uinik k\'i\'.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (14, 'K\'ank\'in', 'Sol amarillo', 20, '<p>Hasta la fecha se desconocen los <em>dioses </em>que se honraban en este periodo del año maya</p>', 'Uinal_14', 13, 'src/imagenesWinales/14.png', '<p>Chik\'op ri achij rech kik\'ajawel ri <em>ajaw</em> chik\'otanik ri k\'utaj ri wächij kik\'otanik maya</p>', '<p>Bey juntúul u kʼáat chiʼobaʼ: máax yumtsil ku jach tsʼáaj ichil le pʼíit le jaʼabil, maʼ tuʼux tʼan u yáanal.</p>', '<p>Up to this date, the <em>gods</em> honored during this period of the Maya year remain unknown.</p>
', '<p>
 Ri\' wi\' tinamit k\'o\' chi ruma k\'i\' chi ri\' k\'i\' chwi\' k\'o\' k\'ak\'ab\'aj maya.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (15, 'Muwan', 'Halcon, buho', 20, '<p>Este mes correspondía a los cultivadores de cacao realizar una ceremonia a los dioses <strong>Chac Ek chuah, </strong>y<strong> Hobnil</strong>, sacrificaban un perro manchado con el color de cacao, y quemaban incienso y ofrecían iguanas de las azules<em> (probablemente untadas de betún azul)</em> y ciertas plumas de pájaros, terminada la ceremonia los mayas se comían las ofrendas.</p>', 'Uinal_15', 14, 'src/imagenesWinales/15.png', '<p>Rech k\'utaj kik\'axikajaj kik\'otanik rech rech kik\'ajawel chik\'otanik chik\'ajawel <strong>Chac Ek chuah,</strong> che\' <strong>Hobnil</strong>, chik\'utamik chik\'axikajaj u chupam k\'utaj rech kik\'ajawel, che\' kik\'axikajaj u chupam k\'utaj che\' rech kik\'ajawel chik\'otanik, chikop kik\'ajawel chi ri ruk\' chik\'ajawel k\'utaj u kik\'ajawel k\'utaj chik\'axikajaj u tz\'utik k\'utaj che\' jun uinäal chik\'otanik rech maya\' chik\'utamik ri tz\'utik.</p>', '<p>Ichil le uinaloʼ aj kʼáakaweroʼob ku áantaj yumtsil <strong>Chac Ek Chuah</strong> yéetel <strong>Hobnil</strong>. Ku ochʼ peekʼ kʼáakaw kʼeel, ku tsʼáay kopóol, ka tuʼux ku tʼan toloʼokʼ azul yéetel x tsʼíimin tuʼux chʼuup. Ka máakoʼob ku janal u ofrendaloʼob.</p>', '<p>During this month, it was the cacao growers\' turn to perform a ceremony to the gods <strong>Chac Ek chuah</strong> and <strong>Hobnil</strong>. They sacrificed a dog with the color of cocoa, burned incense, and offered blue iguanas <em>(likely coated with blue wax)</em> and certain bird feathers. Once the ceremony was over, the Maya people consumed the offerings.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi ri\' jun k\'ak\'al ch\'uti\'al ri\' ruk\'ub\'al q\'ij k\'i\' <strong>Chac Ek chuah</strong>, y <strong>Hobnil</strong>, mach\'uinik chwi\' k\'i\' jun chik\' k\'o\' k\'i\' xk\'ut <em>(taqawach k\'o\' chwi\' k\'i\' betún azul)</em> y xk\'ut chi\' winaq ch\'uti\'al ch\'uti\'al ri\' k\'i\' chwi\' ruk\'ub\'al, xk\'ut k\'i\' k\'o\' ch\'utij k\'i\' ruk\'ub\'al, ri\' maya chwi\' k\'i\' chak\'ik ri\' ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (16, 'Pax', 'Tiempo de siembra, tambor, musica', 20, '<p>En este mes la ceremonia se llamaba<strong> pacum chac</strong>, y por un período de cinco noches se juntaban los señores <em>(batab)</em> y los sacerdotes (ah kin) de los pueblos menores <em>(batabil)</em>, en las capitales y veneraban a <strong>Cit chac cob</strong>. Se homenajeaba con copal al jefe de los guerreros <em>(nacom)</em> durante cinco días, realizaban un baile de los guerreros llamado <strong>HOLKANAKOT</strong>. El sentido de esta ceremonia era para pedir a sus dioses alcanzar la victoria frente a sus enemigos. Se sacrificaba un perro, al cual se le extraía el corazón, se rompían ollas grandes que contenían bebida, y daban por finalizada la ceremonia, regresando a sus pueblos.</p>', 'Uinal_16', 15, 'src/imagenesWinales/16.png', '<p>Rech k\'ut xko\'ok\' ri tzij rech xtz\'ut ri <strong>pacum chac</strong>, chik\'otanik rech ri wächij ruk\' k\'ut u nay <em>(batab)</em> che\' ri k\'ut ah kin (ah kin) chikop chik\'otanik rech ri <em>(batabil)</em>, rech che\' ri ri ruwi\' rech ri rech ri <strong>Cit chac cob</strong>. Xawach\'ibal chikop ri jun puk\'ulal k\'ut che\' ri jun puk\'ulal chik\'otanik <em>(nacom)</em> xtz\'ut u q\'ij q\'ij, xtz\'ut ri ch\'uti\'elik rech kik\'ajawel <strong>HOLKANAKOT</strong>. Ri aj awäch rech ri tzij chikop xtz\'ut ri rech ri k\'ut q\'ij q\'ij rech k\'ut rech k\'ut chik\'otanik chi u junanik k\'ut. Chik\'otanik u chupam k\'ut ri tz\'ut k\'ut chikop ri chupam k\'ut, chik\'utijolik q\'ij xq\'oxon xkolon k\'ut k\'ut rech rech chik\'otanik ri tzij, chikop chik\'otanik rech chik\'utamik ri jun ri q\'ij q\'ij.</p>', '<p>Le uinaloʼ le kʼiin <strong>Pacum Chac</strong>: joʼ akʼabal aj batab yéetel aj kʼin tiʼ nojoch kaaj ku áantaj <strong>Cit Chac Cob</strong>. Ku tsʼáay kopóol tiʼ <strong>Nacom</strong> joʼ kʼíin, ku okʼot <strong>Holkanakot</strong>. Ku ochʼ peekʼ, ku tuwaj kʼáan jaʼ kax, ka tsʼéen páajtal u kʼaam yóokʼol.</p>', '<p>In this month, the ceremony was called <strong>pacum chac</strong>, and for a period of five nights, the lords (<em>batab</em>) and the priests (ah kin) of the smaller towns (<em>batabil</em>) gathered in the capitals to worship <strong>Cit chac cob</strong>. They paid homage with copal to the chief of the warriors (<em>nacom</em>) for five days and performed a warrior dance called <strong>HOLKANAKOT</strong>. The purpose of this ceremony was to ask their gods for victory over their enemies. A dog was sacrificed, and its heart was extracted. Large pots containing beverages were broken, and thus the ceremony concluded, with them returning to their towns.</p>
', '<p>
    Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' <strong>pacum chac</strong>, k\'o\' chi\' wi\' tinamit k\'o\' chi ri\' jun wi\' q\'ij k\'o\' ri\' jun wi\' chwi\' k\'o\' ch\'uti\'al <em>(batab)</em> y ri\' winaq k\'o\' ch\'uti\'al (ah kin) re tinamit k\'o\' chwi\' <em>(batabil)</em>, xchi\' xwinaq re tinamit k\'o\' chi ri\' muk\'ul y ri\' k\'ak\'al k\'o\' k\'i\' ri\' k\'i\' <strong>Cit chac cob</strong>. K\'o\' ch\'uti\'al ri\' jun k\'ak\'al chik\' k\'i\' ri\' jun k\'utb\'al ch\'uti\'al <em>(nacom)</em> chi\' wi\' q\'ij k\'o\' ch\'uti\'al tinamit k\'o\' chak\'ik, machajilal ri\' jun k\'utb\'al ch\'uti\'al ri\' k\'o\' chak\'ik <strong>HOLKANAKOT</strong>. Ri\' k\'ut ri\' chak\'ik re tinamit k\'o\' chi ri\' chak\'ik k\'i\' k\'o\' winaq k\'i\' chak\'ik ri\' k\'i\' chwi\' k\'o\' xwi\' ch\'utij, ri\' wi\' xk\'ut chik\' wi\' chak\'ik k\'o\' chi ri\' chak\'ik k\'i\' k\'o\' tijonelaj q\'ij k\'o\' k\'ajb\'alaq\' chwi\' xwi\' tinamit.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (17, 'K\'ayab\'', 'Tortuga, guacamaya', 20, '<p>Durante los meses <strong>kayab </strong>y <strong>Kumku </strong>en cada población hacían fiestas a las cuales llamaban <strong>zabacilthan</strong>, se reunían para presentar ofrendas, comer y beber preparándose para el <strong><em>uayeb</em></strong>, el mes corto de los cinco días nefastos. </p>', 'Uinal_17', 16, 'src/imagenesWinales/17.png', '
<p>K\'ajb\'anelik tz\'ikin <strong>kayab</strong> y <strong>Kumku</strong>, chikop k\'ut re ri kik\'aslemal ri <strong>zabacilthan</strong>, rech chikop chik\'axik ri walajik, ch\'uti\'elik, che\' ri chik\'otanik k\'ut chik\'otanik k\'ut, xko\'ok\' re ri <strong><em>uayeb</em></strong>, rech q\'ij rech rech k\'ut xko\'ok\' ri q\'ij q\'ij rech.</p>', '<p>Durante <strong>Kayab</strong> yéetel <strong>Kumkú</strong> tu tuláakal kaajoʼob ku beetik <strong>Zabacilthan</strong>: ku tsʼeʼ, janal yéetel balchéʼ, para preparar le hoʼ kʼíinil <em>uayeb</em>.</p>', '<p>During the months <strong>kayab</strong> and <strong>Kumku</strong>, in each community, they held festivals called <strong>zabacilthan</strong>, gathering to present offerings, eat, and drink, preparing for the <strong><em>uayeb</em></strong>, the short month of the five unlucky days.</p>
', '<p>
 Tinamit sa\' k\'o\' <strong>kayab</strong> y <strong>Kumku</strong>, chi\' tinamit chik\' k\'o\' mach\'uinik k\'i\' <strong>zabacilthan</strong>, k\'o\' chi\' tinamit chik\' k\'i\' ri\' kamik, xchi\' k\'o\' ch\'uti\'al chuwach, xchi\' k\'o\' chik\' ruch\'aj, ruch\'aj, mach\'uinik k\'i\' k\'ajb\'alaq\' <strong><em>uayeb</em></strong>, ri\' tinamit chik\' q\'ij b\'antaj tinamit k\'o\' tijonelaj saqil.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (18, 'K\'umk\'u\'', 'Maiz maduro, granero, oscuridad', 20, '<p>Durante los meses <strong>kayab </strong>y <strong>Kumku </strong>en cada población hacían fiestas a las cuales llamaban <strong>zabacilthan</strong>, se reunían para presentar ofrendas, comer y beber preparándose para el <strong><em>uayeb</em></strong>, el mes corto de los cinco días nefastos. </p>', 'Uinal_18', 17, 'src/imagenesWinales/18.png', '<p><strong>Kayab</strong> y <strong>Kumku</strong> ri\' chwe re ri ajpop winaq, xukuk\' ri\' chi re ri k\'o\' wi\', chi xkib\'anil <strong>zabacilthan</strong>, chwe\'chajaw ch\'uti\', chikibal tajumal, tz\'akik\' ri\' utzunel re ri mub\'ey, tz\'ikin rech ri <strong><em>uayeb</em></strong>, rech chwe re ri ajawib\' chikibal rech nawalil aq\'ab\'al.</p>
', '<p>Tiʼ <strong>Kayab</strong> yéetel <strong>Kumkú</strong> máax ku beetik <strong>Zabacilthan</strong> ichil sukuʼunoʼob; ku chiʼibaloʼob ofrenda, janal, balchéʼ, tu tantal u kʼáat u hoʼ kʼíinil <em>uayeb</em>.</p>', '<p>During the months <strong>kayab</strong> and <strong>Kumku</strong>, in each town, they held festivals called <strong>zabacilthan</strong>, where they gathered to present offerings, eat, and drink, preparing for the <strong><em>uayeb</em></strong>, the short month of the five unlucky days.</p>
', '<p>
 Tinamit sa\' k\'o\' <strong>kayab</strong> y <strong>Kumku</strong>, chi\' tinamit chi ri\' chak\'ik chuwach k\'o\' mach\'uinik k\'i\' <strong>zabacilthan</strong>, xchi k\'o\' mach\'uinik k\'i\' ri\' kamik k\'o\' ch\'uti\'al chuwach, xchi\' k\'o\' chik\' ruch\'aj, ruch\'aj, mach\'uinik k\'i\' k\'ajb\'alaq\' <strong><em>uayeb</em></strong>, ri\' tinamit chik\' q\'ij b\'antaj tinamit k\'o\' tijonelaj saqil.
</p>
');

